-- NRSV-CE OLD TESTAMENT BIBLE VERSES (PART 12)

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 1, 1, 'The vision of Isaiah son of Amoz, which he saw concerning Judah and Jerusalem in the days of Uzziah, Jotham, Ahaz, and Hezekiah, kings of Judah.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 1, 2, 'Hear, O heavens, and listen, O earth;  
    for the LORD has spoken:  
I reared children and brought them up,  
    but they have rebelled against me.', 'en', 'NRSV-CE', 'The Wickedness of Judah'),
(23, 'Yes', 'Isaiah', 1, 3, 'The ox knows its owner,  
    and the donkey its master"s crib;  
but Israel does not know,  
    my people do not understand.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 1, 4, 'Ah, sinful nation,  
    people laden with iniquity,  
offspring who do evil,  
    children who deal corruptly,  
who have forsaken the LORD,  
    who have despised the Holy One of Israel,  
    who are utterly estranged!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 1, 5, 'Why do you seek further beatings?  
    Why do you continue to rebel?  
The whole head is sick,  
    and the whole heart faint.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 1, 6, 'From the sole of the foot even to the head,  
    there is no soundness in it,  
but bruises and sores  
    and bleeding wounds;  
they have not been drained, or bound up,  
    or softened with oil.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 1, 7, 'Your country lies desolate,  
    your cities are burned with fire;  
in your very presence  
    aliens devour your land;  
    it is desolate, as overthrown by foreigners.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 1, 8, 'And daughter Zion is left  
    like a booth in a vineyard,  
like a shelter in a cucumber field,  
    like a besieged city.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 1, 9, 'If the LORD of hosts  
    had not left us a few survivors,  
we would have been like Sodom,  
    and become like Gomorrah.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 1, 10, 'Hear the word of the LORD,  
    you rulers of Sodom!  
Listen to the teaching of our God,  
    you people of Gomorrah!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 1, 11, 'What to me is the multitude of your sacrifices?  
    says the LORD;  
I have had enough of burnt offerings of rams  
    and the fat of fed beasts;  
I do not delight in the blood of bulls,  
    or of lambs, or of goats.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 1, 12, 'When you come to appear before me,  
    who asked this from your hand?  
    Trample my courts no more;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 1, 13, 'bringing offerings is futile;  
    incense is an abomination to me.  
New moon and sabbath and calling of convocation--  
    I cannot endure solemn assemblies with iniquity.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 1, 14, 'Your new moons and your appointed festivals  
    my soul hates;  
they have become a burden to me,  
    I am weary of bearing them.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 1, 15, 'When you stretch out your hands,  
    I will hide my eyes from you;  
even though you make many prayers,  
    I will not listen;  
    your hands are full of blood.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 1, 16, 'Wash yourselves; make yourselves clean;  
    remove the evil of your doings  
    from before my eyes;  
cease to do evil,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 1, 17, 'learn to do good;  
seek justice,  
    rescue the oppressed,  
defend the orphan,  
    plead for the widow.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 1, 18, 'Come now, let us argue it out,  
    says the LORD:  
though your sins are like scarlet,  
    they shall be like snow;  
though they are red like crimson,  
    they shall become like wool.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 1, 19, 'If you are willing and obedient,  
    you shall eat the good of the land;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 1, 20, 'but if you refuse and rebel,  
    you shall be devoured by the sword;  
    for the mouth of the LORD has spoken.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 1, 21, 'How the faithful city  
    has become a whore!  
    She that was full of justice,  
righteousness lodged in her--  
    but now murderers!', 'en', 'NRSV-CE', 'The Degenerate City'),
(23, 'Yes', 'Isaiah', 1, 22, 'Your silver has become dross,  
    your wine is mixed with water.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 1, 23, 'Your princes are rebels  
    and companions of thieves.  
Everyone loves a bribe  
    and runs after gifts.  
They do not defend the orphan,  
    and the widow"s cause does not come before them.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 1, 24, 'Therefore says the Sovereign, the LORD of hosts, the Mighty One of Israel:  
Ah, I will pour out my wrath on my enemies,  
    and avenge myself on my foes!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 1, 25, 'I will turn my hand against you;  
    I will smelt away your dross as with lye  
    and remove all your alloy.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 1, 26, 'And I will restore your judges as at the first,  
    and your counselors as at the beginning.  
Afterward you shall be called the city of righteousness,  
    the faithful city.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 1, 27, 'Zion shall be redeemed by justice,  
    and those in her who repent, by righteousness.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 1, 28, 'But rebels and sinners shall be destroyed together,  
    and those who forsake the LORD shall be consumed.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 1, 29, 'For you shall be ashamed of the oaks  
    in which you delighted;  
and you shall blush for the gardens  
    that you have chosen.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 1, 30, 'For you shall be like an oak  
    whose leaf withers,  
    and like a garden without water.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 1, 31, 'The strong shall become like tinder,  
    and their work like a spark;  
they and their work shall burn together,  
    with no one to quench them.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 2, 1, 'The word that Isaiah son of Amoz saw concerning Judah and Jerusalem.', 'en', 'NRSV-CE', 'The Future House of God'),
(23, 'Yes', 'Isaiah', 2, 2, 'In days to come  
    the mountain of the LORD"s house  
shall be established as the highest of the mountains,  
    and shall be raised above the hills;  
all the nations shall stream to it.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 2, 3, 'Many peoples shall come and say,  
"Come, let us go up to the mountain of the LORD,  
    to the house of the God of Jacob;  
that he may teach us his ways  
    and that we may walk in his paths."  
For out of Zion shall go forth instruction,  
    and the word of the LORD from Jerusalem.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 2, 4, 'He shall judge between the nations,  
    and shall arbitrate for many peoples;  
they shall beat their swords into plowshares,  
    and their spears into pruning hooks;  
nation shall not lift up sword against nation,  
    neither shall they learn war any more.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 2, 5, 'O house of Jacob,  
    come, let us walk  
    in the light of the LORD!', 'en', 'NRSV-CE', 'Judgment Pronounced on Arrogance'),
(23, 'Yes', 'Isaiah', 2, 6, 'For you have forsaken the ways of your people,  
    O house of Jacob.  
Indeed they are full of diviners from the east  
    and of soothsayers like the Philistines,  
    and they clasp hands with foreigners.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 2, 7, 'Their land is filled with silver and gold,  
    and there is no end to their treasures;  
their land is filled with horses,  
    and there is no end to their chariots.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 2, 8, 'Their land is filled with idols;  
    they bow down to the work of their hands,  
    to what their own fingers have made.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 2, 9, 'And so people are humbled,  
    and everyone is brought low--  
    do not forgive them!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 2, 10, 'Enter into the rock,  
    and hide in the dust  
from the terror of the LORD,  
    and from the glory of his majesty.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 2, 11, 'The haughty eyes of people shall be brought low,  
    and the pride of everyone shall be humbled;  
and the LORD alone will be exalted on that day.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 2, 12, 'For the LORD of hosts has a day  
    against all that is proud and lofty,  
    against all that is lifted up and high;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 2, 13, 'against all the cedars of Lebanon,  
    lofty and lifted up;  
    and against all the oaks of Bashan;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 2, 14, 'against all the high mountains,  
    and against all the lofty hills;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 2, 15, 'against every high tower,  
    and against every fortified wall;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 2, 16, 'against all the ships of Tarshish,  
    and against all the beautiful craft.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 2, 17, 'The haughtiness of people shall be humbled,  
    and the pride of everyone shall be brought low;  
    and the LORD alone will be exalted on that day.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 2, 18, 'The idols shall utterly pass away.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 2, 19, 'Enter the caves of the rocks  
    and the holes of the ground,  
from the terror of the LORD,  
    and from the glory of his majesty,  
    when he rises to terrify the earth.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 2, 20, 'On that day people will throw away  
    to the moles and to the bats  
their idols of silver and their idols of gold,  
    which they made for themselves to worship,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 2, 21, 'to enter the caverns of the rocks  
    and the clefts in the crags,  
from the terror of the LORD,  
    and from the glory of his majesty,  
    when he rises to terrify the earth.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 2, 22, 'Turn away from mortals,  
    who have only breath in their nostrils,  
    for of what account are they?', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 3, 1, 'For now the Sovereign, the LORD of hosts,  
    is taking away from Jerusalem and from Judah  
support and staff--  
    all support of bread,  
    and all support of water--', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 3, 2, 'warrior and soldier,  
    judge and prophet,  
    diviner and elder,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 3, 3, 'captain of fifty  
    and dignitary,  
counselor and skillful magician  
    and expert enchanter.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 3, 4, 'And I will make boys their princes,  
    and babes shall rule over them.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 3, 5, 'The people will be oppressed,  
    everyone by another  
    and everyone by a neighbor;  
the youth will be insolent to the elder,  
    and the base to the honorable.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 3, 6, 'Someone will even seize a relative,  
    a member of the clan, saying,  
"You have a cloak;  
    you shall be our leader,  
and this heap of ruins  
    shall be under your rule."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 3, 7, 'But the other will cry out on that day, saying,  
"I will not be a healer;  
    in my house there is neither bread nor cloak;  
you shall not make me  
    leader of the people."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 3, 8, 'For Jerusalem has stumbled  
    and Judah has fallen,  
because their speech and their deeds are against the LORD,  
    defying his glorious presence.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 3, 9, 'The look on their faces bears witness against them;  
    they proclaim their sin like Sodom,  
    they do not hide it.  
Woe to them!  
    For they have brought evil on themselves.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 3, 10, 'Tell the innocent how fortunate they are,  
    for they shall eat the fruit of their labors.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 3, 11, 'Woe to the guilty! How unfortunate they are,  
    for what their hands have done shall be done to them.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 3, 12, 'My people--children are their oppressors,  
    and women rule over them.  
O my people, your leaders mislead you,  
    and confuse the course of your paths.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 3, 13, 'The LORD rises to argue his case;  
    he stands to judge the peoples.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 3, 14, 'The LORD enters into judgment  
    with the elders and princes of his people:  
It is you who have devoured the vineyard;  
    the spoil of the poor is in your houses.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 3, 15, 'What do you mean by crushing my people,  
    by grinding the face of the poor? says the Lord God of hosts.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 3, 16, 'The LORD said:  
Because the daughters of Zion are haughty  
    and walk with outstretched necks,  
    glancing wantonly with their eyes,  
mincing along as they go,  
    tinkling with their feet;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 3, 17, 'the Lord will afflict with scabs  
    the heads of the daughters of Zion,  
    and the LORD will lay bare their secret parts.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 3, 18, 'In that day the Lord will take away the finery of the anklets, the headbands, and the crescents;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 3, 19, 'the pendants, the bracelets, and the scarfs;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 3, 20, 'the headdresses, the armlets, the sashes, the perfume boxes, and the amulets;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 3, 21, 'the signet rings and nose rings;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 3, 22, 'the festal robes, the mantles, the cloaks, and the handbags;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 3, 23, 'the garments of gauze, the linen garments, the turbans, and the veils.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 3, 24, 'Instead of perfume there will be a stench;  
    and instead of a sash, a rope;  
and instead of well-set hair, baldness;  
    and instead of a rich robe, a binding of sackcloth;  
    instead of beauty, shame.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 3, 25, 'Your men shall fall by the sword  
    and your warriors in battle.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 3, 26, 'And her gates shall lament and mourn;  
    ravaged, she shall sit upon the ground.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 4, 1, 'Seven women shall take hold of one man in that day, saying,
"We will eat our own bread and wear our own clothes;  
just let us be called by your name;  
    take away our disgrace."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 4, 2, 'On that day the branch of the LORD shall be beautiful and glorious, and the fruit of the land shall be the pride and glory of the survivors of Israel.', 'en', 'NRSV-CE', 'The Future Glory of the Survivors in Zion'),
(23, 'Yes', 'Isaiah', 4, 3, 'Whoever is left in Zion and remains in Jerusalem will be called holy, everyone who has been recorded for life in Jerusalem,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 4, 4, 'once the Lord has washed away the filth of the daughters of Zion and cleansed the bloodstains of Jerusalem from its midst by a spirit of judgment and by a spirit of burning.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 4, 5, 'Then the LORD will create over the whole site of Mount Zion and over its places of assembly a cloud by day and smoke and the shining of a flaming fire by night. Indeed over all the glory there will be a canopy.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 4, 6, 'It will serve as a pavilion, a shade by day from the heat, and a refuge and a shelter from the storm and rain.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 5, 1, 'Let me sing for my beloved
    my love-song concerning his vineyard:  
My beloved had a vineyard  
    on a very fertile hill.', 'en', 'NRSV-CE', 'The Song of the Unfruitful Vineyard'),
(23, 'Yes', 'Isaiah', 5, 2, 'He dug it and cleared it of stones,  
    and planted it with choice vines;  
he built a watchtower in the midst of it,  
    and hewed out a wine vat in it;  
he expected it to yield grapes,  
    but it yielded wild grapes.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 5, 3, 'And now, inhabitants of Jerusalem  
    and people of Judah,  
judge between me  
    and my vineyard.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 5, 4, 'What more was there to do for my vineyard  
    that I have not done in it?  
When I expected it to yield grapes,  
    why did it yield wild grapes?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 5, 5, 'And now I will tell you  
    what I will do to my vineyard.  
I will remove its hedge,  
    and it shall be devoured;  
I will break down its wall,  
    and it shall be trampled down.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 5, 6, 'I will make it a waste;  
    it shall not be pruned or hoed,  
    and it shall be overgrown with briers and thorns;  
I will also command the clouds  
    that they rain no rain upon it.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 5, 7, 'For the vineyard of the LORD of hosts  
    is the house of Israel,  
and the people of Judah  
    are his pleasant planting;  
he expected justice,  
    but saw bloodshed;  
righteousness,  
    but heard a cry!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 5, 8, 'Ah, you who join house to house,  
    who add field to field,  
until there is room for no one but you,  
    and you are left to live alone  
    in the midst of the land!', 'en', 'NRSV-CE', 'Social Injustice Denounced'),
(23, 'Yes', 'Isaiah', 5, 9, 'The LORD of hosts has sworn in my hearing:  
Surely many houses shall be desolate,  
    large and beautiful houses, without inhabitant.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 5, 10, 'For ten acres of vineyard shall yield but one bath,  
    and a homer of seed shall yield a mere ephah.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 5, 11, 'Ah, you who rise early in the morning  
    in pursuit of strong drink,  
who linger in the evening  
    to be inflamed by wine,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 5, 12, 'whose feasts consist of lyre and harp,  
    tambourine and flute and wine,  
but who do not regard the deeds of the LORD,  
    or see the work of his hands!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 5, 13, 'Therefore my people go into exile without knowledge;  
their nobles are dying of hunger,  
    and their multitude is parched with thirst.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 5, 14, 'Therefore Sheol has enlarged its appetite  
    and opened its mouth beyond measure;  
the nobility of Jerusalem and her multitude go down,  
    her throng and all who exult in her.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 5, 15, 'People are bowed down, everyone is brought low,  
    and the eyes of the haughty are humbled.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 5, 16, 'But the LORD of hosts is exalted by justice,  
    and the Holy God shows himself holy by righteousness.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 5, 17, 'Then the lambs shall graze as in their pasture,  
    fatlings and kids shall feed among the ruins.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 5, 18, 'Ah, you who drag iniquity along with cords of falsehood,  
    who drag sin along as with cart ropes,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 5, 19, 'who say, "Let him make haste,  
    let him speed his work  
    that we may see it;  
let the plan of the Holy One of Israel hasten to fulfillment,  
    that we may know it!"', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 5, 20, 'Ah, you who call evil good  
    and good evil,  
who put darkness for light  
    and light for darkness,  
who put bitter for sweet  
    and sweet for bitter!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 5, 21, 'Ah, you who are wise in your own eyes,  
    and shrewd in your own sight!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 5, 22, 'Ah, you who are heroes in drinking wine  
    and valiant at mixing drink,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 5, 23, 'who acquit the guilty for a bribe,  
    and deprive the innocent of their rights!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 5, 24, 'Therefore, as the tongue of fire devours the stubble,  
    and as dry grass sinks down in the flame,  
so their root will become rotten,  
    and their blossom go up like dust;  
for they have rejected the instruction of the LORD of hosts,  
    and have despised the word of the Holy One of Israel.', 'en', 'NRSV-CE', 'Foreign Invasion Predicted'),
(23, 'Yes', 'Isaiah', 5, 25, 'Therefore the anger of the LORD was kindled against his people,  
    and he stretched out his hand against them and struck them;  
    the mountains quaked,  
and their corpses were like refuse  
    in the streets.  
For all this his anger has not turned away,  
    and his hand is stretched out still.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 5, 26, 'He will raise a signal for a nation far away,  
    and whistle for a people at the ends of the earth;  
Here they come, swiftly, speedily!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 5, 27, 'None of them is weary, none stumbles,  
    none slumbers or sleeps,  
not a loincloth is loose,  
    not a sandal-thong broken;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 5, 28, 'their arrows are sharp,  
    all their bows bent,  
their horses" hoofs seem like flint,  
    and their wheels like the whirlwind.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 5, 29, 'Their roaring is like a lion,  
    like young lions they roar;  
they growl and seize their prey,  
    they carry it off, and no one can rescue.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 5, 30, 'They will roar over it on that day,  
    like the roaring of the sea.  
And if one look to the land--  
    only darkness and distress;  
and the light grows dark with clouds.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 6, 1, 'In the year that King Uzziah died, I saw the Lord sitting on a throne, high and lofty; and the hem of his robe filled the temple.', 'en', 'NRSV-CE', 'A Vision of God in the Temple'),
(23, 'Yes', 'Isaiah', 6, 2, 'Seraphs were in attendance above him; each had six wings: with two they covered their faces, and with two they covered their feet, and with two they flew.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 6, 3, 'And one called to another and said:
"Holy, holy, holy is the LORD of hosts;  
the whole earth is full of his glory."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 6, 4, 'The pivots on the thresholds shook at the voices of those who called, and the house filled with smoke.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 6, 5, 'And I said: "Woe is me! I am lost, for I am a man of unclean lips, and I live among a people of unclean lips; yet my eyes have seen the King, the LORD of hosts!"', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 6, 6, 'Then one of the seraphs flew to me, holding a live coal that had been taken from the altar with a pair of tongs.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 6, 7, 'The seraph touched my mouth with it and said: "Now that this has touched your lips, your guilt has departed and your sin is blotted out."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 6, 8, 'Then I heard the voice of the Lord saying, "Whom shall I send, and who will go for us?" And I said, "Here am I; send me!"', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 6, 9, 'And he said, "Go and say to this people:
"Keep listening, but do not comprehend;  
keep looking, but do not understand."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 6, 10, 'Make the mind of this people dull,  
    and stop their ears,  
    and shut their eyes,  
so that they may not look with their eyes,  
    and listen with their ears,  
and comprehend with their minds,  
    and turn and be healed."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 6, 11, 'Then I said, "How long, O Lord?" And he said:  
"Until cities lie waste  
    without inhabitant,  
and houses without people,  
    and the land is utterly desolate;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 6, 12, 'until the LORD sends everyone far away,  
    and vast is the emptiness in the midst of the land.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 6, 13, 'Even if a tenth part remain in it,  
    it will be burned again,  
like a terebinth or an oak  
    whose stump remains standing  
    when it is felled."  
The holy seed is its stump.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 7, 1, 'In the days of Ahaz son of Jotham son of Uzziah, king of Judah, King Rezin of Aram and King Pekah son of Remaliah of Israel went up to attack Jerusalem, but could not mount an attack against it.', 'en', 'NRSV-CE', 'Isaiah Reassures King Ahaz'),
(23, 'Yes', 'Isaiah', 7, 2, 'When the house of David heard that Aram had allied itself with Ephraim, the heart of Ahaz and the heart of his people shook as the trees of the forest shake before the wind.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 7, 3, 'Then the LORD said to Isaiah, Go out to meet Ahaz, you and your son Shear-jashub, at the end of the conduit of the upper pool on the highway to the Fuller"s Field,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 7, 4, 'and say to him, Take heed, be quiet, do not fear, and do not let your heart be faint because of these two smoldering stumps of firebrands, because of the fierce anger of Rezin and Aram and the son of Remaliah.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 7, 5, 'Because Aram--with Ephraim and the son of Remaliah--has plotted evil against you, saying,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 7, 6, 'Let us go up against Judah and cut off Jerusalem and conquer it for ourselves and make the son of Tabeel king in it;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 7, 7, 'therefore thus says the Lord God:
It shall not stand,  
    and it shall not come to pass.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 7, 8, 'For the head of Aram is Damascus,  
    and the head of Damascus is Rezin.
(Within sixty-five years Ephraim will be shattered, no longer a people.)', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 7, 9, 'The head of Ephraim is Samaria,  
    and the head of Samaria is the son of Remaliah.  
If you do not stand firm in faith,  
    you shall not stand at all.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 7, 10, 'Again the LORD spoke to Ahaz, saying,', 'en', 'NRSV-CE', 'Isaiah Gives Ahaz the Sign of Immanuel'),
(23, 'Yes', 'Isaiah', 7, 11, 'Ask a sign of the LORD your God; let it be deep as Sheol or high as heaven.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 7, 12, 'But Ahaz said, I will not ask, and I will not put the LORD to the test.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 7, 13, 'Then Isaiah said: "Hear then, O house of David! Is it too little for you to weary mortals, that you weary my God also?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 7, 14, 'Therefore the Lord himself will give you a sign. Look, the young woman is with child and shall bear a son, and shall name him Immanuel.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 7, 15, 'He shall eat curds and honey by the time he knows how to refuse the evil and choose the good.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 7, 16, 'For before the child knows how to refuse the evil and choose the good, the land before whose two kings you are in dread will be deserted.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 7, 17, 'The LORD will bring on you and on your people and on your ancestral house such days as have not come since the day that Ephraim departed from Judah--the king of Assyria."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 7, 18, 'On that day the LORD will whistle for the fly that is at the sources of the streams of Egypt, and for the bee that is in the land of Assyria.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 7, 19, 'And they will all come and settle in the steep ravines, and in the clefts of the rocks, and on all the thornbushes, and on all the pastures.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 7, 20, 'On that day the Lord will shave with a razor hired beyond the River--with the king of Assyria--the head and the hair of the feet, and it will take off the beard as well.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 7, 21, 'On that day one will keep alive a young cow and two sheep,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 7, 22, 'and will eat curds because of the abundance of milk that they give; for everyone that is left in the land shall eat curds and honey.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 7, 23, 'On that day every place where there used to be a thousand vines, worth a thousand shekels of silver, will become briers and thorns.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 7, 24, 'With bow and arrows one will go there, for all the land will be briers and thorns;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 7, 25, 'and as for all the hills that used to be hoed with a hoe, you will not go there for fear of briers and thorns; but they will become a place where cattle are let loose and where sheep tread.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 8, 1, 'Then the LORD said to me, Take a large tablet and write on it in common characters, "Belonging to Maher-shalal-hash-baz,"', 'en', 'NRSV-CE', 'Isaiah"s Son a Sign of the Assyrian Invasion'),
(23, 'Yes', 'Isaiah', 8, 2, 'and have it attested for me by reliable witnesses, the priest Uriah and Zechariah son of Jeberechiah.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 8, 3, 'And I went to the prophetess, and she conceived and bore a son. Then the LORD said to me, Name him Maher-shalal-hash-baz;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 8, 4, 'for before the child knows how to call "My father" or "My mother," the wealth of Damascus and the spoil of Samaria will be carried away by the king of Assyria.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 8, 5, 'The LORD spoke to me again:', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 8, 6, 'Because this people has refused the waters of Shiloah that flow gently, and melt in fear before Rezin and the son of Remaliah;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 8, 7, 'therefore, the Lord is bringing up against it the mighty flood waters of the River, the king of Assyria and all his glory; it will rise above all its channels and overflow all its banks;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 8, 8, 'it will sweep on into Judah as a flood, and, pouring over, it will reach up to the neck; and its outspread wings will fill the breadth of your land, O Immanuel.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 8, 9, 'Band together, you peoples, and be dismayed;  
    listen, all you far countries;  
gird yourselves and be dismayed;  
    gird yourselves and be dismayed!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 8, 10, 'Take counsel together, but it shall be brought to naught;  
    speak a word, but it will not stand,  
    for God is with us.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 8, 11, 'For the LORD spoke thus to me while his hand was strong upon me, and warned me not to walk in the way of this people, saying:', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 8, 12, 'Do not call conspiracy all that this people calls conspiracy, and do not fear what it fears, or be in dread.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 8, 13, 'But the LORD of hosts, him you shall regard as holy; let him be your fear, and let him be your dread.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 8, 14, 'He will become a sanctuary, a stone one strikes against; for both houses of Israel he will become a rock one stumbles over--a trap and a snare for the inhabitants of Jerusalem.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 8, 15, 'And many among them shall stumble; they shall fall and be broken; they shall be snared and taken.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 8, 16, 'Bind up the testimony, seal the teaching among my disciples.', 'en', 'NRSV-CE', 'Disciples of Isaiah'),
(23, 'Yes', 'Isaiah', 8, 17, 'I will wait for the LORD, who is hiding his face from the house of Jacob, and I will hope in him.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 8, 18, 'See, I and the children whom the LORD has given me are signs and portents in Israel from the LORD of hosts, who dwells on Mount Zion.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 8, 19, 'Now if people say to you, "Consult the ghosts and the familiar spirits that chirp and mutter; should not a people consult their gods, the dead on behalf of the living,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 8, 20, 'for teaching and for instruction?" surely, those who speak like this will have no dawn!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 8, 21, 'They will pass through the land, greatly distressed and hungry; when they are hungry, they will be enraged and will curse their king and their gods. They will turn their faces upward,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 8, 22, 'or they will look to the earth, but will see only distress and darkness, the gloom of anguish; and they will be thrust into thick darkness.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 9, 1, 'But there will be no gloom for those who were in anguish. In the former time he brought into contempt the land of Zebulun and the land of Naphtali, but in the latter time he will make glorious the way of the sea, the land beyond the Jordan, Galilee of the nations.', 'en', 'NRSV-CE', 'The Righteous Reign of the Coming King'),
(23, 'Yes', 'Isaiah', 9, 2, 'The people who walked in darkness  
    have seen a great light;  
those who lived in a land of deep darkness--  
    on them light has shined.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 9, 3, 'You have multiplied the nation,  
    you have increased its joy;  
they rejoice before you  
    as with joy at the harvest,  
    as people exult when dividing plunder.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 9, 4, 'For the yoke of their burden,  
    and the bar across their shoulders,  
    the rod of their oppressor,  
    you have broken as on the day of Midian.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 9, 5, 'For all the boots of the tramping warriors  
    and all the garments rolled in blood  
    shall be burned as fuel for the fire.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 9, 6, 'For a child has been born for us,  
    a son given to us;  
authority rests upon his shoulders;  
    and he is named  
Wonderful Counselor, Mighty God,  
    Everlasting Father, Prince of Peace.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 9, 7, 'His authority shall grow continually,  
    and there shall be endless peace  
for the throne of David and his kingdom.  
    He will establish and uphold it  
with justice and with righteousness  
    from this time onward and forevermore.  
The zeal of the LORD of hosts will do this.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 9, 8, 'The Lord sent a word against Jacob,  
    and it fell on Israel;', 'en', 'NRSV-CE', 'Judgment on Arrogance and Oppression'),
(23, 'Yes', 'Isaiah', 9, 9, 'and all the people knew it--  
    Ephraim and the inhabitants of Samaria--  
    but in pride and arrogance of heart they said:', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 9, 10, '"The bricks have fallen,  
    but we will build with dressed stones;  
the sycamores have been cut down,  
    but we will put cedars in their place."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 9, 11, 'So the LORD raised adversaries against them,  
    and stirred up their enemies,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 9, 12, 'the Arameans on the east and the Philistines on the west,  
    and they devoured Israel with open mouth.  
For all this his anger has not turned away;  
    his hand is stretched out still.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 9, 13, 'The people did not turn to him who struck them,  
    or seek the LORD of hosts.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 9, 14, 'So the LORD cut off from Israel head and tail,  
    palm branch and reed in one day--', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 9, 15, 'elders and dignitaries are the head,  
    and prophets who teach lies are the tail;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 9, 16, 'for those who led this people led them astray,  
    and those who were led by them were left in confusion.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 9, 17, 'That is why the Lord did not have pity on their young people,  
    or compassion on their orphans and widows;  
for everyone was godless and an evildoer,  
    and every mouth spoke folly.  
For all this his anger has not turned away;  
    his hand is stretched out still.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 9, 18, 'For wickedness burned like a fire,  
    consuming briers and thorns;  
it kindled the thickets of the forest,  
    and they swirled upward in a column of smoke.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 9, 19, 'Through the wrath of the LORD of hosts  
    the land was burned,  
and the people became like fuel for the fire;  
    no one spared another.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 9, 20, 'They gorged on the right, but still were hungry,  
    and they devoured on the left, but were not satisfied;  
they devoured the flesh of their own kindred;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 9, 21, 'Manasseh devoured Ephraim, and Ephraim Manasseh,  
    and together they were against Judah.  
For all this his anger has not turned away;  
    his hand is stretched out still.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 10, 1, 'Ah, you who make iniquitous decrees,  
    who write oppressive statutes,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 10, 2, 'to turn aside the needy from justice  
    and to rob the poor of my people of their right,  
that widows may be your spoil,  
    and that you may make the orphans your prey!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 10, 3, 'What will you do on the day of punishment,  
    in the calamity that will come from far away?  
To whom will you flee for help,  
    and where will you leave your wealth,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 10, 4, 'so as not to crouch among the prisoners  
    or fall among the slain?  
For all this his anger has not turned away;  
    his hand is stretched out still.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 10, 5, 'Ah, Assyria, the rod of my anger--  
    the club in their hands is my fury!', 'en', 'NRSV-CE', 'Arrogant Assyria Also Judged'),
(23, 'Yes', 'Isaiah', 10, 6, 'Against a godless nation I send him,  
    and against the people of my wrath I command him,  
to take spoil and seize plunder,  
    and to tread them down like the mire of the streets.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 10, 7, 'But this is not what he intends,  
    nor does he have this in mind;  
but it is in his heart to destroy,  
    and to cut off nations not a few.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 10, 8, 'For he says:  
"Are not my commanders all kings?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 10, 9, 'Is not Calno like Carchemish?  
    Is not Hamath like Arpad?  
    Is not Samaria like Damascus?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 10, 10, 'As my hand has reached to the kingdoms of the idols  
    whose images were greater than those of Jerusalem and Samaria,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 10, 11, 'shall I not do to Jerusalem and her idols  
    what I have done to Samaria and her images?"', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 10, 12, 'When the Lord has finished all his work on Mount Zion and on Jerusalem, he will punish the arrogant boasting of the king of Assyria and his haughty pride.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 10, 13, 'For he says:
"By the strength of my hand I have done it,  
    and by my wisdom, for I have understanding;  
I have removed the boundaries of peoples,  
    and have plundered their treasures;  
    like a bull I have brought down those who sat on thrones.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 10, 14, 'My hand has found, like a nest,  
    the wealth of the peoples;  
and as one gathers eggs that have been forsaken,  
    so I have gathered all the earth;  
and there was none that moved a wing,  
    or opened its mouth, or chirped."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 10, 15, 'Shall the ax vaunt itself over the one who wields it,  
    or the saw magnify itself against the one who handles it?  
As if a rod should raise the one who lifts it up,  
    or as if a staff should lift the one who is not wood!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 10, 16, 'Therefore the Sovereign, the LORD of hosts,  
    will send wasting sickness among his stout warriors,  
and under his glory a burning will be kindled,  
    like the burning of fire.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 10, 17, 'The light of Israel will become a fire,  
    and his Holy One a flame;  
and it will burn and devour  
    his thorns and briers in one day.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 10, 18, 'The glory of his forest and his fruitful land  
    the LORD will destroy, both soul and body,  
    and it will be as when an invalid wastes away.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 10, 19, 'The remnant of the trees of his forest will be so few  
    that a child can write them down.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 10, 20, 'On that day the remnant of Israel and the survivors of the house of Jacob will no more lean on the one who struck them, but will lean on the LORD, the Holy One of Israel, in truth.', 'en', 'NRSV-CE', 'The Repentant Remnant of Israel'),
(23, 'Yes', 'Isaiah', 10, 21, 'A remnant will return, the remnant of Jacob, to the mighty God.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 10, 22, 'For though your people Israel were like the sand of the sea, only a remnant of them will return. Destruction is decreed, overflowing with righteousness.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 10, 23, 'For the Lord God of hosts will make a full end, as decreed, in all the earth.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 10, 24, 'Therefore thus says the Lord God of hosts: O my people, who live in Zion, do not be afraid of the Assyrians when they beat you with a rod and lift up their staff against you as the Egyptians did.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 10, 25, 'For in a very little while my indignation will come to an end, and my anger will be directed to their destruction.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 10, 26, 'The LORD of hosts will wield a whip against them, as when he struck Midian at the rock of Oreb; his staff will be over the sea, and he will lift it as he did in Egypt.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 10, 27, 'On that day his burden will be removed from your shoulder, and his yoke will be destroyed from your neck.
He has gone up from Rimmon,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 10, 28, 'he has come to Aiath;  
he has passed through Migron,  
    at Michmash he stores his baggage;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 10, 29, 'they have crossed over the pass,  
    at Geba they lodge for the night;  
Ramah trembles,  
    Gibeah of Saul has fled.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 10, 30, 'Cry aloud, O daughter Gallim!  
    Listen, O Laishah!  
    Answer her, O Anathoth!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 10, 31, 'Madmenah is in flight,  
    the inhabitants of Gebim flee for safety.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 10, 32, 'This very day he will halt at Nob,  
    he will shake his fist  
    at the mount of daughter Zion,  
    the hill of Jerusalem.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 10, 33, 'Look, the Sovereign, the LORD of hosts,  
    will lop the boughs with terrifying power;  
the tallest trees will be cut down,  
    and the lofty will be brought low.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 10, 34, 'He will hack down the thickets of the forest with an ax,  
    and Lebanon with its majestic trees will fall.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 11, 1, 'A shoot shall come out from the stump of Jesse,  
    and a branch shall grow out of his roots.', 'en', 'NRSV-CE', 'The Peaceful Kingdom'),
(23, 'Yes', 'Isaiah', 11, 2, 'The spirit of the LORD shall rest on him,  
    the spirit of wisdom and understanding,  
    the spirit of counsel and might,  
    the spirit of knowledge and the fear of the LORD.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 11, 3, 'His delight shall be in the fear of the LORD.
He shall not judge by what his eyes see,  
    or decide by what his ears hear;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 11, 4, 'but with righteousness he shall judge the poor,  
    and decide with equity for the meek of the earth;  
he shall strike the earth with the rod of his mouth,  
    and with the breath of his lips he shall kill the wicked.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 11, 5, 'Righteousness shall be the belt around his waist,  
    and faithfulness the belt around his loins.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 11, 6, 'The wolf shall live with the lamb,  
    the leopard shall lie down with the kid,  
the calf and the lion and the fatling together,  
    and a little child shall lead them.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 11, 7, 'The cow and the bear shall graze,  
    their young shall lie down together;  
    and the lion shall eat straw like the ox.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 11, 8, 'The nursing child shall play over the hole of the asp,  
    and the weaned child shall put its hand on the adder"s den.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 11, 9, 'They will not hurt or destroy  
    on all my holy mountain;  
for the earth will be full of the knowledge of the LORD  
    as the waters cover the sea.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 11, 10, 'On that day the root of Jesse shall stand as a signal to the peoples; the nations shall inquire of him, and his dwelling shall be glorious.', 'en', 'NRSV-CE', 'Return of the Remnant of Israel and Judah'),
(23, 'Yes', 'Isaiah', 11, 11, 'On that day the Lord will extend his hand yet a second time to recover the remnant that is left of his people, from Assyria, from Egypt, from Pathros, from Ethiopia, from Elam, from Shinar, from Hamath, and from the coastlands of the sea.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 11, 12, 'He will raise a signal for the nations,  
    and will assemble the outcasts of Israel,  
and gather the dispersed of Judah  
    from the four corners of the earth.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 11, 13, 'The jealousy of Ephraim shall depart,  
    the hostility of Judah shall be cut off;  
Ephraim shall not be jealous of Judah,  
    and Judah shall not be hostile towards Ephraim.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 11, 14, 'But they shall swoop down on the backs of the Philistines in the west,  
    together they shall plunder the people of the east.  
They shall put forth their hand against Edom and Moab,  
    and the Ammonites shall obey them.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 11, 15, 'And the LORD will utterly destroy  
    the tongue of the sea of Egypt;  
and will wave his hand over the River  
    with his scorching wind;  
and will split it into seven channels,  
    and make a way to cross on foot;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 11, 16, 'so there shall be a highway from Assyria  
    for the remnant that is left of his people,  
as there was for Israel  
    when they came up from the land of Egypt.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 12, 1, 'You will say in that day:  
I will give thanks to you, O LORD,  
    for though you were angry with me,  
your anger turned away,  
    and you comforted me.', 'en', 'NRSV-CE', 'Thanksgiving and Praise'),
(23, 'Yes', 'Isaiah', 12, 2, 'Surely God is my salvation;  
    I will trust, and will not be afraid,  
for the Lord God is my strength and my might;  
    he has become my salvation.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 12, 3, 'With joy you will draw water from the wells of salvation.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 12, 4, 'And you will say in that day:
Give thanks to the LORD,  
    call on his name;  
make known his deeds among the nations;  
    proclaim that his name is exalted.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 12, 5, 'Sing praises to the LORD, for he has done gloriously;  
    let this be known in all the earth.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 12, 6, 'Shout aloud and sing for joy, O royal Zion,  
    for great in your midst is the Holy One of Israel.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 13, 1, 'The oracle concerning Babylon that Isaiah son of Amoz saw.', 'en', 'NRSV-CE', 'Proclamation against Babylon'),
(23, 'Yes', 'Isaiah', 13, 2, 'On a bare hill raise a signal,  
    cry aloud to them;  
wave the hand for them to enter  
    the gates of the nobles.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 13, 3, 'I myself have commanded my consecrated ones,  
    have summoned my warriors, my proudly exulting ones,  
    to execute my anger.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 13, 4, 'Listen, a tumult on the mountains  
    as of a great multitude!  
Listen, an uproar of kingdoms,  
    of nations gathering together!  
The LORD of hosts is mustering  
    an army for battle.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 13, 5, 'They come from a distant land,  
    from the end of the heavens,  
the LORD and the weapons of his indignation,  
    to destroy the whole earth.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 13, 6, 'Wail, for the day of the LORD is near;  
    it will come like destruction from the Almighty!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 13, 7, 'Therefore all hands will be feeble,  
    and every human heart will melt,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 13, 8, 'and they will be dismayed.  
Pangs and agony will seize them;  
    they will be in anguish like a woman in labor.  
They will look aghast at one another;  
    their faces will be aflame.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 13, 9, 'See, the day of the LORD comes,  
    cruel, with wrath and fierce anger,  
to make the earth a desolation,  
    and to destroy its sinners from it.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 13, 10, 'For the stars of the heavens and their constellations  
    will not give their light;  
the sun will be dark at its rising,  
    and the moon will not shed its light.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 13, 11, 'I will punish the world for its evil,  
    and the wicked for their iniquity;  
I will put an end to the pride of the arrogant,  
    and lay low the insolence of tyrants.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 13, 12, 'I will make mortals more rare than fine gold,  
    and humans than the gold of Ophir.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 13, 13, 'Therefore I will make the heavens tremble,  
    and the earth will be shaken out of its place,  
at the wrath of the LORD of hosts  
    in the day of his fierce anger.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 13, 14, 'Like a hunted gazelle,  
    or like sheep with no one to gather them,  
all will turn to their own people,  
    and all will flee to their own lands.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 13, 15, 'Whoever is found will be thrust through,  
    and whoever is caught will fall by the sword.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 13, 16, 'Their infants will be dashed to pieces  
    before their eyes;  
their houses will be plundered,  
    and their wives ravished.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 13, 17, 'See, I am stirring up the Medes against them,  
    who have no regard for silver  
    and do not delight in gold.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 13, 18, 'Their bows will slaughter the young men;  
    they will have no mercy on the fruit of the womb;  
    their eyes will not pity children.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 13, 19, 'And Babylon, the glory of kingdoms,  
    the splendor and pride of the Chaldeans,  
will be like Sodom and Gomorrah  
    when God overthrew them.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 13, 20, 'It will never be inhabited  
    or lived in for all generations;  
Arabs will not pitch their tents there,  
    shepherds will not make their flocks lie down there.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 13, 21, 'But wild animals will lie down there,  
    and its houses will be full of howling creatures;  
there ostriches will live,  
    and there goat-demons will dance.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 13, 22, 'Hyenas will cry in its towers,  
    and jackals in the pleasant palaces;  
its time is close at hand,  
    and its days will not be prolonged.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 14, 1, 'But the LORD will have compassion on Jacob and will again choose Israel, and will set them in their own land; and aliens will join them and attach themselves to the house of Jacob.', 'en', 'NRSV-CE', 'Restoration of Judah'),
(23, 'Yes', 'Isaiah', 14, 2, 'And the nations will take them and bring them to their place, and the house of Israel will possess the nations as male and female slaves in the LORD"s land; they will take captive those who were their captors, and rule over those who oppressed them.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 14, 3, 'When the LORD has given you rest from your pain and turmoil and the hard service with which you were made to serve,', 'en', 'NRSV-CE', 'Downfall of the King of Babylon'),
(23, 'Yes', 'Isaiah', 14, 4, 'you will take up this taunt against the king of Babylon:
How the oppressor has ceased!  
    How his insolence has ceased!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 14, 5, 'The LORD has broken the staff of the wicked,  
    the scepter of rulers,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 14, 6, 'that struck down the peoples in wrath  
    with unceasing blows,  
that ruled the nations in anger  
    with unrelenting persecution.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 14, 7, 'The whole earth is at rest and quiet;  
    they break forth into singing.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 14, 8, 'The cypresses exult over you,  
    the cedars of Lebanon, saying,  
"Since you were laid low,  
    no one comes to cut us down."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 14, 9, 'Sheol beneath is stirred up  
    to meet you when you come;  
it rouses the shades to greet you,  
    all who were leaders of the earth;  
it raises from their thrones  
    all who were kings of the nations.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 14, 10, 'All of them will speak  
    and say to you:  
"You too have become as weak as we!  
    You have become like us!"', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 14, 11, 'Your pomp is brought down to Sheol,  
    and the sound of your harps;  
maggots are the bed beneath you,  
    and worms are your covering.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 14, 12, 'How you are fallen from heaven,  
    O Day Star, son of Dawn!  
How you are cut down to the ground,  
    you who laid the nations low!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 14, 13, 'You said in your heart,  
    "I will ascend to heaven;  
I will raise my throne  
    above the stars of God;  
I will sit on the mount of assembly  
    on the heights of Zaphon;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 14, 14, 'I will ascend to the tops of the clouds,  
    I will make myself like the Most High."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 14, 15, 'But you are brought down to Sheol,  
    to the depths of the Pit.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 14, 16, 'Those who see you will stare at you,  
    and ponder over you:  
"Is this the man who made the earth tremble,  
    who shook kingdoms,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 14, 17, 'who made the world like a desert  
    and overthrew its cities,  
    who would not let his prisoners go home?"', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 14, 18, 'All the kings of the nations lie in glory,  
    each in his own tomb;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 14, 19, 'but you are cast out, away from your grave,  
    like loathsome carrion,  
clothed with the dead, those pierced by the sword,  
    who go down to the stones of the Pit,  
    like a corpse trampled underfoot.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 14, 20, 'You will not be joined with them in burial,  
    because you have destroyed your land,  
    you have killed your people.
May the descendants of evildoers  
    nevermore be named!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 14, 21, 'Prepare slaughter for his sons  
    because of the guilt of their father.  
Let them never rise to possess the earth  
    or cover the face of the world with cities.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 14, 22, 'I will rise up against them, says the LORD of hosts, and will cut off from Babylon name and remnant, offspring and posterity, says the LORD.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 14, 23, 'And I will make it a possession of the hedgehog, and pools of water, and I will sweep it with the broom of destruction, says the LORD of hosts.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 14, 24, 'The LORD of hosts has sworn:  
As I have designed,  
    so shall it be;  
and as I have planned,  
    so shall it come to pass:', 'en', 'NRSV-CE', 'An Oracle concerning Assyria'),
(23, 'Yes', 'Isaiah', 14, 25, 'I will break the Assyrian in my land,  
    and on my mountains trample him under foot;  
his yoke shall be removed from them,  
    and his burden from their shoulders.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 14, 26, 'This is the plan that is planned  
    concerning the whole earth;  
and this is the hand that is stretched out  
    over all the nations.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 14, 27, 'For the LORD of hosts has planned,  
    and who will annul it?  
His hand is stretched out,  
    and who will turn it back?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 14, 28, 'In the year that King Ahaz died this oracle came:', 'en', 'NRSV-CE', 'An Oracle concerning Philistia'),
(23, 'Yes', 'Isaiah', 14, 29, 'Do not rejoice, all you Philistines,  
    that the rod that struck you is broken,  
for from the root of the snake will come forth an adder,  
    and its fruit will be a flying fiery serpent.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 14, 30, 'The firstborn of the poor will graze,  
    and the needy lie down in safety;  
but I will make your root die of famine,  
    and your remnant I will kill.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 14, 31, 'Wail, O gate; cry, O city;  
    melt in fear, O Philistia, all of you!  
For smoke comes out of the north,  
    and there is no straggler in its ranks.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 14, 32, 'What will one answer the messengers of the nation?  
"The LORD has founded Zion,  
    and the needy among his people  
    will find refuge in her."', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 15, 1, 'An oracle concerning Moab.
Because Ar is laid waste in a night,  
    Moab is undone;  
because Kir is laid waste in a night,  
    Moab is undone.', 'en', 'NRSV-CE', 'An Oracle concerning Moab'),
(23, 'Yes', 'Isaiah', 15, 2, 'Dibon has gone up to the temple,  
    to the high places to weep;  
over Nebo and over Medeba  
    Moab wails.  
On every head is baldness,  
    every beard is shorn;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 15, 3, 'in the streets they bind on sackcloth;  
    on the housetops and in the squares  
    everyone wails and melts in tears.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 15, 4, 'Heshbon and Elealeh cry out,  
    their voices are heard as far as Jahaz;  
therefore the loins of Moab quiver;  
    his soul trembles.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 15, 5, 'My heart cries out for Moab;  
    his fugitives flee to Zoar,  
    to Eglath-shelishiyah.  
For at the ascent of Luhith  
    they go up weeping;  
on the road to Horonaim  
    they raise a cry of destruction;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 15, 6, 'the waters of Nimrim  
    are a desolation;  
the grass is withered, the new growth fails,  
    the verdure is no more.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 15, 7, 'Therefore the abundance they have gained  
    and what they have laid up  
they carry away  
    over the Wadi of the Willows.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 15, 8, 'For a cry has gone  
    around the land of Moab;  
the wailing reaches to Eglaim,  
    the wailing reaches to Beer-elim.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 15, 9, 'For the waters of Dibon are full of blood;  
    yet I will bring upon Dibon even more--  
a lion for those of Moab who escape,  
    for the remnant of the land.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 16, 1, 'Send lambs  
    to the ruler of the land,  
from Sela, by way of the desert,  
    to the mount of daughter Zion.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 16, 2, 'Like fluttering birds,  
    like scattered nestlings,  
so are the daughters of Moab  
    at the fords of the Arnon.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 16, 3, '"Give counsel,  
    grant justice;  
make your shade like night  
    at the height of noon;  
hide the outcasts,  
    do not betray the fugitive;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 16, 4, 'let the outcasts of Moab  
    settle among you;  
be a refuge to them  
    from the destroyer."
When the oppressor is no more,  
    and destruction has ceased,  
and marauders have vanished from the land,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 16, 5, 'then a throne shall be established in steadfast love  
    in the tent of David,  
    and on it shall sit in faithfulness  
a ruler who seeks justice  
    and is swift to do what is right.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 16, 6, 'We have heard of the pride of Moab  
    --how proud he is!--  
of his arrogance, his pride, and his insolence;  
    his boasts are false.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 16, 7, 'Therefore let Moab wail,  
    let everyone wail for Moab.  
Mourn, utterly stricken,  
    for the raisin cakes of Kir-hareseth.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 16, 8, 'For the fields of Heshbon languish,  
    and the vines of Sibmah,  
whose clusters once made drunk  
    the lords of the nations,  
reached to Jazer  
    and strayed to the desert;  
their shoots once spread abroad  
    and crossed over the sea.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 16, 9, 'Therefore I weep with the weeping of Jazer  
    for the vines of Sibmah;  
I drench you with my tears,  
    O Heshbon and Elealeh;  
for the shout over your fruit harvest  
    and your grain harvest has ceased.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 16, 10, 'Joy and gladness are taken away  
    from the fruitful field;  
and in the vineyards no songs are sung,  
    no shouts are raised;  
no treader treads out wine in the presses;  
    the vintage-shout is hushed.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 16, 11, 'Therefore my heart throbs like a harp for Moab,  
    and my very soul for Kir-heres.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 16, 12, 'When Moab presents himself, when he wearies himself upon the high place, when he comes to his sanctuary to pray, he will not prevail.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 16, 13, 'This was the word that the LORD spoke concerning Moab in the past.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 16, 14, 'But now the LORD says, In three years, like the years of a hired worker, the glory of Moab will be brought into contempt, in spite of all its great multitude; and those who survive will be very few and feeble.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 17, 1, 'An oracle concerning Damascus.
See, Damascus will cease to be a city,  
    and will become a heap of ruins.', 'en', 'NRSV-CE', 'An Oracle concerning Damascus'),
(23, 'Yes', 'Isaiah', 17, 2, 'Her towns will be deserted forever;  
    they will be places for flocks,  
    which will lie down, and no one will make them afraid.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 17, 3, 'The fortress will disappear from Ephraim,  
    and the kingdom from Damascus;  
and the remnant of Aram will be  
    like the glory of the children of Israel,  
says the LORD of hosts.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 17, 4, 'On that day  
    the glory of Jacob will be brought low,  
    and the fat of his flesh will grow lean.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 17, 5, 'And it shall be as when reapers gather standing grain  
    and their arms harvest the ears,  
and as when one gleans the ears of grain  
    in the Valley of Rephaim.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 17, 6, 'Gleanings will be left in it,  
    as when an olive tree is beaten--  
two or three berries  
    in the top of the highest bough,  
four or five  
    on the branches of a fruit tree,  
says the LORD God of Israel.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 17, 7, 'On that day people will regard their Maker, and their eyes will look to the Holy One of Israel;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 17, 8, 'they will not have regard for the altars, the work of their hands, and they will not look to what their own fingers have made, either the sacred poles or the altars of incense.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 17, 9, 'On that day their strong cities will be like the deserted places of the Hivites and the Amorites, which they deserted because of the children of Israel, and there will be desolation.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 17, 10, 'For you have forgotten the God of your salvation,  
    and have not remembered the Rock of your refuge;  
therefore, though you plant pleasant plants  
    and set out slips of an alien god,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 17, 11, 'though you make them grow on the day that you plant them,  
    and make them blossom in the morning that you sow;  
yet the harvest will flee away  
    in a day of grief and incurable pain.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 17, 12, 'Ah, the thunder of many peoples,  
    they thunder like the thundering of the sea!  
Ah, the roar of nations,  
    they roar like the roaring of mighty waters!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 17, 13, 'The nations roar like the roaring of many waters,  
    but he will rebuke them, and they will flee far away,  
chased like chaff on the mountains before the wind  
    and whirling dust before the storm.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 17, 14, 'At evening time, lo, terror!  
    Before morning, they are no more.  
This is the fate of those who despoil us,  
    and the lot of those who plunder us.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 18, 1, 'Ah, land of whirring wings  
    beyond the rivers of Ethiopia,', 'en', 'NRSV-CE', 'An Oracle concerning Ethiopia'),
(23, 'Yes', 'Isaiah', 18, 2, 'sending ambassadors by the Nile  
    in vessels of papyrus on the waters!  
Go, you swift messengers,  
    to a nation tall and smooth,  
to a people feared near and far,  
    a nation mighty and conquering,  
    whose land the rivers divide.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 18, 3, 'All you inhabitants of the world,  
    you who live on the earth,  
when a signal is raised on the mountains, look!  
    When a trumpet is blown, listen!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 18, 4, 'For thus the LORD said to me:  
I will quietly look from my dwelling  
    like clear heat in sunshine,  
    like a cloud of dew in the heat of harvest.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 18, 5, 'For before the harvest, when the blossom is over  
    and the flower becomes a ripening grape,  
he will cut off the shoots with pruning hooks,  
    and the spreading branches he will hew away.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 18, 6, 'They shall all be left  
    to the birds of prey of the mountains  
    and to the animals of the earth.  
And the birds of prey will summer on them,  
    and all the animals of the earth will winter on them.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 18, 7, 'At that time gifts will be brought to the LORD of hosts from a people tall and smooth, from a people feared near and far, a nation mighty and conquering, whose land the rivers divide, to Mount Zion, the place of the name of the LORD of hosts.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 19, 1, 'An oracle concerning Egypt.
See, the LORD is riding on a swift cloud  
    and comes to Egypt;  
the idols of Egypt will tremble at his presence,  
    and the heart of the Egyptians will melt within them.', 'en', 'NRSV-CE', 'An Oracle concerning Egypt'),
(23, 'Yes', 'Isaiah', 19, 2, 'I will stir up Egyptians against Egyptians,  
    and they will fight, one against the other,  
    neighbor against neighbor,  
    city against city, kingdom against kingdom;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 19, 3, 'the spirit of the Egyptians within them will be emptied out,  
    and I will confound their plans;  
they will consult the idols and the spirits of the dead  
    and the ghosts and the familiar spirits;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 19, 4, 'I will deliver the Egyptians  
    into the hand of a hard master;  
a fierce king will rule over them,  
    says the Sovereign, the LORD of hosts.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 19, 5, 'The waters of the Nile will be dried up,  
    and the river will be parched and dry;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 19, 6, 'its canals will become foul,  
    and the branches of Egypt"s Nile will diminish and dry up,  
    reeds and rushes will rot away.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 19, 7, 'There will be bare places by the Nile,  
    on the brink of the Nile;  
and all that is sown by the Nile will dry up,  
    be driven away, and be no more.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 19, 8, 'Those who fish will mourn;  
    all who cast hooks in the Nile will lament,  
    and those who spread nets on the water will languish.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 19, 9, 'The workers in flax will be in despair,  
    and the carders and those at the loom will grow pale.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 19, 10, 'Its weavers will be dismayed,  
    and all who work for wages will be grieved.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 19, 11, 'The princes of Zoan are utterly foolish;  
    the wise counselors of Pharaoh give stupid counsel.  
How can you say to Pharaoh,  
    "I am one of the sages,  
    a descendant of ancient kings"?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 19, 12, 'Where now are your sages?  
    Let them tell you and make known  
    what the LORD of hosts has planned against Egypt.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 19, 13, 'The princes of Zoan have become fools,  
    and the princes of Memphis are deluded;  
those who are the cornerstones of its tribes  
    have led Egypt astray.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 19, 14, 'The LORD has poured into them  
    a spirit of confusion;  
and they have made Egypt stagger in all its doings  
    as a drunkard staggers around in vomit.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 19, 15, 'Neither head nor tail, palm branch or reed,  
    will be able to do anything for Egypt.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 19, 16, 'On that day the Egyptians will be like women, and tremble with fear before the hand that the LORD of hosts raises against them.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 19, 17, 'And the land of Judah will become a terror to the Egyptians; everyone to whom it is mentioned will fear because of the plan that the LORD of hosts is planning against them.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 19, 18, 'On that day there will be five cities in the land of Egypt that speak the language of Canaan and swear allegiance to the LORD of hosts. One of these will be called the City of the Sun.', 'en', 'NRSV-CE', 'Egypt, Assyria, and Israel Blessed'),
(23, 'Yes', 'Isaiah', 19, 19, 'On that day there will be an altar to the LORD in the center of the land of Egypt, and a pillar to the LORD at its border.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 19, 20, 'It will be a sign and a witness to the LORD of hosts in the land of Egypt; when they cry to the LORD because of oppressors, he will send them a savior, and will defend and deliver them.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 19, 21, 'The LORD will make himself known to the Egyptians; and the Egyptians will know the LORD on that day, and will worship with sacrifice and burnt offering, and they will make vows to the LORD and perform them.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 19, 22, 'The LORD will strike Egypt, striking and healing; they will return to the LORD, and he will listen to their supplications and heal them.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 19, 23, 'On that day there will be a highway from Egypt to Assyria, and the Assyrian will come into Egypt, and the Egyptian into Assyria, and the Egyptians will worship with the Assyrians.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 19, 24, 'On that day Israel will be the third with Egypt and Assyria, a blessing in the midst of the earth,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 19, 25, 'whom the LORD of hosts has blessed, saying, "Blessed be Egypt my people, and Assyria the work of my hands, and Israel my heritage."', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 20, 1, 'In the year that the commander-in-chief, who was sent by King Sargon of Assyria, came to Ashdod and fought against it and took it--', 'en', 'NRSV-CE', 'Isaiah Dramatizes the Conquest of Egypt and Ethiopia'),
(23, 'Yes', 'Isaiah', 20, 2, 'at that time the LORD had spoken to Isaiah son of Amoz, saying, "Go, and loose the sackcloth from your loins and take your sandals off your feet," and he had done so, walking naked and barefoot.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 20, 3, 'Then the LORD said, "Just as my servant Isaiah has walked naked and barefoot for three years as a sign and a portent against Egypt and Ethiopia,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 20, 4, 'so shall the king of Assyria lead away the Egyptians as captives and the Ethiopians as exiles, both the young and the old, naked and barefoot, with buttocks uncovered, to the shame of Egypt.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 20, 5, 'And they shall be dismayed and confounded because of Ethiopia their hope and of Egypt their boast.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 20, 6, 'In that day the inhabitants of this coastland will say, "See, this is what has happened to those in whom we hoped and to whom we fled for help and deliverance from the king of Assyria! And we, how shall we escape?""', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 21, 1, 'The oracle concerning the wilderness of the sea.
As whirlwinds in the Negeb sweep on,  
    it comes from the desert,  
    from a terrible land.', 'en', 'NRSV-CE', 'Oracles concerning Babylon, Edom, and Arabia'),
(23, 'Yes', 'Isaiah', 21, 2, 'A stern vision is told to me;  
    the betrayer betrays,  
    and the destroyer destroys.  
Go up, O Elam,  
    lay siege, O Media;  
all the sighing she has caused  
    I bring to an end.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 21, 3, 'Therefore my loins are filled with anguish;  
    pangs have seized me,  
    like the pangs of a woman in labor;  
I am bowed down so that I cannot hear,  
    I am dismayed so that I cannot see.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 21, 4, 'My mind reels, horror has appalled me;  
    the twilight I longed for  
    has been turned for me into trembling.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 21, 5, 'They prepare the table,  
    they spread the rugs,  
    they eat, they drink.  
Rise up, commanders,  
    oil the shield!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 21, 6, 'For thus the Lord said to me:  
"Go, post a lookout,  
    let him announce what he sees.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 21, 7, 'When he sees riders, horsemen in pairs,  
    riders on donkeys, riders on camels,  
let him listen diligently,  
    very diligently."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 21, 8, 'Then the watcher called out:  
"Upon a watchtower I stand, O Lord,  
    continually by day,  
and at my post I am stationed  
    throughout the night.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 21, 9, 'Look, there they come, riders,  
    horsemen in pairs!"  
Then he responded,  
    "Fallen, fallen is Babylon;  
and all the images of her gods  
    lie shattered on the ground."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 21, 10, 'O my threshed and winnowed one,  
    what I have heard from the LORD of hosts,  
    the God of Israel, I announce to you.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 21, 11, 'The oracle concerning Dumah.
One is calling to me from Seir,  
    "Sentinel, what of the night?  
    Sentinel, what of the night?"', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 21, 12, 'The sentinel says:  
"Morning comes, and also the night.  
    If you will inquire, inquire;  
    come back again."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 21, 13, 'The oracle concerning the desert plain.
In the scrub of the desert plain you will lodge,  
    O caravans of Dedanites.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 21, 14, 'Bring water to the thirsty,  
    meet the fugitive with bread,  
    O inhabitants of the land of Tema.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 21, 15, 'For they have fled from the swords,  
    from the drawn sword,  
from the bent bow,  
    and from the stress of battle.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 21, 16, 'For thus the Lord said to me: Within a year, according to the years of a hired worker, all the glory of Kedar will come to an end;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 21, 17, 'and the remaining bows of Kedar"s warriors will be few; for the LORD, the God of Israel, has spoken.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 22, 1, 'The oracle concerning the valley of vision.
What do you mean that you have gone up,  
    all of you, to the housetops,', 'en', 'NRSV-CE', 'A Warning of Destruction of Jerusalem'),
(23, 'Yes', 'Isaiah', 22, 2, 'you that are full of shoutings,  
    tumultuous city, exultant town?  
Your slain are not slain by the sword,  
    nor are they dead in battle.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 22, 3, 'Your rulers have all fled together;  
    they were captured without the use of a bow.  
All of you who were found were captured,  
    though they had fled far away.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 22, 4, 'Therefore I said:  
Look away from me,  
    let me weep bitter tears;  
do not try to comfort me  
    for the destruction of my beloved people.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 22, 5, 'For the Lord God of hosts has a day  
    of tumult and trampling and confusion  
    in the valley of vision,  
a battering down of walls  
    and a cry for help to the mountains.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 22, 6, 'Elam bore the quiver  
    with chariots and cavalry,  
    and Kir uncovered the shield.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 22, 7, 'Your choicest valleys were full of chariots,  
    and the cavalry took their stand at the gates.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 22, 8, 'He has taken away the covering of Judah.
On that day you looked to the weapons of the House of the Forest,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 22, 9, 'and you saw that there were many breaches in the city of David, and you collected the waters of the lower pool.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 22, 10, 'You counted the houses of Jerusalem, and you broke down the houses to fortify the wall.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 22, 11, 'You made a reservoir between the two walls for the water of the old pool. But you did not look to him who did it, or have regard for him who planned it long ago.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 22, 12, 'In that day the Lord God of hosts  
    called to weeping and mourning,  
    to baldness and putting on sackcloth;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 22, 13, 'but instead there was joy and festivity,  
    killing oxen and slaughtering sheep,  
    eating meat and drinking wine.  
"Let us eat and drink,  
    for tomorrow we die."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 22, 14, 'The LORD of hosts has revealed himself in my ears:  
Surely this iniquity will not be forgiven you until you die,  
    says the Lord God of hosts.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 22, 15, 'Thus says the Lord God of hosts: Come, go to this steward, to Shebna, who is master of the household, and say to him:', 'en', 'NRSV-CE', 'Denunciation of Self-Seeking Officials'),
(23, 'Yes', 'Isaiah', 22, 16, 'What right do you have here? Who are your relatives here, that you have cut out a tomb here for yourself, cutting a tomb on the height, and carving a habitation for yourself in the rock?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 22, 17, 'The LORD is about to hurl you away violently, my fellow. He will seize firm hold on you,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 22, 18, 'whirl you round and round, and throw you like a ball into a wide land; there you shall die, and there your splendid chariots shall lie, O you disgrace to your master"s house!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 22, 19, 'I will thrust you from your office, and you will be pulled down from your post.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 22, 20, 'On that day I will call my servant Eliakim son of Hilkiah,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 22, 21, 'and will clothe him with your robe and bind your sash on him. I will commit your authority to his hand, and he shall be a father to the inhabitants of Jerusalem and to the house of Judah.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 22, 22, 'I will place on his shoulder the key of the house of David; he shall open, and no one shall shut; he shall shut, and no one shall open.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 22, 23, 'I will fasten him like a peg in a secure place, and he will become a throne of honor to his ancestral house.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 22, 24, 'And they will hang on him the whole weight of his ancestral house, the offspring and issue, every small vessel, from the cups to all the flagons.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 22, 25, 'On that day, says the LORD of hosts, the peg that was fastened in a secure place will give way; it will be cut down and fall, and the load that was on it will perish, for the LORD has spoken.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 23, 1, 'The oracle concerning Tyre.
Wail, O ships of Tarshish,  
    for your fortress is destroyed.  
When they came in from Cyprus  
    they learned of it.', 'en', 'NRSV-CE', 'An Oracle concerning Tyre'),
(23, 'Yes', 'Isaiah', 23, 2, 'Be still, O inhabitants of the coast,  
    O merchants of Sidon,  
your messengers crossed over the sea', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 23, 3, 'and were on the mighty waters;  
your revenue was the grain of Shihor,  
    the harvest of the Nile;  
    you were the merchant of the nations.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 23, 4, 'Be ashamed, O Sidon, for the sea has spoken,  
    the fortress of the sea, saying:  
"I have neither labored nor given birth,  
    I have neither reared young men  
    nor brought up young women."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 23, 5, 'When the report comes to Egypt,  
    they will be in anguish over the report about Tyre.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 23, 6, 'Cross over to Tarshish--  
    wail, O inhabitants of the coast!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 23, 7, 'Is this your exultant city  
    whose origin is from days of old,  
whose feet carried her  
    to settle far away?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 23, 8, 'Who has planned this  
    against Tyre, the bestower of crowns,  
whose merchants were princes,  
    whose traders were the honored of the earth?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 23, 9, 'The LORD of hosts has planned it--  
    to defile the pride of all glory,  
    to shame all the honored of the earth.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 23, 10, 'Cross over to your own land,  
    O ships of Tarshish;  
    this is a harbor no more.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 23, 11, 'He has stretched out his hand over the sea,  
    he has shaken the kingdoms;  
the LORD has given command concerning Canaan  
    to destroy its fortresses.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 23, 12, 'He said:  
You will exult no longer,  
    O oppressed virgin daughter Sidon;  
rise, cross over to Cyprus--  
    even there you will have no rest.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 23, 13, 'Look at the land of the Chaldeans! This is the people; it was not Assyria. They destined Tyre for wild animals. They erected their siege towers, they tore down her palaces, they made her a ruin.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 23, 14, 'Wail, O ships of Tarshish,  
    for your fortress is destroyed.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 23, 15, 'From that day Tyre will be forgotten for seventy years, the lifetime of one king. At the end of seventy years, it will happen to Tyre as in the song about the prostitute:', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 23, 16, 'Take a harp,  
    go about the city,  
    you forgotten prostitute!  
Make sweet melody,  
    sing many songs,  
    that you may be remembered.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 23, 17, 'At the end of seventy years, the LORD will visit Tyre, and she will return to her trade, and will prostitute herself with all the kingdoms of the world on the face of the earth.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 23, 18, 'Her merchandise and her wages will be dedicated to the LORD; her profits will not be stored or hoarded, but her merchandise will supply abundant food and fine clothing for those who live in the presence of the LORD.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 24, 1, 'Now the LORD is about to lay waste the earth and make it desolate,  
    and he will twist its surface and scatter its inhabitants.', 'en', 'NRSV-CE', 'Impending Judgment on the Earth'),
(23, 'Yes', 'Isaiah', 24, 2, 'And it shall be, as with the people, so with the priest;  
    as with the slave, so with his master;  
    as with the maid, so with her mistress;  
as with the buyer, so with the seller;  
    as with the lender, so with the borrower;  
    as with the creditor, so with the debtor.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 24, 3, 'The earth shall be utterly laid waste and utterly despoiled;  
    for the LORD has spoken this word.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 24, 4, 'The earth dries up and withers,  
    the world languishes and withers;  
    the heavens languish together with the earth.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 24, 5, 'The earth lies polluted  
    under its inhabitants;  
for they have transgressed laws,  
    violated the statutes,  
    broken the everlasting covenant.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 24, 6, 'Therefore a curse devours the earth,  
    and its inhabitants suffer for their guilt;  
therefore the inhabitants of the earth dwindled,  
    and few people are left.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 24, 7, 'The wine dries up,  
    the vine languishes,  
    all the merry-hearted sigh.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 24, 8, 'The mirth of the timbrels is stilled,  
    the noise of the jubilant has ceased,  
    the mirth of the lyre is stilled.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 24, 9, 'No longer do they drink wine with singing;  
    strong drink is bitter to those who drink it.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 24, 10, 'The city of chaos is broken down,  
    every house is shut up so that no one can enter.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 24, 11, 'There is an outcry in the streets for lack of wine;  
    all joy has reached its eventide;  
    the gladness of the earth is banished.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 24, 12, 'Desolation is left in the city,  
    the gates are battered into ruins.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 24, 13, 'For thus it shall be on the earth  
    and among the nations,  
as when an olive tree is beaten,  
    as at the gleaning when the grape harvest is ended.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 24, 14, 'They lift up their voices, they sing for joy;  
    they shout from the west over the majesty of the LORD.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 24, 15, 'Therefore in the east give glory to the LORD;  
    in the coastlands of the sea glorify the name of the LORD, the God of Israel.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 24, 16, 'From the ends of the earth we hear songs of praise,  
    of glory to the Righteous One.  
But I say, I pine away,  
    I pine away. Woe is me!  
For the treacherous deal treacherously,  
    the treacherous deal very treacherously.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 24, 17, 'Terror, and the pit, and the snare  
    are upon you, O inhabitant of the earth!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 24, 18, 'Whoever flees at the sound of the terror  
    shall fall into the pit;  
and whoever climbs out of the pit  
    shall be caught in the snare.  
For the windows of heaven are opened,  
    and the foundations of the earth tremble.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 24, 19, 'The earth is utterly broken,  
    the earth is torn asunder,  
    the earth is violently shaken.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 24, 20, 'The earth staggers like a drunkard,  
    it sways like a hut;  
its transgression lies heavy upon it,  
    and it falls, and will not rise again.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 24, 21, 'On that day the LORD will punish  
    the host of heaven in heaven,  
    and on earth the kings of the earth.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 24, 22, 'They will be gathered together  
    like prisoners in a pit;  
they will be shut up in a prison,  
    and after many days they will be punished.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 24, 23, 'Then the moon will be abashed,  
    and the sun ashamed;  
for the LORD of hosts will reign  
    on Mount Zion and in Jerusalem,  
and before his elders he will manifest his glory.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 25, 1, 'O LORD, you are my God;  
    I will exalt you, I will praise your name;  
for you have done wonderful things,  
    plans formed of old, faithful and sure.', 'en', 'NRSV-CE', 'Praise for Deliverance from Oppression'),
(23, 'Yes', 'Isaiah', 25, 2, 'For you have made the city a heap,  
    the fortified city a ruin;  
the palace of aliens is a city no more,  
    it will never be rebuilt.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 25, 3, 'Therefore strong peoples will glorify you;  
    cities of ruthless nations will fear you.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 25, 4, 'For you have been a refuge to the poor,  
    a refuge to the needy in their distress,  
    a shelter from the rainstorm and a shade from the heat.  
When the blast of the ruthless was like a winter rainstorm,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 25, 5, 'the noise of aliens like heat in a dry place,  
you subdued the heat with the shade of clouds;  
    the song of the ruthless was stilled.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 25, 6, 'On this mountain the LORD of hosts will make for all peoples  
    a feast of rich food, a feast of well-aged wines,  
    of rich food filled with marrow, of well-aged wines strained clear.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 25, 7, 'And he will destroy on this mountain  
    the shroud that is cast over all peoples,  
    the sheet that is spread over all nations;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 25, 8, 'he will swallow up death forever.  
Then the Lord God will wipe away the tears from all faces,  
    and the disgrace of his people he will take away from all the earth,  
    for the LORD has spoken.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 25, 9, 'It will be said on that day,  
    Lo, this is our God; we have waited for him, so that he might save us.  
    This is the LORD for whom we have waited;  
    let us be glad and rejoice in his salvation.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 25, 10, 'For the hand of the LORD will rest on this mountain.
The Moabites shall be trodden down in their place  
    as straw is trodden down in a dung-pit.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 25, 11, 'Though they spread out their hands in the midst of it,  
    as swimmers spread out their hands to swim,  
    their pride will be laid low despite the struggle of their hands.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 25, 12, 'The high fortifications of his walls will be brought down,  
    laid low, cast to the ground, even to the dust.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 26, 1, 'On that day this song will be sung in the land of Judah:  
We have a strong city;  
    he sets up victory  
    like walls and bulwarks.', 'en', 'NRSV-CE', 'Judah"s Song of Victory'),
(23, 'Yes', 'Isaiah', 26, 2, 'Open the gates,  
    so that the righteous nation that keeps faith  
    may enter in.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 26, 3, 'Those of steadfast mind you keep in peace--  
    in peace because they trust in you.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 26, 4, 'Trust in the LORD forever,  
    for in the Lord God  
    you have an everlasting rock.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 26, 5, 'For he has brought low  
    the inhabitants of the height;  
    the lofty city he lays low.  
He lays it low to the ground,  
    casts it to the dust.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 26, 6, 'The foot tramples it,  
    the feet of the poor,  
    the steps of the needy.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 26, 7, 'The way of the righteous is level;  
    O Just One, you make smooth the path of the righteous.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 26, 8, 'In the path of your judgments,  
    O LORD, we wait for you;  
your name and your renown  
    are the soul"s desire.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 26, 9, 'My soul yearns for you in the night,  
    my spirit within me earnestly seeks you.  
For when your judgments are in the earth,  
    the inhabitants of the world learn righteousness.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 26, 10, 'If favor is shown to the wicked,  
    they do not learn righteousness;  
in the land of uprightness they deal perversely  
    and do not see the majesty of the LORD.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 26, 11, 'O LORD, your hand is lifted up,  
    but they do not see it.  
Let them see your zeal for your people, and be ashamed.  
    Let the fire for your adversaries consume them.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 26, 12, 'O LORD, you will ordain peace for us,  
    for indeed, all that we have done, you have done for us.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 26, 13, 'O LORD our God,  
    other lords besides you have ruled over us,  
    but we acknowledge your name alone.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 26, 14, 'The dead do not live;  
    shades do not rise--  
because you have punished and destroyed them,  
    and wiped out all memory of them.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 26, 15, 'But you have increased the nation, O LORD,  
    you have increased the nation; you are glorified;  
    you have enlarged all the borders of the land.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 26, 16, 'O LORD, in distress they sought you,  
    they poured out a prayer  
    when your chastening was on them.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 26, 17, 'Like a woman with child,  
    who writhes and cries out in her pangs  
    when she is near her time,  
so were we because of you, O LORD;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 26, 18, 'we were with child, we writhed,  
    but we gave birth only to wind.  
We have won no victories on earth,  
    and no one is born to inhabit the world.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 26, 19, 'Your dead shall live, their corpses shall rise.  
    O dwellers in the dust, awake and sing for joy!  
For your dew is a radiant dew,  
    and the earth will give birth to those long dead.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 26, 20, 'Come, my people, enter your chambers,  
    and shut your doors behind you;  
hide yourselves for a little while  
    until the wrath is past.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 26, 21, 'For the LORD comes out from his place  
    to punish the inhabitants of the earth for their iniquity;  
the earth will disclose the blood shed on it,  
    and will no longer cover its slain.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 27, 1, 'On that day the LORD with his cruel and great and strong sword will punish Leviathan the fleeing serpent, Leviathan the twisting serpent, and he will kill the dragon that is in the sea.', 'en', 'NRSV-CE', 'Israel"s Redemption'),
(23, 'Yes', 'Isaiah', 27, 2, 'On that day:  
A pleasant vineyard, sing about it!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 27, 3, 'I, the LORD, am its keeper;  
    every moment I water it.  
I guard it night and day  
    so that no one can harm it;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 27, 4, 'I have no wrath.  
If it gives me thorns and briers,  
    I will march to battle against it.  
    I will burn it up.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 27, 5, 'Or else let it cling to me for protection,  
    let it make peace with me,  
    let it make peace with me.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 27, 6, 'In days to come Jacob shall take root,  
    Israel shall blossom and put forth shoots,  
    and fill the whole world with fruit.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 27, 7, 'Has he struck them down as he struck down those who struck them?  
    Or have they been killed as their killers were killed?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 27, 8, 'By expulsion, by exile you struggled against them;  
    with his fierce blast he removed them in the day of the east wind.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 27, 9, 'Therefore by this the guilt of Jacob will be expiated,  
    and this will be the full fruit of the removal of his sin:  
when he makes all the stones of the altars  
    like chalkstones crushed to pieces,  
    no sacred poles or incense altars will remain standing.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 27, 10, 'For the fortified city is solitary,  
    a habitation deserted and forsaken, like the wilderness;  
the calves graze there,  
    there they lie down, and strip its branches.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 27, 11, 'When its boughs are dry, they are broken;  
    women come and make a fire of them.  
For this is a people without understanding;  
    therefore he that made them will not have compassion on them,  
    he that formed them will show them no favor.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 27, 12, 'On that day the LORD will thresh from the channel of the Euphrates to the Wadi of Egypt, and you will be gathered one by one, O people of Israel.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 27, 13, 'And on that day a great trumpet will be blown, and those who were lost in the land of Assyria and those who were driven out to the land of Egypt will come and worship the LORD on the holy mountain at Jerusalem.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 28, 1, 'Ah, the proud garland of the drunkards of Ephraim,  
    and the fading flower of its glorious beauty,  
    which is on the head of those bloated with rich food, of those overcome with wine!', 'en', 'NRSV-CE', 'Judgment on Corrupt Rulers, Priests, and Prophets'),
(23, 'Yes', 'Isaiah', 28, 2, 'See, the Lord has one who is mighty and strong;  
    like a storm of hail, a destroying tempest,  
like a storm of mighty, overflowing waters;  
    with his hand he will hurl them down to the earth.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 28, 3, 'Trampled under foot will be  
    the proud garland of the drunkards of Ephraim.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 28, 4, 'And the fading flower of its glorious beauty,  
    which is on the head of those bloated with rich food,  
will be like a first-ripe fig before the summer;  
    whoever sees it, eats it up  
    as soon as it comes to hand.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 28, 5, 'In that day the LORD of hosts will be a garland of glory,  
    and a diadem of beauty, to the remnant of his people;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 28, 6, 'and a spirit of justice to the one who sits in judgment,  
    and strength to those who turn back the battle at the gate.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 28, 7, 'These also reel with wine  
    and stagger with strong drink;  
the priest and the prophet reel with strong drink,  
    they are confused with wine,  
    they stagger with strong drink;  
they err in vision,  
    they stumble in giving judgment.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 28, 8, 'All tables are covered with filthy vomit;  
    no place is clean.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 28, 9, '"Whom will he teach knowledge,  
    and to whom will he explain the message?  
Those who are weaned from milk,  
    those taken from the breast?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 28, 10, 'For it is precept upon precept, precept upon precept,  
    line upon line, line upon line,  
    here a little, there a little."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 28, 11, 'Truly, with stammering lip  
    and with alien tongue  
he will speak to this people,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 28, 12, 'to whom he has said,  
"This is rest;  
    give rest to the weary;  
and this is repose";  
    yet they would not hear.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 28, 13, 'Therefore the word of the LORD will be to them,  
    "Precept upon precept, precept upon precept,  
    line upon line, line upon line,  
    here a little, there a little;"  
in order that they may go, and fall backward,  
    and be broken, and snared, and taken.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 28, 14, 'Therefore hear the word of the LORD, you scoffers  
    who rule this people in Jerusalem.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 28, 15, 'Because you have said, "We have made a covenant with death,  
    and with Sheol we have an agreement;  
when the overwhelming scourge passes through  
    it will not come to us;  
for we have made lies our refuge,  
    and in falsehood we have taken shelter";', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 28, 16, 'therefore thus says the Lord God,  
See, I am laying in Zion a foundation stone,  
    a tested stone,  
a precious cornerstone, a sure foundation:  
    "One who trusts will not panic."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 28, 17, 'And I will make justice the line,  
    and righteousness the plummet;  
hail will sweep away the refuge of lies,  
    and waters will overwhelm the shelter.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 28, 18, 'Then your covenant with death will be annulled,  
    and your agreement with Sheol will not stand;  
when the overwhelming scourge passes through  
    you will be beaten down by it.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 28, 19, 'As often as it passes through, it will take you;  
    for morning by morning it will pass through,  
    by day and by night;  
and it will be sheer terror to understand the message.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 28, 20, 'For the bed is too short to stretch oneself on it,  
    and the covering too narrow to wrap oneself in it.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 28, 21, 'For the LORD will rise up as on Mount Perazim,  
    he will rage as in the valley of Gibeon  
to do his deed--strange is his deed!--  
    and to work his work--alien is his work!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 28, 22, 'Now therefore do not scoff,  
    or your bonds will be made stronger;  
for I have heard a decree of destruction  
    from the Lord God of hosts upon the whole land.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 28, 23, 'Listen, and hear my voice;  
    Pay attention, and hear my speech.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 28, 24, 'Do those who plow for sowing plow continually?  
    Do they continually open and harrow their ground?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 28, 25, 'When they have leveled its surface,  
    do they not scatter dill, sow cummin,  
and plant wheat in rows  
    and barley in its proper place,  
    and spelt as the border?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 28, 26, 'For they are well instructed;  
    their God teaches them.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 28, 27, 'Dill is not threshed with a threshing sledge,  
    nor is a cart wheel rolled over cummin;  
but dill is beaten out with a stick,  
    and cummin with a rod.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 28, 28, 'Grain is crushed for bread,  
    but one does not thresh it forever;  
one drives the cart wheel and horses over it,  
    but does not pulverize it.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 28, 29, 'This also comes from the LORD of hosts;  
    he is wonderful in counsel,  
    and excellent in wisdom.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 29, 1, 'Ah, Ariel, Ariel,  
    the city where David encamped!  
Add year to year;  
    let the festivals run their round.', 'en', 'NRSV-CE', 'The Siege of Jerusalem'),
(23, 'Yes', 'Isaiah', 29, 2, 'Yet I will distress Ariel,  
    and there shall be moaning and lamentation,  
    and Jerusalem shall be to me like an Ariel.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 29, 3, 'And like David I will encamp against you;  
    I will besiege you with towers  
    and raise siegeworks against you.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 29, 4, 'Then deep from the earth you shall speak,  
    from low in the dust your words shall come;  
your voice shall come from the ground like the voice of a ghost,  
    and your speech shall whisper out of the dust.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 29, 5, 'But the multitude of your foes shall be like small dust,  
    and the multitude of tyrants like flying chaff.  
And in an instant, suddenly,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 29, 6, 'you will be visited by the LORD of hosts  
with thunder and earthquake and great noise,  
    with whirlwind and tempest, and the flame of a devouring fire.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 29, 7, 'And the multitude of all the nations that fight against Ariel,  
    all that fight against her and her stronghold, and who distress her,  
    shall be like a dream, a vision of the night.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 29, 8, 'Just as when a hungry person dreams of eating  
    and wakes up still hungry,  
or a thirsty person dreams of drinking  
    and wakes up faint, still thirsty,  
so shall the multitude of all the nations be  
    that fight against Mount Zion.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 29, 9, 'Stupefy yourselves and be in a stupor,  
    blind yourselves and be blind!  
Be drunk, but not from wine;  
    stagger, but not from strong drink!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 29, 10, 'For the LORD has poured out upon you  
    a spirit of deep sleep;  
he has closed your eyes, you prophets,  
    and covered your heads, you seers.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 29, 11, 'The vision of all this has become for you like the words of a sealed document. If it is given to those who can read, with the command, "Read this," they say, "We cannot, for it is sealed."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 29, 12, 'And if it is given to those who cannot read, saying, "Read this," they say, "We cannot read."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 29, 13, 'The Lord said:  
Because these people draw near with their mouths  
    and honor me with their lips,  
    while their hearts are far from me,  
and their worship of me is a human commandment learned by rote;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 29, 14, 'so I will again do  
    amazing things with this people,  
    shocking and amazing.  
The wisdom of their wise shall perish,  
    and the discernment of the discerning shall be hidden.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 29, 15, 'Ha! You who hide a plan too deep for the LORD,  
    whose deeds are in the dark,  
    and who say, "Who sees us? Who knows us?"', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 29, 16, 'You turn things upside down!  
    Shall the potter be regarded as the clay?  
Shall the thing made say of its maker,  
    "He did not make me";  
or the thing formed say of the one who formed it,  
    "He has no understanding"?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 29, 17, 'Shall not Lebanon in a very little while  
    become a fruitful field,  
    and the fruitful field be regarded as a forest?', 'en', 'NRSV-CE', 'Hope for the Future'),
(23, 'Yes', 'Isaiah', 29, 18, 'On that day the deaf shall hear  
    the words of a scroll,  
and out of their gloom and darkness  
    the eyes of the blind shall see.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 29, 19, 'The meek shall obtain fresh joy in the LORD,  
    and the neediest people shall exult in the Holy One of Israel.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 29, 20, 'For the tyrant shall be no more,  
    and the scoffer shall cease to be;  
    all those alert to do evil shall be cut off--', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 29, 21, 'those who cause a person to lose a lawsuit,  
    who set a trap for the arbiter in the gate,  
    and without grounds deny justice to the one in the right.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 29, 22, 'Therefore thus says the LORD, who redeemed Abraham, concerning the house of Jacob:
No longer shall Jacob be ashamed,  
    no longer shall his face grow pale.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 29, 23, 'For when he sees his children,  
    the work of my hands, in his midst,  
    they will sanctify my name;  
they will sanctify the Holy One of Jacob,  
    and will stand in awe of the God of Israel.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 29, 24, 'And those who err in spirit will come to understanding,  
    and those who grumble will accept instruction.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 30, 1, 'Oh, rebellious children, says the LORD,  
who carry out a plan, but not mine;  
who make an alliance, but against my will,  
    adding sin to sin;', 'en', 'NRSV-CE', 'The Futility of Reliance on Egypt'),
(23, 'Yes', 'Isaiah', 30, 2, 'who set out to go down to Egypt  
    without asking for my counsel,  
to take refuge in the protection of Pharaoh,  
    and to seek shelter in the shadow of Egypt;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 30, 3, 'Therefore the protection of Pharaoh shall become your shame,  
    and the shelter in the shadow of Egypt your humiliation.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 30, 4, 'For though his officials are at Zoan  
    and his envoys reach Hanes,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 30, 5, 'everyone comes to shame  
    through a people that cannot profit them,  
that brings neither help nor profit,  
    but shame and disgrace.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 30, 6, 'An oracle concerning the animals of the Negeb.
Through a land of trouble and distress,  
    of lioness and roaring lion,  
    of viper and flying serpent,  
they carry their riches on the backs of donkeys,  
    and their treasures on the humps of camels,  
    to a people that cannot profit them.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 30, 7, 'For Egypt"s help is worthless and empty,  
    therefore I have called her,  
    "Rahab who sits still."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 30, 8, 'Go now, write it before them on a tablet,  
    and inscribe it in a book,  
so that it may be for the time to come  
    as a witness forever.', 'en', 'NRSV-CE', 'A Rebellious People'),
(23, 'Yes', 'Isaiah', 30, 9, 'For they are a rebellious people,  
    faithless children,  
children who will not hear  
    the instruction of the LORD;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 30, 10, 'who say to the seers, "Do not see";  
    and to the prophets, "Do not prophesy to us what is right;  
speak to us smooth things,  
    prophesy illusions,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 30, 11, 'leave the way, turn aside from the path,  
    let us hear no more about the Holy One of Israel."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 30, 12, 'Therefore thus says the Holy One of Israel:  
Because you reject this word,  
    and put your trust in oppression and deceit,  
    and rely on them;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 30, 13, 'therefore this iniquity shall become for you  
    like a break in a high wall, bulging out, and about to collapse,  
    whose crash comes suddenly, in an instant;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 30, 14, 'its breaking is like that of a potter"s vessel  
    that is smashed so ruthlessly  
that among its fragments not a sherd is found  
    for taking fire from the hearth,  
    or dipping water out of the cistern.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 30, 15, 'For thus said the Lord God, the Holy One of Israel:  
In returning and rest you shall be saved;  
    in quietness and in trust shall be your strength.  
But you refused', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 30, 16, 'and said,  
"No! We will flee upon horses"--  
    therefore you shall flee!  
and, "We will ride upon swift steeds"--  
    therefore your pursuers shall be swift!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 30, 17, 'A thousand shall flee at the threat of one,  
    at the threat of five you shall flee,  
until you are left  
    like a flagstaff on the top of a mountain,  
    like a signal on a hill.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 30, 18, 'Therefore the LORD waits to be gracious to you;  
    therefore he will rise up to show mercy to you.  
For the LORD is a God of justice;  
    blessed are all those who wait for him.', 'en', 'NRSV-CE', 'God"s Promise to Zion'),
(23, 'Yes', 'Isaiah', 30, 19, 'Truly, O people in Zion, inhabitants of Jerusalem, you shall weep no more. He will surely be gracious to you at the sound of your cry; when he hears it, he will answer you.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 30, 20, 'Though the Lord may give you the bread of adversity and the water of affliction, yet your Teacher will not hide himself any more, but your eyes shall see your Teacher.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 30, 21, 'And when you turn to the right or when you turn to the left, your ears shall hear a word behind you, saying, "This is the way; walk in it."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 30, 22, 'Then you will defile your silver-covered idols and your gold-plated images. You will scatter them like filthy rags; you will say to them, "Away with you!"', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 30, 23, 'He will give rain for the seed with which you sow the ground, and grain, the produce of the ground, which will be rich and plenteous. On that day your cattle will graze in broad pastures;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 30, 24, 'and the oxen and donkeys that till the ground will eat silage, which has been winnowed with shovel and fork.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 30, 25, 'On every lofty mountain and every high hill there will be brooks running with water--on a day of the great slaughter, when the towers fall.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 30, 26, 'Moreover the light of the moon will be like the light of the sun, and the light of the sun will be sevenfold, like the light of seven days, on the day when the LORD binds up the injuries of his people, and heals the wounds inflicted by his blow.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 30, 27, 'See, the name of the LORD comes from far away,  
    burning with his anger, and in thick rising smoke;  
his lips are full of indignation,  
    and his tongue is like a devouring fire;', 'en', 'NRSV-CE', 'Judgment on Assyria'),
(23, 'Yes', 'Isaiah', 30, 28, 'his breath is like an overflowing stream  
    that reaches up to the neck--  
to sift the nations with the sieve of destruction,  
    and to place on the jaws of the peoples a bridle that leads them astray.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 30, 29, 'You shall have a song as in the night when a holy festival is kept; and gladness of heart, as when one sets out to the sound of the flute to go to the mountain of the LORD, to the Rock of Israel.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 30, 30, 'And the LORD will cause his majestic voice to be heard and the descending blow of his arm to be seen, in furious anger and a flame of devouring fire, with a cloudburst and tempest and hailstones.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 30, 31, 'The Assyrian will be terror-stricken at the voice of the LORD, when he strikes with his rod.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 30, 32, 'And every stroke of the staff of punishment that the LORD lays upon him will be to the sound of timbrels and lyres; battling with brandished arm he will fight with him.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 30, 33, 'For his burning place has long been prepared; truly it is made ready for the king, its pyre made deep and wide, with fire and wood in abundance; the breath of the LORD, like a stream of sulfur, kindles it.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 31, 1, 'Alas for those who go down to Egypt for help  
    and who rely on horses,  
who trust in chariots because they are many  
    and in horsemen because they are very strong,  
but do not look to the Holy One of Israel  
    or consult the LORD!', 'en', 'NRSV-CE', 'Alliance with Egypt Is Futile'),
(23, 'Yes', 'Isaiah', 31, 2, 'Yet he too is wise and brings disaster;  
    he does not call back his words,  
but will rise against the house of the evildoers,  
    and against the helpers of those who work iniquity.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 31, 3, 'The Egyptians are human, and not God;  
    their horses are flesh, and not spirit.  
When the LORD stretches out his hand,  
    the helper will stumble, and the one helped will fall,  
    and they will all perish together.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 31, 4, 'For thus the LORD said to me,  
As a lion or a young lion growls over its prey,  
    and--when a band of shepherds is called out against it--  
is not terrified by their shouting  
    or daunted at their noise,  
so the LORD of hosts will come down  
    to fight upon Mount Zion and upon its hill.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 31, 5, 'Like birds hovering overhead, so the LORD of hosts  
    will protect Jerusalem;  
he will protect and deliver it,  
    he will spare and rescue it.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 31, 6, 'Turn back to him whom you have deeply betrayed, O people of Israel.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 31, 7, 'For on that day all of you shall throw away your idols of silver and idols of gold, which your hands have sinfully made for you.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 31, 8, '"Then the Assyrian shall fall by a sword, not of mortals;  
    and a sword, not of humans, shall devour him;  
he shall flee from the sword,  
    and his young men shall be put to forced labor.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 31, 9, 'His rock shall pass away in terror,  
    and his officers desert the standard in panic,"  
says the LORD, whose fire is in Zion,  
    and whose furnace is in Jerusalem.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 32, 1, 'See, a king will reign in righteousness,  
    and princes will rule with justice.', 'en', 'NRSV-CE', 'Government with Justice Predicted'),
(23, 'Yes', 'Isaiah', 32, 2, 'Each will be like a hiding place from the wind,  
    a covert from the tempest,  
like streams of water in a dry place,  
    like the shade of a great rock in a weary land.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 32, 3, 'Then the eyes of those who have sight will not be closed,  
    and the ears of those who have hearing will listen.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 32, 4, 'The minds of the rash will have good judgment,  
    and the tongues of stammerers will speak readily and distinctly.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 32, 5, 'A fool will no longer be called noble,  
    nor a villain said to be honorable.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 32, 6, 'For fools speak folly,  
    and their minds plot iniquity:  
to practice ungodliness,  
    to utter error concerning the LORD,  
to leave the craving of the hungry unsatisfied,  
    and to deprive the thirsty of drink.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 32, 7, 'The villainies of villains are evil;  
    they devise wicked devices  
to ruin the poor with lying words,  
    even when the plea of the needy is right.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 32, 8, 'But those who are noble plan noble things,  
    and by noble things they stand.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 32, 9, 'Rise up, you women who are at ease, hear my voice;  
    you complacent daughters, listen to my speech.', 'en', 'NRSV-CE', 'Complacent Women Warned of Disaster'),
(23, 'Yes', 'Isaiah', 32, 10, 'In little more than a year  
    you will shudder, you complacent ones;  
for the vintage will fail,  
    the fruit harvest will not come.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 32, 11, 'Tremble, you women who are at ease,  
    shudder, you complacent ones;  
strip, and make yourselves bare,  
    and put sackcloth on your loins.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 32, 12, 'Beat your breasts for the pleasant fields,  
    for the fruitful vine,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 32, 13, 'for the soil of my people  
    growing up in thorns and briers;  
yes, for all the joyous houses  
    in the jubilant city.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 32, 14, 'For the palace will be forsaken,  
    the populous city deserted;  
the hill and the watchtower  
    will become dens forever,  
the joy of wild asses,  
    a pasture for flocks;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 32, 15, 'until a spirit from on high is poured out on us,  
    and the wilderness becomes a fruitful field,  
    and the fruitful field is deemed a forest.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 32, 16, 'Then justice will dwell in the wilderness,  
    and righteousness abide in the fruitful field.', 'en', 'NRSV-CE', 'The Peace of God"s Reign'),
(23, 'Yes', 'Isaiah', 32, 17, 'The effect of righteousness will be peace,  
    and the result of righteousness, quietness and trust forever.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 32, 18, 'My people will abide in a peaceful habitation,  
    in secure dwellings, and in quiet resting places.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 32, 19, 'The forest will disappear completely,  
    and the city will be utterly laid low.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 32, 20, 'Happy will you be who sow beside every stream,  
    who let the ox and the donkey range freely.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 33, 1, 'Ah, you destroyer,  
    who yourself have not been destroyed;  
you treacherous one,  
    with whom no one has dealt treacherously!  
When you have ceased to destroy,  
    you will be destroyed;  
and when you have stopped dealing treacherously,  
    you will be dealt with treacherously.', 'en', 'NRSV-CE', 'A Prophecy of Deliverance from Foes'),
(23, 'Yes', 'Isaiah', 33, 2, 'O LORD, be gracious to us; we wait for you.  
    Be our arm every morning,  
    our salvation in the time of trouble.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 33, 3, 'At the sound of tumult, peoples fled;  
    before your majesty, nations scattered.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 33, 4, 'Spoil was gathered as the caterpillar gathers;  
    as locusts leap, they leaped upon it.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 33, 5, 'The LORD is exalted, he dwells on high;  
    he filled Zion with justice and righteousness;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 33, 6, 'he will be the stability of your times,  
    abundance of salvation, wisdom, and knowledge;  
    the fear of the LORD is Zion"s treasure.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 33, 7, 'Listen! the valiant cry in the streets;  
    the envoys of peace weep bitterly.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 33, 8, 'The highways are deserted,  
    travelers have quit the road.  
The treaty is broken,  
    its oaths are despised,  
    its obligation is disregarded.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 33, 9, 'The land mourns and languishes;  
    Lebanon is confounded and withers away;  
Sharon is like a desert;  
    and Bashan and Carmel shake off their leaves.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 33, 10, '"Now I will arise," says the LORD,  
    "now I will lift myself up;  
    now I will be exalted.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 33, 11, 'You conceive chaff, you bring forth stubble;  
    your breath is a fire that will consume you.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 33, 12, 'And the peoples will be as if burned to lime,  
    like thorns cut down, that are burned in the fire."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 33, 13, 'Hear, you who are far away, what I have done;  
    and you who are near, acknowledge my might.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 33, 14, 'The sinners in Zion are afraid;  
    trembling has seized the godless:  
"Who among us can live with the devouring fire?  
    Who among us can live with everlasting flames?"', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 33, 15, 'Those who walk righteously and speak uprightly,  
    who despise the gain of oppression,  
who wave away a bribe instead of accepting it,  
    who stop their ears from hearing of bloodshed  
    and shut their eyes from looking on evil,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 33, 16, 'they will live on the heights;  
    their refuge will be the fortresses of rocks;  
    their food will be supplied, their water assured.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 33, 17, 'Your eyes will see the king in his beauty;  
    they will behold a land that stretches far away.', 'en', 'NRSV-CE', 'The Land of the Majestic King'),
(23, 'Yes', 'Isaiah', 33, 18, 'Your mind will muse on the terror:  
    "Where is the one who counted?  
    Where is the one who weighed the tribute?  
    Where is the one who counted the towers?"', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 33, 19, 'No longer will you see the insolent people,  
    the people of an obscure speech that you cannot comprehend,  
    stammering in a language that you cannot understand.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 33, 20, 'Look on Zion, the city of our appointed festivals!  
    Your eyes will see Jerusalem,  
    a quiet habitation, an immovable tent,  
whose stakes will never be pulled up,  
    and none of whose ropes will be broken.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 33, 21, 'But there the LORD in majesty will be for us  
    a place of broad rivers and streams,  
where no galley with oars can go,  
    nor stately ship can pass.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 33, 22, 'For the LORD is our judge, the LORD is our ruler,  
    the LORD is our king; he will save us.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 33, 23, 'Your rigging hangs loose;  
    it cannot hold the mast firm in its place,  
    or keep the sail spread out.
Then prey and spoil in abundance will be divided;  
    even the lame will fall to plundering.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 33, 24, 'And no inhabitant will say, "I am sick";  
    the people who live there will be forgiven their iniquity.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 34, 1, 'Draw near, O nations, to hear;  
    O peoples, give heed!  
Let the earth hear, and all that fills it;  
    the world, and all that comes from it.', 'en', 'NRSV-CE', 'Judgment on the Nations'),
(23, 'Yes', 'Isaiah', 34, 2, 'For the LORD is enraged against all the nations,  
    and furious against all their hordes;  
    he has doomed them, has given them over for slaughter.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 34, 3, 'Their slain shall be cast out,  
    and the stench of their corpses shall rise;  
    the mountains shall flow with their blood.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 34, 4, 'All the host of heaven shall rot away,  
    and the skies roll up like a scroll.  
All their host shall wither  
    like a leaf withering on a vine,  
    or fruit withering on a fig tree.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 34, 5, 'When my sword has drunk its fill in the heavens,  
    lo, it will descend upon Edom,  
    upon the people I have doomed to judgment.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 34, 6, 'The LORD has a sword; it is sated with blood,  
    it is gorged with fat,  
    with the blood of lambs and goats,  
    with the fat of the kidneys of rams.  
For the LORD has a sacrifice in Bozrah,  
    a great slaughter in the land of Edom.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 34, 7, 'Wild oxen shall fall with them,  
    and young steers with the mighty bulls.  
Their land shall be soaked with blood,  
    and their soil made rich with fat.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 34, 8, 'For the LORD has a day of vengeance,  
    a year of vindication by Zion"s cause.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 34, 9, 'And the streams of Edom shall be turned into pitch,  
    and her soil into sulfur;  
    her land shall become burning pitch.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 34, 10, 'Night and day it shall not be quenched;  
    its smoke shall go up forever.  
From generation to generation it shall lie waste;  
    no one shall pass through it forever and ever.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 34, 11, 'But the hawk and the hedgehog shall possess it;  
    the owl and the raven shall live in it.  
He shall stretch the line of confusion over it,  
    and the plummet of chaos over its nobles.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 34, 12, 'They shall name it No Kingdom There,  
    and all its princes shall be nothing.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 34, 13, 'Thorns shall grow over its strongholds,  
    nettles and thistles in its fortresses.  
It shall be the haunt of jackals,  
    an abode for ostriches.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 34, 14, 'Wildcats shall meet with hyenas,  
    goat-demons shall call to each other;  
there too Lilith shall repose,  
    and find a place to rest.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 34, 15, 'There shall the owl nest  
    and lay and hatch and brood in its shadow;  
there too the buzzards shall gather,  
    each one with its mate.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 34, 16, 'Seek and read from the book of the LORD:  
    Not one of these shall be missing;  
    none shall be without its mate.  
For the mouth of the LORD has commanded,  
    and his spirit has gathered them.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 34, 17, 'He has cast the lot for them,  
    his hand has portioned it out to them with the line;  
they shall possess it forever,  
    from generation to generation they shall live in it.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 35, 1, 'The wilderness and the dry land shall be glad,  
    the desert shall rejoice and blossom;  
like the crocus', 'en', 'NRSV-CE', 'The Return of the Redeemed to Zion'),
(23, 'Yes', 'Isaiah', 35, 2, 'it shall blossom abundantly,  
    and rejoice with joy and singing.  
The glory of Lebanon shall be given to it,  
    the majesty of Carmel and Sharon.  
They shall see the glory of the LORD,  
    the majesty of our God.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 35, 3, 'Strengthen the weak hands,  
    and make firm the feeble knees.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 35, 4, 'Say to those who are of a fearful heart,  
    "Be strong, do not fear!  
Here is your God.  
    He will come with vengeance,  
with terrible recompense.  
    He will come and save you."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 35, 5, 'Then the eyes of the blind shall be opened,  
    and the ears of the deaf unstopped;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 35, 6, 'then the lame shall leap like a deer,  
    and the tongue of the speechless sing for joy.  
For waters shall break forth in the wilderness,  
    and streams in the desert;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 35, 7, 'the burning sand shall become a pool,  
    and the thirsty ground springs of water;  
the haunt of jackals shall become a swamp,  
    the grass shall become reeds and rushes.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 35, 8, 'A highway shall be there,  
    and it shall be called the Holy Way;  
the unclean shall not travel on it,  
    but it shall be for God"s people;  
    no traveler, not even fools, shall go astray.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 35, 9, 'No lion shall be there,  
    nor shall any ravenous beast come up on it;  
they shall not be found there,  
    but the redeemed shall walk there.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 35, 10, 'And the ransomed of the LORD shall return,  
    and come to Zion with singing;  
everlasting joy shall be upon their heads;  
    they shall obtain joy and gladness,  
    and sorrow and sighing shall flee away.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 36, 1, 'In the fourteenth year of King Hezekiah, King Sennacherib of Assyria came up against all the fortified cities of Judah and captured them.', 'en', 'NRSV-CE', 'Sennacherib Threatens Jerusalem'),
(23, 'Yes', 'Isaiah', 36, 2, 'The king of Assyria sent the Rabshakeh from Lachish to King Hezekiah at Jerusalem, with a great army. He stood by the conduit of the upper pool on the highway to the Fuller"s Field.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 36, 3, 'And there came out to him Eliakim son of Hilkiah, who was in charge of the palace, and Shebna the secretary, and Joah son of Asaph, the recorder.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 36, 4, 'The Rabshakeh said to them, "Say to Hezekiah: Thus says the great king, the king of Assyria: On what do you base this confidence of yours?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 36, 5, 'Do you think that mere words are strategy and power for war? On whom do you now rely, that you have rebelled against me?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 36, 6, 'See, you are relying on Egypt, that broken reed of a staff, which will pierce the hand of anyone who leans on it. Such is Pharaoh king of Egypt to all who rely on him.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 36, 7, 'But if you say to me, "We rely on the LORD our God," is it not he whose high places and altars Hezekiah has removed, saying to Judah and to Jerusalem, "You shall worship before this altar"?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 36, 8, 'Come now, make a wager with my master the king of Assyria: I will give you two thousand horses, if you are able on your part to set riders on them.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 36, 9, 'How then can you repulse a single captain among the least of my master"s servants, when you rely on Egypt for chariots and for horsemen?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 36, 10, 'Moreover, is it without the LORD that I have come up against this land to destroy it? The LORD said to me, Go up against this land, and destroy it."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 36, 11, 'Then Eliakim, Shebna, and Joah said to the Rabshakeh, "Please speak to your servants in Aramaic, for we understand it; do not speak to us in the language of Judah within the hearing of the people who are on the wall."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 36, 12, 'But the Rabshakeh said, "Has my master sent me to speak these words to your master and to you, and not to the people sitting on the wall, who are doomed with you to eat their own dung and drink their own urine?"', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 36, 13, 'Then the Rabshakeh stood and called out in a loud voice in the language of Judah, "Hear the words of the great king, the king of Assyria!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 36, 14, 'Thus says the king: "Do not let Hezekiah deceive you, for he will not be able to deliver you.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 36, 15, 'Do not let Hezekiah make you rely on the LORD by saying, The LORD will surely deliver us; this city will not be given into the hand of the king of Assyria."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 36, 16, 'Do not listen to Hezekiah; for thus says the king of Assyria: "Make your peace with me and come out to me; then every one of you will eat from your own vine and your own fig tree and drink water from your own cistern,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 36, 17, 'until I come and take you away to a land like your own land, a land of grain and wine, a land of bread and vineyards.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 36, 18, 'Do not let Hezekiah mislead you by saying, The LORD will save us. Has any of the gods of the nations saved their land out of the hand of the king of Assyria?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 36, 19, 'Where are the gods of Hamath and Arpad? Where are the gods of Sepharvaim? Have they delivered Samaria out of my hand?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 36, 20, 'Who among all the gods of these countries have saved their countries out of my hand, that the LORD should save Jerusalem out of my hand?""', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 36, 21, 'But they were silent and answered him not a word, for the king"s command was, "Do not answer him."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 36, 22, 'Then Eliakim son of Hilkiah, who was in charge of the palace, and Shebna the secretary, and Joah son of Asaph, the recorder, came to Hezekiah with their clothes torn, and told him the words of the Rabshakeh.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 37, 1, 'When King Hezekiah heard it, he tore his clothes, covered himself with sackcloth, and went into the house of the LORD.', 'en', 'NRSV-CE', 'Hezekiah Consults Isaiah'),
(23, 'Yes', 'Isaiah', 37, 2, 'And he sent Eliakim, who was in charge of the palace, and Shebna the secretary, and the senior priests, covered with sackcloth, to the prophet Isaiah son of Amoz.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 37, 3, 'They said to him, "Thus says Hezekiah, This day is a day of distress, of rebuke, and of disgrace; children have come to the birth, and there is no strength to bring them forth.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 37, 4, 'It may be that the LORD your God heard the words of the Rabshakeh, whom his master the king of Assyria has sent to mock the living God, and will rebuke the words that the LORD your God has heard; therefore lift up your prayer for the remnant that is left."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 37, 5, 'When the servants of King Hezekiah came to Isaiah,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 37, 6, 'Isaiah said to them, "Say to your master, "Thus says the LORD: Do not be afraid because of the words that you have heard, with which the servants of the king of Assyria have reviled me.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 37, 7, 'I myself will put a spirit in him, so that he shall hear a rumor, and return to his own land; I will cause him to fall by the sword in his own land.""', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 37, 8, 'The Rabshakeh returned, and found the king of Assyria fighting against Libnah; for he had heard that the king had left Lachish.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 37, 9, 'Now the king heard concerning King Tirhakah of Ethiopia, "He has set out to fight against you." When he heard it, he sent messengers to Hezekiah, saying,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 37, 10, '"Thus shall you speak to King Hezekiah of Judah: Do not let your God on whom you rely deceive you by promising that Jerusalem will not be given into the hand of the king of Assyria.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 37, 11, 'See, you have heard what the kings of Assyria have done to all lands, destroying them utterly. Shall you be delivered?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 37, 12, 'Have the gods of the nations delivered them, the nations that my predecessors destroyed, Gozan, Haran, Rezeph, and the people of Eden who were in Telassar?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 37, 13, 'Where is the king of Hamath, the king of Arpad, the king of the city of Sepharvaim, the king of Hena, or the king of Ivvah?"', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 37, 14, 'Hezekiah received the letter from the hand of the messengers and read it; then Hezekiah went up to the house of the LORD and spread it before the LORD.', 'en', 'NRSV-CE', 'Hezekiah"s Prayer'),
(23, 'Yes', 'Isaiah', 37, 15, 'And Hezekiah prayed to the LORD, saying:', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 37, 16, '"O LORD of hosts, God of Israel, who are enthroned above the cherubim, you are God, you alone, of all the kingdoms of the earth; you have made heaven and earth.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 37, 17, 'Incline your ear, O LORD, and hear; open your eyes, O LORD, and see; hear all the words of Sennacherib, which he has sent to mock the living God.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 37, 18, 'Truly, O LORD, the kings of Assyria have laid waste all the nations and their lands,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 37, 19, 'and have hurled their gods into the fire, though they were no gods, but the work of human hands--wood and stone--and so they were destroyed.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 37, 20, 'So now, O LORD our God, save us from his hand, so that all the kingdoms of the earth may know that you alone are the LORD."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 37, 21, 'Then Isaiah son of Amoz sent to Hezekiah, saying: "Thus says the LORD, the God of Israel: Because you have prayed to me concerning King Sennacherib of Assyria,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 37, 22, 'this is the word that the LORD has spoken concerning him:
She despises you, she scorns you--  
    virgin daughter Zion;  
she tosses her head--behind your back,  
    daughter Jerusalem.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 37, 23, '"Whom have you mocked and reviled?  
    Against whom have you raised your voice  
and haughtily lifted your eyes?  
    Against the Holy One of Israel!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 37, 24, 'By your servants you have mocked the Lord,  
    and you have said, "With my many chariots  
I have gone up the heights of the mountains,  
    to the far recesses of Lebanon;  
I felled its tallest cedars,  
    its choicest cypresses;  
I came to its remotest height,  
    its densest forest.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 37, 25, 'I dug wells  
    and drank waters,  
I dried up with the sole of my foot  
    all the streams of Egypt."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 37, 26, '"Have you not heard  
    that I determined it long ago?  
I planned from days of old  
    what now I bring to pass,  
that you should make fortified cities  
    crash into heaps of ruins,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 37, 27, 'while their inhabitants, shorn of strength,  
    are dismayed and confounded;  
they have become like plants of the field  
    and like tender grass,  
like grass on the housetops,  
    blighted before it is grown.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 37, 28, '"I know your rising up and your sitting down,  
    your going out and coming in,  
    and your raging against me.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 37, 29, 'Because you have raged against me  
    and your arrogance has come to my ears,  
I will put my hook in your nose  
    and my bit in your mouth;  
I will turn you back on the way  
    by which you came.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 37, 30, '"And this shall be the sign for you: This year eat what grows of itself, and in the second year what springs from that; then in the third year sow, reap, plant vineyards, and eat their fruit.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 37, 31, 'The surviving remnant of the house of Judah shall again take root downward, and bear fruit upward;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 37, 32, 'for from Jerusalem a remnant shall go out, and from Mount Zion a band of survivors. The zeal of the LORD of hosts will do this.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 37, 33, '"Therefore thus says the LORD concerning the king of Assyria: He shall not come into this city, shoot an arrow there, come before it with a shield, or cast up a siege ramp against it.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 37, 34, 'By the way that he came, by the same he shall return; he shall not come into this city, says the LORD.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 37, 35, 'For I will defend this city to save it, for my own sake and for the sake of my servant David."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 37, 36, 'Then the angel of the LORD set out and struck down one hundred eighty-five thousand in the camp of the Assyrians; when morning dawned, they were all dead bodies.', 'en', 'NRSV-CE', 'Sennacherib"s Defeat and Death'),
(23, 'Yes', 'Isaiah', 37, 37, 'Then King Sennacherib of Assyria left, went home, and lived at Nineveh.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 37, 38, 'As he was worshiping in the house of his god Nisroch, his sons Adrammelech and Sharezer killed him with the sword, and they escaped into the land of Ararat. His son Esar-haddon succeeded him.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 38, 1, 'In those days Hezekiah became sick and was at the point of death. The prophet Isaiah son of Amoz came to him, and said to him, "Thus says the LORD: Set your house in order, for you shall die; you shall not recover."', 'en', 'NRSV-CE', 'Hezekiah"s Illness'),
(23, 'Yes', 'Isaiah', 38, 2, 'Then Hezekiah turned his face to the wall, and prayed to the LORD:', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 38, 3, '"Remember now, O LORD, I implore you, how I have walked before you in faithfulness with a whole heart, and have done what is good in your sight." And Hezekiah wept bitterly.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 38, 4, 'Then the word of the LORD came to Isaiah:', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 38, 5, '"Go and say to Hezekiah, Thus says the LORD, the God of your ancestor David: I have heard your prayer, I have seen your tears; I will add fifteen years to your life.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 38, 6, 'I will deliver you and this city out of the hand of the king of Assyria, and defend this city.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 38, 7, '"This is the sign to you from the LORD, that the LORD will do this thing that he has promised:', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 38, 8, 'See, I will make the shadow cast by the declining sun on the dial of Ahaz turn back ten steps." So the sun turned back on the dial the ten steps by which it had declined.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 38, 9, 'A writing of King Hezekiah of Judah, after he had been sick and had recovered from his sickness:', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 38, 10, 'I said: In the noontide of my days  
    I must depart;  
I am consigned to the gates of Sheol  
    for the rest of my years.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 38, 11, 'I said, I shall not see the LORD  
    in the land of the living;  
I shall look upon mortals no more  
    among the inhabitants of the world.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 38, 12, 'My dwelling is plucked up and removed from me  
    like a shepherd"s tent;  
like a weaver I have rolled up my life;  
    he cuts me off from the loom;  
from day to night you bring me to an end;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 38, 13, 'I cry for help until morning;  
like a lion he breaks all my bones;  
    from day to night you bring me to an end.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 38, 14, 'Like a swallow or a crane I clamor,  
    I moan like a dove.  
My eyes are weary with looking upward.  
    O Lord, I am oppressed; be my security!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 38, 15, 'But what can I say? For he has spoken to me,  
    and he himself has done it.  
All my sleep has fled  
    because of the bitterness of my soul.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 38, 16, 'O Lord, by these things people live,  
    and in all these is the life of my spirit.  
    Oh, restore me to health and make me live!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 38, 17, 'Surely it was for my welfare  
    that I had great bitterness;  
but you have held back my life  
    from the pit of destruction,  
for you have cast all my sins  
    behind your back.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 38, 18, 'For Sheol cannot thank you,  
    death cannot praise you;  
those who go down to the Pit cannot hope  
    for your faithfulness.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 38, 19, 'The living, the living, they thank you,  
    as I do this day;  
fathers make known to children  
    your faithfulness.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 38, 20, 'The LORD will save me,  
    and we will sing to stringed instruments  
all the days of our lives,  
    at the house of the LORD.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 38, 21, 'Now Isaiah had said, "Let them take a lump of figs, and apply it to the boil, so that he may recover."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 38, 22, 'Hezekiah also had said, "What is the sign that I shall go up to the house of the LORD?"', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 39, 1, 'At that time King Merodach-baladan son of Baladan of Babylon sent envoys with letters and a present to Hezekiah, for he heard that he had been sick and had recovered.', 'en', 'NRSV-CE', 'Envoys from Babylon Welcomed'),
(23, 'Yes', 'Isaiah', 39, 2, 'Hezekiah welcomed them; he showed them his treasure house, the silver, the gold, the spices, the precious oil, his whole armory, all that was found in his storehouses. There was nothing in his house or in all his realm that Hezekiah did not show them.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 39, 3, 'Then the prophet Isaiah came to King Hezekiah and said to him, "What did these men say? From where did they come to you?" Hezekiah answered, "They have come to me from a far country, from Babylon."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 39, 4, 'He said, "What have they seen in your house?" Hezekiah answered, "They have seen all that is in my house; there is nothing in my storehouses that I did not show them."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 39, 5, 'Then Isaiah said to Hezekiah, "Hear the word of the LORD of hosts:', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 39, 6, 'Days are coming when all that is in your house, and that which your ancestors have stored up until this day, shall be carried to Babylon; nothing shall be left, says the LORD.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 39, 7, 'Some of your own sons who are born to you shall be taken away; they shall be eunuchs in the palace of the king of Babylon."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 39, 8, 'Then Hezekiah said to Isaiah, "The word of the LORD that you have spoken is good." For he thought, "There will be peace and security in my days."', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 40, 1, 'Comfort, O comfort my people,  
    says your God.', 'en', 'NRSV-CE', 'God"s People Are Comforted'),
(23, 'Yes', 'Isaiah', 40, 2, 'Speak tenderly to Jerusalem,  
    and cry to her  
that she has served her term,  
    that her penalty is paid,  
that she has received from the LORD"s hand  
    double for all her sins.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 40, 3, 'A voice cries out:  
"In the wilderness prepare the way of the LORD,  
    make straight in the desert a highway for our God.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 40, 4, 'Every valley shall be lifted up,  
    and every mountain and hill be made low;  
the uneven ground shall become level,  
    and the rough places a plain.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 40, 5, 'Then the glory of the LORD shall be revealed,  
    and all people shall see it together,  
    for the mouth of the LORD has spoken."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 40, 6, 'A voice says, "Cry out!"  
    And I said, "What shall I cry?"  
All people are grass,  
    their constancy is like the flower of the field.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 40, 7, 'The grass withers, the flower fades,  
    when the breath of the LORD blows upon it;  
    surely the people are grass.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 40, 8, 'The grass withers, the flower fades;  
    but the word of our God will stand forever.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 40, 9, 'Get you up to a high mountain,  
    O Zion, herald of good tidings;  
lift up your voice with strength,  
    O Jerusalem, herald of good tidings,  
    lift it up, do not fear;  
say to the cities of Judah,  
    "Here is your God!"', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 40, 10, 'See, the Lord God comes with might,  
    and his arm rules for him;  
his reward is with him,  
    and his recompense before him.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 40, 11, 'He will feed his flock like a shepherd;  
    he will gather the lambs in his arms,  
and carry them in his bosom,  
    and gently lead the mother sheep.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 40, 12, 'Who has measured the waters in the hollow of his hand  
    and marked off the heavens with a span,  
enclosed the dust of the earth in a measure,  
    and weighed the mountains in scales  
    and the hills in a balance?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 40, 13, 'Who has directed the spirit of the LORD,  
    or as his counselor has instructed him?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 40, 14, 'Whom did he consult for his enlightenment,  
    and who taught him the path of justice?  
Who taught him knowledge,  
    and showed him the way of understanding?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 40, 15, 'Even the nations are like a drop from a bucket,  
    and are accounted as dust on the scales;  
    see, he takes up the isles like fine dust.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 40, 16, 'Lebanon would not provide fuel enough,  
    nor are its animals enough for a burnt offering.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 40, 17, 'All the nations are as nothing before him;  
    they are accounted by him as less than nothing and emptiness.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 40, 18, 'To whom then will you liken God,  
    or what likeness compare with him?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 40, 19, 'An idol? --A workman casts it,  
    and a goldsmith overlays it with gold,  
    and casts for it silver chains.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 40, 20, 'As a gift one chooses mulberry wood  
    --wood that will not rot--  
then seeks out a skilled artisan  
    to set up an image that will not topple.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 40, 21, 'Have you not known? Have you not heard?  
    Has it not been told you from the beginning?  
    Have you not understood from the foundations of the earth?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 40, 22, 'It is he who sits above the circle of the earth,  
    and its inhabitants are like grasshoppers;  
who stretches out the heavens like a curtain,  
    and spreads them like a tent to live in;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 40, 23, 'who brings princes to naught,  
    and makes the rulers of the earth as nothing.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 40, 24, 'Scarcely are they planted, scarcely sown,  
    scarcely has their stem taken root in the earth,  
when he blows upon them, and they wither,  
    and the tempest carries them off like stubble.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 40, 25, 'To whom then will you compare me,  
    or who is my equal? says the Holy One.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 40, 26, 'Lift up your eyes on high and see:  
    Who created these?  
He who brings out their host and numbers them,  
    calling them all by name;  
because he is great in strength,  
    mighty in power,  
    not one is missing.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 40, 27, 'Why do you say, O Jacob,  
    and speak, O Israel,  
"My way is hidden from the LORD,  
    and my right is disregarded by my God"?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 40, 28, 'Have you not known? Have you not heard?  
The LORD is the everlasting God,  
    the Creator of the ends of the earth.  
He does not faint or grow weary;  
    his understanding is unsearchable.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 40, 29, 'He gives power to the faint,  
    and strengthens the powerless.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 40, 30, 'Even youths will faint and be weary,  
    and the young will fall exhausted;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 40, 31, 'but those who wait for the LORD shall renew their strength,  
    they shall mount up with wings like eagles,  
they shall run and not be weary,  
    they shall walk and not faint.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 41, 1, 'Listen to me in silence, O coastlands;  
    let the peoples renew their strength;  
let them approach, then let them speak;  
    let us together draw near for judgment.', 'en', 'NRSV-CE', 'Israel Assured of God"s Help'),
(23, 'Yes', 'Isaiah', 41, 2, 'Who has roused a victor from the east,  
    summoned him to his service?  
He delivers up nations to him,  
    and tramples kings under foot;  
he makes them like dust with his sword,  
    like driven stubble with his bow.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 41, 3, 'He pursues them and passes on safely,  
    scarcely touching the path with his feet.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 41, 4, 'Who has performed and done this,  
    calling the generations from the beginning?  
I, the LORD, am first,  
    and will be with the last.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 41, 5, 'The coastlands have seen and are afraid,  
    the ends of the earth tremble;  
    they have drawn near and come.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 41, 6, 'Each one helps the other,  
    saying to one another, "Take courage!"', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 41, 7, 'The artisan encourages the goldsmith,  
    and the one who smooths with the hammer encourages the one who strikes the anvil,  
saying of the soldering, "It is good";  
    and they fasten it with nails so that it cannot be moved.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 41, 8, 'But you, Israel, my servant,  
    Jacob, whom I have chosen,  
    the offspring of Abraham, my friend;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 41, 9, 'you whom I took from the ends of the earth,  
    and called from its farthest corners,  
saying to you, "You are my servant,  
    I have chosen you and not cast you off";', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 41, 10, 'do not fear, for I am with you,  
    do not be afraid, for I am your God;  
I will strengthen you, I will help you,  
    I will uphold you with my victorious right hand.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 41, 11, 'Yes, all who are incensed against you  
    shall be ashamed and disgraced;  
those who strive against you  
    shall be as nothing and shall perish.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 41, 12, 'You shall seek those who contend with you,  
    but you shall not find them;  
those who war against you  
    shall be as nothing at all.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 41, 13, 'For I, the LORD your God,  
    hold your right hand;  
it is I who say to you, "Do not fear,  
    I will help you."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 41, 14, 'Do not fear, you worm Jacob,  
    you insect Israel!  
I will help you, says the LORD;  
    your Redeemer is the Holy One of Israel.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 41, 15, 'Now, I will make of you a threshing sledge,  
    sharp, new, and having teeth;  
you shall thresh the mountains and crush them,  
    and you shall make the hills like chaff.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 41, 16, 'You shall winnow them and the wind shall carry them away,  
    and the tempest shall scatter them.  
Then you shall rejoice in the LORD;  
    in the Holy One of Israel you shall glory.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 41, 17, 'When the poor and needy seek water,  
    and there is none,  
    and their tongue is parched with thirst,  
I the LORD will answer them,  
    I the God of Israel will not forsake them.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 41, 18, 'I will open rivers on the bare heights,  
    and fountains in the midst of the valleys;  
I will make the wilderness a pool of water,  
    and the dry land springs of water.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 41, 19, 'I will put in the wilderness the cedar,  
    the acacia, the myrtle, and the olive;  
I will set in the desert the cypress,  
    the plane and the pine together,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 41, 20, 'so that all may see and know,  
    all may consider and understand,  
that the hand of the LORD has done this,  
    the Holy One of Israel has created it.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 41, 21, 'Set forth your case, says the LORD;  
    bring your proofs, says the King of Jacob.', 'en', 'NRSV-CE', 'The Futility of Idols'),
(23, 'Yes', 'Isaiah', 41, 22, 'Let them bring them, and tell us  
    what is to happen.  
Tell us the former things, what they are,  
    so that we may consider them,  
and that we may know their outcome;  
    or declare to us the things to come.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 41, 23, 'Tell us what is to come hereafter,  
    that we may know that you are gods;  
do good, or do harm,  
    that we may be afraid and terrified.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 41, 24, 'You, indeed, are nothing  
    and your work is nothing at all;  
    whoever chooses you is an abomination.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 41, 25, 'I stirred up one from the north, and he has come,  
    from the rising of the sun he was summoned by name.  
He shall trample on rulers as on mortar,  
    as the potter treads clay.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 41, 26, 'Who declared it from the beginning, so that we might know,  
    and beforehand, so that we might say, "He is right"?  
There was no one who declared it, none who proclaimed,  
    none who heard your words.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 41, 27, 'I first have declared it to Zion,  
    and I give to Jerusalem a herald of good tidings.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 41, 28, 'But when I look there is no one;  
    among these there is no counselor  
    who, when I ask, gives an answer.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 41, 29, 'No, they are all a delusion;  
    their works are nothing;  
    their images are empty wind.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 42, 1, 'Here is my servant, whom I uphold,  
    my chosen, in whom my soul delights;  
I have put my spirit upon him;  
    he will bring forth justice to the nations.', 'en', 'NRSV-CE', 'The Servant, a Light to the Nations'),
(23, 'Yes', 'Isaiah', 42, 2, 'He will not cry or lift up his voice,  
    or make it heard in the street;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 42, 3, 'a bruised reed he will not break,  
    and a dimly burning wick he will not quench;  
    he will faithfully bring forth justice.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 42, 4, 'He will not grow faint or be crushed  
    until he has established justice in the earth;  
    and the coastlands wait for his teaching.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 42, 5, 'Thus says God, the LORD,  
    who created the heavens and stretched them out,  
    who spread out the earth and what comes from it,  
who gives breath to the people upon it  
    and spirit to those who walk in it:', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 42, 6, 'I am the LORD, I have called you in righteousness,  
    I have taken you by the hand and kept you;  
I have given you as a covenant to the people,  
    a light to the nations,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 42, 7, 'to open the eyes that are blind,  
to bring out the prisoners from the dungeon,  
    from the prison those who sit in darkness.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 42, 8, 'I am the LORD, that is my name;  
    my glory I give to no other,  
    nor my praise to idols.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 42, 9, 'See, the former things have come to pass,  
    and new things I now declare;  
before they spring forth,  
    I tell you of them.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 42, 10, 'Sing to the LORD a new song,  
    his praise from the end of the earth!  
Let the sea roar and all that fills it,  
    the coastlands and their inhabitants.', 'en', 'NRSV-CE', 'A Hymn of Praise'),
(23, 'Yes', 'Isaiah', 42, 11, 'Let the desert and its towns lift up their voice,  
    the villages that Kedar inhabits;  
let the inhabitants of Sela sing for joy,  
    let them shout from the tops of the mountains.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 42, 12, 'Let them give glory to the LORD,  
    and declare his praise in the coastlands.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 42, 13, 'The LORD goes forth like a soldier,  
    like a warrior he stirs up his fury;  
he cries out, he shouts aloud,  
    he shows himself mighty against his foes.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 42, 14, 'For a long time I have held my peace,  
    I have kept still and restrained myself;  
now I will cry out like a woman in labor,  
    I will gasp and pant.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 42, 15, 'I will lay waste mountains and hills,  
    and dry up all their herbage;  
I will turn the rivers into islands,  
    and dry up the pools.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 42, 16, 'I will lead the blind  
    by a road they do not know,  
by paths they have not known  
    I will guide them.  
I will turn the darkness before them into light,  
    the rough places into level ground.  
These are the things I will do,  
    and I will not forsake them.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 42, 17, 'They shall be turned back and utterly put to shame--  
    those who trust in carved images,  
who say to cast images,  
    "You are our gods."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 42, 18, 'Listen, you that are deaf;  
    and you that are blind, look up and see!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 42, 19, 'Who is blind but my servant,  
    or deaf like my messenger whom I send?  
Who is blind like my dedicated one,  
    or blind like the servant of the LORD?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 42, 20, 'He sees many things, but does not observe them;  
    his ears are open, but he does not hear.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 42, 21, 'The LORD was pleased, for the sake of his righteousness,  
    to magnify his teaching and make it glorious.', 'en', 'NRSV-CE', 'Israel"s Disobedience'),
(23, 'Yes', 'Isaiah', 42, 22, 'But this is a people robbed and plundered,  
    all of them are trapped in holes  
    and hidden in prisons;  
they have become a prey with no one to rescue,  
    a spoil with no one to say, "Restore!"', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 42, 23, 'Who among you will give heed to this,  
    who will attend and listen for the time to come?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 42, 24, 'Who gave up Jacob to the spoiler,  
    and Israel to the robbers?  
Was it not the LORD, against whom we have sinned,  
    in whose ways they would not walk,  
    and whose law they would not obey?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 42, 25, 'So he poured upon him the heat of his anger  
    and the fury of war;  
it set him on fire all around, but he did not understand;  
    it burned him, but he did not take it to heart.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 43, 1, 'But now thus says the LORD,  
    he who created you, O Jacob,  
    he who formed you, O Israel:  
Do not fear, for I have redeemed you;  
    I have called you by name, you are mine.', 'en', 'NRSV-CE', 'Restoration and Protection Promised'),
(23, 'Yes', 'Isaiah', 43, 2, 'When you pass through the waters, I will be with you;  
    and through the rivers, they shall not overwhelm you;  
when you walk through fire you shall not be burned,  
    and the flame shall not consume you.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 43, 3, 'For I am the LORD your God,  
    the Holy One of Israel, your Savior.  
I give Egypt as your ransom,  
    Ethiopia and Seba in exchange for you.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 43, 4, 'Because you are precious in my sight,  
    and honored, and I love you,  
I give people in return for you,  
    nations in exchange for your life.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 43, 5, 'Do not fear, for I am with you;  
    I will bring your offspring from the east,  
    and from the west I will gather you;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 43, 6, 'I will say to the north, "Give them up,"  
    and to the south, "Do not withhold;  
bring my sons from far away  
    and my daughters from the end of the earth--', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 43, 7, 'everyone who is called by my name,  
    whom I created for my glory,  
    whom I formed and made."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 43, 8, 'Bring forth the people who are blind, yet have eyes,  
    who are deaf, yet have ears!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 43, 9, 'Let all the nations gather together,  
    and let the peoples assemble.  
Who among them declared this,  
    and foretold to us the former things?  
Let them bring their witnesses to justify them,  
    and let them hear and say, "It is true."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 43, 10, 'You are my witnesses, says the LORD,  
    and my servant whom I have chosen,  
so that you may know and believe me  
    and understand that I am he.  
Before me no god was formed,  
    nor shall there be any after me.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 43, 11, 'I, I am the LORD,  
    and besides me there is no savior.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 43, 12, 'I declared and saved and proclaimed,  
    when there was no strange god among you;  
    and you are my witnesses, says the LORD.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 43, 13, 'I am God, and also henceforth I am He;  
    there is no one who can deliver from my hand;  
    I work and who can hinder it?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 43, 14, 'Thus says the LORD,  
    your Redeemer, the Holy One of Israel:  
For your sake I will send to Babylon  
    and break down all the bars,  
    and the shouting of the Chaldeans will be turned to lamentation.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 43, 15, 'I am the LORD, your Holy One,  
    the Creator of Israel, your King.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 43, 16, 'Thus says the LORD,  
    who makes a way in the sea,  
    a path in the mighty waters,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 43, 17, 'who brings out chariot and horse,  
    army and warrior;  
they lie down, they cannot rise,  
    they are extinguished, quenched like a wick:', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 43, 18, 'Do not remember the former things,  
    or consider the things of old.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 43, 19, 'I am about to do a new thing;  
    now it springs forth, do you not perceive it?  
I will make a way in the wilderness  
    and rivers in the desert.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 43, 20, 'The wild animals will honor me,  
    the jackals and the ostriches;  
for I give water in the wilderness,  
    rivers in the desert,  
to give drink to my chosen people,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 43, 21, 'the people whom I formed for myself  
so that they might declare my praise.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 43, 22, 'Yet you did not call upon me, O Jacob;  
    but you have been weary of me, O Israel!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 43, 23, 'You have not brought me your sheep for burnt offerings,  
    or honored me with your sacrifices.  
I have not burdened you with offerings,  
    or wearied you with frankincense.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 43, 24, 'You have not bought me sweet cane with money,  
    or satisfied me with the fat of your sacrifices.  
But you have burdened me with your sins;  
    you have wearied me with your iniquities.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 43, 25, 'I, I am He  
    who blots out your transgressions for my own sake,  
    and I will not remember your sins.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 43, 26, 'Accuse me, let us go to trial;  
    set forth your case, so that you may be proved right.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 43, 27, 'Your first ancestor sinned,  
    and your interpreters transgressed against me.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 43, 28, 'Therefore I profaned the princes of the sanctuary,  
    I delivered Jacob to utter destruction,  
    and Israel to reviling.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 44, 1, 'But now hear, O Jacob my servant,  
    Israel whom I have chosen!', 'en', 'NRSV-CE', 'God"s Blessing on Israel'),
(23, 'Yes', 'Isaiah', 44, 2, 'Thus says the LORD who made you,  
    who formed you in the womb and will help you:  
Do not fear, O Jacob my servant,  
    Jeshurun whom I have chosen.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 44, 3, 'For I will pour water on the thirsty land,  
    and streams on the dry ground;  
I will pour my spirit upon your descendants,  
    and my blessing on your offspring.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 44, 4, 'They shall spring up like a green tamarisk,  
    like willows by flowing streams.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 44, 5, 'This one will say, "I am the LORD"s,"  
    another will be called by the name of Jacob,  
yet another will write on the hand, "The LORD"s,"  
    and adopt the name of Israel.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 44, 6, 'Thus says the LORD, the King of Israel,  
    and his Redeemer, the LORD of hosts:  
I am the first and I am the last;  
    besides me there is no god.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 44, 7, 'Who is like me? Let them proclaim it,  
    let them declare and set it forth before me.  
Who has announced from of old the things to come?  
    Let them tell us what is yet to be.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 44, 8, 'Do not fear, or be afraid;  
    have I not told you from of old and declared it?  
    You are my witnesses!  
Is there any god besides me?  
    There is no other rock; I know not one.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 44, 9, 'All who make idols are nothing, and the things they delight in do not profit; their witnesses neither see nor know. And so they will be put to shame.', 'en', 'NRSV-CE', 'The Absurdity of Idol Worship'),
(23, 'Yes', 'Isaiah', 44, 10, 'Who would fashion a god or cast an image that can do no good?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 44, 11, 'Look, all its devotees shall be put to shame; the artisans too are merely human. Let them all assemble, let them stand up; they shall be terrified, they shall all be put to shame.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 44, 12, 'The ironsmith fashions it and works it over the coals, shaping it with hammers, and forging it with his strong arm; he becomes hungry and his strength fails, he drinks no water and is faint.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 44, 13, 'The carpenter stretches a line, marks it out with a stylus, fashions it with planes, and marks it with a compass; he makes it in human form, with human beauty, to be set up in a shrine.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 44, 14, 'He cuts down cedars or chooses a holm tree or an oak and lets it grow strong among the trees of the forest. He plants a cedar and the rain nourishes it.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 44, 15, 'Then it can be used as fuel. Part of it he takes and warms himself; he kindles a fire and bakes bread. Then he makes a god and worships it, makes it a carved image and bows down before it.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 44, 16, 'Half of it he burns in the fire; over this half he roasts meat, eats it and is satisfied. He also warms himself and says, "Ah, I am warm, I can feel the fire!"', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 44, 17, 'The rest of it he makes into a god, his idol, bows down to it and worships it; he prays to it and says, "Save me, for you are my god!"', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 44, 18, 'They do not know, nor do they comprehend; for their eyes are shut, so that they cannot see, and their minds as well, so that they cannot understand.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 44, 19, 'No one considers, nor is there knowledge or discernment to say, "Half of it I burned in the fire; I also baked bread on its coals, I roasted meat and have eaten. Now shall I make the rest of it an abomination? Shall I fall down before a block of wood?"', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 44, 20, 'He feeds on ashes; a deluded mind has led him astray, and he cannot save himself or say, "Is not this thing in my right hand a fraud?"', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 44, 21, 'Remember these things, O Jacob,  
    and Israel, for you are my servant;  
I formed you, you are my servant;  
    O Israel, you will not be forgotten by me.', 'en', 'NRSV-CE', 'Israel Is Not Forgotten'),
(23, 'Yes', 'Isaiah', 44, 22, 'I have swept away your transgressions like a cloud,  
    and your sins like mist;  
return to me, for I have redeemed you.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 44, 23, 'Sing, O heavens, for the LORD has done it;  
    shout, O depths of the earth;  
break forth into singing, O mountains,  
    O forest, and every tree in it!  
For the LORD has redeemed Jacob,  
    and will be glorified in Israel.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 44, 24, 'Thus says the LORD, your Redeemer,  
    who formed you in the womb:  
I am the LORD, who made all things,  
    who alone stretched out the heavens,  
    who by myself spread out the earth;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 44, 25, 'who frustrates the omens of liars,  
    and makes fools of diviners;  
who turns back the wise,  
    and makes their knowledge foolish;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 44, 26, 'who confirms the word of his servant,  
    and fulfills the prediction of his messengers;  
who says of Jerusalem, "It shall be inhabited,"  
    and of the cities of Judah, "They shall be rebuilt,  
    and I will raise up their ruins";', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 44, 27, 'who says to the deep, "Be dry--  
    I will dry up your rivers";', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 44, 28, 'who says of Cyrus, "He is my shepherd,  
    and he shall carry out all my purpose";  
and who says of Jerusalem, "It shall be rebuilt,"  
    and of the temple, "Your foundation shall be laid."', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 45, 1, 'Thus says the LORD to his anointed, to Cyrus,  
    whose right hand I have grasped  
to subdue nations before him  
    and strip kings of their robes,  
to open doors before him--  
    and the gates shall not be closed:', 'en', 'NRSV-CE', 'Cyrus, God"s Instrument'),
(23, 'Yes', 'Isaiah', 45, 2, 'I will go before you  
    and level the mountains,  
I will break in pieces the doors of bronze  
    and cut through the bars of iron,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 45, 3, 'I will give you the treasures of darkness  
    and riches hidden in secret places,  
so that you may know that it is I, the LORD,  
    the God of Israel, who call you by your name.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 45, 4, 'For the sake of my servant Jacob,  
    and Israel my chosen,  
I call you by your name,  
    I surname you, though you do not know me.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 45, 5, 'I am the LORD, and there is no other;  
    besides me there is no god.  
    I arm you, though you do not know me,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 45, 6, 'so that they may know, from the rising of the sun  
    and from the west, that there is no one besides me;  
    I am the LORD, and there is no other.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 45, 7, 'I form light and create darkness,  
    I make weal and create woe;  
    I the LORD do all these things.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 45, 8, 'Shower, O heavens, from above,  
    and let the skies rain down righteousness;  
let the earth open, that salvation may spring up,  
    and let it cause righteousness to sprout up also;  
    I the LORD have created it.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 45, 9, 'Woe to you who strive with your Maker,  
    earthen vessels with the potter!  
Does the clay say to the one who fashions it, "What are you making"?  
    or "Your work has no handles"?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 45, 10, 'Woe to anyone who says to a father, "What are you begetting?"  
    or to a woman, "With what are you in labor?"', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 45, 11, 'Thus says the LORD,  
    the Holy One of Israel, and its Maker:  
Will you question me about my children,  
    or command me concerning the work of my hands?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 45, 12, 'I made the earth,  
    and created humankind upon it;  
it was my hands that stretched out the heavens,  
    and I commanded all their host.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 45, 13, 'I have aroused Cyrus in righteousness,  
    and I will make all his paths straight;  
he shall build my city  
    and set my exiles free,  
not for price or reward,  
    says the LORD of hosts.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 45, 14, 'Thus says the LORD:  
The wealth of Egypt and the merchandise of Ethiopia,  
    and the Sabeans, tall of stature,  
shall come over to you and be yours,  
    they shall follow you;  
    they shall come over in chains and bow down to you.  
They will make supplication to you, saying,  
    "God is with you alone, and there is no other;  
    there is no god besides him."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 45, 15, 'Truly, you are a God who hides himself,  
    O God of Israel, the Savior.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 45, 16, 'All of them are put to shame and confounded,  
    the makers of idols go in confusion together.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 45, 17, 'But Israel is saved by the LORD  
    with everlasting salvation;  
you shall not be put to shame or confounded  
    to all eternity.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 45, 18, 'For thus says the LORD,  
who created the heavens  
    (he is God!),  
who formed the earth and made it  
    (he established it;  
he did not create it a chaos,  
    he formed it to be inhabited!):  
I am the LORD, and there is no other.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 45, 19, 'I did not speak in secret,  
    in a land of darkness;  
I did not say to the offspring of Jacob,  
    "Seek me in chaos."  
I the LORD speak the truth,  
    I declare what is right.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 45, 20, 'Assemble yourselves and come together,  
    draw near, you survivors of the nations!  
They have no knowledge--  
    those who carry about their wooden idols,  
and keep on praying to a god  
    that cannot save.', 'en', 'NRSV-CE', 'Idols Cannot Save Babylon'),
(23, 'Yes', 'Isaiah', 45, 21, 'Declare and present your case;  
    let them take counsel together!  
Who told this long ago?  
    Who declared it of old?  
Was it not I, the LORD?  
    There is no other god besides me,  
a righteous God and a Savior;  
    there is no one besides me.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 45, 22, 'Turn to me and be saved,  
    all the ends of the earth!  
    For I am God, and there is no other.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 45, 23, 'By myself I have sworn,  
    from my mouth has gone forth in righteousness  
    a word that shall not return:  
"To me every knee shall bow,  
    every tongue shall swear."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 45, 24, 'Only in the LORD, it shall be said of me,  
    are righteousness and strength;  
all who were incensed against him  
    shall come to him and be ashamed.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 45, 25, 'In the LORD all the offspring of Israel  
    shall triumph and glory.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 46, 1, 'Bel bows down, Nebo stoops,  
    their idols are on beasts and cattle;  
these things you carry are loaded  
    as burdens on weary animals.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 46, 2, 'They stoop, they bow down together;  
    they cannot save the burden,  
    but themselves go into captivity.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 46, 3, 'Listen to me, O house of Jacob,  
    all the remnant of the house of Israel,  
who have been borne by me from your birth,  
    carried from the womb;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 46, 4, 'even to your old age I am he,  
    even when you turn gray I will carry you.  
I have made, and I will bear;  
    I will carry and will save.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 46, 5, 'To whom will you liken me and make me equal,  
    and compare me, as though we were alike?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 46, 6, 'Those who lavish gold from the purse,  
    and weigh out silver in the scales--  
they hire a goldsmith, who makes it into a god;  
    then they fall down and worship!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 46, 7, 'They lift it to their shoulders, they carry it,  
    they set it in its place, and it stands there;  
    it cannot move from its place.  
If one cries out to it, it does not answer  
    or save anyone from trouble.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 46, 8, 'Remember this and consider,  
    recall it to mind, you transgressors,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 46, 9, 'remember the former things of old;  
for I am God, and there is no other;  
    I am God, and there is no one like me,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 46, 10, 'declaring the end from the beginning  
    and from ancient times things not yet done,  
saying, "My purpose shall stand,  
    and I will fulfill my intention,"', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 46, 11, 'calling a bird of prey from the east,  
    the man for my purpose from a far country.  
I have spoken, and I will bring it to pass;  
    I have planned, and I will do it.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 46, 12, 'Listen to me, you stubborn of heart,  
    you who are far from deliverance:', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 46, 13, 'I bring near my deliverance, it is not far off,  
    and my salvation will not tarry;  
I will put salvation in Zion,  
    for Israel my glory.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 47, 1, 'Come down and sit in the dust,  
    virgin daughter Babylon!  
Sit on the ground without a throne,  
    daughter Chaldea!  
For you shall no more be called  
    tender and delicate.', 'en', 'NRSV-CE', 'The Humiliation of Babylon'),
(23, 'Yes', 'Isaiah', 47, 2, 'Take the millstones and grind meal,  
    remove your veil,  
strip off your robe, uncover your legs,  
    pass through the rivers.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 47, 3, 'Your nakedness shall be uncovered,  
    and your shame shall be seen.  
I will take vengeance,  
    and I will spare no one.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 47, 4, 'Our Redeemer--the LORD of hosts is his name--  
    is the Holy One of Israel.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 47, 5, 'Sit in silence, and go into darkness,  
    daughter Chaldea!  
For you shall no more be called  
    the mistress of kingdoms.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 47, 6, 'I was angry with my people,  
    I profaned my heritage;  
I gave them into your hand,  
    you showed them no mercy;  
on the aged you made your yoke  
    exceedingly heavy.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 47, 7, 'You said, "I shall be mistress forever,"  
    so that you did not lay these things to heart  
    or remember their end.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 47, 8, 'Now therefore hear this, you lover of pleasures,  
    who sit securely,  
who say in your heart,  
    "I am, and there is no one besides me;  
I shall not sit as a widow  
    or know the loss of children"--', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 47, 9, 'both these things shall come upon you  
    in a moment, in one day:  
the loss of children and widowhood  
    shall come upon you in full measure,  
in spite of your many sorceries  
    and the great power of your enchantments.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 47, 10, 'You felt secure in your wickedness;  
    you said, "No one sees me."  
Your wisdom and your knowledge  
    led you astray,  
and you said in your heart,  
    "I am, and there is no one besides me."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 47, 11, 'But evil shall come upon you,  
    which you cannot charm away;  
disaster shall fall upon you,  
    which you will not be able to ward off;  
and ruin shall come on you suddenly,  
    of which you know nothing.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 47, 12, 'Stand fast in your enchantments  
    and your many sorceries,  
    with which you have labored from your youth;  
perhaps you may be able to succeed,  
    perhaps you may inspire terror.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 47, 13, 'You are wearied with your many consultations;  
    let those who study the heavens  
stand up and save you,  
    those who gaze at the stars,  
and at each new moon predict  
    what shall befall you.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 47, 14, 'See, they are like stubble,  
    the fire consumes them;  
they cannot deliver themselves  
    from the power of the flame.  
No coal for warming oneself is this,  
    no fire to sit before!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 47, 15, 'Such to you are those with whom you have labored,  
    who have trafficked with you from your youth;  
they all wander about in their own paths;  
    there is no one to save you.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 48, 1, 'Hear this, O house of Jacob,  
    who are called by the name of Israel,  
    and who came forth from the loins of Judah;  
who swear by the name of the LORD,  
    and invoke the God of Israel,  
    but not in truth or right.', 'en', 'NRSV-CE', 'God the Creator and Redeemer'),
(23, 'Yes', 'Isaiah', 48, 2, 'For they call themselves after the holy city,  
    and lean on the God of Israel;  
    the LORD of hosts is his name.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 48, 3, 'The former things I declared long ago,  
    they went out from my mouth and I made them known;  
    then suddenly I did them and they came to pass.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 48, 4, 'Because I know that you are obstinate,  
    and your neck is an iron sinew  
    and your forehead brass,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 48, 5, 'I declared them to you from long ago,  
    before they came to pass I announced them to you,  
so that you would not say, "My idol did them,  
    my carved image and my cast image commanded them."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 48, 6, 'You have heard; now see all this;  
    and will you not declare it?  
From this time forward I make you hear new things,  
    hidden things that you have not known.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 48, 7, 'They are created now, not long ago;  
    before today you have never heard of them,  
    so that you could not say, "I already knew them."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 48, 8, 'You have never heard, you have never known,  
    from of old your ear has not been opened.  
For I knew that you would deal very treacherously,  
    and that from birth you were called a rebel.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 48, 9, 'For my name"s sake I defer my anger,  
    for the sake of my praise I restrain it for you,  
    so that I may not cut you off.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 48, 10, 'See, I have refined you, but not like silver;  
    I have tested you in the furnace of adversity.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 48, 11, 'For my own sake, for my own sake, I do it,  
    for why should my name be profaned?  
    My glory I will not give to another.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 48, 12, 'Listen to me, O Jacob,  
    and Israel, whom I called:  
I am He; I am the first,  
    and I am the last.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 48, 13, 'My hand laid the foundation of the earth,  
    and my right hand spread out the heavens;  
when I summon them,  
    they stand at attention.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 48, 14, 'Assemble, all of you, and hear!  
    Who among them has declared these things?  
The LORD loves him;  
    he shall perform his purpose on Babylon,  
    and his arm shall be against the Chaldeans.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 48, 15, 'I, even I, have spoken and called him,  
    I have brought him, and he will prosper in his way.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 48, 16, 'Draw near to me, hear this!  
    From the beginning I have not spoken in secret,  
    from the time it came to be I have been there.  
And now the Lord God has sent me and his spirit.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 48, 17, 'Thus says the LORD,  
    your Redeemer, the Holy One of Israel:  
I am the LORD your God,  
    who teaches you for your own good,  
    who leads you in the way you should go.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 48, 18, 'O that you had paid attention to my commandments!  
    Then your prosperity would have been like a river,  
    and your success like the waves of the sea;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 48, 19, 'your offspring would have been like the sand,  
    and your descendants like its grains;  
their name would never be cut off  
    or destroyed from before me.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 48, 20, 'Go out from Babylon, flee from Chaldea,  
    declare this with a shout of joy, proclaim it,  
send it forth to the end of the earth;  
    say, "The LORD has redeemed his servant Jacob!"', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 48, 21, 'They did not thirst when he led them through the deserts;  
    he made water flow for them from the rock;  
    he split open the rock and the water gushed out.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 48, 22, '"There is no peace," says the LORD, "for the wicked."', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 49, 1, 'Listen to me, O coastlands,  
    pay attention, you peoples from far away!  
The LORD called me before I was born,  
    while I was in my mother"s womb he named me.', 'en', 'NRSV-CE', 'The Servant"s Mission'),
(23, 'Yes', 'Isaiah', 49, 2, 'He made my mouth like a sharp sword,  
    in the shadow of his hand he hid me;  
he made me a polished arrow,  
    in his quiver he hid me away.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 49, 3, 'And he said to me, "You are my servant,  
    Israel, in whom I will be glorified."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 49, 4, 'But I said, "I have labored in vain,  
    I have spent my strength for nothing and vanity;  
yet surely my cause is with the LORD,  
    and my reward with my God."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 49, 5, 'And now the LORD says,  
    who formed me in the womb to be his servant,  
to bring Jacob back to him,  
    and that Israel might be gathered to him,  
for I am honored in the sight of the LORD,  
    and my God has become my strength--', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 49, 6, 'he says,  
"It is too light a thing that you should be my servant  
    to raise up the tribes of Jacob  
    and to restore the survivors of Israel;  
I will give you as a light to the nations,  
    that my salvation may reach to the end of the earth."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 49, 7, 'Thus says the LORD,  
    the Redeemer of Israel and his Holy One,  
to one deeply despised, abhorred by the nations,  
    the slave of rulers,  
"Kings shall see and stand up,  
    princes, and they shall prostrate themselves,  
because of the LORD, who is faithful,  
    the Holy One of Israel, who has chosen you."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 49, 8, 'Thus says the LORD:  
In a time of favor I have answered you,  
    on a day of salvation I have helped you;  
I have kept you and given you  
    as a covenant to the people,  
to establish the land,  
    to apportion the desolate heritages;', 'en', 'NRSV-CE', 'Zion"s Children to Be Brought Home'),
(23, 'Yes', 'Isaiah', 49, 9, 'saying to the prisoners, "Come out,"  
    to those who are in darkness, "Show yourselves."  
They shall feed along the ways,  
    on all the bare heights shall be their pasture;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 49, 10, 'they shall not hunger or thirst,  
    neither scorching wind nor sun shall strike them down,  
for he who has pity on them will lead them,  
    and by springs of water will guide them.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 49, 11, 'And I will turn all my mountains into a road,  
    and my highways shall be raised up.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 49, 12, 'Lo, these shall come from far away,  
    and lo, these from the north and from the west,  
    and these from the land of Syene.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 49, 13, 'Sing for joy, O heavens, and exult, O earth;  
    break forth, O mountains, into singing!  
For the LORD has comforted his people,  
    and will have compassion on his suffering ones.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 49, 14, 'But Zion said, "The LORD has forsaken me,  
    my Lord has forgotten me."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 49, 15, 'Can a woman forget her nursing child,  
    or show no compassion for the child of her womb?  
Even these may forget,  
    yet I will not forget you.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 49, 16, 'See, I have inscribed you on the palms of my hands;  
    your walls are continually before me.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 49, 17, 'Your builders outdo your destroyers,  
    and those who laid you waste go away from you.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 49, 18, 'Lift up your eyes all around and see;  
    they all gather, they come to you.  
As I live, says the LORD,  
    you shall put all of them on like an ornament,  
    and like a bride you shall bind them on.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 49, 19, 'Surely your waste and your desolate places  
    and your devastated land--  
surely now you will be too crowded for your inhabitants,  
    and those who swallowed you up will be far away.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 49, 20, 'The children born in the time of your bereavement  
    will yet say in your hearing:  
"The place is too crowded for me;  
    make room for me to settle."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 49, 21, 'Then you will say in your heart,  
    "Who has borne me these?  
I was bereaved and barren,  
    exiled and put away--  
    so who has reared these?  
I was left all alone--  
    where then have these come from?"', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 49, 22, 'Thus says the Lord God:  
I will soon lift up my hand to the nations,  
    and raise my signal to the peoples;  
and they shall bring your sons in their bosom,  
    and your daughters shall be carried on their shoulders.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 49, 23, 'Kings shall be your foster fathers,  
    and their queens your nursing mothers.  
With their faces to the ground they shall bow down to you,  
    and lick the dust of your feet.  
Then you will know that I am the LORD;  
    those who wait for me shall not be put to shame.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 49, 24, 'Can the prey be taken from the mighty,  
    or the captives of a tyrant be rescued?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 49, 25, 'But thus says the LORD:  
Even the captives of the mighty shall be taken,  
    and the prey of the tyrant be rescued;  
for I will contend with those who contend with you,  
    and I will save your children.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 49, 26, 'I will make your oppressors eat their own flesh,  
    and they shall be drunk with their own blood as with wine.  
Then all flesh shall know  
    that I am the LORD your Savior,  
    and your Redeemer, the Mighty One of Jacob.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 50, 1, 'Thus says the LORD:  
Where is your mother"s bill of divorce  
    with which I put her away?  
Or which of my creditors is it  
    to whom I have sold you?  
No, because of your sins you were sold,  
    and for your transgressions your mother was put away.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 50, 2, 'Why was no one there when I came?  
    Why did no one answer when I called?  
Is my hand shortened, that it cannot redeem?  
    Or have I no power to deliver?  
By my rebuke I dry up the sea,  
    I make the rivers a desert;  
their fish stink for lack of water,  
    and die of thirst.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 50, 3, 'I clothe the heavens with blackness,  
    and make sackcloth their covering.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 50, 4, 'The Lord God has given me  
    the tongue of a teacher,  
that I may know how to sustain  
    the weary with a word.  
Morning by morning he wakens--  
    wakens my ear  
    to listen as those who are taught.', 'en', 'NRSV-CE', 'The Servant"s Humiliation and Vindication'),
(23, 'Yes', 'Isaiah', 50, 5, 'The Lord God has opened my ear,  
    and I was not rebellious,  
    I did not turn backward.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 50, 6, 'I gave my back to those who struck me,  
    and my cheeks to those who pulled out the beard;  
I did not hide my face  
    from insult and spitting.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 50, 7, 'The Lord God helps me;  
    therefore I have not been disgraced;  
therefore I have set my face like flint,  
    and I know that I shall not be put to shame;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 50, 8, 'he who vindicates me is near.  
Who will contend with me?  
    Let us stand up together.  
Who are my adversaries?  
    Let them confront me.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 50, 9, 'It is the Lord God who helps me;  
    who will declare me guilty?  
All of them will wear out like a garment;  
    the moth will eat them up.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 50, 10, 'Who among you fears the LORD  
    and obeys the voice of his servant,  
who walks in darkness  
    and has no light,  
yet trusts in the name of the LORD  
    and relies upon his God?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 50, 11, 'But all of you are kindlers of fire,  
    lighters of firebrands.  
Walk in the flame of your fire,  
    and among the brands that you have kindled!  
This is what you shall have from my hand:  
    you shall lie down in torment.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 51, 1, 'Listen to me, you that pursue righteousness,  
    you that seek the LORD.  
Look to the rock from which you were hewn,  
    and to the quarry from which you were dug.', 'en', 'NRSV-CE', 'Blessings in Store for God"s People'),
(23, 'Yes', 'Isaiah', 51, 2, 'Look to Abraham your father  
    and to Sarah who bore you;  
for he was but one when I called him,  
    but I blessed him and made him many.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 51, 3, 'For the LORD will comfort Zion;  
    he will comfort all her waste places,  
and will make her wilderness like Eden,  
    her desert like the garden of the LORD;  
joy and gladness will be found in her,  
    thanksgiving and the voice of song.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 51, 4, 'Listen to me, my people,  
    and give heed to me, my nation;  
for a teaching will go out from me,  
    and my justice for a light to the peoples.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 51, 5, 'I will bring near my deliverance swiftly,  
    my salvation has gone out  
    and my arms will rule the peoples;  
the coastlands wait for me,  
    and for my arm they hope.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 51, 6, 'Lift up your eyes to the heavens,  
    and look at the earth beneath;  
for the heavens will vanish like smoke,  
    the earth will wear out like a garment,  
    and those who live on it will die like gnats;  
but my salvation will be forever,  
    and my deliverance will never be ended.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 51, 7, 'Listen to me, you who know righteousness,  
    you people who have my teaching in your hearts;  
do not fear the reproach of others,  
    and do not be dismayed when they revile you.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 51, 8, 'For the moth will eat them up like a garment,  
    and the worm will eat them like wool;  
but my deliverance will be forever,  
    and my salvation to all generations.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 51, 9, 'Awake, awake, put on strength,  
    O arm of the LORD!  
Awake, as in days of old,  
    the generations of long ago!  
Was it not you who cut Rahab in pieces,  
    who pierced the dragon?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 51, 10, 'Was it not you who dried up the sea,  
    the waters of the great deep;  
who made the depths of the sea a way  
    for the redeemed to cross over?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 51, 11, 'So the ransomed of the LORD shall return,  
    and come to Zion with singing;  
everlasting joy shall be upon their heads;  
    they shall obtain joy and gladness,  
    and sorrow and sighing shall flee away.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 51, 12, 'I, I am he who comforts you;  
    why then are you afraid of a mere mortal who must die,  
    a human being who fades like grass?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 51, 13, 'You have forgotten the LORD, your Maker,  
    who stretched out the heavens  
    and laid the foundations of the earth.  
You fear continually all day long  
    because of the fury of the oppressor,  
who is bent on destruction.  
    But where is the fury of the oppressor?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 51, 14, 'The oppressed shall speedily be released;  
    they shall not die and go down to the Pit,  
    nor shall they lack bread.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 51, 15, 'For I am the LORD your God,  
    who stirs up the sea so that its waves roar--  
    the LORD of hosts is his name.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 51, 16, 'I have put my words in your mouth,  
    and hidden you in the shadow of my hand,  
stretching out the heavens  
    and laying the foundations of the earth,  
    and saying to Zion, "You are my people."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 51, 17, 'Rouse yourself, rouse yourself!  
    Stand up, O Jerusalem,  
you who have drunk at the hand of the LORD  
    the cup of his wrath,  
who have drunk to the dregs  
    the bowl of staggering.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 51, 18, 'There is no one to guide her  
    among all the children she has borne;  
there is no one to take her by the hand  
    among all the children she has brought up.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 51, 19, 'These two things have befallen you  
    --who will grieve with you?--  
devastation and destruction, famine and sword--  
    who will comfort you?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 51, 20, 'Your children have fainted,  
    they lie at the head of every street  
    like an antelope in a net;  
they are full of the wrath of the LORD,  
    the rebuke of your God.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 51, 21, 'Therefore hear this, you who are wounded,  
    who are drunk, but not with wine:', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 51, 22, 'Thus says your Sovereign, the LORD,  
    your God who pleads the cause of his people:  
See, I have taken from your hand the cup of staggering;  
you shall drink no more  
    from the bowl of my wrath.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 51, 23, 'And I will put it into the hand of your tormentors,  
    who have said to you,  
    "Bow down, that we may walk on you";  
and you have made your back like the ground  
    and like the street for them to walk on.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 52, 1, 'Awake, awake,  
    put on your strength, O Zion!  
Put on your beautiful garments,  
    O Jerusalem, the holy city;  
for the uncircumcised and the unclean  
    shall enter you no more.', 'en', 'NRSV-CE', 'Let Zion Rejoice'),
(23, 'Yes', 'Isaiah', 52, 2, 'Shake yourself from the dust, rise up,  
    O captive Jerusalem;  
loose the bonds from your neck,  
    O captive daughter Zion!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 52, 3, 'For thus says the LORD: You were sold for nothing, and you shall be redeemed without money.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 52, 4, 'For thus says the Lord God: Long ago, my people went down into Egypt to reside there as aliens; the Assyrian, too, has oppressed them without cause.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 52, 5, 'Now therefore what am I doing here, says the LORD, seeing that my people are taken away without cause? Their rulers howl, says the LORD, and continually, all day long, my name is despised.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 52, 6, 'Therefore my people shall know my name; therefore in that day they shall know that it is I who speak; here am I.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 52, 7, 'How beautiful upon the mountains  
    are the feet of the messenger who announces peace,  
who brings good news,  
    who announces salvation,  
    who says to Zion, "Your God reigns."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 52, 8, 'Listen! Your sentinels lift up their voices,  
    together they sing for joy;  
for in plain sight they see  
    the return of the LORD to Zion.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 52, 9, 'Break forth together into singing,  
    you ruins of Jerusalem;  
for the LORD has comforted his people,  
    he has redeemed Jerusalem.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 52, 10, 'The LORD has bared his holy arm  
    before the eyes of all the nations;  
and all the ends of the earth shall see  
    the salvation of our God.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 52, 11, 'Depart, depart, go out from there!  
    Touch no unclean thing;  
go out from the midst of it, purify yourselves,  
    you who carry the vessels of the LORD.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 52, 12, 'For you shall not go out in haste,  
    and you shall not go in flight;  
for the LORD will go before you,  
    and the God of Israel will be your rear guard.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 52, 13, 'See, my servant shall prosper;  
    he shall be exalted and lifted up,  
    and shall be very high.', 'en', 'NRSV-CE', 'The Suffering Servant'),
(23, 'Yes', 'Isaiah', 52, 14, 'Just as there were many who were astonished at him  
    --so marred was his appearance, beyond human semblance,  
    and his form beyond that of mortals--', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 52, 15, 'so he shall startle many nations;  
    kings shall shut their mouths because of him;  
for that which had not been told them they shall see,  
    and that which they had not heard they shall contemplate.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 53, 1, 'Who has believed what we have heard?  
    And to whom has the arm of the LORD been revealed?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 53, 2, 'For he grew up before him like a young plant,  
    and like a root out of dry ground;  
he had no form or majesty that we should look at him,  
    nothing in his appearance that we should desire him.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 53, 3, 'He was despised and rejected by others;  
    a man of suffering and acquainted with infirmity;  
and as one from whom others hide their faces  
    he was despised, and we held him of no account.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 53, 4, 'Surely he has borne our infirmities  
    and carried our diseases;  
yet we accounted him stricken,  
    struck down by God, and afflicted.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 53, 5, 'But he was wounded for our transgressions,  
    crushed for our iniquities;  
upon him was the punishment that made us whole,  
    and by his bruises we are healed.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 53, 6, 'All we like sheep have gone astray;  
    we have all turned to our own way,  
and the LORD has laid on him  
    the iniquity of us all.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 53, 7, 'He was oppressed, and he was afflicted,  
    yet he did not open his mouth;  
like a lamb that is led to the slaughter,  
    and like a sheep that before its shearers is silent,  
    so he did not open his mouth.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 53, 8, 'By a perversion of justice he was taken away.  
    Who could have imagined his future?  
For he was cut off from the land of the living,  
    stricken for the transgression of my people.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 53, 9, 'They made his grave with the wicked  
    and his tomb with the rich,  
although he had done no violence,  
    and there was no deceit in his mouth.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 53, 10, 'Yet it was the will of the LORD to crush him with pain.  
When you make his life an offering for sin,  
    he shall see his offspring, and shall prolong his days;  
through him the will of the LORD shall prosper.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 53, 11, 'Out of his anguish he shall see light;  
he shall find satisfaction through his knowledge.  
    The righteous one, my servant, shall make many righteous,  
    and he shall bear their iniquities.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 53, 12, 'Therefore I will allot him a portion with the great,  
    and he shall divide the spoil with the strong;  
because he poured out himself to death,  
    and was numbered with the transgressors;  
yet he bore the sin of many,  
    and made intercession for the transgressors.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 54, 1, 'Sing, O barren one who did not bear;  
    burst into song and shout,  
    you who have not been in labor!  
For the children of the desolate woman will be more  
    than the children of her that is married, says the LORD.', 'en', 'NRSV-CE', 'The Eternal Covenant of Peace'),
(23, 'Yes', 'Isaiah', 54, 2, 'Enlarge the site of your tent,  
    and let the curtains of your habitations be stretched out;  
do not hold back; lengthen your cords  
    and strengthen your stakes.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 54, 3, 'For you will spread out to the right and to the left,  
    and your descendants will possess the nations  
    and will settle the desolate towns.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 54, 4, 'Do not fear, for you will not be ashamed;  
    do not be discouraged, for you will not suffer disgrace;  
for you will forget the shame of your youth,  
    and the disgrace of your widowhood you will remember no more.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 54, 5, 'For your Maker is your husband,  
    the LORD of hosts is his name;  
the Holy One of Israel is your Redeemer,  
    the God of the whole earth he is called.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 54, 6, 'For the LORD has called you  
    like a wife forsaken and grieved in spirit,  
like the wife of a man"s youth when she is cast off,  
    says your God.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 54, 7, 'For a brief moment I abandoned you,  
    but with great compassion I will gather you.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 54, 8, 'In overflowing wrath for a moment  
    I hid my face from you,  
but with everlasting love I will have compassion on you,  
    says the LORD, your Redeemer.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 54, 9, 'This is like the days of Noah to me:  
    Just as I swore that the waters of Noah  
    would never again go over the earth,  
so I have sworn that I will not be angry with you  
    and will not rebuke you.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 54, 10, 'For the mountains may depart  
    and the hills be removed,  
but my steadfast love shall not depart from you,  
    and my covenant of peace shall not be removed,  
    says the LORD, who has compassion on you.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 54, 11, 'O afflicted one, storm-tossed, and not comforted,  
    I am about to set your stones in antimony,  
    and lay your foundations with sapphires.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 54, 12, 'I will make your pinnacles of rubies,  
    your gates of jewels,  
    and all your wall of precious stones.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 54, 13, 'All your children shall be taught by the LORD,  
    and great shall be the prosperity of your children.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 54, 14, 'In righteousness you shall be established;  
    you shall be far from oppression, for you shall not fear;  
    and from terror, for it shall not come near you.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 54, 15, 'If anyone stirs up strife,  
    it is not from me;  
whoever stirs up strife with you  
    shall fall because of you.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 54, 16, 'See it is I who have created the smith  
    who blows the fire of coals,  
    and produces a weapon fit for its purpose;  
I have also created the ravager to destroy.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 54, 17, 'No weapon that is fashioned against you shall prosper,  
    and you shall confute every tongue that rises against you in judgment.  
This is the heritage of the servants of the LORD  
    and their vindication from me, says the LORD.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 55, 1, 'Ho, everyone who thirsts,  
    come to the waters;  
and you that have no money,  
    come, buy and eat!  
Come, buy wine and milk  
    without money and without price.', 'en', 'NRSV-CE', 'An Invitation to Abundant Life'),
(23, 'Yes', 'Isaiah', 55, 2, 'Why do you spend your money for that which is not bread,  
    and your labor for that which does not satisfy?  
Listen carefully to me, and eat what is good,  
    and delight yourselves in rich food.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 55, 3, 'Incline your ear, and come to me;  
    listen, so that you may live.  
I will make with you an everlasting covenant,  
    my steadfast, sure love for David.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 55, 4, 'See, I made him a witness to the peoples,  
    a leader and commander for the peoples.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 55, 5, 'See, you shall call nations that you do not know,  
    and nations that do not know you shall run to you,  
because of the LORD your God, the Holy One of Israel,  
    for he has glorified you.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 55, 6, 'Seek the LORD while he may be found,  
    call upon him while he is near;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 55, 7, 'let the wicked forsake their way,  
    and the unrighteous their thoughts;  
let them return to the LORD, that he may have mercy on them,  
    and to our God, for he will abundantly pardon.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 55, 8, 'For my thoughts are not your thoughts,  
    nor are your ways my ways, says the LORD.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 55, 9, 'For as the heavens are higher than the earth,  
    so are my ways higher than your ways  
    and my thoughts than your thoughts.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 55, 10, 'For as the rain and the snow come down from heaven,  
    and do not return there until they have watered the earth,  
making it bring forth and sprout,  
    giving seed to the sower and bread to the eater,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 55, 11, 'so shall my word be that goes out from my mouth;  
    it shall not return to me empty,  
but it shall accomplish that which I purpose,  
    and succeed in the thing for which I sent it.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 55, 12, 'For you shall go out in joy,  
    and be led back in peace;  
the mountains and the hills before you  
    shall burst into song,  
    and all the trees of the field shall clap their hands.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 55, 13, 'Instead of the thorn shall come up the cypress;  
    instead of the brier shall come up the myrtle;  
and it shall be to the LORD for a memorial,  
    for an everlasting sign that shall not be cut off.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 56, 1, 'Thus says the LORD:  
    Maintain justice, and do what is right,  
for soon my salvation will come,  
    and my deliverance be revealed.', 'en', 'NRSV-CE', 'The Covenant Extended to All Who Obey'),
(23, 'Yes', 'Isaiah', 56, 2, 'Happy is the mortal who does this,  
    the one who holds it fast,  
who keeps the sabbath, not profaning it,  
    and refrains from doing any evil.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 56, 3, 'Do not let the foreigner joined to the LORD say,  
    "The LORD will surely separate me from his people";  
and do not let the eunuch say,  
    "I am just a dry tree."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 56, 4, 'For thus says the LORD:  
To the eunuchs who keep my sabbaths,  
    who choose the things that please me  
    and hold fast my covenant,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 56, 5, 'I will give, in my house and within my walls,  
    a monument and a name  
    better than sons and daughters;  
I will give them an everlasting name  
    that shall not be cut off.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 56, 6, 'And the foreigners who join themselves to the LORD,  
    to minister to him, to love the name of the LORD,  
    and to be his servants,  
all who keep the sabbath, and do not profane it,  
    and hold fast my covenant--', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 56, 7, 'these I will bring to my holy mountain,  
    and make them joyful in my house of prayer;  
their burnt offerings and their sacrifices  
    will be accepted on my altar;  
for my house shall be called a house of prayer  
    for all peoples.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 56, 8, 'Thus says the Lord God,  
    who gathers the outcasts of Israel,  
I will gather others to them  
    besides those already gathered.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 56, 9, 'All you wild animals,  
    all you wild animals in the forest, come to devour!', 'en', 'NRSV-CE', 'The Corruption of Israel"s Rulers'),
(23, 'Yes', 'Isaiah', 56, 10, 'Israel"s sentinels are blind,  
    they are all without knowledge;  
they are all silent dogs  
    that cannot bark;  
dreaming, lying down,  
    loving to slumber.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 56, 11, 'The dogs have a mighty appetite;  
    they never have enough.  
The shepherds also have no understanding;  
    they have all turned to their own way,  
    to their own gain, one and all.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 56, 12, '"Come," they say, "let us get wine;  
    let us fill ourselves with strong drink.  
And tomorrow will be like today,  
    great beyond measure."', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 57, 1, 'The righteous perish,  
    and no one takes it to heart;  
the devout are taken away,  
    while no one understands.  
For the righteous are taken away from calamity,', 'en', 'NRSV-CE', 'Israel"s Futile Idolatry'),
(23, 'Yes', 'Isaiah', 57, 2, 'and they enter into peace;  
those who walk uprightly  
    will rest on their couches.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 57, 3, 'But as for you, come here,  
    you children of a sorceress,  
    you offspring of an adulterer and a whore.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 57, 4, 'Whom are you mocking?  
    Against whom do you open your mouth wide  
    and stick out your tongue?  
Are you not children of transgression,  
    the offspring of deceit--', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 57, 5, 'you that burn with lust among the oaks,  
    under every green tree;  
you that slaughter your children in the valleys,  
    under the clefts of the rocks?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 57, 6, 'Among the smooth stones of the valley is your portion;  
    they, they, are your lot;  
to them you have poured out a drink offering,  
    you have brought a grain offering.  
    Shall I be appeased for these things?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 57, 7, 'Upon a high and lofty mountain  
    you have set your bed,  
    and there you went up to offer sacrifice.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 57, 8, 'Behind the door and the doorpost  
    you have set up your symbol;  
for, in deserting me, you have uncovered your bed,  
    you have gone up to it,  
    you have made it wide;  
and you have made a bargain for yourself with them,  
    you have loved their bed,  
    you have gazed on their nakedness.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 57, 9, 'You journeyed to Molech with oil,  
    and multiplied your perfumes;  
you sent your envoys far away,  
    and sent down even to Sheol.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 57, 10, 'You grew weary from your many wanderings,  
    but you did not say, "It is useless."  
You found your desire rekindled,  
    and so you did not weaken.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 57, 11, 'Whom did you dread and fear  
    so that you lied,  
and did not remember me  
    or give me a thought?  
Have I not kept silent and closed my eyes,  
    and so you do not fear me?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 57, 12, 'I will concede your righteousness and your works,  
    but they will not help you.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 57, 13, 'When you cry out, let your collection of idols deliver you!  
    The wind will carry them off,  
    a breath will take them away.  
But whoever takes refuge in me shall possess the land  
    and inherit my holy mountain.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 57, 14, 'It shall be said,  
"Build up, build up, prepare the way,  
    remove every obstruction from my people"s way."', 'en', 'NRSV-CE', 'A Promise of Help and Healing'),
(23, 'Yes', 'Isaiah', 57, 15, 'For thus says the high and lofty one  
    who inhabits eternity, whose name is Holy:  
I dwell in the high and holy place,  
    and also with those who are contrite and humble in spirit,  
to revive the spirit of the humble,  
    and to revive the heart of the contrite.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 57, 16, 'For I will not continually accuse,  
    nor will I always be angry;  
for then the spirits would grow faint before me,  
    even the souls that I have made.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 57, 17, 'Because of their wicked covetousness I was angry;  
    I struck them, I hid and was angry;  
    but they kept turning back to their own ways.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 57, 18, 'I have seen their ways, but I will heal them;  
    I will lead them and repay them with comfort,  
    creating for their mourners the fruit of the lips.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 57, 19, 'Peace, peace, to the far and the near, says the LORD;  
    and I will heal them.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 57, 20, 'But the wicked are like the tossing sea  
    that cannot keep still;  
    its waters toss up mire and mud.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 57, 21, 'There is no peace, says my God, for the wicked.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 58, 1, 'Shout out, do not hold back!  
    Lift up your voice like a trumpet!  
Announce to my people their rebellion,  
    to the house of Jacob their sins.', 'en', 'NRSV-CE', 'False and True Worship'),
(23, 'Yes', 'Isaiah', 58, 2, 'Yet day after day they seek me  
    and delight to know my ways,  
as if they were a nation that practiced righteousness  
    and did not forsake the ordinance of their God;  
they ask of me righteous judgments,  
    they delight to draw near to God.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 58, 3, '"Why do we fast, but you do not see?  
    Why humble ourselves, but you do not notice?"  
Look, you serve your own interest on your fast day,  
    and oppress all your workers.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 58, 4, 'Look, you fast only to quarrel and to fight  
    and to strike with a wicked fist.  
Such fasting as you do today  
    will not make your voice heard on high.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 58, 5, 'Is such the fast that I choose,  
    a day to humble oneself?  
Is it to bow down the head like a bulrush,  
    and to lie in sackcloth and ashes?  
Will you call this a fast,  
    a day acceptable to the LORD?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 58, 6, 'Is not this the fast that I choose:  
    to loose the bonds of injustice,  
    to undo the thongs of the yoke,  
to let the oppressed go free,  
    and to break every yoke?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 58, 7, 'Is it not to share your bread with the hungry,  
    and bring the homeless poor into your house;  
when you see the naked, to cover them,  
    and not to hide yourself from your own kin?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 58, 8, 'Then your light shall break forth like the dawn,  
    and your healing shall spring up quickly;  
your vindicator shall go before you,  
    the glory of the LORD shall be your rear guard.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 58, 9, 'Then you shall call, and the LORD will answer;  
    you shall cry for help, and he will say, Here I am.
If you remove the yoke from among you,  
    the pointing of the finger, the speaking of evil,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 58, 10, 'if you offer your food to the hungry  
    and satisfy the needs of the afflicted,  
then your light shall rise in the darkness  
    and your gloom be like the noonday.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 58, 11, 'The LORD will guide you continually,  
    and satisfy your needs in parched places,  
    and make your bones strong;  
and you shall be like a watered garden,  
    like a spring of water,  
    whose waters never fail.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 58, 12, 'Your ancient ruins shall be rebuilt;  
    you shall raise up the foundations of many generations;  
you shall be called the repairer of the breach,  
    the restorer of streets to live in.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 58, 13, 'If you refrain from trampling the sabbath,  
    from pursuing your own interests on my holy day;  
if you call the sabbath a delight  
    and the holy day of the LORD honorable;  
if you honor it, not going your own ways,  
    serving your own interests, or pursuing your own affairs;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 58, 14, 'then you shall take delight in the LORD,  
    and I will make you ride upon the heights of the earth;  
I will feed you with the heritage of your ancestor Jacob,  
    for the mouth of the LORD has spoken.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 59, 1, 'See, the LORD"s hand is not too short to save,  
    nor his ear too dull to hear.', 'en', 'NRSV-CE', 'Injustice and Oppression to Be Punished'),
(23, 'Yes', 'Isaiah', 59, 2, 'Rather, your iniquities have been barriers  
    between you and your God,  
and your sins have hidden his face from you  
    so that he does not hear.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 59, 3, 'For your hands are defiled with blood,  
    and your fingers with iniquity;  
your lips have spoken lies,  
    your tongue mutters wickedness.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 59, 4, 'No one brings suit justly,  
    no one goes to law honestly;  
they rely on empty pleas, they speak lies,  
    conceiving mischief and begetting iniquity.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 59, 5, 'They hatch adders" eggs,  
    and weave the spider"s web;  
whoever eats their eggs dies,  
    and the crushed egg hatches out a viper.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 59, 6, 'Their webs cannot serve as clothing;  
    they cannot cover themselves with what they make.  
Their works are works of iniquity,  
    and deeds of violence are in their hands.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 59, 7, 'Their feet run to evil,  
    and they rush to shed innocent blood;  
their thoughts are thoughts of iniquity,  
    desolation and destruction are in their highways.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 59, 8, 'The way of peace they do not know,  
    and there is no justice in their paths.  
Their roads they have made crooked;  
    no one who walks in them knows peace.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 59, 9, 'Therefore justice is far from us,  
    and righteousness does not reach us;  
we wait for light, and lo! there is darkness;  
    and for brightness, but we walk in gloom.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 59, 10, 'We grope like the blind along a wall,  
    groping like those who have no eyes;  
we stumble at noon as in the twilight,  
    among the vigorous as though we were dead.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 59, 11, 'We all growl like bears;  
    like doves we moan mournfully.  
We wait for justice, but there is none;  
    for salvation, but it is far from us.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 59, 12, 'For our transgressions before you are many,  
    and our sins testify against us.  
Our transgressions indeed are with us,  
    and we know our iniquities:', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 59, 13, 'transgressing, and denying the LORD,  
    and turning away from following our God,  
talking oppression and revolt,  
    conceiving lying words and uttering them from the heart.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 59, 14, 'Justice is turned back,  
    and righteousness stands at a distance;  
for truth stumbles in the public square,  
    and uprightness cannot enter.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 59, 15, 'Truth is lacking,  
    and whoever turns from evil is despoiled.
The LORD saw it, and it displeased him  
    that there was no justice.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 59, 16, 'He saw that there was no one,  
    and was appalled that there was no one to intervene;  
so his own arm brought him victory,  
    and his righteousness upheld him.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 59, 17, 'He put on righteousness like a breastplate,  
    and a helmet of salvation on his head;  
he put on garments of vengeance for clothing,  
    and wrapped himself in fury as in a mantle.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 59, 18, 'According to their deeds, so will he repay;  
    wrath to his adversaries, requital to his enemies;  
    to the coastlands he will render requital.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 59, 19, 'So those in the west shall fear the name of the LORD,  
    and those in the east, his glory;  
for he will come like a pent-up stream  
    that the wind of the LORD drives on.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 59, 20, 'And he will come to Zion as Redeemer,  
    to those in Jacob who turn from transgression, says the LORD.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 59, 21, 'And as for me, this is my covenant with them, says the LORD: my spirit that is upon you, and my words that I have put in your mouth, shall not depart out of your mouth, or out of the mouths of your children, or out of the mouths of your children"s children, says the LORD, from now on and forever.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 60, 1, 'Arise, shine; for your light has come,  
    and the glory of the LORD has risen upon you.', 'en', 'NRSV-CE', 'The Ingathering of the Dispersed'),
(23, 'Yes', 'Isaiah', 60, 2, 'For darkness shall cover the earth,  
    and thick darkness the peoples;  
but the LORD will arise upon you,  
    and his glory will appear over you.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 60, 3, 'Nations shall come to your light,  
    and kings to the brightness of your dawn.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 60, 4, 'Lift up your eyes and look around;  
    they all gather together, they come to you;  
your sons shall come from far away,  
    and your daughters shall be carried on their nurses" arms.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 60, 5, 'Then you shall see and be radiant;  
    your heart shall thrill and rejoice,  
because the abundance of the sea shall be brought to you,  
    the wealth of the nations shall come to you.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 60, 6, 'A multitude of camels shall cover you,  
    the young camels of Midian and Ephah;  
    all those from Sheba shall come.  
They shall bring gold and frankincense,  
    and shall proclaim the praise of the LORD.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 60, 7, 'All the flocks of Kedar shall be gathered to you,  
    the rams of Nebaioth shall minister to you;  
they shall be acceptable on my altar,  
    and I will glorify my glorious house.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 60, 8, 'Who are these that fly like a cloud,  
    and like doves to their windows?', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 60, 9, 'For the coastlands shall wait for me,  
    the ships of Tarshish first,  
to bring your children from far away,  
    their silver and gold with them,  
for the name of the LORD your God,  
    and for the Holy One of Israel,  
    because he has glorified you.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 60, 10, 'Foreigners shall build up your walls,  
    and their kings shall minister to you;  
for in my wrath I struck you down,  
    but in my favor I have had mercy on you.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 60, 11, 'Your gates shall always be open;  
    day and night they shall not be shut,  
so that nations shall bring you their wealth,  
    with their kings led in procession.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 60, 12, 'For the nation and kingdom  
    that will not serve you shall perish;  
    those nations shall be utterly laid waste.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 60, 13, 'The glory of Lebanon shall come to you,  
    the cypress, the plane, and the pine,  
to beautify the place of my sanctuary;  
    and I will glorify where my feet rest.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 60, 14, 'The descendants of those who oppressed you  
    shall come bending low to you,  
and all who despised you  
    shall bow down at your feet;  
they shall call you the City of the LORD,  
    the Zion of the Holy One of Israel.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 60, 15, 'Whereas you have been forsaken and hated,  
    with no one passing through,  
I will make you majestic forever,  
    a joy from age to age.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 60, 16, 'You shall suck the milk of nations,  
    you shall suck the breasts of kings;  
and you shall know that I, the LORD, am your Savior  
    and your Redeemer, the Mighty One of Jacob.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 60, 17, 'Instead of bronze I will bring gold,  
    instead of iron I will bring silver;  
instead of wood, bronze,  
    instead of stones, iron.  
I will appoint Peace as your overseer  
    and Righteousness as your taskmaster.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 60, 18, 'Violence shall no more be heard in your land,  
    devastation or destruction within your borders;  
you shall call your walls Salvation,  
    and your gates Praise.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 60, 19, 'The sun shall no longer be  
    your light by day,  
nor for brightness shall the moon  
    give light to you by night;  
but the LORD will be your everlasting light,  
    and your God will be your glory.', 'en', 'NRSV-CE', 'God the Glory of Zion'),
(23, 'Yes', 'Isaiah', 60, 20, 'Your sun shall no more go down,  
    or your moon withdraw itself;  
for the LORD will be your everlasting light,  
    and your days of mourning shall be ended.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 60, 21, 'Your people shall all be righteous;  
    they shall possess the land forever.  
They are the shoot that I planted, the work of my hands,  
    so that I might be glorified.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 60, 22, 'The least of them shall become a clan,  
    and the smallest one a mighty nation;  
I am the LORD;  
    in its time I will accomplish it quickly.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 61, 1, 'The spirit of the Lord God is upon me,  
    because the LORD has anointed me;  
he has sent me to bring good news to the oppressed,  
    to bind up the brokenhearted,  
to proclaim liberty to the captives,  
    and release to the prisoners;', 'en', 'NRSV-CE', 'The Good News of Deliverance'),
(23, 'Yes', 'Isaiah', 61, 2, 'to proclaim the year of the LORD"s favor,  
    and the day of vengeance of our God;  
    to comfort all who mourn;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 61, 3, 'to provide for those who mourn in Zion--  
    to give them a garland instead of ashes,  
the oil of gladness instead of mourning,  
    the mantle of praise instead of a faint spirit.  
They will be called oaks of righteousness,  
    the planting of the LORD, to display his glory.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 61, 4, 'They shall build up the ancient ruins,  
    they shall raise up the former devastations;  
they shall repair the ruined cities,  
    the devastations of many generations.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 61, 5, 'Strangers shall stand and feed your flocks,  
    foreigners shall till your land and dress your vines;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 61, 6, 'but you shall be called priests of the LORD,  
    you shall be named ministers of our God;  
you shall enjoy the wealth of the nations,  
    and in their riches you shall glory.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 61, 7, 'Because their shame was double,  
    and dishonor was proclaimed as their lot,  
therefore they shall possess a double portion;  
    everlasting joy shall be theirs.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 61, 8, 'For I the LORD love justice,  
    I hate robbery and wrongdoing;  
I will faithfully give them their recompense,  
    and I will make an everlasting covenant with them.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 61, 9, 'Their descendants shall be known among the nations,  
    and their offspring among the peoples;  
all who see them shall acknowledge  
    that they are a people whom the LORD has blessed.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 61, 10, 'I will greatly rejoice in the LORD,  
    my whole being shall exult in my God;  
for he has clothed me with the garments of salvation,  
    he has covered me with the robe of righteousness,  
as a bridegroom decks himself with a garland,  
    and as a bride adorns herself with her jewels.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 61, 11, 'For as the earth brings forth its shoots,  
    and as a garden causes what is sown in it to spring up,  
so the Lord God will cause righteousness and praise  
    to spring up before all the nations.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 62, 1, 'For Zion"s sake I will not keep silent,  
    and for Jerusalem"s sake I will not rest,  
until her vindication shines out like the dawn,  
    and her salvation like a burning torch.', 'en', 'NRSV-CE', 'The Vindication and Salvation of Zion'),
(23, 'Yes', 'Isaiah', 62, 2, 'The nations shall see your vindication,  
    and all the kings your glory;  
and you shall be called by a new name  
    that the mouth of the LORD will give.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 62, 3, 'You shall be a crown of beauty in the hand of the LORD,  
    and a royal diadem in the hand of your God.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 62, 4, 'You shall no more be termed Forsaken,  
    and your land shall no more be termed Desolate;  
but you shall be called My Delight Is in Her,  
    and your land Married;  
for the LORD delights in you,  
    and your land shall be married.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 62, 5, 'For as a young man marries a young woman,  
    so shall your builder marry you,  
and as the bridegroom rejoices over the bride,  
    so shall your God rejoice over you.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 62, 6, 'Upon your walls, O Jerusalem,  
    I have posted sentinels;  
all day and all night  
    they shall never be silent.  
You who remind the LORD,  
    take no rest,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 62, 7, 'and give him no rest  
    until he establishes Jerusalem  
    and makes it renowned throughout the earth.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 62, 8, 'The LORD has sworn by his right hand  
    and by his mighty arm:  
I will not again give your grain  
    to be food for your enemies,  
and foreigners shall not drink the wine  
    for which you have labored;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 62, 9, 'but those who garner it shall eat it  
    and praise the LORD,  
and those who gather it shall drink it  
    in my holy courts.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 62, 10, 'Go through, go through the gates,  
    prepare the way for the people;  
build up, build up the highway,  
    clear it of stones,  
    lift up an ensign over the peoples.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 62, 11, 'The LORD has proclaimed  
    to the end of the earth:  
Say to daughter Zion,  
    "See, your salvation comes;  
his reward is with him,  
    and his recompense before him."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 62, 12, 'They shall be called, "The Holy People,  
    The Redeemed of the LORD";  
and you shall be called, "Sought Out,  
    A City Not Forsaken."', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 63, 1, '"Who is this that comes from Edom,  
    from Bozrah in garments stained crimson?  
Who is this so splendidly robed,  
    marching in his great might?"
"It is I, announcing vindication,  
    mighty to save."', 'en', 'NRSV-CE', 'Vengeance on Edom'),
(23, 'Yes', 'Isaiah', 63, 2, '"Why are your robes red,  
    and your garments like theirs who tread the wine press?"', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 63, 3, '"I have trodden the wine press alone,  
    and from the peoples no one was with me;  
I trod them in my anger  
    and trampled them in my wrath;  
their juice spattered on my garments,  
    and stained all my robes.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 63, 4, 'For the day of vengeance was in my heart,  
    and the year for my redeeming work had come.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 63, 5, 'I looked, but there was no helper;  
    I stared, but there was no one to sustain me;  
so my own arm brought me victory,  
    and my wrath sustained me.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 63, 6, 'I trampled down peoples in my anger,  
    I crushed them in my wrath,  
    and I poured out their lifeblood on the earth."', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 63, 7, 'I will recount the gracious deeds of the LORD,  
    the praiseworthy acts of the LORD,  
because of all that the LORD has done for us,  
    and the great favor to the house of Israel  
that he has shown them according to his mercy,  
    according to the abundance of his steadfast love.', 'en', 'NRSV-CE', 'God"s Mercy Remembered'),
(23, 'Yes', 'Isaiah', 63, 8, 'For he said, "Surely they are my people,  
    children who will not deal falsely";  
and he became their savior', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 63, 9, 'in all their distress.  
It was no messenger or angel  
    but his presence that saved them;  
in his love and in his pity he redeemed them;  
    he lifted them up and carried them all the days of old.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 63, 10, 'But they rebelled  
    and grieved his holy spirit;  
therefore he became their enemy;  
    he himself fought against them.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 63, 11, 'Then they remembered the days of old,  
    of Moses his servant.  
Where is the one who brought them up out of the sea  
    with the shepherds of his flock?  
Where is the one who put within them  
    his holy spirit,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 63, 12, 'who caused his glorious arm  
    to march at the right hand of Moses,  
who divided the waters before them  
    to make for himself an everlasting name,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 63, 13, 'who led them through the depths?  
Like a horse in the desert,  
    they did not stumble.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 63, 14, 'Like cattle that go down into the valley,  
    the spirit of the LORD gave them rest.  
Thus you led your people,  
    to make for yourself a glorious name.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 63, 15, 'Look down from heaven and see,  
    from your holy and glorious habitation.  
Where are your zeal and your might?  
    The yearning of your heart and your compassion?  
    They are withheld from me.', 'en', 'NRSV-CE', 'A Prayer of Penitence'),
(23, 'Yes', 'Isaiah', 63, 16, 'For you are our father,  
    though Abraham does not know us  
    and Israel does not acknowledge us;  
you, O LORD, are our father;  
    our Redeemer from of old is your name.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 63, 17, 'Why, O LORD, do you make us stray from your ways  
    and harden our heart, so that we do not fear you?  
Turn back for the sake of your servants,  
    for the sake of the tribes that are your heritage.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 63, 18, 'Your holy people took possession for a little while;  
    but now our adversaries have trampled down your sanctuary.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 63, 19, 'We have long been like those whom you do not rule,  
    like those not called by your name.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 64, 1, 'O that you would tear open the heavens and come down,  
    so that the mountains would quake at your presence--', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 64, 2, 'as when fire kindles brushwood  
    and the fire causes water to boil--  
to make your name known to your adversaries,  
    so that the nations might tremble at your presence!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 64, 3, 'When you did awesome deeds that we did not expect,  
    you came down, the mountains quaked at your presence.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 64, 4, 'From ages past no one has heard,  
    no ear has perceived,  
no eye has seen any God besides you,  
    who works for those who wait for him.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 64, 5, 'You meet those who gladly do right,  
    those who remember you in your ways.  
But you were angry, and we sinned;  
    because you hid yourself we transgressed.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 64, 6, 'We have all become like one who is unclean,  
    and all our righteous deeds are like a filthy cloth.  
We all fade like a leaf,  
    and our iniquities, like the wind, take us away.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 64, 7, 'There is no one who calls on your name,  
    or attempts to take hold of you;  
for you have hidden your face from us,  
    and have delivered us into the hand of our iniquity.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 64, 8, 'Yet, O LORD, you are our Father;  
    we are the clay, and you are our potter;  
    we are all the work of your hand.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 64, 9, 'Do not be exceedingly angry, O LORD,  
    and do not remember iniquity forever.  
    Now consider, we are all your people.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 64, 10, 'Your holy cities have become a wilderness,  
    Zion has become a wilderness,  
    Jerusalem a desolation.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 64, 11, 'Our holy and beautiful house,  
    where our ancestors praised you,  
has been burned by fire,  
    and all our pleasant places have become ruins.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 64, 12, 'After all this, will you restrain yourself, O LORD?  
    Will you keep silent, and punish us so severely?', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 65, 1, 'I was ready to be sought out by those who did not ask,  
    to be found by those who did not seek me.  
I said, "Here I am, here I am,"  
    to a nation that did not call on my name.', 'en', 'NRSV-CE', 'The Righteousness of God"s Judgment'),
(23, 'Yes', 'Isaiah', 65, 2, 'I held out my hands all day long  
    to a rebellious people,  
who walk in a way that is not good,  
    following their own devices;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 65, 3, 'a people who provoke me  
    to my face continually,  
sacrificing in gardens  
    and offering incense on bricks;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 65, 4, 'who sit inside tombs,  
    and spend the night in secret places;  
who eat swine"s flesh,  
    with broth of abominable things in their vessels;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 65, 5, 'who say, "Keep to yourself,  
    do not come near me, for I am too holy for you."  
These are a smoke in my nostrils,  
    a fire that burns all day long.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 65, 6, 'See, it is written before me:  
    I will not keep silent, but I will repay;  
I will indeed repay into their laps', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 65, 7, 'their iniquities and their ancestors" iniquities together,  
says the LORD;  
because they offered incense on the mountains  
    and reviled me on the hills,  
I will measure into their laps  
    full payment for their actions.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 65, 8, 'Thus says the LORD:  
As the wine is found in the cluster,  
    and they say, "Do not destroy it,  
    for there is a blessing in it,"  
so I will do for my servants" sake,  
    and not destroy them all.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 65, 9, 'I will bring forth descendants from Jacob,  
    and from Judah inheritors of my mountains;  
my chosen shall inherit it,  
    and my servants shall settle there.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 65, 10, 'Sharon shall become a pasture for flocks,  
    and the Valley of Achor a place for herds to lie down,  
    for my people who have sought me.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 65, 11, 'But you who forsake the LORD,  
    who forget my holy mountain,  
who set a table for Fortune  
    and fill cups of mixed wine for Destiny;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 65, 12, 'I will destine you to the sword,  
    and all of you shall bow down to the slaughter;  
because, when I called, you did not answer,  
    when I spoke, you did not listen,  
but you did what was evil in my sight,  
    and chose what I did not delight in.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 65, 13, 'Therefore thus says the Lord God:  
My servants shall eat,  
    but you shall be hungry;  
my servants shall drink,  
    but you shall be thirsty;  
my servants shall rejoice,  
    but you shall be put to shame;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 65, 14, 'my servants shall sing for gladness of heart,  
    but you shall cry out for pain of heart,  
    and shall wail for anguish of spirit.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 65, 15, 'You shall leave your name to my chosen to use as a curse,  
    and the Lord God will put you to death;  
    but to his servants he will give a different name.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 65, 16, 'Then whoever invokes a blessing in the land  
    shall bless by the God of faithfulness,  
and whoever takes an oath in the land  
    shall swear by the God of faithfulness;  
because the former troubles are forgotten  
    and are hidden from my sight.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 65, 17, 'For I am about to create new heavens  
    and a new earth;  
the former things shall not be remembered  
    or come to mind.', 'en', 'NRSV-CE', 'The Glorious New Creation'),
(23, 'Yes', 'Isaiah', 65, 18, 'But be glad and rejoice forever  
    in what I am creating;  
for I am about to create Jerusalem as a joy,  
    and its people as a delight.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 65, 19, 'I will rejoice in Jerusalem,  
    and delight in my people;  
no more shall the sound of weeping be heard in it,  
    or the cry of distress.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 65, 20, 'No more shall there be in it  
    an infant that lives but a few days,  
    or an old person who does not live out a lifetime;  
for one who dies at a hundred years will be considered a youth,  
    and one who falls short of a hundred will be considered accursed.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 65, 21, 'They shall build houses and inhabit them;  
    they shall plant vineyards and eat their fruit.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 65, 22, 'They shall not build and another inhabit;  
    they shall not plant and another eat;  
for like the days of a tree shall the days of my people be,  
    and my chosen shall long enjoy the work of their hands.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 65, 23, 'They shall not labor in vain,  
    or bear children for calamity;  
for they shall be offspring blessed by the LORD--  
    and their descendants as well.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 65, 24, 'Before they call I will answer,  
    while they are yet speaking I will hear.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 65, 25, 'The wolf and the lamb shall feed together,  
    the lion shall eat straw like the ox;  
    but the serpent--its food shall be dust!  
They shall not hurt or destroy  
    on all my holy mountain,  
says the LORD.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(23, 'Yes', 'Isaiah', 66, 1, 'Thus says the LORD:  
Heaven is my throne  
    and the earth is my footstool;  
what is the house that you would build for me,  
    and what is my resting place?', 'en', 'NRSV-CE', 'The Worship God Demands'),
(23, 'Yes', 'Isaiah', 66, 2, 'All these things my hand has made,  
    and so all these things are mine,  
says the LORD.  
But this is the one to whom I will look,  
    to the humble and contrite in spirit,  
    who trembles at my word.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 66, 3, 'Whoever slaughters an ox is like one who kills a human being;  
    whoever sacrifices a lamb, like one who breaks a dog"s neck;  
whoever presents a grain offering, like one who offers swine"s blood;  
    whoever makes a memorial offering of frankincense, like one who blesses an idol.  
These have chosen their own ways,  
    and in their abominations they take delight;', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 66, 4, 'I also will choose to mock them,  
    and bring upon them what they fear;  
because, when I called, no one answered,  
    when I spoke, they did not listen;  
but they did what was evil in my sight,  
    and chose what did not please me.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 66, 5, 'Hear the word of the LORD,  
    you who tremble at his word:  
Your own people who hate you  
    and reject you for my name"s sake  
have said, "Let the LORD be glorified,  
    so that we may see your joy";  
    but it is they who shall be put to shame.', 'en', 'NRSV-CE', 'The LORD Vindicates Zion'),
(23, 'Yes', 'Isaiah', 66, 6, 'Listen, an uproar from the city!  
    A voice from the temple!  
The voice of the LORD,  
    dealing retribution to his enemies!', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 66, 7, 'Before she was in labor  
    she gave birth;  
before her pain came upon her  
    she delivered a son.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 66, 8, 'Who has heard of such a thing?  
    Who has seen such things?  
Shall a land be born in one day?  
    Shall a nation be delivered in one moment?  
Yet as soon as Zion was in labor  
    she delivered her children.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 66, 9, 'Shall I open the womb and not deliver?  
    says the LORD;  
shall I, the one who delivers, shut the womb?  
    says your God.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 66, 10, 'Rejoice with Jerusalem, and be glad for her,  
    all you who love her;  
rejoice with her in joy,  
    all you who mourn over her--', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 66, 11, 'that you may nurse and be satisfied  
    from her consoling breast;  
that you may drink deeply with delight  
    from her glorious bosom.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 66, 12, 'For thus says the LORD:  
I will extend prosperity to her like a river,  
    and the wealth of the nations like an overflowing stream;  
and you shall nurse and be carried on her arm,  
    and dandled on her knees.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 66, 13, 'As a mother comforts her child,  
    so I will comfort you;  
    you shall be comforted in Jerusalem.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 66, 14, 'You shall see, and your heart shall rejoice;  
    your bodies shall flourish like the grass;  
and it shall be known that the hand of the LORD is with his servants,  
    and his indignation is against his enemies.', 'en', 'NRSV-CE', 'The Reign and Indignation of God'),
(23, 'Yes', 'Isaiah', 66, 15, 'For the LORD will come in fire,  
    and his chariots like the whirlwind,  
to pay back his anger in fury,  
    and his rebuke in flames of fire.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 66, 16, 'For by fire will the LORD execute judgment,  
    and by his sword, on all flesh;  
    and those slain by the LORD shall be many.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 66, 17, 'Those who sanctify and purify themselves to go into the gardens, following the one in the center, eating the flesh of pigs, vermin, and rodents, shall come to an end together, says the LORD.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 66, 18, 'For I know their works and their thoughts, and I am coming to gather all nations and tongues; and they shall come and shall see my glory,', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 66, 19, 'and I will set a sign among them. From them I will send survivors to the nations, to Tarshish, Put, and Lud--which draw the bow--to Tubal and Javan, to the coastlands far away that have not heard of my fame or seen my glory; and they shall declare my glory among the nations.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 66, 20, 'They shall bring all your kindred from all the nations as an offering to the LORD, on horses, and in chariots, and in litters, and on mules, and on dromedaries, to my holy mountain Jerusalem, says the LORD, just as the Israelites bring a grain offering in a clean vessel to the house of the LORD.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 66, 21, 'And I will also take some of them as priests and as Levites, says the LORD.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 66, 22, 'For as the new heavens and the new earth,  
    which I will make,  
shall remain before me, says the LORD;  
    so shall your descendants and your name remain.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 66, 23, 'From new moon to new moon,  
    and from sabbath to sabbath,  
all flesh shall come to worship before me,  
says the LORD.', 'en', 'NRSV-CE', NULL),
(23, 'Yes', 'Isaiah', 66, 24, 'And they shall go out and look at the dead bodies of the people who have rebelled against me; for their worm shall not die, their fire shall not be quenched, and they shall be an abhorrence to all flesh.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 1, 1, 'The words of Jeremiah son of Hilkiah, of the priests who were in Anathoth in the land of Benjamin,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 1, 2, 'to whom the word of the LORD came in the days of King Josiah son of Amon of Judah, in the thirteenth year of his reign.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 1, 3, 'It came also in the days of King Jehoiakim son of Josiah of Judah, and until the end of the eleventh year of King Zedekiah son of Josiah of Judah, until the captivity of Jerusalem in the fifth month.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 1, 4, 'Now the word of the LORD came to me saying,', 'en', 'NRSV-CE', 'Jeremiah"s Call and Commission'),
(24, 'Yer', 'Jeremiah', 1, 5, '"Before I formed you in the womb I knew you,  
and before you were born I consecrated you;  
I appointed you a prophet to the nations."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 1, 6, 'Then I said, "Ah, Lord God! Truly I do not know how to speak, for I am only a boy."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 1, 7, 'But the LORD said to me,
"Do not say, "I am only a boy";  
for you shall go to all to whom I send you,  
and you shall speak whatever I command you.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 1, 8, 'Do not be afraid of them,  
for I am with you to deliver you,  
says the LORD."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 1, 9, 'Then the LORD put out his hand and touched my mouth; and the LORD said to me,
"Now I have put my words in your mouth.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 1, 10, 'See, today I appoint you over nations and over kingdoms,  
to pluck up and to pull down,  
to destroy and to overthrow,  
to build and to plant."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 1, 11, 'The word of the LORD came to me, saying, "Jeremiah, what do you see?" And I said, "I see a branch of an almond tree."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 1, 12, 'Then the LORD said to me, "You have seen well, for I am watching over my word to perform it."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 1, 13, 'The word of the LORD came to me a second time, saying, "What do you see?" And I said, "I see a boiling pot, tilted away from the north."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 1, 14, 'Then the LORD said to me: Out of the north disaster shall break out on all the inhabitants of the land.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 1, 15, 'For now I am calling all the tribes of the kingdoms of the north, says the LORD; and they shall come and all of them shall set their thrones at the entrance of the gates of Jerusalem, against all its surrounding walls and against all the cities of Judah.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 1, 16, 'And I will utter my judgments against them, for all their wickedness in forsaking me; they have made offerings to other gods, and worshiped the works of their own hands.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 1, 17, 'But you, gird up your loins; stand up and tell them everything that I command you. Do not break down before them, or I will break you before them.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 1, 18, 'And I for my part have made you today a fortified city, an iron pillar, and a bronze wall, against the whole land--against the kings of Judah, its princes, its priests, and the people of the land.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 1, 19, 'They will fight against you; but they shall not prevail against you, for I am with you, says the LORD, to deliver you.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 2, 1, 'The word of the LORD came to me, saying:', 'en', 'NRSV-CE', 'God Pleads with Israel to Repent'),
(24, 'Yer', 'Jeremiah', 2, 2, 'Go and proclaim in the hearing of Jerusalem, Thus says the LORD:
I remember the devotion of your youth,  
    your love as a bride,  
how you followed me in the wilderness,  
    in a land not sown.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 2, 3, 'Israel was holy to the LORD,  
    the first fruits of his harvest.  
All who ate of it were held guilty;  
    disaster came upon them,  
says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 2, 4, 'Hear the word of the LORD, O house of Jacob, and all the families of the house of Israel.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 2, 5, 'Thus says the LORD:
What wrong did your ancestors find in me  
    that they went far from me,  
and went after worthless things, and became worthless themselves?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 2, 6, 'They did not say, "Where is the LORD  
    who brought us up from the land of Egypt,  
who led us in the wilderness,  
    in a land of deserts and pits,  
in a land of drought and deep darkness,  
    in a land that no one passes through,  
    where no one lives?"', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 2, 7, 'I brought you into a plentiful land  
    to eat its fruits and its good things.  
But when you entered you defiled my land,  
    and made my heritage an abomination.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 2, 8, 'The priests did not say, "Where is the LORD?"  
    Those who handle the law did not know me;  
the rulers transgressed against me;  
    the prophets prophesied by Baal,  
    and went after things that do not profit.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 2, 9, 'Therefore once more I accuse you,  
says the LORD,  
    and I accuse your children"s children.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 2, 10, 'Cross to the coasts of Cyprus and look,  
    send to Kedar and examine with care;  
    see if there has ever been such a thing.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 2, 11, 'Has a nation changed its gods,  
    even though they are no gods?  
But my people have changed their glory  
    for something that does not profit.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 2, 12, 'Be appalled, O heavens, at this,  
    be shocked, be utterly desolate,  
says the LORD,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 2, 13, 'for my people have committed two evils:  
    they have forsaken me,  
the fountain of living water,  
    and dug out cisterns for themselves,  
cracked cisterns  
    that can hold no water.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 2, 14, 'Is Israel a slave? Is he a homeborn servant?  
    Why then has he become plunder?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 2, 15, 'The lions have roared against him,  
    they have roared loudly.  
They have made his land a waste;  
    his cities are in ruins, without inhabitant.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 2, 16, 'Moreover, the people of Memphis and Tahpanhes  
    have broken the crown of your head.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 2, 17, 'Have you not brought this upon yourself  
    by forsaking the LORD your God,  
    while he led you in the way?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 2, 18, 'What then do you gain by going to Egypt,  
    to drink the waters of the Nile?  
Or what do you gain by going to Assyria,  
    to drink the waters of the Euphrates?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 2, 19, 'Your wickedness will punish you,  
    and your apostasies will convict you.  
Know and see that it is evil and bitter  
    for you to forsake the LORD your God;  
    the fear of me is not in you,  
says the Lord God of hosts.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 2, 20, 'For long ago you broke your yoke  
    and burst your bonds,  
    and you said, "I will not serve!"  
On every high hill  
    and under every green tree  
    you sprawled and played the whore.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 2, 21, 'Yet I planted you as a choice vine,  
    from the purest stock.  
How then did you turn degenerate  
    and become a wild vine?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 2, 22, 'Though you wash yourself with lye  
    and use much soap,  
    the stain of your guilt is still before me,  
says the Lord God.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 2, 23, 'How can you say, "I am not defiled,  
    I have not gone after the Baals"?  
Look at your way in the valley;  
    know what you have done--  
a restive young camel interlacing her tracks,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 2, 24, 'a wild ass at home in the wilderness,  
in her heat sniffing the wind!  
    Who can restrain her lust?  
None who seek her need weary themselves;  
    in her month they will find her.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 2, 25, 'Keep your feet from going unshod  
    and your throat from thirst.  
But you said, "It is hopeless,  
    for I have loved strangers,  
    and after them I will go."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 2, 26, 'As a thief is shamed when caught,  
    so the house of Israel shall be shamed--  
they, their kings, their officials,  
    their priests, and their prophets,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 2, 27, 'who say to a tree, "You are my father,"  
    and to a stone, "You gave me birth."  
For they have turned their backs to me,  
    and not their faces.  
But in the time of their trouble they say,  
    "Come and save us!"', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 2, 28, 'But where are your gods  
    that you made for yourself?  
Let them come, if they can save you,  
    in your time of trouble;  
for you have as many gods  
    as you have towns, O Judah.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 2, 29, 'Why do you complain against me?  
    You have all rebelled against me,  
says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 2, 30, 'In vain I have struck down your children;  
    they accepted no correction.  
Your own sword devoured your prophets  
    like a ravening lion.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 2, 31, 'And you, O generation, behold the word of the LORD!  
Have I been a wilderness to Israel,  
    or a land of thick darkness?  
Why then do my people say, "We are free,  
    we will come to you no more"?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 2, 32, 'Can a girl forget her ornaments,  
    or a bride her attire?  
Yet my people have forgotten me,  
    days without number.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 2, 33, 'How well you direct your course  
    to seek lovers!  
So that even to wicked women  
    you have taught your ways.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 2, 34, 'Also on your skirts is found  
    the lifeblood of the innocent poor,  
though you did not catch them breaking in.  
    Yet in spite of all these things', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 2, 35, 'you say, "I am innocent;  
    surely his anger has turned from me."  
Now I am bringing you to judgment  
    for saying, "I have not sinned."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 2, 36, 'How lightly you gad about,  
    changing your ways!  
You shall be put to shame by Egypt  
    as you were put to shame by Assyria.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 2, 37, 'From there also you will come away  
    with your hands on your head;  
for the LORD has rejected those in whom you trust,  
    and you will not prosper through them.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 3, 1, 'If a man divorces his wife  
    and she goes from him  
and becomes another man"s wife,  
    will he return to her?  
Would not such a land be greatly polluted?  
You have played the whore with many lovers;  
    and would you return to me?  
says the LORD.', 'en', 'NRSV-CE', 'Unfaithful Israel'),
(24, 'Yer', 'Jeremiah', 3, 2, 'Look up to the bare heights, and see!  
    Where have you not been lain with?  
By the waysides you have sat waiting for lovers,  
    like a nomad in the wilderness.  
You have polluted the land  
    with your whoring and wickedness.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 3, 3, 'Therefore the showers have been withheld,  
    and the spring rain has not come;  
yet you have the forehead of a whore,  
    you refuse to be ashamed.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 3, 4, 'Have you not just now called to me,  
    "My Father, you are the friend of my youth--', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 3, 5, 'will he be angry forever,  
    will he be indignant to the end?"  
This is how you have spoken,  
    but you have done all the evil that you could.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 3, 6, 'The LORD said to me in the days of King Josiah: Have you seen what she did, that faithless one, Israel, how she went up on every high hill and under every green tree, and played the whore there?', 'en', 'NRSV-CE', 'A Call to Repentance'),
(24, 'Yer', 'Jeremiah', 3, 7, 'And I thought, "After she has done all this she will return to me"; but she did not return, and her false sister Judah saw it.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 3, 8, 'She saw that for all the adulteries of that faithless one, Israel, I had sent her away with a decree of divorce; yet her false sister Judah did not fear, but she too went and played the whore.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 3, 9, 'Because she took her whoredom so lightly, she polluted the land, committing adultery with stone and tree.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 3, 10, 'Yet for all this her false sister Judah did not return to me with her whole heart, but only in pretense, says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 3, 11, 'Then the LORD said to me: Faithless Israel has shown herself less guilty than false Judah.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 3, 12, 'Go, and proclaim these words toward the north, and say:
Return, faithless Israel,  
says the LORD.  
I will not look on you in anger,  
    for I am merciful,  
says the LORD;  
I will not be angry forever.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 3, 13, 'Only acknowledge your guilt,  
    that you have rebelled against the LORD your God,  
and scattered your favors among strangers under every green tree,  
    and have not obeyed my voice,  
says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 3, 14, 'Return, O faithless children,  
says the LORD,  
    for I am your master;  
I will take you, one from a city and two from a family,  
    and I will bring you to Zion.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 3, 15, 'I will give you shepherds after my own heart, who will feed you with knowledge and understanding.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 3, 16, 'And when you have multiplied and increased in the land, in those days, says the LORD, they shall no longer say, "The ark of the covenant of the LORD." It shall not come to mind, or be remembered, or missed; nor shall another one be made.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 3, 17, 'At that time Jerusalem shall be called the throne of the LORD, and all nations shall gather to it, to the presence of the LORD in Jerusalem, and they shall no longer stubbornly follow their own evil will.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 3, 18, 'In those days the house of Judah shall join the house of Israel, and together they shall come from the land of the north to the land that I gave your ancestors for a heritage.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 3, 19, 'I thought  
    how I would set you among my children,  
and give you a pleasant land,  
    the most beautiful heritage of all the nations.  
And I thought you would call me, My Father,  
    and would not turn from following me.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 3, 20, 'Instead, as a faithless wife leaves her husband,  
    so you have been faithless to me, O house of Israel,  
says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 3, 21, 'A voice on the bare heights is heard,  
    the plaintive weeping of Israel"s children,  
because they have perverted their way,  
    they have forgotten the LORD their God:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 3, 22, 'Return, O faithless children,  
    I will heal your faithlessness.
"Here we come to you;  
    for you are the LORD our God.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 3, 23, 'Truly the hills are a delusion,  
    the orgies on the mountains.  
Truly in the LORD our God  
    is the salvation of Israel.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 3, 24, '"But from our youth the shameful thing has devoured all for which our ancestors had labored, their flocks and their herds, their sons and their daughters.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 3, 25, 'Let us lie down in our shame, and let our dishonor cover us; for we have sinned against the LORD our God, we and our ancestors, from our youth even to this day; and we have not obeyed the voice of the LORD our God."', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 4, 1, 'If you return, O Israel,
says the LORD,  
    if you return to me,  
if you remove your abominations from my presence,  
    and do not waver,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 4, 2, 'and if you swear, "As the LORD lives!"  
    in truth, in justice, and in uprightness,  
then nations shall be blessed by him,  
    and by him they shall boast.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 4, 3, 'For thus says the LORD to the people of Judah and to the inhabitants of Jerusalem:
Break up your fallow ground,  
    and do not sow among thorns.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 4, 4, 'Circumcise yourselves to the LORD,  
    remove the foreskin of your hearts,  
    O people of Judah and inhabitants of Jerusalem,  
or else my wrath will go forth like fire,  
    and burn with no one to quench it,  
    because of the evil of your doings.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 4, 5, 'Declare in Judah, and proclaim in Jerusalem, and say:
Blow the trumpet through the land;  
    shout aloud and say,  
"Gather together, and let us go  
    into the fortified cities!"', 'en', 'NRSV-CE', 'Invasion and Desolation of Judah Threatened'),
(24, 'Yer', 'Jeremiah', 4, 6, 'Raise a standard toward Zion,  
    flee for safety, do not delay,  
for I am bringing evil from the north,  
    and a great destruction.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 4, 7, 'A lion has gone up from its thicket,  
    a destroyer of nations has set out;  
    he has gone out from his place  
to make your land a waste;  
    your cities will be ruins  
    without inhabitant.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 4, 8, 'Because of this put on sackcloth,  
    lament and wail:  
"The fierce anger of the LORD  
    has not turned away from us."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 4, 9, 'On that day, says the LORD, courage shall fail the king and the officials; the priests shall be appalled and the prophets astounded.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 4, 10, 'Then I said, "Ah, Lord God, how utterly you have deceived this people and Jerusalem, saying, "It shall be well with you," even while the sword is at the throat!"', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 4, 11, 'At that time it will be said to this people and to Jerusalem: A hot wind comes from me out of the bare heights in the desert toward my poor people, not to winnow or cleanse--', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 4, 12, 'a wind too strong for that. Now it is I who speak in judgment against them.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 4, 13, 'Look! He comes up like clouds,  
    his chariots like the whirlwind;  
his horses are swifter than eagles--  
    woe to us, for we are ruined!', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 4, 14, 'O Jerusalem, wash your heart clean of wickedness  
    so that you may be saved.  
How long shall your evil schemes  
    lodge within you?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 4, 15, 'For a voice declares from Dan  
    and proclaims disaster from Mount Ephraim.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 4, 16, 'Tell the nations, "Here they are!"  
    Proclaim against Jerusalem,  
"Besiegers come from a distant land;  
    they shout against the cities of Judah.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 4, 17, 'They have closed in around her like watchers of a field,  
    because she has rebelled against me,  
says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 4, 18, 'Your ways and your doings  
    have brought this upon you.  
This is your doom; how bitter it is!  
    It has reached your very heart."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 4, 19, 'My anguish, my anguish! I writhe in pain!  
    Oh, the walls of my heart!  
My heart is beating wildly;  
    I cannot keep silent;  
for I hear the sound of the trumpet,  
    the alarm of war.', 'en', 'NRSV-CE', 'Sorrow for a Doomed Nation'),
(24, 'Yer', 'Jeremiah', 4, 20, 'Disaster overtakes disaster,  
    the whole land is laid waste.  
Suddenly my tents are destroyed,  
    my curtains in a moment.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 4, 21, 'How long must I see the standard,  
    and hear the sound of the trumpet?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 4, 22, '"For my people are foolish,  
    they do not know me;  
they are stupid children,  
    they have no understanding.  
They are skilled in doing evil,  
    but do not know how to do good."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 4, 23, 'I looked on the earth, and lo, it was waste and void;  
    and to the heavens, and they had no light.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 4, 24, 'I looked on the mountains, and lo, they were quaking,  
    and all the hills moved to and fro.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 4, 25, 'I looked, and lo, there was no one at all,  
    and all the birds of the air had fled.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 4, 26, 'I looked, and lo, the fruitful land was a desert,  
    and all its cities were laid in ruins  
    before the LORD, before his fierce anger.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 4, 27, 'For thus says the LORD: The whole land shall be a desolation; yet I will not make a full end.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 4, 28, 'Because of this the earth shall mourn,  
    and the heavens above grow black;  
for I have spoken, I have purposed;  
    I have not relented nor will I turn back.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 4, 29, 'At the noise of horseman and archer  
    every town takes to flight;  
they enter thickets; they climb among rocks;  
    all the towns are forsaken,  
    and no one lives in them.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 4, 30, 'And you, O desolate one,  
what do you mean that you dress in crimson,  
    that you deck yourself with ornaments of gold,  
    that you enlarge your eyes with paint?  
In vain you beautify yourself.  
    Your lovers despise you;  
    they seek your life.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 4, 31, 'For I heard a cry as of a woman in labor,  
    anguish as of one bringing forth her first child,  
the cry of daughter Zion gasping for breath,  
    stretching out her hands,  
"Woe is me! I am fainting before killers!"', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 5, 1, 'Run to and fro through the streets of Jerusalem,  
    look around and take note!  
Search its squares and see  
    if you can find one person  
who acts justly  
    and seeks truth--  
so that I may pardon Jerusalem.', 'en', 'NRSV-CE', 'The Utter Corruption of God"s People'),
(24, 'Yer', 'Jeremiah', 5, 2, 'Although they say, "As the LORD lives,"  
    yet they swear falsely.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 5, 3, 'O LORD, do your eyes not look for truth?  
You have struck them,  
    but they felt no anguish;  
you have consumed them,  
    but they refused to take correction.  
They have made their faces harder than rock;  
    they have refused to turn back.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 5, 4, 'Then I said, "These are only the poor,  
    they have no sense;  
for they do not know the way of the LORD,  
    the law of their God.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 5, 5, 'Let me go to the rich  
    and speak to them;  
surely they know the way of the LORD,  
    the law of their God."  
But they all alike had broken the yoke,  
    they had burst the bonds.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 5, 6, 'Therefore a lion from the forest shall kill them,  
    a wolf from the desert shall destroy them.  
A leopard is watching against their cities;  
    everyone who goes out of them shall be torn in pieces--  
because their transgressions are many,  
    their apostasies are great.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 5, 7, 'How can I pardon you?  
    Your children have forsaken me,  
    and have sworn by those who are no gods.  
When I fed them to the full,  
    they committed adultery  
    and trooped to the houses of prostitutes.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 5, 8, 'They were well-fed lusty stallions,  
    each neighing for his neighbor"s wife.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 5, 9, 'Shall I not punish them for these things?  
says the LORD;  
    and shall I not bring retribution  
    on a nation such as this?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 5, 10, 'Go up through her vine-rows and destroy,  
    but do not make a full end;  
strip away her branches,  
    for they are not the LORD"s.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 5, 11, 'For the house of Israel and the house of Judah  
    have been utterly faithless to me,  
says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 5, 12, 'They have spoken falsely of the LORD,  
    and have said, "He will do nothing.  
No evil will come upon us,  
    and we shall not see sword or famine."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 5, 13, 'The prophets are nothing but wind,  
    for the word is not in them.  
Thus shall it be done to them!', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 5, 14, 'Therefore thus says the LORD, the God of hosts:  
Because they have spoken this word,  
I am now making my words in your mouth a fire,  
    and this people wood, and the fire shall devour them.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 5, 15, 'I am going to bring upon you  
    a nation from far away, O house of Israel,  
says the LORD.  
It is an enduring nation,  
    it is an ancient nation,  
a nation whose language you do not know,  
    nor can you understand what they say.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 5, 16, 'Their quiver is like an open tomb;  
    all of them are mighty warriors.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 5, 17, 'They shall eat up your harvest and your food;  
    they shall eat up your sons and your daughters;  
they shall eat up your flocks and your herds;  
    they shall eat up your vines and your fig trees;  
they shall destroy with the sword  
    your fortified cities in which you trust.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 5, 18, 'But even in those days, says the LORD, I will not make a full end of you.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 5, 19, 'And when your people say, "Why has the LORD our God done all these things to us?" you shall say to them, "As you have forsaken me and served foreign gods in your land, so you shall serve strangers in a land that is not yours."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 5, 20, 'Declare this in the house of Jacob,  
    proclaim it in Judah:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 5, 21, 'Hear this, O foolish and senseless people,  
    who have eyes, but do not see,  
    who have ears, but do not hear.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 5, 22, 'Do you not fear me? says the LORD;  
    Do you not tremble before me?  
I placed the sand as a boundary for the sea,  
    a perpetual barrier that it cannot pass;  
though the waves toss, they cannot prevail,  
    though they roar, they cannot pass over it.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 5, 23, 'But this people has a stubborn and rebellious heart;  
    they have turned aside and gone away.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 5, 24, 'They do not say in their hearts,  
    "Let us fear the LORD our God,  
who gives the rain in its season,  
    the autumn rain and the spring rain,  
and keeps for us  
    the weeks appointed for the harvest."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 5, 25, 'Your iniquities have turned these away,  
    and your sins have deprived you of good.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 5, 26, 'For scoundrels are found among my people;  
    they take over the goods of others.  
Like fowlers they set a trap;  
    they catch human beings.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 5, 27, 'Like a cage full of birds,  
    their houses are full of treachery;  
therefore they have become great and rich,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 5, 28, 'they have grown fat and sleek.  
They know no limits in deeds of wickedness;  
    they do not judge with justice  
the cause of the orphan, to make it prosper,  
    and they do not defend the rights of the needy.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 5, 29, 'Shall I not punish them for these things?  
says the LORD,  
    and shall I not bring retribution  
    on a nation such as this?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 5, 30, 'An appalling and horrible thing  
    has happened in the land:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 5, 31, 'the prophets prophesy falsely,  
    and the priests rule as the prophets direct;  
my people love to have it so,  
    but what will you do when the end comes?', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 6, 1, 'Flee for safety, O children of Benjamin,  
    from the midst of Jerusalem!  
Blow the trumpet in Tekoa,  
    and raise a signal on Beth-haccherem;  
for evil looms out of the north,  
    and great destruction.', 'en', 'NRSV-CE', 'The Imminence and Horror of the Invasion'),
(24, 'Yer', 'Jeremiah', 6, 2, 'I have likened daughter Zion  
    to the loveliest pasture.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 6, 3, 'Shepherds with their flocks shall come against her.  
    They shall pitch their tents around her;  
    they shall pasture, all in their places.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 6, 4, '"Prepare war against her;  
    up, and let us attack at noon!"  
"Woe to us, for the day declines,  
    the shadows of evening lengthen!"', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 6, 5, '"Up, and let us attack by night,  
    and destroy her palaces!"', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 6, 6, 'For thus says the LORD of hosts:  
Cut down her trees;  
    cast up a siege ramp against Jerusalem.  
This is the city that must be punished;  
    there is nothing but oppression within her.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 6, 7, 'As a well keeps its water fresh,  
    so she keeps fresh her wickedness;  
violence and destruction are heard within her;  
    sickness and wounds are ever before me.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 6, 8, 'Take warning, O Jerusalem,  
    or I shall turn from you in disgust,  
and make you a desolation,  
    an uninhabited land.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 6, 9, 'Thus says the LORD of hosts:  
Glean thoroughly as a vine  
    the remnant of Israel;  
like a grape-gatherer, pass your hand again  
    over its branches.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 6, 10, 'To whom shall I speak and give warning,  
    that they may hear?  
See, their ears are closed,  
    they cannot listen.  
The word of the LORD is to them an object of scorn;  
    they take no pleasure in it.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 6, 11, 'But I am full of the wrath of the LORD;  
    I am weary of holding it in.
Pour it out on the children in the street,  
    and on the gatherings of young men as well;  
both husband and wife shall be taken,  
    the old folk and the very aged.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 6, 12, 'Their houses shall be turned over to others,  
    their fields and wives together;  
for I will stretch out my hand  
    against the inhabitants of the land,  
says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 6, 13, 'For from the least to the greatest of them,  
    everyone is greedy for unjust gain;  
and from prophet to priest,  
    everyone deals falsely.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 6, 14, 'They have treated the wound of my people carelessly,  
    saying, "Peace, peace,"  
    when there is no peace.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 6, 15, 'They acted shamefully, they committed abomination;  
    yet they were not ashamed,  
    they did not know how to blush.  
Therefore they shall fall among those who fall;  
    at the time that I punish them, they shall be overthrown,  
says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 6, 16, 'Thus says the LORD:  
Stand at the crossroads, and look,  
    and ask for the ancient paths,  
where the good way lies; and walk in it,  
    and find rest for your souls.  
But they said, "We will not walk in it."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 6, 17, 'Also I raised up sentinels for you:  
    "Give heed to the sound of the trumpet!"  
But they said, "We will not give heed."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 6, 18, 'Therefore hear, O nations,  
    and know, O congregation, what will happen to them.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 6, 19, 'Hear, O earth; I am going to bring disaster on this people,  
    the fruit of their schemes,  
because they have not given heed to my words;  
    and as for my teaching, they have rejected it.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 6, 20, 'Of what use to me is frankincense that comes from Sheba,  
    or sweet cane from a distant land?  
Your burnt offerings are not acceptable,  
    nor are your sacrifices pleasing to me.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 6, 21, 'Therefore thus says the LORD:  
See, I am laying before this people  
    stumbling blocks against which they shall stumble;  
parents and children together,  
    neighbor and friend shall perish.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 6, 22, 'Thus says the LORD:  
See, a people is coming from the land of the north,  
    a great nation is stirring from the farthest parts of the earth.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 6, 23, 'They grasp the bow and the javelin,  
    they are cruel and have no mercy,  
    their sound is like the roaring sea;  
they ride on horses,  
    equipped like a warrior for battle,  
    against you, O daughter Zion!', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 6, 24, '"We have heard news of them,  
    our hands fall helpless;  
anguish has taken hold of us,  
    pain as of a woman in labor.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 6, 25, 'Do not go out into the field,  
    or walk on the road;  
for the enemy has a sword,  
    terror is on every side."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 6, 26, 'O my poor people, put on sackcloth,  
    and roll in ashes;  
make mourning as for an only child,  
    most bitter lamentation:  
for suddenly the destroyer  
    will come upon us.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 6, 27, 'I have made you a tester and a refiner among my people  
    so that you may know and test their ways.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 6, 28, 'They are all stubbornly rebellious,  
    going about with slanders;  
they are bronze and iron,  
    all of them act corruptly.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 6, 29, 'The bellows blow fiercely,  
    the lead is consumed by the fire;  
in vain the refining goes on,  
    for the wicked are not removed.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 6, 30, 'They are called "rejected silver,"  
    for the LORD has rejected them.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 7, 1, 'The word that came to Jeremiah from the LORD:', 'en', 'NRSV-CE', 'Jeremiah Proclaims God"s Judgment on the Nation'),
(24, 'Yer', 'Jeremiah', 7, 2, 'Stand in the gate of the LORD"s house, and proclaim there this word, and say, Hear the word of the LORD, all you people of Judah, you that enter these gates to worship the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 7, 3, 'Thus says the LORD of hosts, the God of Israel: Amend your ways and your doings, and let me dwell with you in this place.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 7, 4, 'Do not trust in these deceptive words: "This is the temple of the LORD, the temple of the LORD, the temple of the LORD."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 7, 5, 'For if you truly amend your ways and your doings, if you truly act justly one with another,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 7, 6, 'if you do not oppress the alien, the orphan, and the widow, or shed innocent blood in this place, and if you do not go after other gods to your own hurt,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 7, 7, 'then I will dwell with you in this place, in the land that I gave of old to your ancestors forever and ever.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 7, 8, 'Here you are, trusting in deceptive words to no avail.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 7, 9, 'Will you steal, murder, commit adultery, swear falsely, make offerings to Baal, and go after other gods that you have not known,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 7, 10, 'and then come and stand before me in this house, which is called by my name, and say, "We are safe!"--only to go on doing all these abominations?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 7, 11, 'Has this house, which is called by my name, become a den of robbers in your sight? You know, I too am watching, says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 7, 12, 'Go now to my place that was in Shiloh, where I made my name dwell at first, and see what I did to it for the wickedness of my people Israel.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 7, 13, 'And now, because you have done all these things, says the LORD, and when I spoke to you persistently, you did not listen, and when I called you, you did not answer,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 7, 14, 'therefore I will do to the house that is called by my name, in which you trust, and to the place that I gave to you and to your ancestors, just what I did to Shiloh.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 7, 15, 'And I will cast you out of my sight, just as I cast out all your kinsfolk, all the offspring of Ephraim.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 7, 16, 'As for you, do not pray for this people, do not raise a cry or prayer on their behalf, and do not intercede with me, for I will not hear you.', 'en', 'NRSV-CE', 'The People"s Disobedience'),
(24, 'Yer', 'Jeremiah', 7, 17, 'Do you not see what they are doing in the towns of Judah and in the streets of Jerusalem?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 7, 18, 'The children gather wood, the fathers kindle fire, and the women knead dough, to make cakes for the queen of heaven; and they pour out drink offerings to other gods, to provoke me to anger.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 7, 19, 'Is it I whom they provoke? says the LORD. Is it not themselves, to their own hurt?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 7, 20, 'Therefore thus says the Lord God: My anger and my wrath shall be poured out on this place, on human beings and animals, on the trees of the field and the fruit of the ground; it will burn and not be quenched.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 7, 21, 'Thus says the LORD of hosts, the God of Israel: Add your burnt offerings to your sacrifices, and eat the flesh.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 7, 22, 'For in the day that I brought your ancestors out of the land of Egypt, I did not speak to them or command them concerning burnt offerings and sacrifices.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 7, 23, 'But this command I gave them, "Obey my voice, and I will be your God, and you shall be my people; and walk only in the way that I command you, so that it may be well with you."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 7, 24, 'Yet they did not obey or incline their ear, but, in the stubbornness of their evil will, they walked in their own counsels, and looked backward rather than forward.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 7, 25, 'From the day that your ancestors came out of the land of Egypt until this day, I have persistently sent all my servants the prophets to them, day after day;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 7, 26, 'yet they did not listen to me, or pay attention, but they stiffened their necks. They did worse than their ancestors did.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 7, 27, 'So you shall speak all these words to them, but they will not listen to you. You shall call to them, but they will not answer you.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 7, 28, 'You shall say to them: This is the nation that did not obey the voice of the LORD their God, and did not accept discipline; truth has perished; it is cut off from their lips.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 7, 29, 'Cut off your hair and throw it away;  
    raise a lamentation on the bare heights,  
for the LORD has rejected and forsaken  
    the generation that provoked his wrath.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 7, 30, 'For the people of Judah have done evil in my sight, says the LORD; they have set their abominations in the house that is called by my name, defiling it.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 7, 31, 'And they go on building the high place of Topheth, which is in the valley of the son of Hinnom, to burn their sons and their daughters in the fire--which I did not command, nor did it come into my mind.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 7, 32, 'Therefore, the days are surely coming, says the LORD, when it will no more be called Topheth, or the valley of the son of Hinnom, but the valley of Slaughter: for they will bury in Topheth until there is no more room.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 7, 33, 'The corpses of this people will be food for the birds of the air, and for the animals of the earth; and no one will frighten them away.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 7, 34, 'And I will bring to an end the sound of mirth and gladness, the voice of the bride and bridegroom in the cities of Judah and in the streets of Jerusalem; for the land shall become a waste.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 8, 1, 'At that time, says the LORD, the bones of the kings of Judah, the bones of its officials, the bones of the priests, the bones of the prophets, and the bones of the inhabitants of Jerusalem shall be brought out of their tombs;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 8, 2, 'and they shall be spread before the sun and the moon and all the host of heaven, which they have loved and served, which they have followed, and which they have inquired of and worshiped; and they shall not be gathered or buried; they shall be like dung on the surface of the ground.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 8, 3, 'Death shall be preferred to life by all the remnant that remains of this evil family in all the places where I have driven them, says the LORD of hosts.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 8, 4, 'You shall say to them, Thus says the LORD:  
When people fall, do they not get up again?  
    If they go astray, do they not turn back?', 'en', 'NRSV-CE', 'The Blind Perversity of the Whole Nation'),
(24, 'Yer', 'Jeremiah', 8, 5, 'Why then has this people turned away  
    in perpetual backsliding?  
They have held fast to deceit,  
    they have refused to return.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 8, 6, 'I have given heed and listened,  
    but they do not speak honestly;  
no one repents of wickedness,  
    saying, "What have I done!"  
All of them turn to their own course,  
    like a horse plunging headlong into battle.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 8, 7, 'Even the stork in the heavens  
    knows its times;  
and the turtledove, swallow, and crane  
    observe the time of their coming;  
but my people do not know  
    the ordinance of the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 8, 8, 'How can you say, "We are wise,  
    and the law of the LORD is with us,"  
when, in fact, the false pen of the scribes  
    has made it into a lie?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 8, 9, 'The wise shall be put to shame,  
    they shall be dismayed and taken;  
since they have rejected the word of the LORD,  
    what wisdom is in them?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 8, 10, 'Therefore I will give their wives to others  
    and their fields to conquerors,  
because from the least to the greatest  
    everyone is greedy for unjust gain;  
from prophet to priest  
    everyone deals falsely.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 8, 11, 'They have treated the wound of my people carelessly,  
    saying, "Peace, peace,"  
    when there is no peace.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 8, 12, 'They acted shamefully, they committed abomination;  
    yet they were not at all ashamed,  
    they did not know how to blush.  
Therefore they shall fall among those who fall;  
    at the time when I punish them, they shall be overthrown,  
says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 8, 13, 'When I wanted to gather them, says the LORD,  
    there are no grapes on the vine,  
    nor figs on the fig tree;  
even the leaves are withered,  
    and what I gave them has passed away from them.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 8, 14, 'Why do we sit still?  
Gather together, let us go into the fortified cities  
    and perish there;  
for the LORD our God has doomed us to perish,  
    and has given us poisoned water to drink,  
    because we have sinned against the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 8, 15, 'We look for peace, but find no good,  
    for a time of healing, but there is terror instead.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 8, 16, 'The snorting of their horses is heard from Dan;  
    at the sound of the neighing of their stallions  
    the whole land quakes.  
They come and devour the land and all that fills it,  
    the city and those who live in it.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 8, 17, 'See, I am letting snakes loose among you,  
    adders that cannot be charmed,  
    and they shall bite you,  
says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 8, 18, 'My joy is gone, grief is upon me,  
    my heart is sick.', 'en', 'NRSV-CE', 'The Prophet Mourns for the People'),
(24, 'Yer', 'Jeremiah', 8, 19, 'Hark, the cry of my poor people  
    from far and wide in the land:  
"Is the LORD not in Zion?  
    Is her King not in her?"  
("Why have they provoked me to anger with their images,  
    with their foreign idols?")', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 8, 20, '"The harvest is past, the summer is ended,  
    and we are not saved."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 8, 21, 'For the hurt of my poor people I am hurt,  
    I mourn, and dismay has taken hold of me.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 8, 22, 'Is there no balm in Gilead?  
    Is there no physician there?  
Why then has the health of my poor people  
    not been restored?', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 9, 1, 'O that my head were a spring of water,  
    and my eyes a fountain of tears,  
so that I might weep day and night  
    for the slain of my poor people!', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 9, 2, 'O that I had in the desert  
    a traveler"s lodging place,  
that I might leave my people  
    and go away from them!  
For they are all adulterers,  
    a band of traitors.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 9, 3, 'They bend their tongues like bows;  
    they have grown strong in the land for falsehood, and not for truth;  
for they proceed from evil to evil,  
    and they do not know me, says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 9, 4, 'Beware of your neighbors,  
    and put no trust in any of your kin;  
for all your kin are supplanters,  
    and every neighbor goes around like a slanderer.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 9, 5, 'They all deceive their neighbors,  
    and no one speaks the truth;  
they have taught their tongues to speak lies;  
    they commit iniquity and are too weary to repent.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 9, 6, 'Oppression upon oppression, deceit upon deceit!  
    They refuse to know me, says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 9, 7, 'Therefore thus says the LORD of hosts:  
I will now refine and test them,  
    for what else can I do with my sinful people?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 9, 8, 'Their tongue is a deadly arrow;  
    it speaks deceit through the mouth.  
They all speak friendly words to their neighbors,  
    but inwardly are planning to lay an ambush.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 9, 9, 'Shall I not punish them for these things? says the LORD;  
    and shall I not bring retribution  
    on a nation such as this?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 9, 10, 'Take up weeping and wailing for the mountains,  
    and a lamentation for the pastures of the wilderness,  
because they are laid waste so that no one passes through,  
    and the lowing of cattle is not heard;  
both the birds of the air and the animals  
    have fled and are gone.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 9, 11, 'I will make Jerusalem a heap of ruins,  
    a lair of jackals;  
and I will make the towns of Judah a desolation,  
    without inhabitant.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 9, 12, 'Who is wise enough to understand this? To whom has the mouth of the LORD spoken, so that they may declare it? Why is the land ruined and laid waste like a wilderness, so that no one passes through?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 9, 13, 'And the LORD says: Because they have forsaken my law that I set before them, and have not obeyed my voice, or walked in accordance with it,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 9, 14, 'but have stubbornly followed their own hearts and have gone after the Baals, as their ancestors taught them.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 9, 15, 'Therefore thus says the LORD of hosts, the God of Israel: I am feeding this people with wormwood, and giving them poisonous water to drink.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 9, 16, 'I will scatter them among nations that neither they nor their ancestors have known; and I will send the sword after them, until I have consumed them.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 9, 17, 'Thus says the LORD of hosts:  
Consider, and call for the mourning women to come;  
    send for the skilled women to come;', 'en', 'NRSV-CE', 'The People Mourn in Judgment'),
(24, 'Yer', 'Jeremiah', 9, 18, 'let them quickly raise a dirge over us,  
    so that our eyes may run down with tears,  
    and our eyelids flow with water.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 9, 19, 'For a sound of wailing is heard from Zion:  
    "How we are ruined!  
    We are utterly shamed,  
because we have left the land,  
    because they have cast down our dwellings."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 9, 20, 'Hear, O women, the word of the LORD,  
    and let your ears receive the word of his mouth;  
teach to your daughters a dirge,  
    and each to her neighbor a lament.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 9, 21, '"Death has come up into our windows,  
    it has entered our palaces,  
to cut off the children from the streets  
    and the young men from the squares."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 9, 22, 'Speak! Thus says the LORD:  
"Human corpses shall fall  
    like dung upon the open field,  
like sheaves behind the reaper,  
    and no one shall gather them."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 9, 23, 'Thus says the LORD: Do not let the wise boast in their wisdom, do not let the mighty boast in their might, do not let the wealthy boast in their wealth;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 9, 24, 'but let those who boast boast in this, that they understand and know me, that I am the LORD; I act with steadfast love, justice, and righteousness in the earth, for in these things I delight, says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 9, 25, 'The days are surely coming, says the LORD, when I will attend to all those who are circumcised only in the foreskin:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 9, 26, 'Egypt, Judah, Edom, the Ammonites, Moab, and all those with shaven temples who live in the desert. For all these nations are uncircumcised, and all the house of Israel is uncircumcised in heart.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 10, 1, 'Hear the word that the LORD speaks to you, O house of Israel.', 'en', 'NRSV-CE', 'Idolatry Has Brought Ruin on Israel'),
(24, 'Yer', 'Jeremiah', 10, 2, 'Thus says the LORD:
Do not learn the way of the nations,  
    or be dismayed at the signs of the heavens;  
    for the nations are dismayed at them.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 10, 3, 'For the customs of the peoples are false:  
a tree from the forest is cut down,  
    and worked with an ax by the hands of an artisan;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 10, 4, 'people deck it with silver and gold;  
    they fasten it with hammer and nails  
    so that it cannot move.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 10, 5, 'Their idols are like scarecrows in a cucumber field,  
    and they cannot speak;  
they have to be carried,  
    for they cannot walk.  
Do not be afraid of them,  
    for they cannot do evil,  
    nor is it in them to do good.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 10, 6, 'There is none like you, O LORD;  
    you are great, and your name is great in might.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 10, 7, 'Who would not fear you, O King of the nations?  
    For that is your due;  
among all the wise ones of the nations  
    and in all their kingdoms  
    there is no one like you.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 10, 8, 'They are both stupid and foolish;  
    the instruction given by idols  
    is no better than wood!', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 10, 9, 'Beaten silver is brought from Tarshish,  
    and gold from Uphaz.  
They are the work of the artisan and of the hands of the goldsmith;  
    their clothing is blue and purple;  
    they are all the product of skilled workers.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 10, 10, 'But the LORD is the true God;  
    he is the living God and the everlasting King.  
At his wrath the earth quakes,  
    and the nations cannot endure his indignation.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 10, 11, 'Thus shall you say to them: The gods who did not make the heavens and the earth shall perish from the earth and from under the heavens.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 10, 12, 'It is he who made the earth by his power,  
    who established the world by his wisdom,  
    and by his understanding stretched out the heavens.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 10, 13, 'When he utters his voice, there is a tumult of waters in the heavens,  
    and he makes the mist rise from the ends of the earth.  
He makes lightnings for the rain,  
    and he brings out the wind from his storehouses.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 10, 14, 'Everyone is stupid and without knowledge;  
    goldsmiths are all put to shame by their idols;  
for their images are false,  
    and there is no breath in them.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 10, 15, 'They are worthless, a work of delusion;  
    at the time of their punishment they shall perish.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 10, 16, 'Not like these is the LORD, the portion of Jacob,  
    for he is the one who formed all things,  
and Israel is the tribe of his inheritance;  
    the LORD of hosts is his name.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 10, 17, 'Gather up your bundle from the ground,  
    O you who live under siege!', 'en', 'NRSV-CE', 'The Coming Exile'),
(24, 'Yer', 'Jeremiah', 10, 18, 'For thus says the LORD:  
I am going to sling out the inhabitants of the land  
    at this time,  
and I will bring distress on them,  
    so that they shall feel it.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 10, 19, 'Woe is me because of my hurt!  
    My wound is severe.  
But I said, "Truly this is my punishment,  
    and I must bear it."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 10, 20, 'My tent is destroyed,  
    and all my cords are broken;  
my children have gone from me,  
    and they are no more;  
there is no one to spread my tent again,  
    and to set up my curtains.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 10, 21, 'For the shepherds are stupid,  
    and do not inquire of the LORD;  
therefore they have not prospered,  
    and all their flock is scattered.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 10, 22, 'Hear, a noise! Listen, it is coming--  
    a great commotion from the land of the north  
to make the cities of Judah a desolation,  
    a lair of jackals.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 10, 23, 'I know, O LORD, that the way of human beings is not in their control,  
    that mortals as they walk cannot direct their steps.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 10, 24, 'Correct me, O LORD, but in just measure;  
    not in your anger, or you will bring me to nothing.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 10, 25, 'Pour out your wrath on the nations that do not know you,  
    and on the peoples that do not call on your name;  
for they have devoured Jacob;  
    they have devoured him and consumed him,  
    and have laid waste his habitation.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 11, 1, 'The word that came to Jeremiah from the LORD:', 'en', 'NRSV-CE', 'Israel and Judah Have Broken the Covenant'),
(24, 'Yer', 'Jeremiah', 11, 2, 'Hear the words of this covenant, and speak to the people of Judah and the inhabitants of Jerusalem.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 11, 3, 'You shall say to them, Thus says the LORD, the God of Israel: Cursed be anyone who does not heed the words of this covenant,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 11, 4, 'which I commanded your ancestors when I brought them out of the land of Egypt, from the iron-smelter, saying, Listen to my voice, and do all that I command you. So shall you be my people, and I will be your God,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 11, 5, 'that I may perform the oath that I swore to your ancestors, to give them a land flowing with milk and honey, as at this day. Then I answered, "So be it, LORD."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 11, 6, 'And the LORD said to me: Proclaim all these words in the cities of Judah, and in the streets of Jerusalem: Hear the words of this covenant and do them.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 11, 7, 'For I solemnly warned your ancestors when I brought them up out of the land of Egypt, warning them persistently, even to this day, saying, Obey my voice.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 11, 8, 'Yet they did not obey or incline their ear, but everyone walked in the stubbornness of an evil will. So I brought upon them all the words of this covenant, which I commanded them to do, but they did not.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 11, 9, 'And the LORD said to me: Conspiracy exists among the people of Judah and the inhabitants of Jerusalem.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 11, 10, 'They have turned back to the iniquities of their ancestors of old, who refused to heed my words; they have gone after other gods to serve them; the house of Israel and the house of Judah have broken the covenant that I made with their ancestors.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 11, 11, 'Therefore, thus says the LORD, assuredly I am going to bring disaster upon them that they cannot escape; though they cry out to me, I will not listen to them.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 11, 12, 'Then the cities of Judah and the inhabitants of Jerusalem will go and cry out to the gods to whom they make offerings, but they will never save them in the time of their trouble.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 11, 13, 'For your gods have become as many as your towns, O Judah; and as many as the streets of Jerusalem are the altars to shame you have set up, altars to make offerings to Baal.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 11, 14, 'As for you, do not pray for this people, or lift up a cry or prayer on their behalf, for I will not listen when they call to me in the time of their trouble.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 11, 15, 'What right has my beloved in my house, when she has done vile deeds? Can vows and sacrificial flesh avert your doom? Can you then exult?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 11, 16, 'The LORD once called you, "A green olive tree, fair with goodly fruit"; but with the roar of a great tempest he will set fire to it, and its branches will be consumed.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 11, 17, 'The LORD of hosts, who planted you, has pronounced evil against you, because of the evil that the house of Israel and the house of Judah have done, provoking me to anger by making offerings to Baal.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 11, 18, 'It was the LORD who made it known to me, and I knew;  
    then you showed me their evil deeds.', 'en', 'NRSV-CE', 'Jeremiah"s Life Threatened'),
(24, 'Yer', 'Jeremiah', 11, 19, 'But I was like a gentle lamb  
    led to the slaughter.  
And I did not know it was against me  
    that they devised schemes, saying,  
"Let us destroy the tree with its fruit,  
    let us cut him off from the land of the living,  
    so that his name will no longer be remembered!"', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 11, 20, 'But you, O LORD of hosts, who judge righteously,  
    who try the heart and the mind,  
let me see your retribution upon them,  
    for to you I have committed my cause.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 11, 21, 'Therefore thus says the LORD concerning the people of Anathoth, who seek your life, and say, "You shall not prophesy in the name of the LORD, or you will die by our hand"--', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 11, 22, 'therefore thus says the LORD of hosts: I am going to punish them; the young men shall die by the sword; their sons and their daughters shall die by famine;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 11, 23, 'and not even a remnant shall be left of them. For I will bring disaster upon the people of Anathoth, the year of their punishment.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 12, 1, 'You will be in the right, O LORD,  
    when I lay charges against you;  
    but let me put my case to you.  
Why does the way of the guilty prosper?  
    Why do all who are treacherous thrive?', 'en', 'NRSV-CE', 'Jeremiah Complains to God'),
(24, 'Yer', 'Jeremiah', 12, 2, 'You plant them, and they take root;  
    they grow and bring forth fruit;  
you are near in their mouths  
    yet far from their hearts.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 12, 3, 'But you, O LORD, know me;  
    You see me and test me--my heart is with you.  
Pull them out like sheep for the slaughter,  
    and set them apart for the day of slaughter.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 12, 4, 'How long will the land mourn,  
    and the grass of every field wither?  
For the wickedness of those who live in it  
    the animals and the birds are swept away,  
    and because people said, "He is blind to our ways."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 12, 5, 'If you have raced with foot-runners and they have wearied you,  
    how will you compete with horses?  
And if in a safe land you fall down,  
    how will you fare in the thickets of the Jordan?', 'en', 'NRSV-CE', 'God Replies to Jeremiah'),
(24, 'Yer', 'Jeremiah', 12, 6, 'For even your kinsfolk and your own family,  
    even they have dealt treacherously with you;  
    they are in full cry after you;  
do not believe them,  
    though they speak friendly words to you.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 12, 7, 'I have forsaken my house,  
    I have abandoned my heritage;  
I have given the beloved of my heart  
    into the hands of her enemies.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 12, 8, 'My heritage has become to me  
    like a lion in the forest;  
she has lifted up her voice against me--  
    therefore I hate her.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 12, 9, 'Is the hyena greedy for my heritage at my command?  
    Are the birds of prey all around her?  
Go, assemble all the wild animals;  
    bring them to devour her.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 12, 10, 'Many shepherds have destroyed my vineyard,  
    they have trampled down my portion,  
they have made my pleasant portion  
    a desolate wilderness.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 12, 11, 'They have made it a desolation;  
    desolate, it mourns to me.  
The whole land is made desolate,  
    but no one lays it to heart.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 12, 12, 'Upon all the bare heights in the desert  
    spoilers have come;  
for the sword of the LORD devours  
    from one end of the land to the other;  
    no one shall be safe.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 12, 13, 'They have sown wheat and have reaped thorns,  
    they have tired themselves out but profit nothing.  
They shall be ashamed of their harvests  
    because of the fierce anger of the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 12, 14, 'Thus says the LORD concerning all my evil neighbors who touch the heritage that I have given my people Israel to inherit: I am about to pluck them up from their land, and I will pluck up the house of Judah from among them.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 12, 15, 'And after I have plucked them up, I will again have compassion on them, and I will bring them again to their heritage and to their land, every one of them.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 12, 16, 'And then, if they will diligently learn the ways of my people, to swear by my name, "As the LORD lives," as they taught my people to swear by Baal, then they shall be built up in the midst of my people.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 12, 17, 'But if any nation will not listen, then I will completely uproot it and destroy it, says the LORD.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 13, 1, 'Thus said the LORD to me, "Go and buy yourself a linen loincloth, and put it on your loins, but do not dip it in water."', 'en', 'NRSV-CE', 'The Linen Loincloth'),
(24, 'Yer', 'Jeremiah', 13, 2, 'So I bought a loincloth according to the word of the LORD, and put it on my loins.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 13, 3, 'And the word of the LORD came to me a second time, saying,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 13, 4, '"Take the loincloth that you bought and are wearing, and go now to the Euphrates, and hide it there in a cleft of the rock."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 13, 5, 'So I went, and hid it by the Euphrates, as the LORD commanded me.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 13, 6, 'And after many days the LORD said to me, "Go now to the Euphrates, and take from there the loincloth that I commanded you to hide there."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 13, 7, 'Then I went to the Euphrates, and dug, and I took the loincloth from the place where I had hidden it. But now the loincloth was ruined; it was good for nothing.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 13, 8, 'Then the word of the LORD came to me:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 13, 9, 'Thus says the LORD: Just so I will ruin the pride of Judah and the great pride of Jerusalem.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 13, 10, 'This evil people, who refuse to hear my words, who stubbornly follow their own will and have gone after other gods to serve them and worship them, shall be like this loincloth, which is good for nothing.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 13, 11, 'For as the loincloth clings to one"s loins, so I made the whole house of Israel and the whole house of Judah cling to me, says the LORD, in order that they might be for me a people, a name, a praise, and a glory. But they would not listen.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 13, 12, 'You shall speak to them this word: Thus says the LORD, the God of Israel: Every wine-jar should be filled with wine. And they will say to you, "Do you think we do not know that every wine-jar should be filled with wine?"', 'en', 'NRSV-CE', 'Symbol of the Wine-Jars'),
(24, 'Yer', 'Jeremiah', 13, 13, 'Then you shall say to them: Thus says the LORD: I am about to fill all the inhabitants of this land--the kings who sit on David"s throne, the priests, the prophets, and all the inhabitants of Jerusalem--with drunkenness.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 13, 14, 'And I will dash them one against another, parents and children together, says the LORD. I will not pity or spare or have compassion when I destroy them.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 13, 15, 'Hear and give ear; do not be haughty,  
    for the LORD has spoken.', 'en', 'NRSV-CE', 'Exile Threatened'),
(24, 'Yer', 'Jeremiah', 13, 16, 'Give glory to the LORD your God  
    before he brings darkness,  
and before your feet stumble  
    on the mountains at twilight;  
while you look for light,  
    he turns it into gloom  
    and makes it deep darkness.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 13, 17, 'But if you will not listen,  
    my soul will weep in secret for your pride;  
my eyes will weep bitterly and run down with tears,  
    because the LORD"s flock has been taken captive.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 13, 18, 'Say to the king and the queen mother:  
    "Take a lowly seat,  
for your beautiful crown  
    has come down from your head."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 13, 19, 'The towns of the Negeb are shut up  
    with no one to open them;  
all Judah is taken into exile,  
    wholly taken into exile.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 13, 20, 'Lift up your eyes and see  
    those who come from the north.  
Where is the flock that was given you,  
    your beautiful flock?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 13, 21, 'What will you say when they set as head over you  
    those whom you have trained  
    to be your allies?  
Will not pangs take hold of you,  
    like those of a woman in labor?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 13, 22, 'And if you say in your heart,  
    "Why have these things come upon me?"  
it is for the greatness of your iniquity  
    that your skirts are lifted up,  
    and you are violated.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 13, 23, 'Can Ethiopians change their skin  
    or leopards their spots?  
Then also you can do good  
    who are accustomed to do evil.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 13, 24, 'I will scatter you like chaff  
    driven by the wind from the desert.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 13, 25, 'This is your lot,  
    the portion I have measured out to you, says the LORD,  
because you have forgotten me  
    and trusted in lies.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 13, 26, 'I myself will lift up your skirts over your face,  
    and your shame will be seen.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 13, 27, 'I have seen your abominations,  
    your adulteries and neighings, your shameless prostitutions  
    on the hills of the countryside.  
Woe to you, O Jerusalem!  
    How long will it be  
    before you are made clean?', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 14, 1, 'The word of the LORD that came to Jeremiah concerning the drought:', 'en', 'NRSV-CE', 'The Great Drought'),
(24, 'Yer', 'Jeremiah', 14, 2, 'Judah mourns  
    and her gates languish;  
they lie in gloom on the ground,  
    and the cry of Jerusalem goes up.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 14, 3, 'Her nobles send their servants for water;  
    they come to the cisterns,  
they find no water,  
    they return with their vessels empty.  
They are ashamed and dismayed  
    and cover their heads,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 14, 4, 'because the ground is cracked.  
    Because there has been no rain on the land  
the farmers are dismayed;  
    they cover their heads.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 14, 5, 'Even the doe in the field forsakes her newborn fawn  
    because there is no grass.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 14, 6, 'The wild asses stand on the bare heights,  
    they pant for air like jackals;  
their eyes fail  
    because there is no herbage.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 14, 7, 'Although our iniquities testify against us,  
    act, O LORD, for your name"s sake;  
our apostasies indeed are many,  
    and we have sinned against you.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 14, 8, 'O hope of Israel,  
    its savior in time of trouble,  
why should you be like a stranger in the land,  
    like a traveler turning aside for the night?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 14, 9, 'Why should you be like someone confused,  
    like a mighty warrior who cannot give help?  
Yet you, O LORD, are in the midst of us,  
    and we are called by your name;  
    do not forsake us!', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 14, 10, 'Thus says the LORD concerning this people:  
Truly they have loved to wander,  
    they have not restrained their feet;  
therefore the LORD does not accept them,  
    now he will remember their iniquity  
    and punish their sins.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 14, 11, 'The LORD said to me: Do not pray for the welfare of this people.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 14, 12, 'Although they fast, I do not hear their cry, and although they offer burnt offering and grain offering, I do not accept them; but by the sword, by famine, and by pestilence I consume them.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 14, 13, 'Then I said: "Ah, Lord God! Here are the prophets saying to them, "You shall not see the sword, nor shall you have famine, but I will give you true peace in this place.""', 'en', 'NRSV-CE', 'Denunciation of Lying Prophets'),
(24, 'Yer', 'Jeremiah', 14, 14, 'And the LORD said to me: The prophets are prophesying lies in my name; I did not send them, nor did I command them or speak to them. They are prophesying to you a lying vision, worthless divination, and the deceit of their own minds.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 14, 15, 'Therefore thus says the LORD concerning the prophets who prophesy in my name though I did not send them, and who say, "Sword and famine shall not come on this land": By sword and famine those prophets shall be consumed.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 14, 16, 'And the people to whom they prophesy shall be thrown out into the streets of Jerusalem, victims of famine and sword. There shall be no one to bury them--themselves, their wives, their sons, and their daughters. For I will pour out their wickedness upon them.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 14, 17, 'You shall say to them this word:  
Let my eyes run down with tears night and day,  
    and let them not cease,  
for the virgin daughter--my people--is struck down with a crushing blow,  
    with a very grievous wound.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 14, 18, 'If I go out into the field,  
    look--those killed by the sword!  
And if I enter the city,  
    look--those sick with famine!  
For both prophet and priest ply their trade throughout the land,  
    and have no knowledge.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 14, 19, 'Have you completely rejected Judah?  
    Does your heart loathe Zion?  
Why have you struck us down  
    so that there is no healing for us?  
We look for peace, but find no good;  
    for a time of healing, but there is terror instead.', 'en', 'NRSV-CE', 'The People Plead for Mercy'),
(24, 'Yer', 'Jeremiah', 14, 20, 'We acknowledge our wickedness, O LORD,  
    the iniquity of our ancestors,  
    for we have sinned against you.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 14, 21, 'Do not spurn us, for your name"s sake;  
    do not dishonor your glorious throne;  
    remember and do not break your covenant with us.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 14, 22, 'Can any idols of the nations bring rain?  
    Or can the heavens give showers?  
Is it not you, O LORD our God?  
    We set our hope on you,  
    for it is you who do all this.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 15, 1, 'Then the LORD said to me: Though Moses and Samuel stood before me, yet my heart would not turn toward this people. Send them out of my sight, and let them go!', 'en', 'NRSV-CE', 'Punishment Is Inevitable'),
(24, 'Yer', 'Jeremiah', 15, 2, 'And when they say to you, "Where shall we go?" you shall say to them: Thus says the LORD:
Those destined for pestilence, to pestilence,  
    and those destined for the sword, to the sword;  
those destined for famine, to famine,  
    and those destined for captivity, to captivity.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 15, 3, 'And I will appoint over them four kinds of destroyers, says the LORD: the sword to kill, the dogs to drag away, and the birds of the air and the wild animals of the earth to devour and destroy.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 15, 4, 'I will make them a horror to all the kingdoms of the earth because of what King Manasseh son of Hezekiah of Judah did in Jerusalem.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 15, 5, 'Who will have pity on you, O Jerusalem,  
    or who will bemoan you?  
Who will turn aside  
    to ask about your welfare?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 15, 6, 'You have rejected me, says the LORD,  
    you are going backward;  
so I have stretched out my hand against you and destroyed you--  
    I am weary of relenting.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 15, 7, 'I have winnowed them with a winnowing fork  
    in the gates of the land;  
I have bereaved them, I have destroyed my people;  
    they did not turn from their ways.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 15, 8, 'Their widows became more numerous  
    than the sand of the seas;  
I have brought against the mothers of youths  
    a destroyer at noonday;  
I have made anguish and terror  
    fall upon her suddenly.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 15, 9, 'She who bore seven has languished;  
    she has swooned away;  
her sun went down while it was yet day;  
    she has been shamed and disgraced.  
And the rest of them I will give to the sword  
    before their enemies,  
says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 15, 10, 'Woe is me, my mother, that you ever bore me, a man of strife and contention to the whole land! I have not lent, nor have I borrowed, yet all of them curse me.', 'en', 'NRSV-CE', 'Jeremiah Complains Again and Is Reassured'),
(24, 'Yer', 'Jeremiah', 15, 11, 'The LORD said: Surely I have intervened in your life for good, surely I have imposed enemies on you in a time of trouble and in a time of distress.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 15, 12, 'Can iron and bronze break iron from the north?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 15, 13, 'Your wealth and your treasures I will give as plunder, without price, for all your sins, throughout all your territory.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 15, 14, 'I will make you serve your enemies in a land that you do not know, for in my anger a fire is kindled that shall burn forever.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 15, 15, 'O LORD, you know;  
    remember me and visit me,  
    and bring down retribution for me on my persecutors.  
In your forbearance do not take me away;  
    know that on your account I suffer insult.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 15, 16, 'Your words were found, and I ate them,  
    and your words became to me a joy  
    and the delight of my heart;  
for I am called by your name,  
    O LORD, God of hosts.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 15, 17, 'I did not sit in the company of merrymakers,  
    nor did I rejoice;  
under the weight of your hand I sat alone,  
    for you had filled me with indignation.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 15, 18, 'Why is my pain unceasing,  
    my wound incurable,  
    refusing to be healed?  
Truly, you are to me like a deceitful brook,  
    like waters that fail.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 15, 19, 'Therefore thus says the LORD:  
If you turn back, I will take you back,  
    and you shall stand before me.  
If you utter what is precious, and not what is worthless,  
    you shall serve as my mouth.  
It is they who will turn to you,  
    not you who will turn to them.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 15, 20, 'And I will make you to this people  
    a fortified wall of bronze;  
they will fight against you,  
    but they shall not prevail over you,  
for I am with you  
    to save you and deliver you,  
says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 15, 21, 'I will deliver you out of the hand of the wicked,  
    and redeem you from the grasp of the ruthless.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 16, 1, 'The word of the LORD came to me:', 'en', 'NRSV-CE', 'Jeremiah"s Celibacy and Message'),
(24, 'Yer', 'Jeremiah', 16, 2, 'You shall not take a wife, nor shall you have sons or daughters in this place.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 16, 3, 'For thus says the LORD concerning the sons and daughters who are born in this place, and concerning the mothers who bear them and the fathers who beget them in this land:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 16, 4, 'They shall die of deadly diseases. They shall not be lamented, nor shall they be buried; they shall become like dung on the surface of the ground. They shall perish by the sword and by famine, and their dead bodies shall become food for the birds of the air and for the wild animals of the earth.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 16, 5, 'For thus says the LORD: Do not enter the house of mourning, or go to lament, or bemoan them; for I have taken away my peace from this people, says the LORD, my steadfast love and mercy.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 16, 6, 'Both great and small shall die in this land; they shall not be buried, and no one shall lament for them; there shall be no gashing, no shaving of the head for them.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 16, 7, 'No one shall break bread for the mourner, to offer comfort for the dead; nor shall anyone give them the cup of consolation to drink for their fathers or their mothers.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 16, 8, 'You shall not go into the house of feasting to sit with them, to eat and drink.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 16, 9, 'For thus says the LORD of hosts, the God of Israel: I am going to banish from this place, in your days and before your eyes, the voice of mirth and the voice of gladness, the voice of the bridegroom and the voice of the bride.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 16, 10, 'And when you tell this people all these words, and they say to you, "Why has the LORD pronounced all this great evil against us? What is our iniquity? What is the sin that we have committed against the LORD our God?"', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 16, 11, 'then you shall say to them: It is because your ancestors have forsaken me, says the LORD, and have gone after other gods and have served and worshiped them, and have forsaken me and have not kept my law;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 16, 12, 'and because you have behaved worse than your ancestors, for here you are, every one of you, following your stubborn evil will, refusing to listen to me.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 16, 13, 'Therefore I will hurl you out of this land into a land that neither you nor your ancestors have known, and there you shall serve other gods day and night, for I will show you no favor.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 16, 14, 'Therefore, the days are surely coming, says the LORD, when it shall no longer be said, "As the LORD lives who brought the people of Israel up out of the land of Egypt,"', 'en', 'NRSV-CE', 'God Will Restore Israel'),
(24, 'Yer', 'Jeremiah', 16, 15, 'but "As the LORD lives who brought the people of Israel up out of the land of the north and out of all the lands where he had driven them." For I will bring them back to their own land that I gave to their ancestors.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 16, 16, 'I am now sending for many fishermen, says the LORD, and they shall catch them; and afterward I will send for many hunters, and they shall hunt them from every mountain and every hill, and out of the clefts of the rocks.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 16, 17, 'For my eyes are on all their ways; they are not hidden from my presence, nor is their iniquity concealed from my sight.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 16, 18, 'And I will doubly repay their iniquity and their sin, because they have polluted my land with the carcasses of their detestable idols, and have filled my inheritance with their abominations.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 16, 19, 'O LORD, my strength and my stronghold,  
    my refuge in the day of trouble,  
to you shall the nations come  
    from the ends of the earth and say:  
Our ancestors have inherited nothing but lies,  
    worthless things in which there is no profit.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 16, 20, 'Can mortals make for themselves gods?  
    Such are no gods!', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 16, 21, '"Therefore I am surely going to teach them, this time I am going to teach them my power and my might, and they shall know that my name is the LORD."', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 17, 1, 'The sin of Judah is written with an iron pen; with a diamond point it is engraved on the tablet of their hearts, and on the horns of their altars,', 'en', 'NRSV-CE', 'Judah"s Sin and Punishment'),
(24, 'Yer', 'Jeremiah', 17, 2, 'while their children remember their altars and their sacred poles, beside every green tree, and on the high hills,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 17, 3, 'on the mountains in the open country. Your wealth and all your treasures I will give for spoil as the price of your sin throughout all your territory.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 17, 4, 'By your own act you shall lose the heritage that I gave you, and I will make you serve your enemies in a land that you do not know, for in my anger a fire is kindled that shall burn forever.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 17, 5, 'Thus says the LORD:  
Cursed are those who trust in mere mortals  
    and make mere flesh their strength,  
    whose hearts turn away from the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 17, 6, 'They shall be like a shrub in the desert,  
    and shall not see when relief comes.  
They shall live in the parched places of the wilderness,  
    in an uninhabited salt land.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 17, 7, 'Blessed are those who trust in the LORD,  
    whose trust is the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 17, 8, 'They shall be like a tree planted by water,  
    sending out its roots by the stream.  
It shall not fear when heat comes,  
    and its leaves shall stay green;  
in the year of drought it is not anxious,  
    and it does not cease to bear fruit.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 17, 9, 'The heart is devious above all else;  
    it is perverse--  
    who can understand it?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 17, 10, 'I the LORD test the mind  
    and search the heart,  
to give to all according to their ways,  
    according to the fruit of their doings.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 17, 11, 'Like the partridge hatching what it did not lay,  
    so are all who amass wealth unjustly;  
in mid-life it will leave them,  
    and at their end they will prove to be fools.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 17, 12, 'O glorious throne, exalted from the beginning,  
    shrine of our sanctuary!', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 17, 13, 'O hope of Israel! O LORD!  
    All who forsake you shall be put to shame;  
those who turn away from you shall be recorded in the underworld,  
    for they have forsaken the fountain of living water, the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 17, 14, 'Heal me, O LORD, and I shall be healed;  
    save me, and I shall be saved;  
    for you are my praise.', 'en', 'NRSV-CE', 'Jeremiah Prays for Vindication'),
(24, 'Yer', 'Jeremiah', 17, 15, 'See how they say to me,  
    "Where is the word of the LORD?  
    Let it come!"', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 17, 16, 'But I have not run away from being a shepherd in your service,  
    nor have I desired the fatal day.  
You know what came from my lips;  
    it was before your face.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 17, 17, 'Do not become a terror to me;  
    you are my refuge in the day of disaster;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 17, 18, 'Let my persecutors be shamed,  
    but do not let me be shamed;  
let them be dismayed,  
    but do not let me be dismayed;  
bring on them the day of disaster;  
    destroy them with double destruction!', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 17, 19, 'Thus said the LORD to me: Go and stand in the People"s Gate, by which the kings of Judah enter and by which they go out, and in all the gates of Jerusalem,', 'en', 'NRSV-CE', 'Hallow the Sabbath Day'),
(24, 'Yer', 'Jeremiah', 17, 20, 'and say to them: Hear the word of the LORD, you kings of Judah, and all Judah, and all the inhabitants of Jerusalem, who enter by these gates.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 17, 21, 'Thus says the LORD: For the sake of your lives, take care that you do not bear a burden on the sabbath day or bring it in by the gates of Jerusalem.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 17, 22, 'And do not carry a burden out of your houses on the sabbath or do any work, but keep the sabbath day holy, as I commanded your ancestors.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 17, 23, 'Yet they did not listen or incline their ear; they stiffened their necks and would not hear or receive instruction.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 17, 24, 'But if you listen to me, says the LORD, and bring in no burden by the gates of this city on the sabbath day, but keep the sabbath day holy and do no work on it,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 17, 25, 'then there shall enter by the gates of this city kings who sit on the throne of David, riding in chariots and on horses, they and their officials, the people of Judah and the inhabitants of Jerusalem; and this city shall be inhabited forever.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 17, 26, 'And people shall come from the towns of Judah and the places around Jerusalem, from the land of Benjamin, from the Shephelah, from the hill country, and from the Negeb, bringing burnt offerings and sacrifices, grain offerings and frankincense, and bringing thank offerings to the house of the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 17, 27, 'But if you do not listen to me, to keep the sabbath day holy, and to carry in no burden through the gates of Jerusalem on the sabbath day, then I will kindle a fire in its gates; it shall devour the palaces of Jerusalem and shall not be quenched.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 18, 1, 'The word that came to Jeremiah from the LORD:', 'en', 'NRSV-CE', 'The Potter and the Clay'),
(24, 'Yer', 'Jeremiah', 18, 2, '"Come, go down to the potter"s house, and there I will let you hear my words."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 18, 3, 'So I went down to the potter"s house, and there he was working at his wheel.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 18, 4, 'The vessel he was making of clay was spoiled in the potter"s hand, and he reworked it into another vessel, as seemed good to him.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 18, 5, 'Then the word of the LORD came to me:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 18, 6, 'Can I not do with you, O house of Israel, just as this potter has done? says the LORD. Just like the clay in the potter"s hand, so are you in my hand, O house of Israel.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 18, 7, 'At one moment I may declare concerning a nation or a kingdom, that I will pluck up and break down and destroy it,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 18, 8, 'but if that nation, concerning which I have spoken, turns from its evil, I will change my mind about the disaster that I intended to bring on it.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 18, 9, 'And at another moment I may declare concerning a nation or a kingdom that I will build and plant it,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 18, 10, 'but if it does evil in my sight, not listening to my voice, then I will change my mind about the good that I had intended to do to it.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 18, 11, 'Now, therefore, say to the people of Judah and the inhabitants of Jerusalem: Thus says the LORD: Look, I am a potter shaping evil against you and devising a plan against you. Turn now, all of you from your evil way, and amend your ways and your doings.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 18, 12, 'But they say, "It is no use! We will follow our own plans, and each of us will act according to the stubbornness of our evil will."', 'en', 'NRSV-CE', 'Israel"s Stubborn Idolatry'),
(24, 'Yer', 'Jeremiah', 18, 13, 'Therefore thus says the LORD:  
Ask among the nations:  
    Who has heard the like of this?  
The virgin Israel has done  
    a most horrible thing.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 18, 14, 'Does the snow of Lebanon leave  
    the crags of Sirion?  
Do the mountain waters run dry,  
    the cold flowing streams?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 18, 15, 'But my people have forgotten me,  
    they burn offerings to a delusion;  
they have stumbled in their ways,  
    in the ancient roads,  
and have gone into bypaths,  
    not the highway,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 18, 16, 'making their land a horror,  
    a thing to be hissed at forever.  
All who pass by it are horrified  
    and shake their heads.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 18, 17, 'Like the wind from the east,  
    I will scatter them before the enemy.  
I will show them my back, not my face,  
    in the day of their calamity.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 18, 18, 'Then they said, "Come, let us make plots against Jeremiah--for instruction shall not perish from the priest, nor counsel from the wise, nor the word from the prophet. Come, let us bring charges against him, and let us not heed any of his words."', 'en', 'NRSV-CE', 'A Plot against Jeremiah'),
(24, 'Yer', 'Jeremiah', 18, 19, 'Give heed to me, O LORD,  
    and listen to what my adversaries say!', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 18, 20, 'Is evil a recompense for good?  
    Yet they have dug a pit for my life.  
Remember how I stood before you  
    to speak good for them,  
    to turn away your wrath from them.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 18, 21, 'Therefore give their children over to famine;  
    hurl them out to the power of the sword,  
let their wives become childless and widowed.  
    May their men meet death by pestilence,  
    their youths be slain by the sword in battle.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 18, 22, 'May a cry be heard from their houses,  
    when you bring the marauder suddenly upon them!  
For they have dug a pit to catch me,  
    and laid snares for my feet.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 18, 23, 'Yet you, O LORD, know  
    all their plotting to kill me.  
Do not forgive their iniquity,  
    do not blot out their sin from your sight.  
Let them be tripped up before you;  
    deal with them while you are angry.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 19, 1, 'Thus said the LORD: Go and buy a potter"s earthenware jug. Take with you some of the elders of the people and some of the senior priests,', 'en', 'NRSV-CE', 'The Broken Earthenware Jug'),
(24, 'Yer', 'Jeremiah', 19, 2, 'and go out to the valley of the son of Hinnom at the entry of the Potsherd Gate, and proclaim there the words that I tell you.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 19, 3, 'You shall say: Hear the word of the LORD, O kings of Judah and inhabitants of Jerusalem. Thus says the LORD of hosts, the God of Israel: I am going to bring such disaster upon this place that the ears of everyone who hears of it will tingle.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 19, 4, 'Because the people have forsaken me, and have profaned this place by making offerings in it to other gods whom neither they nor their ancestors nor the kings of Judah have known, and because they have filled this place with the blood of the innocent,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 19, 5, 'and gone on building the high places of Baal to burn their children in the fire as burnt offerings to Baal, which I did not command or decree, nor did it enter my mind;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 19, 6, 'therefore the days are surely coming, says the LORD, when this place shall no more be called Topheth, or the valley of the son of Hinnom, but the valley of Slaughter.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 19, 7, 'And in this place I will make void the plans of Judah and Jerusalem, and will make them fall by the sword before their enemies, and by the hand of those who seek their life. I will give their dead bodies for food to the birds of the air and to the wild animals of the earth.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 19, 8, 'And I will make this city a horror, a thing to be hissed at; everyone who passes by it will be horrified and will hiss because of all its disasters.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 19, 9, 'And I will make them eat the flesh of their sons and the flesh of their daughters, and all shall eat the flesh of their neighbors in the siege, and in the distress with which their enemies and those who seek their life afflict them.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 19, 10, 'Then you shall break the jug in the sight of those who go with you,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 19, 11, 'and shall say to them: Thus says the LORD of hosts: So will I break this people and this city, as one breaks a potter"s vessel, so that it can never be mended. In Topheth they shall bury until there is no more room to bury.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 19, 12, 'Thus will I do to this place, says the LORD, and to its inhabitants, making this city like Topheth.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 19, 13, 'And the houses of Jerusalem and the houses of the kings of Judah shall be defiled like the place of Topheth--all the houses upon whose roofs offerings have been made to the whole host of heaven, and libations have been poured out to other gods.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 19, 14, 'When Jeremiah came from Topheth, where the LORD had sent him to prophesy, he stood in the court of the LORD"s house and said to all the people:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 19, 15, 'Thus says the LORD of hosts, the God of Israel: I am now bringing upon this city and upon all its towns all the disaster that I have pronounced against it, because they have stiffened their necks, refusing to hear my words.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 20, 1, 'Now the priest Pashhur son of Immer, who was chief officer in the house of the LORD, heard Jeremiah prophesying these things.', 'en', 'NRSV-CE', 'Jeremiah Persecuted by Pashhur'),
(24, 'Yer', 'Jeremiah', 20, 2, 'Then Pashhur struck the prophet Jeremiah, and put him in the stocks that were in the upper Benjamin Gate of the house of the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 20, 3, 'The next morning when Pashhur released Jeremiah from the stocks, Jeremiah said to him, The LORD has named you not Pashhur but "Terror-all-around."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 20, 4, 'For thus says the LORD: I am making you a terror to yourself and to all your friends; and they shall fall by the sword of their enemies while you look on. And I will give all Judah into the hand of the king of Babylon; he shall carry them captive to Babylon, and shall kill them with the sword.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 20, 5, 'I will give all the wealth of this city, all its gains, all its prized belongings, and all the treasures of the kings of Judah into the hand of their enemies, who shall plunder them, and seize them, and carry them to Babylon.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 20, 6, 'And you, Pashhur, and all who live in your house, shall go into captivity, and to Babylon you shall go; there you shall die, and there you shall be buried, you and all your friends, to whom you have prophesied falsely.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 20, 7, 'O LORD, you have enticed me,  
    and I was enticed;  
you have overpowered me,  
    and you have prevailed.  
I have become a laughingstock all day long;  
    everyone mocks me.', 'en', 'NRSV-CE', 'Jeremiah Denounces His Persecutors'),
(24, 'Yer', 'Jeremiah', 20, 8, 'For whenever I speak, I must cry out,  
    I must shout, "Violence and destruction!"  
For the word of the LORD has become for me  
    a reproach and derision all day long.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 20, 9, 'If I say, "I will not mention him,  
    or speak any more in his name,"  
then within me there is something like a burning fire  
    shut up in my bones;  
I am weary with holding it in,  
    and I cannot.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 20, 10, 'For I hear many whispering:  
    "Terror is all around!  
Denounce him! Let us denounce him!"  
    All my close friends  
    are watching for me to stumble.  
"Perhaps he can be enticed,  
    and we can prevail against him,  
    and take our revenge on him."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 20, 11, 'But the LORD is with me like a dread warrior;  
    therefore my persecutors will stumble,  
    and they will not prevail.  
They will be greatly shamed,  
    for they will not succeed.  
Their eternal dishonor  
    will never be forgotten.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 20, 12, 'O LORD of hosts, you test the righteous,  
    you see the heart and the mind;  
let me see your retribution upon them,  
    for to you I have committed my cause.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 20, 13, 'Sing to the LORD;  
    praise the LORD!  
For he has delivered the life of the needy  
    from the hands of evildoers.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 20, 14, 'Cursed be the day  
    on which I was born!  
The day when my mother bore me,  
    let it not be blessed!', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 20, 15, 'Cursed be the man  
    who brought the news to my father, saying,  
"A child is born to you, a son,"  
    making him very glad.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 20, 16, 'Let that man be like the cities  
    that the LORD overthrew without pity;  
let him hear a cry in the morning  
    and an alarm at noon,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 20, 17, 'because he did not kill me in the womb;  
    so my mother would have been my grave,  
    and her womb forever great.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 20, 18, 'Why did I come forth from the womb  
    to see toil and sorrow,  
    and spend my days in shame?', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 21, 1, 'This is the word that came to Jeremiah from the LORD, when King Zedekiah sent to him Pashhur son of Malchiah and the priest Zephaniah son of Maaseiah, saying,', 'en', 'NRSV-CE', 'Jerusalem Will Fall to Nebuchadrezzar'),
(24, 'Yer', 'Jeremiah', 21, 2, '"Please inquire of the LORD on our behalf, for King Nebuchadrezzar of Babylon is making war against us; perhaps the LORD will perform a wonderful deed for us, as he has often done, and will make him withdraw from us."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 21, 3, 'Then Jeremiah said to them:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 21, 4, 'Thus you shall say to Zedekiah: Thus says the LORD, the God of Israel: I am going to turn back the weapons of war that are in your hands and with which you are fighting against the king of Babylon and against the Chaldeans who are besieging you outside the walls; and I will bring them together into the center of this city.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 21, 5, 'I myself will fight against you with outstretched hand and mighty arm, in anger, in fury, and in great wrath.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 21, 6, 'And I will strike down the inhabitants of this city, both human beings and animals; they shall die of a great pestilence.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 21, 7, 'Afterward, says the LORD, I will give King Zedekiah of Judah, and his servants, and the people in this city--those who survive the pestilence, sword, and famine--into the hands of King Nebuchadrezzar of Babylon, into the hands of their enemies, into the hands of those who seek their lives. He shall strike them down with the edge of the sword; he shall not pity them, or spare them, or have compassion.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 21, 8, 'And to this people you shall say: Thus says the LORD: See, I am setting before you the way of life and the way of death.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 21, 9, 'Those who stay in this city shall die by the sword, by famine, and by pestilence; but those who go out and surrender to the Chaldeans who are besieging you shall live and shall have their lives as a prize of war.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 21, 10, 'For I have set my face against this city for evil and not for good, says the LORD: it shall be given into the hands of the king of Babylon, and he shall burn it with fire.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 21, 11, 'To the house of the king of Judah say: Hear the word of the LORD,', 'en', 'NRSV-CE', 'Message to the House of David'),
(24, 'Yer', 'Jeremiah', 21, 12, 'O house of David! Thus says the LORD:
Execute justice in the morning,  
    and deliver from the hand of the oppressor  
    anyone who has been robbed,  
or else my wrath will go forth like fire,  
    and burn, with no one to quench it,  
    because of your evil doings.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 21, 13, 'See, I am against you, O inhabitant of the valley,  
    O rock of the plain,  
says the LORD;  
you who say, "Who can come down against us,  
    or who can enter our places of refuge?"', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 21, 14, 'I will punish you according to the fruit of your doings,  
says the LORD;  
    I will kindle a fire in its forest,  
    and it shall devour all that is around it.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 22, 1, 'Thus says the LORD: Go down to the house of the king of Judah, and speak there this word,', 'en', 'NRSV-CE', 'Exhortation to Repent'),
(24, 'Yer', 'Jeremiah', 22, 2, 'and say: Hear the word of the LORD, O King of Judah sitting on the throne of David--you, and your servants, and your people who enter these gates.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 22, 3, 'Thus says the LORD: Act with justice and righteousness, and deliver from the hand of the oppressor anyone who has been robbed. And do no wrong or violence to the alien, the orphan, and the widow, or shed innocent blood in this place.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 22, 4, 'For if you will indeed obey this word, then through the gates of this house shall enter kings who sit on the throne of David, riding in chariots and on horses, they, and their servants, and their people.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 22, 5, 'But if you will not heed these words, I swear by myself, says the LORD, that this house shall become a desolation.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 22, 6, 'For thus says the LORD concerning the house of the king of Judah:
You are like Gilead to me,  
    like the summit of Lebanon;  
but I swear that I will make you a desert,  
    an uninhabited city.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 22, 7, 'I will prepare destroyers against you,  
    all with their weapons;  
they shall cut down your choicest cedars  
    and cast them into the fire.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 22, 8, 'And many nations will pass by this city, and all of them will say one to another, "Why has the LORD dealt in this way with that great city?"', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 22, 9, 'And they will answer, "Because they abandoned the covenant of the LORD their God, and worshiped other gods and served them."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 22, 10, 'Do not weep for him who is dead,  
    nor bemoan him;  
weep rather for him who goes away,  
    for he shall return no more  
    to see his native land.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 22, 11, 'For thus says the LORD concerning Shallum son of King Josiah of Judah, who succeeded his father Josiah, and who went away from this place: He shall return here no more,', 'en', 'NRSV-CE', 'Message to the Sons of Josiah'),
(24, 'Yer', 'Jeremiah', 22, 12, 'but in the place where they have carried him captive he shall die, and he shall never see this land again.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 22, 13, 'Woe to him who builds his house by unrighteousness,  
    and his upper rooms by injustice;  
who makes his neighbors work for nothing,  
    and does not give them their wages;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 22, 14, 'who says, "I will build myself a spacious house  
    with large upper rooms,"  
and who cuts out windows for it,  
    paneling it with cedar,  
    and painting it with vermilion.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 22, 15, 'Are you a king  
    because you compete in cedar?  
Did not your father eat and drink  
    and do justice and righteousness?  
    Then it was well with him.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 22, 16, 'He judged the cause of the poor and needy;  
    then it was well.  
Is not this to know me?  
    says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 22, 17, 'But your eyes and heart  
    are only on your dishonest gain,  
for shedding innocent blood,  
    and for practicing oppression and violence.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 22, 18, 'Therefore thus says the LORD concerning King Jehoiakim son of Josiah of Judah:
They shall not lament for him, saying,  
    "Alas, my brother!" or "Alas, sister!"  
They shall not lament for him, saying,  
    "Alas, lord!" or "Alas, his majesty!"', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 22, 19, 'With the burial of a donkey he shall be buried--  
    dragged off and thrown out beyond the gates of Jerusalem.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 22, 20, 'Go up to Lebanon, and cry out,  
    and lift up your voice in Bashan;  
cry out from Abarim,  
    for all your lovers are crushed.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 22, 21, 'I spoke to you in your prosperity,  
    but you said, "I will not listen."  
This has been your way from your youth,  
    for you have not obeyed my voice.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 22, 22, 'The wind shall shepherd all your shepherds,  
    and your lovers shall go into captivity;  
then you will be ashamed and dismayed  
    because of all your wickedness.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 22, 23, 'O inhabitant of Lebanon,  
    nested among the cedars,  
how you will groan when pangs come upon you,  
    pain as of a woman in labor!', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 22, 24, 'As I live, says the LORD, even if King Coniah son of Jehoiakim of Judah were the signet ring on my right hand, even from there I would tear you off', 'en', 'NRSV-CE', 'Judgment on Coniah (Jehoiachin)'),
(24, 'Yer', 'Jeremiah', 22, 25, 'and give you into the hands of those who seek your life, into the hands of those of whom you are afraid, even into the hands of King Nebuchadrezzar of Babylon and into the hands of the Chaldeans.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 22, 26, 'I will hurl you and the mother who bore you into another country, where you were not born, and there you shall die.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 22, 27, 'But they shall not return to the land to which they long to return.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 22, 28, 'Is this man Coniah a despised broken pot,  
    a vessel no one wants?  
Why are he and his offspring hurled out  
    and cast away in a land that they do not know?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 22, 29, 'O land, land, land,  
    hear the word of the LORD!', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 22, 30, 'Thus says the LORD:  
Record this man as childless,  
    a man who shall not succeed in his days;  
for none of his offspring shall succeed  
    in sitting on the throne of David,  
    and ruling again in Judah.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 23, 1, 'Woe to the shepherds who destroy and scatter the sheep of my pasture! says the LORD.', 'en', 'NRSV-CE', 'Restoration after Exile'),
(24, 'Yer', 'Jeremiah', 23, 2, 'Therefore thus says the LORD, the God of Israel, concerning the shepherds who shepherd my people: It is you who have scattered my flock, and have driven them away, and you have not attended to them. So I will attend to you for your evil doings, says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 23, 3, 'Then I myself will gather the remnant of my flock out of all the lands where I have driven them, and I will bring them back to their fold, and they shall be fruitful and multiply.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 23, 4, 'I will raise up shepherds over them who will shepherd them, and they shall not fear any longer, or be dismayed, nor shall any be missing, says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 23, 5, 'The days are surely coming, says the LORD, when I will raise up for David a righteous Branch, and he shall reign as king and deal wisely, and shall execute justice and righteousness in the land.', 'en', 'NRSV-CE', 'The Righteous Branch of David'),
(24, 'Yer', 'Jeremiah', 23, 6, 'In his days Judah will be saved and Israel will live in safety. And this is the name by which he will be called: "The LORD is our righteousness."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 23, 7, 'Therefore, the days are surely coming, says the LORD, when it shall no longer be said, "As the LORD lives who brought the people of Israel up out of the land of Egypt,"', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 23, 8, 'but "As the LORD lives who brought out and led the offspring of the house of Israel out of the land of the north and out of all the lands where he had driven them." Then they shall live in their own land.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 23, 9, 'Concerning the prophets:
My heart is crushed within me,  
    all my bones shake;  
I have become like a drunkard,  
    like one overcome by wine,  
because of the LORD  
    and because of his holy words.', 'en', 'NRSV-CE', 'False Prophets of Hope Denounced'),
(24, 'Yer', 'Jeremiah', 23, 10, 'For the land is full of adulterers;  
    because of the curse the land mourns,  
    and the pastures of the wilderness are dried up.  
Their course has been evil,  
    and their might is not right.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 23, 11, 'Both prophet and priest are ungodly;  
    even in my house I have found their wickedness,  
says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 23, 12, 'Therefore their way shall be to them  
    like slippery paths in the darkness,  
    into which they shall be driven and fall;  
for I will bring disaster upon them  
    in the year of their punishment,  
says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 23, 13, 'In the prophets of Samaria  
    I saw a disgusting thing:  
they prophesied by Baal  
    and led my people Israel astray.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 23, 14, 'But in the prophets of Jerusalem  
    I have seen a more shocking thing:  
they commit adultery and walk in lies;  
    they strengthen the hands of evildoers,  
    so that no one turns from wickedness;  
all of them have become like Sodom to me,  
    and its inhabitants like Gomorrah.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 23, 15, 'Therefore thus says the LORD of hosts concerning the prophets:  
"I am going to make them eat wormwood,  
    and give them poisoned water to drink;  
for from the prophets of Jerusalem  
    ungodliness has spread throughout the land."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 23, 16, 'Thus says the LORD of hosts: Do not listen to the words of the prophets who prophesy to you; they are deluding you. They speak visions of their own minds, not from the mouth of the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 23, 17, 'They keep saying to those who despise the word of the LORD, "It shall be well with you"; and to all who stubbornly follow their own stubborn hearts, they say, "No calamity shall come upon you."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 23, 18, 'For who has stood in the council of the LORD  
    so as to see and to hear his word?  
    Who has given heed to his word so as to proclaim it?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 23, 19, 'Look, the storm of the LORD!  
    Wrath has gone forth,  
a whirling tempest;  
    it will burst upon the head of the wicked.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 23, 20, 'The anger of the LORD will not turn back  
    until he has executed and accomplished  
    the intents of his mind.  
In the latter days you will understand it clearly.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 23, 21, 'I did not send the prophets,  
    yet they ran;  
I did not speak to them,  
    yet they prophesied.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 23, 22, 'But if they had stood in my council,  
    then they would have proclaimed my words to my people,  
and they would have turned them from their evil way,  
    and from the evil of their doings.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 23, 23, 'Am I a God near by, says the LORD, and not a God far off?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 23, 24, 'Who can hide in secret places so that I cannot see them? says the LORD. Do I not fill heaven and earth? says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 23, 25, 'I have heard what the prophets have said who prophesy lies in my name, saying, "I have dreamed, I have dreamed!"', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 23, 26, 'How long? Will the hearts of the prophets ever turn back--those who prophesy lies, and who prophesy the deceit of their own heart?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 23, 27, 'They plan to make my people forget my name by their dreams that they tell one another, just as their ancestors forgot my name for Baal.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 23, 28, 'Let the prophet who has a dream tell the dream, but let the one who has my word speak my word faithfully. What has straw in common with wheat? says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 23, 29, 'Is not my word like fire, says the LORD, and like a hammer that breaks a rock in pieces?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 23, 30, 'See, therefore, I am against the prophets, says the LORD, who steal my words from one another.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 23, 31, 'See, I am against the prophets, says the LORD, who use their own tongues and say, "Says the LORD."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 23, 32, 'See, I am against those who prophesy lying dreams, says the LORD, and who tell them, and who lead my people astray by their lies and their recklessness, when I did not send them or appoint them; so they do not profit this people at all, says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 23, 33, 'When this people, or a prophet, or a priest asks you, "What is the burden of the LORD?" you shall say to them, "You are the burden, and I will cast you off, says the LORD."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 23, 34, 'And as for the prophet, priest, or the people who say, "The burden of the LORD," I will punish them and their households.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 23, 35, 'Thus shall you say to one another, among yourselves, "What has the LORD answered?" or "What has the LORD spoken?"', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 23, 36, 'But "the burden of the LORD" you shall mention no more, for the burden is everyone"s own word, and so you pervert the words of the living God, the LORD of hosts, our God.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 23, 37, 'Thus you shall ask the prophet, "What has the LORD answered you?" or "What has the LORD spoken?"', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 23, 38, 'But if you say, "the burden of the LORD," thus says the LORD: Because you have said these words, "the burden of the LORD," when I sent to you, saying, You shall not say, "the burden of the LORD,"', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 23, 39, 'therefore, I will surely lift you up and cast you away from my presence, you and the city that I gave to you and your ancestors.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 23, 40, 'And I will bring upon you everlasting disgrace and perpetual shame, which shall not be forgotten.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 24, 1, 'The LORD showed me two baskets of figs placed before the temple of the LORD. This was after King Nebuchadrezzar of Babylon had taken into exile from Jerusalem King Jeconiah son of Jehoiakim of Judah, together with the officials of Judah, the artisans, and the smiths, and had brought them to Babylon.', 'en', 'NRSV-CE', 'The Good and the Bad Figs'),
(24, 'Yer', 'Jeremiah', 24, 2, 'One basket had very good figs, like first-ripe figs, but the other basket had very bad figs, so bad that they could not be eaten.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 24, 3, 'And the LORD said to me, "What do you see, Jeremiah?" I said, "Figs, the good figs very good, and the bad figs very bad, so bad that they cannot be eaten."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 24, 4, 'Then the word of the LORD came to me:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 24, 5, 'Thus says the LORD, the God of Israel: Like these good figs, so I will regard as good the exiles from Judah, whom I have sent away from this place to the land of the Chaldeans.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 24, 6, 'I will set my eyes upon them for good, and I will bring them back to this land. I will build them up, and not tear them down; I will plant them, and not pluck them up.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 24, 7, 'I will give them a heart to know that I am the LORD; and they shall be my people and I will be their God, for they shall return to me with their whole heart.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 24, 8, 'But thus says the LORD: Like the bad figs that are so bad they cannot be eaten, so will I treat King Zedekiah of Judah, his officials, the remnant of Jerusalem who remain in this land, and those who live in the land of Egypt.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 24, 9, 'I will make them a horror, an evil thing, to all the kingdoms of the earth--a disgrace, a byword, a taunt, and a curse in all the places where I shall drive them.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 24, 10, 'And I will send sword, famine, and pestilence upon them, until they are utterly destroyed from the land that I gave to them and their ancestors.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 25, 1, 'The word that came to Jeremiah concerning all the people of Judah, in the fourth year of King Jehoiakim son of Josiah of Judah (that was the first year of King Nebuchadrezzar of Babylon),', 'en', 'NRSV-CE', 'The Babylonian Captivity Foretold'),
(24, 'Yer', 'Jeremiah', 25, 2, 'which the prophet Jeremiah spoke to all the people of Judah and all the inhabitants of Jerusalem:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 25, 3, 'For twenty-three years, from the thirteenth year of King Josiah son of Amon of Judah, to this day, the word of the LORD has come to me, and I have spoken persistently to you, but you have not listened.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 25, 4, 'And though the LORD persistently sent you all his servants the prophets, you have neither listened nor inclined your ears to hear', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 25, 5, 'when they said, "Turn now, every one of you, from your evil way and wicked doings, and you will remain upon the land that the LORD has given to you and your ancestors from of old and forever;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 25, 6, 'do not go after other gods to serve and worship them, and do not provoke me to anger with the work of your hands. Then I will do you no harm."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 25, 7, 'Yet you did not listen to me, says the LORD, and so you have provoked me to anger with the work of your hands to your own harm.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 25, 8, 'Therefore thus says the LORD of hosts: Because you have not obeyed my words,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 25, 9, 'I am going to send for all the tribes of the north, says the LORD, even for King Nebuchadrezzar of Babylon, my servant, and I will bring them against this land and its inhabitants, and against all these nations around; I will utterly destroy them, and make them an object of horror and of hissing, and an everlasting disgrace.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 25, 10, 'And I will banish from them the sound of mirth and the sound of gladness, the voice of the bridegroom and the voice of the bride, the sound of the millstones and the light of the lamp.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 25, 11, 'This whole land shall become a ruin and a waste, and these nations shall serve the king of Babylon seventy years.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 25, 12, 'Then after seventy years are completed, I will punish the king of Babylon and that nation, the land of the Chaldeans, for their iniquity, says the LORD, making the land an everlasting waste.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 25, 13, 'I will bring upon that land all the words that I have uttered against it, everything written in this book, which Jeremiah prophesied against all the nations.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 25, 14, 'For many nations and great kings shall make slaves of them also; and I will repay them according to their deeds and the work of their hands.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 25, 15, 'For thus the LORD, the God of Israel, said to me: Take from my hand this cup of the wine of wrath, and make all the nations to whom I send you drink it.', 'en', 'NRSV-CE', 'The Cup of God"s Wrath'),
(24, 'Yer', 'Jeremiah', 25, 16, 'They shall drink and stagger and go out of their minds because of the sword that I am sending among them.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 25, 17, 'So I took the cup from the LORD"s hand, and made all the nations to whom the LORD sent me drink it:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 25, 18, 'Jerusalem and the towns of Judah, its kings and officials, to make them a desolation and a waste, an object of hissing and of cursing, as they are today;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 25, 19, 'Pharaoh king of Egypt, his servants, his officials, and all his people;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 25, 20, 'all the mixed people; all the kings of the land of Uz; all the kings of the land of the Philistines--Ashkelon, Gaza, Ekron, and the remnant of Ashdod;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 25, 21, 'Edom, Moab, and the Ammonites;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 25, 22, 'all the kings of Tyre, all the kings of Sidon, and the kings of the coastland across the sea;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 25, 23, 'Dedan, Tema, Buz, and all who have shaven temples;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 25, 24, 'all the kings of Arabia and all the kings of the mixed peoples that live in the desert;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 25, 25, 'all the kings of Zimri, all the kings of Elam, and all the kings of Media;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 25, 26, 'all the kings of the north, far and near, one after another, and all the kingdoms of the world that are on the face of the earth. And after them the king of Sheshach shall drink.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 25, 27, 'Then you shall say to them, Thus says the LORD of hosts, the God of Israel: Drink, get drunk and vomit, fall and rise no more, because of the sword that I am sending among you.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 25, 28, 'And if they refuse to accept the cup from your hand to drink, then you shall say to them: Thus says the LORD of hosts: You must drink!', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 25, 29, 'See, I am beginning to bring disaster on the city that is called by my name, and how can you possibly avoid punishment? You shall not go unpunished, for I am summoning a sword against all the inhabitants of the earth, says the LORD of hosts.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 25, 30, 'You, therefore, shall prophesy against them all these words, and say to them:
The LORD will roar from on high,  
    and from his holy habitation utter his voice;  
he will roar mightily against his fold,  
    and shout, like those who tread grapes,  
    against all the inhabitants of the earth.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 25, 31, 'The clamor will resound to the ends of the earth,  
    for the LORD has an indictment against the nations;  
he is entering into judgment with all flesh,  
    and the guilty he will put to the sword,  
says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 25, 32, 'Thus says the LORD of hosts:  
See, disaster is spreading  
    from nation to nation,  
and a great tempest is stirring  
    from the farthest parts of the earth!', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 25, 33, 'Those slain by the LORD on that day shall extend from one end of the earth to the other. They shall not be lamented, or gathered, or buried; they shall become dung on the surface of the ground.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 25, 34, 'Wail, you shepherds, and cry out;  
    roll in ashes, you lords of the flock,  
for the days of your slaughter have come--and your dispersions,  
    and you shall fall like a choice vessel.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 25, 35, 'Flight shall fail the shepherds,  
    and there shall be no escape for the lords of the flock.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 25, 36, 'Hark! the cry of the shepherds,  
    and the wail of the lords of the flock!  
For the LORD is despoiling their pasture,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 25, 37, 'and the peaceful folds are devastated,  
    because of the fierce anger of the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 25, 38, 'Like a lion he has left his covert;  
    for their land has become a waste  
because of the cruel sword,  
    and because of his fierce anger.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 26, 1, 'At the beginning of the reign of King Jehoiakim son of Josiah of Judah, this word came from the LORD:', 'en', 'NRSV-CE', 'Jeremiah"s Prophecies in the Temple'),
(24, 'Yer', 'Jeremiah', 26, 2, 'Thus says the LORD: Stand in the court of the LORD"s house, and speak to all the cities of Judah that come to worship in the house of the LORD; speak to them all the words that I command you; do not hold back a word.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 26, 3, 'It may be that they will listen, all of them, and will turn from their evil way, that I may change my mind about the disaster that I intend to bring on them because of their evil doings.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 26, 4, 'You shall say to them: Thus says the LORD: If you will not listen to me, to walk in my law that I have set before you,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 26, 5, 'and to heed the words of my servants the prophets whom I send to you urgently--though you have not heeded--', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 26, 6, 'then I will make this house like Shiloh, and I will make this city a curse for all the nations of the earth.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 26, 7, 'The priests and the prophets and all the people heard Jeremiah speaking these words in the house of the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 26, 8, 'And when Jeremiah had finished speaking all that the LORD had commanded him to speak to all the people, then the priests and the prophets and all the people laid hold of him, saying, "You shall die!', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 26, 9, 'Why have you prophesied in the name of the LORD, saying, "This house shall be like Shiloh, and this city shall be desolate, without inhabitant"?" And all the people gathered around Jeremiah in the house of the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 26, 10, 'When the officials of Judah heard these things, they came up from the king"s house to the house of the LORD and took their seat in the entry of the New Gate of the house of the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 26, 11, 'Then the priests and the prophets said to the officials and to all the people, "This man deserves the sentence of death because he has prophesied against this city, as you have heard with your own ears."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 26, 12, 'Then Jeremiah spoke to all the officials and all the people, saying, "It is the LORD who sent me to prophesy against this house and this city all the words you have heard.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 26, 13, 'Now therefore amend your ways and your doings, and obey the voice of the LORD your God, and the LORD will change his mind about the disaster that he has pronounced against you.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 26, 14, 'But as for me, here I am in your hands. Do with me as seems good and right to you.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 26, 15, 'Only know for certain that if you put me to death, you will be bringing innocent blood upon yourselves and upon this city and its inhabitants, for in truth the LORD sent me to you to speak all these words in your ears."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 26, 16, 'Then the officials and all the people said to the priests and the prophets, "This man does not deserve the sentence of death, for he has spoken to us in the name of the LORD our God."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 26, 17, 'And some of the elders of the land arose and said to all the assembled people,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 26, 18, '"Micah of Moresheth, who prophesied during the days of King Hezekiah of Judah, said to all the people of Judah: "Thus says the LORD of hosts,
Zion shall be plowed as a field;  
    Jerusalem shall become a heap of ruins,  
    and the mountain of the house a wooded height."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 26, 19, 'Did King Hezekiah of Judah and all Judah actually put him to death? Did he not fear the LORD and entreat the favor of the LORD, and did not the LORD change his mind about the disaster that he had pronounced against them? But we are about to bring great disaster on ourselves!"', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 26, 20, 'There was another man prophesying in the name of the LORD, Uriah son of Shemaiah from Kiriath-jearim. He prophesied against this city and against this land in words exactly like those of Jeremiah.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 26, 21, 'And when King Jehoiakim, with all his warriors and all the officials, heard his words, the king sought to put him to death; but when Uriah heard of it, he was afraid and fled and escaped to Egypt.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 26, 22, 'Then King Jehoiakim sent Elnathan son of Achbor and men with him to Egypt,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 26, 23, 'and they took Uriah from Egypt and brought him to King Jehoiakim, who struck him down with the sword and threw his dead body into the burial place of the common people.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 26, 24, 'But the hand of Ahikam son of Shaphan was with Jeremiah so that he was not given over into the hands of the people to be put to death.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 27, 1, 'In the beginning of the reign of King Zedekiah son of Josiah of Judah, this word came to Jeremiah from the LORD.', 'en', 'NRSV-CE', 'The Sign of the Yoke'),
(24, 'Yer', 'Jeremiah', 27, 2, 'Thus the LORD said to me: Make yourself a yoke of straps and bars, and put them on your neck.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 27, 3, 'Send word to the king of Edom, the king of Moab, the king of the Ammonites, the king of Tyre, and the king of Sidon by the hand of the envoys who have come to Jerusalem to King Zedekiah of Judah.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 27, 4, 'Give them this charge for their masters: Thus says the LORD of hosts, the God of Israel: This is what you shall say to your masters:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 27, 5, 'It is I who by my great power and my outstretched arm have made the earth, with the people and animals that are on the earth, and I give it to whomever I please.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 27, 6, 'Now I have given all these lands into the hand of King Nebuchadnezzar of Babylon, my servant, and I have given him even the wild animals of the field to serve him.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 27, 7, 'All the nations shall serve him and his son and his grandson, until the time of his own land comes; then many nations and great kings shall make him their slave.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 27, 8, 'But if any nation or kingdom will not serve this king, Nebuchadnezzar of Babylon, and put its neck under the yoke of the king of Babylon, then I will punish that nation with the sword, with famine, and with pestilence, says the LORD, until I have completed its destruction by his hand.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 27, 9, 'You, therefore, must not listen to your prophets, your diviners, your dreamers, your soothsayers, or your sorcerers, who are saying to you, "You shall not serve the king of Babylon."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 27, 10, 'For they are prophesying a lie to you, with the result that you will be removed far from your land; I will drive you out, and you will perish.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 27, 11, 'But any nation that will bring its neck under the yoke of the king of Babylon and serve him, I will leave on its own land, says the LORD, to till it and live there.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 27, 12, 'I spoke to King Zedekiah of Judah in the same way: Bring your necks under the yoke of the king of Babylon, and serve him and his people, and live.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 27, 13, 'Why should you and your people die by the sword, by famine, and by pestilence, as the LORD has spoken concerning any nation that will not serve the king of Babylon?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 27, 14, 'Do not listen to the words of the prophets who are telling you not to serve the king of Babylon, for they are prophesying a lie to you.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 27, 15, 'I have not sent them, says the LORD, but they are prophesying falsely in my name, with the result that I will drive you out and you will perish, you and the prophets who are prophesying to you.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 27, 16, 'Then I spoke to the priests and to all this people, saying, Thus says the LORD: Do not listen to the words of your prophets who are prophesying to you, saying, "The vessels of the LORD"s house will soon be brought back from Babylon," for they are prophesying a lie to you.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 27, 17, 'Do not listen to them; serve the king of Babylon and live. Why should this city become a desolation?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 27, 18, 'If indeed they are prophets, and if the word of the LORD is with them, then let them intercede with the LORD of hosts, that the vessels left in the house of the LORD, in the house of the king of Judah, and in Jerusalem may not go to Babylon.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 27, 19, 'For thus says the LORD of hosts concerning the pillars, the sea, the stands, and the rest of the vessels that are left in this city,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 27, 20, 'which King Nebuchadnezzar of Babylon did not take away when he took into exile from Jerusalem to Babylon King Jeconiah son of Jehoiakim of Judah, and all the nobles of Judah and Jerusalem--', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 27, 21, 'thus says the LORD of hosts, the God of Israel, concerning the vessels left in the house of the LORD, in the house of the king of Judah, and in Jerusalem:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 27, 22, 'They shall be carried to Babylon, and there they shall stay, until the day when I give attention to them, says the LORD. Then I will bring them up and restore them to this place.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 28, 1, 'In that same year, at the beginning of the reign of King Zedekiah of Judah, in the fifth month of the fourth year, the prophet Hananiah son of Azzur, from Gibeon, spoke to me in the house of the LORD, in the presence of the priests and all the people, saying,', 'en', 'NRSV-CE', 'Hananiah Opposes Jeremiah and Dies'),
(24, 'Yer', 'Jeremiah', 28, 2, '"Thus says the LORD of hosts, the God of Israel: I have broken the yoke of the king of Babylon.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 28, 3, 'Within two years I will bring back to this place all the vessels of the LORD"s house, which King Nebuchadnezzar of Babylon took away from this place and carried to Babylon.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 28, 4, 'I will also bring back to this place King Jeconiah son of Jehoiakim of Judah, and all the exiles from Judah who went to Babylon, says the LORD, for I will break the yoke of the king of Babylon."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 28, 5, 'Then the prophet Jeremiah spoke to the prophet Hananiah in the presence of the priests and all the people who were standing in the house of the LORD;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 28, 6, 'and the prophet Jeremiah said, "Amen! May the LORD do so; may the LORD fulfill the words that you have prophesied, and bring back to this place from Babylon the vessels of the house of the LORD, and all the exiles.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 28, 7, 'But listen now to this word that I speak in your hearing and in the hearing of all the people.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 28, 8, 'The prophets who preceded you and me from ancient times prophesied war, famine, and pestilence against many countries and great kingdoms.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 28, 9, 'As for the prophet who prophesies peace, when the word of that prophet comes true, then it will be known that the LORD has truly sent the prophet."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 28, 10, 'Then the prophet Hananiah took the yoke from the neck of the prophet Jeremiah, and broke it.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 28, 11, 'And Hananiah spoke in the presence of all the people, saying, "Thus says the LORD: This is how I will break the yoke of King Nebuchadnezzar of Babylon from the neck of all the nations within two years." At this, the prophet Jeremiah went his way.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 28, 12, 'Sometime after the prophet Hananiah had broken the yoke from the neck of the prophet Jeremiah, the word of the LORD came to Jeremiah:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 28, 13, 'Go, tell Hananiah, Thus says the LORD: You have broken wooden bars only to forge iron bars in place of them!', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 28, 14, 'For thus says the LORD of hosts, the God of Israel: I have put an iron yoke on the neck of all these nations so that they may serve King Nebuchadnezzar of Babylon, and they shall indeed serve him; I have even given him the wild animals.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 28, 15, 'And the prophet Jeremiah said to the prophet Hananiah, "Listen, Hananiah, the LORD has not sent you, and you made this people trust in a lie.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 28, 16, 'Therefore thus says the LORD: I am going to send you off the face of the earth. Within this year you will be dead, because you have spoken rebellion against the LORD."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 28, 17, 'In that same year, in the seventh month, the prophet Hananiah died.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 29, 1, 'These are the words of the letter that the prophet Jeremiah sent from Jerusalem to the remaining elders among the exiles, and to the priests, the prophets, and all the people, whom Nebuchadnezzar had taken into exile from Jerusalem to Babylon.', 'en', 'NRSV-CE', 'Jeremiah"s Letter to the Exiles in Babylon'),
(24, 'Yer', 'Jeremiah', 29, 2, 'This was after King Jeconiah, and the queen mother, the court officials, the leaders of Judah and Jerusalem, the artisans, and the smiths had departed from Jerusalem.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 29, 3, 'The letter was sent by the hand of Elasah son of Shaphan and Gemariah son of Hilkiah, whom King Zedekiah of Judah sent to Babylon to King Nebuchadnezzar of Babylon. It said:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 29, 4, 'Thus says the LORD of hosts, the God of Israel, to all the exiles whom I have sent into exile from Jerusalem to Babylon:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 29, 5, 'Build houses and live in them; plant gardens and eat what they produce.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 29, 6, 'Take wives and have sons and daughters; take wives for your sons, and give your daughters in marriage, that they may bear sons and daughters; multiply there, and do not decrease.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 29, 7, 'But seek the welfare of the city where I have sent you into exile, and pray to the LORD on its behalf, for in its welfare you will find your welfare.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 29, 8, 'For thus says the LORD of hosts, the God of Israel: Do not let the prophets and the diviners who are among you deceive you, and do not listen to the dreams that they dream,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 29, 9, 'for it is a lie that they are prophesying to you in my name; I did not send them, says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 29, 10, 'For thus says the LORD: Only when Babylon"s seventy years are completed will I visit you, and I will fulfill to you my promise and bring you back to this place.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 29, 11, 'For surely I know the plans I have for you, says the LORD, plans for your welfare and not for harm, to give you a future with hope.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 29, 12, 'Then when you call upon me and come and pray to me, I will hear you.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 29, 13, 'When you search for me, you will find me; if you seek me with all your heart,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 29, 14, 'I will let you find me, says the LORD, and I will restore your fortunes and gather you from all the nations and all the places where I have driven you, says the LORD, and I will bring you back to the place from which I sent you into exile.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 29, 15, 'Because you have said, "The LORD has raised up prophets for us in Babylon,"--', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 29, 16, 'Thus says the LORD concerning the king who sits on the throne of David, and concerning all the people who live in this city, your kinsfolk who did not go out with you into exile:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 29, 17, 'Thus says the LORD of hosts, I am going to let loose on them sword, famine, and pestilence, and I will make them like rotten figs that are so bad they cannot be eaten.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 29, 18, 'I will pursue them with the sword, with famine, and with pestilence, and will make them a horror to all the kingdoms of the earth, to be an object of cursing, and horror, and hissing, and a derision among all the nations where I have driven them,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 29, 19, 'because they did not heed my words, says the LORD, when I persistently sent to you my servants the prophets, but they would not listen, says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 29, 20, 'But now, all you exiles whom I sent away from Jerusalem to Babylon, hear the word of the LORD:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 29, 21, 'Thus says the LORD of hosts, the God of Israel, concerning Ahab son of Kolaiah and Zedekiah son of Maaseiah, who are prophesying a lie to you in my name: I am going to deliver them into the hand of King Nebuchadrezzar of Babylon, and he shall kill them before your eyes.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 29, 22, 'And on account of them this curse shall be used by all the exiles from Judah in Babylon: "The LORD make you like Zedekiah and Ahab, whom the king of Babylon roasted in the fire,"', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 29, 23, 'because they have perpetrated outrage in Israel and have committed adultery with their neighbors" wives, and have spoken in my name lying words that I did not command them; I am the one who knows and bears witness, says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 29, 24, 'To Shemaiah of Nehelam you shall say:', 'en', 'NRSV-CE', 'The Letter of Shemaiah'),
(24, 'Yer', 'Jeremiah', 29, 25, 'Thus says the LORD of hosts, the God of Israel: In your own name you sent a letter to all the people who are in Jerusalem, and to the priest Zephaniah son of Maaseiah, and to all the priests, saying,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 29, 26, 'The LORD himself has made you priest instead of the priest Jehoiada, so that there may be officers in the house of the LORD to control any madman who plays the prophet, to put him in the stocks and the collar.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 29, 27, 'So now why have you not rebuked Jeremiah of Anathoth who plays the prophet for you?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 29, 28, 'For he has actually sent to us in Babylon, saying, "It will be a long time; build houses and live in them, and plant gardens and eat what they produce."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 29, 29, 'The priest Zephaniah read this letter in the hearing of the prophet Jeremiah.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 29, 30, 'Then the word of the LORD came to Jeremiah:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 29, 31, 'Send to all the exiles, saying, Thus says the LORD concerning Shemaiah of Nehelam: Because Shemaiah has prophesied to you, though I did not send him, and has led you to trust in a lie,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 29, 32, 'therefore thus says the LORD: I am going to punish Shemaiah of Nehelam and his descendants; he shall not have anyone living among this people to see the good that I am going to do to my people, says the LORD, for he has spoken rebellion against the LORD.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 30, 1, 'The word that came to Jeremiah from the LORD:', 'en', 'NRSV-CE', 'Restoration Promised for Israel and Judah'),
(24, 'Yer', 'Jeremiah', 30, 2, 'Thus says the LORD, the God of Israel: Write in a book all the words that I have spoken to you.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 30, 3, 'For the days are surely coming, says the LORD, when I will restore the fortunes of my people, Israel and Judah, says the LORD, and I will bring them back to the land that I gave to their ancestors and they shall take possession of it.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 30, 4, 'These are the words that the LORD spoke concerning Israel and Judah:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 30, 5, 'Thus says the LORD:  
We have heard a cry of panic,  
    of terror, and no peace.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 30, 6, 'Ask now, and see,  
    can a man bear a child?  
Why then do I see every man  
    with his hands on his loins like a woman in labor?  
    Why has every face turned pale?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 30, 7, 'Alas! that day is so great  
    there is none like it;  
it is a time of distress for Jacob;  
    yet he shall be rescued from it.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 30, 8, 'On that day, says the LORD of hosts, I will break the yoke from off his neck, and I will burst his bonds, and strangers shall no more make a servant of him.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 30, 9, 'But they shall serve the LORD their God and David their king, whom I will raise up for them.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 30, 10, 'But as for you, have no fear, my servant Jacob, says the LORD,  
    and do not be dismayed, O Israel;  
for I am going to save you from far away,  
    and your offspring from the land of their captivity.  
Jacob shall return and have quiet and ease,  
    and no one shall make him afraid.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 30, 11, 'For I am with you, says the LORD, to save you;  
I will make an end of all the nations  
    among which I scattered you,  
    but of you I will not make an end.  
I will chastise you in just measure,  
    and I will by no means leave you unpunished.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 30, 12, 'For thus says the LORD:  
Your hurt is incurable,  
    your wound is grievous.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 30, 13, 'There is no one to uphold your cause,  
    no medicine for your wound,  
    no healing for you.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 30, 14, 'All your lovers have forgotten you;  
    they care nothing for you;  
for I have dealt you the blow of an enemy,  
    the punishment of a merciless foe,  
because your guilt is great,  
    because your sins are so numerous.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 30, 15, 'Why do you cry out over your hurt?  
    Your pain is incurable.  
Because your guilt is great,  
    because your sins are so numerous,  
    I have done these things to you.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 30, 16, 'Therefore all who devour you shall be devoured,  
    and all your foes, every one of them, shall go into captivity;  
those who plunder you shall be plundered,  
    and all who prey on you I will make a prey.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 30, 17, 'For I will restore health to you,  
    and your wounds I will heal,  
says the LORD,  
because they have called you an outcast:  
    "It is Zion; no one cares for her!"', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 30, 18, 'Thus says the LORD:  
I am going to restore the fortunes of the tents of Jacob,  
    and have compassion on his dwellings;  
the city shall be rebuilt upon its mound,  
    and the citadel set on its rightful site.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 30, 19, 'Out of them shall come thanksgiving,  
    and the sound of merrymakers.  
I will make them many, and they shall not be few;  
    I will make them honored, and they shall not be disdained.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 30, 20, 'Their children shall be as of old,  
    their congregation shall be established before me;  
    and I will punish all who oppress them.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 30, 21, 'Their prince shall be one of their own,  
    their ruler shall come from their midst;  
I will bring him near, and he shall approach me,  
    for who would otherwise dare to approach me?  
says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 30, 22, 'And you shall be my people,  
    and I will be your God.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 30, 23, 'Look, the storm of the LORD!  
    Wrath has gone forth,  
a whirling tempest;  
    it will burst upon the head of the wicked.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 30, 24, 'The fierce anger of the LORD will not turn back  
    until he has executed and accomplished  
    the intents of his mind.  
In the latter days you will understand this.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 31, 1, 'At that time, says the LORD, I will be the God of all the families of Israel, and they shall be my people.', 'en', 'NRSV-CE', 'The Joyful Return of the Exiles'),
(24, 'Yer', 'Jeremiah', 31, 2, 'Thus says the LORD:  
The people who survived the sword  
    found grace in the wilderness;  
when Israel sought for rest,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 31, 3, 'the LORD appeared to him from far away.  
I have loved you with an everlasting love;  
    therefore I have continued my faithfulness to you.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 31, 4, 'Again I will build you, and you shall be built,  
    O virgin Israel!  
Again you shall take your tambourines,  
    and go forth in the dance of the merrymakers.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 31, 5, 'Again you shall plant vineyards  
    on the mountains of Samaria;  
the planters shall plant,  
    and shall enjoy the fruit.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 31, 6, 'For there shall be a day when sentinels will call  
    in the hill country of Ephraim:  
"Come, let us go up to Zion,  
    to the LORD our God."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 31, 7, 'For thus says the LORD:  
Sing aloud with gladness for Jacob,  
    and raise shouts for the chief of the nations;  
proclaim, give praise, and say,  
    "Save, O LORD, your people,  
    the remnant of Israel."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 31, 8, 'See, I am going to bring them from the land of the north,  
    and gather them from the farthest parts of the earth,  
among them the blind and the lame,  
    those with child and those in labor, together;  
    a great company, they shall return here.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 31, 9, 'With weeping they shall come,  
    and with consolations I will lead them back,  
I will let them walk by brooks of water,  
    in a straight path in which they shall not stumble;  
for I have become a father to Israel,  
    and Ephraim is my firstborn.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 31, 10, 'Hear the word of the LORD, O nations,  
    and declare it in the coastlands far away;  
say, "He who scattered Israel will gather him,  
    and will keep him as a shepherd a flock."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 31, 11, 'For the LORD has ransomed Jacob,  
    and has redeemed him from hands too strong for him.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 31, 12, 'They shall come and sing aloud on the height of Zion,  
    and they shall be radiant over the goodness of the LORD,  
over the grain, the wine, and the oil,  
    and over the young of the flock and the herd;  
their life shall become like a watered garden,  
    and they shall never languish again.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 31, 13, 'Then shall the young women rejoice in the dance,  
    and the young men and the old shall be merry.  
I will turn their mourning into joy,  
    I will comfort them, and give them gladness for sorrow.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 31, 14, 'I will give the priests their fill of fatness,  
    and my people shall be satisfied with my bounty,  
says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 31, 15, 'Thus says the LORD:  
A voice is heard in Ramah,  
    lamentation and bitter weeping.  
Rachel is weeping for her children;  
    she refuses to be comforted for her children,  
    because they are no more.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 31, 16, 'Thus says the LORD:  
Keep your voice from weeping,  
    and your eyes from tears;  
for there is a reward for your work,  
says the LORD:  
    they shall come back from the land of the enemy;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 31, 17, 'there is hope for your future,  
says the LORD:  
    your children shall come back to their own country.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 31, 18, 'Indeed I heard Ephraim pleading:  
"You disciplined me, and I took the discipline;  
    I was like a calf untrained.  
Bring me back, let me come back,  
    for you are the LORD my God.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 31, 19, 'For after I had turned away I repented;  
    and after I was discovered, I struck my thigh;  
I was ashamed, and I was dismayed  
    because I bore the disgrace of my youth."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 31, 20, 'Is Ephraim my dear son?  
    Is he the child I delight in?  
As often as I speak against him,  
    I still remember him.  
Therefore I am deeply moved for him;  
    I will surely have mercy on him,  
says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 31, 21, 'Set up road markers for yourself,  
    make yourself signposts;  
consider well the highway,  
    the road by which you went.  
Return, O virgin Israel,  
    return to these your cities.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 31, 22, 'How long will you waver,  
    O faithless daughter?  
For the LORD has created a new thing on the earth:  
    a woman encompasses a man.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 31, 23, 'Thus says the LORD of hosts, the God of Israel: Once more they shall use these words in the land of Judah and in its towns when I restore their fortunes:
"The LORD bless you, O abode of righteousness,  
    O holy hill!"', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 31, 24, 'And Judah and all its towns shall live there together, and the farmers and those who wander with their flocks.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 31, 25, 'I will satisfy the weary,  
    and all who are faint I will replenish.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 31, 26, 'Thereupon I awoke and looked, and my sleep was pleasant to me.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 31, 27, 'The days are surely coming, says the LORD, when I will sow the house of Israel and the house of Judah with the seed of humans and the seed of animals.', 'en', 'NRSV-CE', 'Individual Retribution'),
(24, 'Yer', 'Jeremiah', 31, 28, 'And just as I have watched over them to pluck up and break down, to overthrow, destroy, and bring evil, so I will watch over them to build and to plant, says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 31, 29, 'In those days they shall no longer say:
"The parents have eaten sour grapes,  
    and the children"s teeth are set on edge."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 31, 30, 'But all shall die for their own sins; the teeth of everyone who eats sour grapes shall be set on edge.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 31, 31, 'The days are surely coming, says the LORD, when I will make a new covenant with the house of Israel and the house of Judah.', 'en', 'NRSV-CE', 'A New Covenant'),
(24, 'Yer', 'Jeremiah', 31, 32, 'It will not be like the covenant that I made with their ancestors when I took them by the hand to bring them out of the land of Egypt--a covenant that they broke, though I was their husband, says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 31, 33, 'But this is the covenant that I will make with the house of Israel after those days, says the LORD: I will put my law within them, and I will write it on their hearts; and I will be their God, and they shall be my people.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 31, 34, 'No longer shall they teach one another, or say to each other, "Know the LORD," for they shall all know me, from the least of them to the greatest, says the LORD; for I will forgive their iniquity, and remember their sin no more.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 31, 35, 'Thus says the LORD,  
who gives the sun for light by day  
    and the fixed order of the moon and the stars for light by night,  
who stirs up the sea so that its waves roar--  
    the LORD of hosts is his name:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 31, 36, 'If this fixed order were ever to cease  
    from my presence, says the LORD,  
then also the offspring of Israel would cease  
    to be a nation before me forever.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 31, 37, 'Thus says the LORD:  
If the heavens above can be measured,  
    and the foundations of the earth below can be explored,  
then I will reject all the offspring of Israel  
    because of all they have done,  
says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 31, 38, 'The days are surely coming, says the LORD, when the city shall be rebuilt for the LORD from the tower of Hananel to the Corner Gate.', 'en', 'NRSV-CE', 'Jerusalem to Be Enlarged'),
(24, 'Yer', 'Jeremiah', 31, 39, 'And the measuring line shall go out farther, straight to the hill Gareb, and shall then turn to Goah.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 31, 40, 'The whole valley of the dead bodies and the ashes, and all the fields as far as the Wadi Kidron, to the corner of the Horse Gate toward the east, shall be sacred to the LORD. It shall never again be uprooted or overthrown.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 32, 1, 'The word that came to Jeremiah from the LORD in the tenth year of King Zedekiah of Judah, which was the eighteenth year of Nebuchadrezzar.', 'en', 'NRSV-CE', 'Jeremiah Buys a Field During the Siege'),
(24, 'Yer', 'Jeremiah', 32, 2, 'At that time the army of the king of Babylon was besieging Jerusalem, and the prophet Jeremiah was confined in the court of the guard that was in the palace of the king of Judah,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 3, 'where King Zedekiah of Judah had confined him. Zedekiah had said, "Why do you prophesy and say: Thus says the LORD: I am going to give this city into the hand of the king of Babylon, and he shall take it;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 4, 'King Zedekiah of Judah shall not escape out of the hands of the Chaldeans, but shall surely be given into the hands of the king of Babylon, and shall speak with him face to face and see him eye to eye;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 5, 'and he shall take Zedekiah to Babylon, and there he shall remain until I attend to him, says the LORD; though you fight against the Chaldeans, you shall not succeed?"', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 6, 'Jeremiah said, The word of the LORD came to me:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 7, 'Hanamel son of your uncle Shallum is going to come to you and say, "Buy my field that is at Anathoth, for the right of redemption by purchase is yours."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 8, 'Then my cousin Hanamel came to me in the court of the guard, in accordance with the word of the LORD, and said to me, "Buy my field that is at Anathoth in the land of Benjamin, for the right of possession and redemption is yours; buy it for yourself." Then I knew that this was the word of the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 9, 'And I bought the field at Anathoth from my cousin Hanamel, and weighed out the money to him, seventeen shekels of silver.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 10, 'I signed the deed, sealed it, got witnesses, and weighed the money on scales.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 11, 'Then I took the sealed deed of purchase, containing the terms and conditions, and the open copy;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 12, 'and I gave the deed of purchase to Baruch son of Neriah son of Mahseiah, in the presence of my cousin Hanamel, in the presence of the witnesses who signed the deed of purchase, and in the presence of all the Judeans who were sitting in the court of the guard.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 13, 'In their presence I charged Baruch, saying,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 14, 'Thus says the LORD of hosts, the God of Israel: Take these deeds, both this sealed deed of purchase and this open deed, and put them in an earthenware jar, in order that they may last for a long time.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 15, 'For thus says the LORD of hosts, the God of Israel: Houses and fields and vineyards shall again be bought in this land.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 16, 'After I had given the deed of purchase to Baruch son of Neriah, I prayed to the LORD, saying:', 'en', 'NRSV-CE', 'Jeremiah Prays for Understanding'),
(24, 'Yer', 'Jeremiah', 32, 17, 'Ah Lord God! It is you who made the heavens and the earth by your great power and by your outstretched arm! Nothing is too hard for you.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 18, 'You show steadfast love to the thousandth generation, but repay the guilt of parents into the laps of their children after them, O great and mighty God whose name is the LORD of hosts,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 19, 'great in counsel and mighty in deed; whose eyes are open to all the ways of mortals, rewarding all according to their ways and according to the fruit of their doings.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 20, 'You showed signs and wonders in the land of Egypt, and to this day in Israel and among all humankind, and have made yourself a name that continues to this very day.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 21, 'You brought your people Israel out of the land of Egypt with signs and wonders, with a strong hand and outstretched arm, and with great terror;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 22, 'and you gave them this land, which you swore to their ancestors to give them, a land flowing with milk and honey;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 23, 'and they entered and took possession of it. But they did not obey your voice or follow your law; of all you commanded them to do, they did nothing. Therefore you have made all these disasters come upon them.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 24, 'See, the siege ramps have been cast up against the city to take it, and the city, faced with sword, famine, and pestilence, has been given into the hands of the Chaldeans who are fighting against it. What you spoke has happened, as you yourself can see.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 25, 'Yet you, O Lord God, have said to me, "Buy the field for money and get witnesses"--though the city has been given into the hands of the Chaldeans.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 26, 'The word of the LORD came to Jeremiah:', 'en', 'NRSV-CE', 'God"s Assurance of the People"s Return'),
(24, 'Yer', 'Jeremiah', 32, 27, 'See, I am the LORD, the God of all flesh; is anything too hard for me?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 28, 'Therefore, thus says the LORD: I am going to give this city into the hands of the Chaldeans and into the hand of King Nebuchadrezzar of Babylon, and he shall take it.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 29, 'The Chaldeans who are fighting against this city shall come, set it on fire, and burn it, with the houses on whose roofs offerings have been made to Baal and libations have been poured out to other gods, to provoke me to anger.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 30, 'For the people of Israel and the people of Judah have done nothing but evil in my sight from their youth; the people of Israel have done nothing but provoke me to anger by the work of their hands, says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 31, 'This city has aroused my anger and wrath, from the day it was built until this day, so that I will remove it from my sight', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 32, 'because of all the evil of the people of Israel and the people of Judah that they did to provoke me to anger--they, their kings and their officials, their priests and their prophets, the citizens of Judah and the inhabitants of Jerusalem.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 33, 'They have turned their backs to me, not their faces; though I have taught them persistently, they would not listen and accept correction.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 34, 'They set up their abominations in the house that bears my name, and defiled it.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 35, 'They built the high places of Baal in the valley of the son of Hinnom, to offer up their sons and daughters to Molech, though I did not command them, nor did it enter my mind that they should do this abomination, causing Judah to sin.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 36, 'Now therefore thus says the LORD, the God of Israel, concerning this city of which you say, "It is being given into the hand of the king of Babylon by the sword, by famine, and by pestilence":', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 37, 'See, I am going to gather them from all the lands to which I drove them in my anger and my wrath and in great indignation; I will bring them back to this place, and I will settle them in safety.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 38, 'They shall be my people, and I will be their God.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 39, 'I will give them one heart and one way, that they may fear me for all time, for their own good and the good of their children after them.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 40, 'I will make an everlasting covenant with them, never to draw back from doing good to them; and I will put the fear of me in their hearts, so that they may not turn from me.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 41, 'I will rejoice in doing good to them, and I will plant them in this land in faithfulness, with all my heart and all my soul.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 42, 'For thus says the LORD: Just as I have brought all this great disaster upon this people, so I will bring upon them all the good fortune that I now promise them.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 43, 'Fields shall be bought in this land of which you are saying, It is a desolation, without human beings or animals; it has been given into the hands of the Chaldeans.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 32, 44, 'Fields shall be bought for money, and deeds shall be signed and sealed and witnessed, in the land of Benjamin, in the places around Jerusalem, and in the cities of Judah, of the hill country, of the Shephelah, and of the Negeb; for I will restore their fortunes, says the LORD.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 33, 1, 'The word of the LORD came to Jeremiah a second time, while he was still confined in the court of the guard:', 'en', 'NRSV-CE', 'Healing after Punishment'),
(24, 'Yer', 'Jeremiah', 33, 2, 'Thus says the LORD who made the earth, the LORD who formed it to establish it--the LORD is his name:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 33, 3, 'Call to me and I will answer you, and will tell you great and hidden things that you have not known.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 33, 4, 'For thus says the LORD, the God of Israel, concerning the houses of this city and the houses of the kings of Judah that were torn down to make a defense against the siege ramps and before the sword:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 33, 5, 'The Chaldeans are coming in to fight and to fill them with the dead bodies of those whom I shall strike down in my anger and my wrath, for I have hidden my face from this city because of all their wickedness.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 33, 6, 'I am going to bring it recovery and healing; I will heal them and reveal to them abundance of prosperity and security.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 33, 7, 'I will restore the fortunes of Judah and the fortunes of Israel, and rebuild them as they were at first.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 33, 8, 'I will cleanse them from all the guilt of their sin against me, and I will forgive all the guilt of their sin and rebellion against me.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 33, 9, 'And this city shall be to me a name of joy, a praise and a glory before all the nations of the earth who shall hear of all the good that I do for them; they shall fear and tremble because of all the good and all the prosperity I provide for it.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 33, 10, 'Thus says the LORD: In this place of which you say, "It is a waste without human beings or animals," in the towns of Judah and the streets of Jerusalem that are desolate, without inhabitants, human or animal, there shall once more be heard', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 33, 11, 'the voice of mirth and the voice of gladness, the voice of the bridegroom and the voice of the bride, the voices of those who sing, as they bring thank offerings to the house of the LORD:
"Give thanks to the LORD of hosts,  
    for the LORD is good,  
    for his steadfast love endures forever!"
For I will restore the fortunes of the land as at first, says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 33, 12, 'Thus says the LORD of hosts: In this place that is waste, without human beings or animals, and in all its towns there shall again be pasture for shepherds resting their flocks.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 33, 13, 'In the towns of the hill country, of the Shephelah, and of the Negeb, in the land of Benjamin, the places around Jerusalem, and in the towns of Judah, flocks shall again pass under the hands of the one who counts them, says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 33, 14, 'The days are surely coming, says the LORD, when I will fulfill the promise I made to the house of Israel and the house of Judah.', 'en', 'NRSV-CE', 'The Righteous Branch and the Covenant with David'),
(24, 'Yer', 'Jeremiah', 33, 15, 'In those days and at that time I will cause a righteous Branch to spring up for David; and he shall execute justice and righteousness in the land.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 33, 16, 'In those days Judah will be saved and Jerusalem will live in safety. And this is the name by which it will be called: "The LORD is our righteousness."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 33, 17, 'For thus says the LORD: David shall never lack a man to sit on the throne of the house of Israel,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 33, 18, 'and the levitical priests shall never lack a man in my presence to offer burnt offerings, to make grain offerings, and to make sacrifices for all time.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 33, 19, 'The word of the LORD came to Jeremiah:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 33, 20, 'Thus says the LORD: If any of you could break my covenant with the day and my covenant with the night, so that day and night would not come at their appointed time,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 33, 21, 'only then could my covenant with my servant David be broken, so that he would not have a son to reign on his throne, and my covenant with my ministers the Levites.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 33, 22, 'Just as the host of heaven cannot be numbered and the sands of the sea cannot be measured, so I will increase the offspring of my servant David, and the Levites who minister to me.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 33, 23, 'The word of the LORD came to Jeremiah:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 33, 24, 'Have you not observed how these people say, "The two families that the LORD chose have been rejected by him," and how they hold my people in such contempt that they no longer regard them as a nation?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 33, 25, 'Thus says the LORD: Only if I had not established my covenant with day and night and the ordinances of heaven and earth,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 33, 26, 'would I reject the offspring of Jacob and of my servant David and not choose any of his descendants as rulers over the offspring of Abraham, Isaac, and Jacob. For I will restore their fortunes, and will have mercy upon them.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 34, 1, 'The word that came to Jeremiah from the LORD, when King Nebuchadrezzar of Babylon and all his army and all the kingdoms of the earth and all the peoples under his dominion were fighting against Jerusalem and all its cities:', 'en', 'NRSV-CE', 'Death in Captivity Predicted for Zedekiah'),
(24, 'Yer', 'Jeremiah', 34, 2, 'Thus says the LORD, the God of Israel: Go and speak to King Zedekiah of Judah and say to him: Thus says the LORD: I am going to give this city into the hand of the king of Babylon, and he shall burn it with fire.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 34, 3, 'And you yourself shall not escape from his hand, but shall surely be captured and handed over to him; you shall see the king of Babylon eye to eye and speak with him face to face; and you shall go to Babylon.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 34, 4, 'Yet hear the word of the LORD, O King Zedekiah of Judah! Thus says the LORD concerning you: You shall not die by the sword;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 34, 5, 'you shall die in peace. And as spices were burned for your ancestors, the earlier kings who preceded you, so they shall burn spices for you and lament for you, saying, "Alas, lord!" For I have spoken the word, says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 34, 6, 'Then the prophet Jeremiah spoke all these words to Zedekiah king of Judah, in Jerusalem,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 34, 7, 'when the army of the king of Babylon was fighting against Jerusalem and against all the cities of Judah that were left, Lachish and Azekah; for these were the only fortified cities of Judah that remained.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 34, 8, 'The word that came to Jeremiah from the LORD, after King Zedekiah had made a covenant with all the people in Jerusalem to make a proclamation of liberty to them--', 'en', 'NRSV-CE', 'Treacherous Treatment of Slaves'),
(24, 'Yer', 'Jeremiah', 34, 9, 'that all should set free their Hebrew slaves, male and female, so that no one should hold another Judean in slavery.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 34, 10, 'And they obeyed, all the officials and all the people who had entered into the covenant that all would set free their slaves, male or female, so that they would not be enslaved again; they obeyed and set them free.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 34, 11, 'But afterward they turned around and took back the male and female slaves they had set free, and brought them again into subjection as slaves.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 34, 12, 'The word of the LORD came to Jeremiah from the LORD:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 34, 13, 'Thus says the LORD, the God of Israel: I myself made a covenant with your ancestors when I brought them out of the land of Egypt, out of the house of slavery, saying,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 34, 14, '"Every seventh year each of you must set free any Hebrews who have been sold to you and have served you six years; you must set them free from your service." But your ancestors did not listen to me or incline their ears to me.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 34, 15, 'You yourselves recently repented and did what was right in my sight by proclaiming liberty to one another, and you made a covenant before me in the house that is called by my name;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 34, 16, 'but then you turned around and profaned my name when each of you took back your male and female slaves, whom you had set free according to their desire, and you brought them again into subjection to be your slaves.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 34, 17, 'Therefore, thus says the LORD: You have not obeyed me by granting a release to your neighbors and friends; I am going to grant a release to you, says the LORD--a release to the sword, to pestilence, and to famine. I will make you a horror to all the kingdoms of the earth.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 34, 18, 'And those who transgressed my covenant and did not keep the terms of the covenant that they made before me, I will make like the calf when they cut it in two and passed between its parts:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 34, 19, 'the officials of Judah, the officials of Jerusalem, the eunuchs, the priests, and all the people of the land who passed between the parts of the calf', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 34, 20, 'shall be handed over to their enemies and to those who seek their lives. Their corpses shall become food for the birds of the air and the wild animals of the earth.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 34, 21, 'And as for King Zedekiah of Judah and his officials, I will hand them over to their enemies and to those who seek their lives, to the army of the king of Babylon, which has withdrawn from you.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 34, 22, 'I am going to command, says the LORD, and will bring them back to this city; and they will fight against it, and take it, and burn it with fire. The towns of Judah I will make a desolation without inhabitant.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 35, 1, 'The word that came to Jeremiah from the LORD in the days of King Jehoiakim son of Josiah of Judah:', 'en', 'NRSV-CE', 'The Rechabites Commended'),
(24, 'Yer', 'Jeremiah', 35, 2, 'Go to the house of the Rechabites, and speak with them, and bring them to the house of the LORD, into one of the chambers; then offer them wine to drink.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 35, 3, 'So I took Jaazaniah son of Jeremiah son of Habazziniah, and his brothers, and all his sons, and the whole house of the Rechabites.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 35, 4, 'I brought them to the house of the LORD into the chamber of the sons of Hanan son of Igdaliah, the man of God, which was near the chamber of the officials, above the chamber of Maaseiah son of Shallum, keeper of the threshold.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 35, 5, 'Then I set before the Rechabites pitchers full of wine, and cups; and I said to them, "Have some wine."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 35, 6, 'But they answered, "We will drink no wine, for our ancestor Jonadab son of Rechab commanded us, "You shall never drink wine, neither you nor your children;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 35, 7, 'nor shall you ever build a house, or sow seed; nor shall you plant a vineyard, or even own one; but you shall live in tents all your days, that you may live many days in the land where you reside."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 35, 8, 'We have obeyed the charge of our ancestor Jonadab son of Rechab in all that he commanded us, to drink no wine all our days, ourselves, our wives, our sons, or our daughters,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 35, 9, 'and not to build houses to live in. We have no vineyard or field or seed;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 35, 10, 'but we have lived in tents, and have obeyed and done all that our ancestor Jonadab commanded us.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 35, 11, 'But when King Nebuchadrezzar of Babylon came up against the land, we said, "Come, and let us go to Jerusalem for fear of the army of the Chaldeans and the army of the Arameans." That is why we are living in Jerusalem."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 35, 12, 'Then the word of the LORD came to Jeremiah:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 35, 13, 'Thus says the LORD of hosts, the God of Israel: Go and say to the people of Judah and the inhabitants of Jerusalem, Can you not learn a lesson and obey my words? says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 35, 14, 'The command has been carried out that Jonadab son of Rechab gave to his descendants to drink no wine; and they drink none to this day, for they have obeyed their ancestor"s command. But I myself have spoken to you persistently, and you have not obeyed me.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 35, 15, 'I have sent to you all my servants the prophets, sending them persistently, saying, "Turn now every one of you from your evil way, and amend your doings, and do not go after other gods to serve them, and then you shall live in the land that I gave to you and your ancestors." But you did not incline your ear or obey me.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 35, 16, 'The descendants of Jonadab son of Rechab have carried out the command that their ancestor gave them, but this people has not obeyed me.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 35, 17, 'Therefore, thus says the LORD, the God of hosts, the God of Israel: I am going to bring on Judah and on all the inhabitants of Jerusalem every disaster that I have pronounced against them; because I have spoken to them and they have not listened, I have called to them and they have not answered.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 35, 18, 'But to the house of the Rechabites Jeremiah said: Thus says the LORD of hosts, the God of Israel: Because you have obeyed the command of your ancestor Jonadab, and kept all his precepts, and done all that he commanded you,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 35, 19, 'therefore thus says the LORD of hosts, the God of Israel: Jonadab son of Rechab shall not lack a descendant to stand before me for all time.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 36, 1, 'In the fourth year of King Jehoiakim son of Josiah of Judah, this word came to Jeremiah from the LORD:', 'en', 'NRSV-CE', 'The Scroll Read in the Temple'),
(24, 'Yer', 'Jeremiah', 36, 2, 'Take a scroll and write on it all the words that I have spoken to you against Israel and Judah and all the nations, from the day I spoke to you, from the days of Josiah until today.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 36, 3, 'It may be that when the house of Judah hears of all the disasters that I intend to do to them, all of them may turn from their evil ways, so that I may forgive their iniquity and their sin.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 36, 4, 'Then Jeremiah called Baruch son of Neriah, and Baruch wrote on a scroll at Jeremiah"s dictation all the words of the LORD that he had spoken to him.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 36, 5, 'And Jeremiah ordered Baruch, saying, "I am prevented from entering the house of the LORD;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 36, 6, 'so you go yourself, and on a fast day in the hearing of the people in the LORD"s house you shall read the words of the LORD from the scroll that you have written at my dictation. You shall read them also in the hearing of all the people of Judah who come up from their towns.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 36, 7, 'It may be that their plea will come before the LORD, and that all of them will turn from their evil ways, for great is the anger and wrath that the LORD has pronounced against this people."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 36, 8, 'And Baruch son of Neriah did all that the prophet Jeremiah ordered him about reading from the scroll the words of the LORD in the LORD"s house.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 36, 9, 'In the fifth year of King Jehoiakim son of Josiah of Judah, in the ninth month, all the people in Jerusalem and all the people who came from the towns of Judah to Jerusalem proclaimed a fast before the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 36, 10, 'Then, in the hearing of all the people, Baruch read the words of Jeremiah from the scroll, in the house of the LORD, in the chamber of Gemariah son of Shaphan the secretary, which was in the upper court, at the entry of the New Gate of the LORD"s house.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 36, 11, 'When Micaiah son of Gemariah son of Shaphan heard all the words of the LORD from the scroll,', 'en', 'NRSV-CE', 'The Scroll Read in the Palace'),
(24, 'Yer', 'Jeremiah', 36, 12, 'he went down to the king"s house, into the secretary"s chamber; and all the officials were sitting there: Elishama the secretary, Delaiah son of Shemaiah, Elnathan son of Achbor, Gemariah son of Shaphan, Zedekiah son of Hananiah, and all the officials.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 36, 13, 'And Micaiah told them all the words that he had heard, when Baruch read the scroll in the hearing of the people.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 36, 14, 'Then all the officials sent Jehudi son of Nethaniah son of Shelemiah son of Cushi to say to Baruch, "Bring the scroll that you read in the hearing of the people, and come." So Baruch son of Neriah took the scroll in his hand and came to them.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 36, 15, 'And they said to him, "Sit down and read it to us." So Baruch read it to them.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 36, 16, 'When they heard all the words, they turned to one another in alarm, and said to Baruch, "We certainly must report all these words to the king."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 36, 17, 'Then they questioned Baruch, "Tell us now, how did you write all these words? Was it at his dictation?"', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 36, 18, 'Baruch answered them, "He dictated all these words to me, and I wrote them with ink on the scroll."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 36, 19, 'Then the officials said to Baruch, "Go and hide, you and Jeremiah, and let no one know where you are."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 36, 20, 'Leaving the scroll in the chamber of Elishama the secretary, they went to the court of the king; and they reported all the words to the king.', 'en', 'NRSV-CE', 'Jehoiakim Burns the Scroll'),
(24, 'Yer', 'Jeremiah', 36, 21, 'Then the king sent Jehudi to get the scroll, and he took it from the chamber of Elishama the secretary; and Jehudi read it to the king and all the officials who stood beside the king.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 36, 22, 'Now the king was sitting in his winter apartment (it was the ninth month), and there was a fire burning in the brazier before him.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 36, 23, 'As Jehudi read three or four columns, the king would cut them off with a penknife and throw them into the fire in the brazier, until the entire scroll was consumed in the fire that was in the brazier.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 36, 24, 'Yet neither the king, nor any of his servants who heard all these words, was alarmed, nor did they tear their garments.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 36, 25, 'Even when Elnathan and Delaiah and Gemariah urged the king not to burn the scroll, he would not listen to them.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 36, 26, 'And the king commanded Jerahmeel the king"s son and Seraiah son of Azriel and Shelemiah son of Abdeel to arrest the secretary Baruch and the prophet Jeremiah. But the LORD hid them.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 36, 27, 'Now, after the king had burned the scroll with the words that Baruch wrote at Jeremiah"s dictation, the word of the LORD came to Jeremiah:', 'en', 'NRSV-CE', 'Jeremiah Dictates Another'),
(24, 'Yer', 'Jeremiah', 36, 28, 'Take another scroll and write on it all the former words that were in the first scroll, which King Jehoiakim of Judah has burned.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 36, 29, 'And concerning King Jehoiakim of Judah you shall say: Thus says the LORD, You have dared to burn this scroll, saying, Why have you written in it that the king of Babylon will certainly come and destroy this land, and will cut off from it human beings and animals?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 36, 30, 'Therefore thus says the LORD concerning King Jehoiakim of Judah: He shall have no one to sit upon the throne of David, and his dead body shall be cast out to the heat by day and the frost by night.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 36, 31, 'And I will punish him and his offspring and his servants for their iniquity; I will bring on them, and on the inhabitants of Jerusalem, and on the people of Judah, all the disasters with which I have threatened them--but they would not listen.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 36, 32, 'Then Jeremiah took another scroll and gave it to the secretary Baruch son of Neriah, who wrote on it at Jeremiah"s dictation all the words of the scroll that King Jehoiakim of Judah had burned in the fire; and many similar words were added to them.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 37, 1, 'Zedekiah son of Josiah, whom King Nebuchadrezzar of Babylon made king in the land of Judah, succeeded Coniah son of Jehoiakim.', 'en', 'NRSV-CE', 'Zedekiah"s Vain Hope'),
(24, 'Yer', 'Jeremiah', 37, 2, 'But neither he nor his servants nor the people of the land listened to the words of the LORD that he spoke through the prophet Jeremiah.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 37, 3, 'King Zedekiah sent Jehucal son of Shelemiah and the priest Zephaniah son of Maaseiah to the prophet Jeremiah saying, "Please pray for us to the LORD our God."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 37, 4, 'Now Jeremiah was still going in and out among the people, for he had not yet been put in prison.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 37, 5, 'Meanwhile, the army of Pharaoh had come out of Egypt; and when the Chaldeans who were besieging Jerusalem heard news of them, they withdrew from Jerusalem.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 37, 6, 'Then the word of the LORD came to the prophet Jeremiah:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 37, 7, 'Thus says the LORD, God of Israel: This is what the two of you shall say to the king of Judah, who sent you to me to inquire of me: Pharaoh"s army, which set out to help you, is going to return to its own land, to Egypt.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 37, 8, 'And the Chaldeans shall return and fight against this city; they shall take it and burn it with fire.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 37, 9, 'Thus says the LORD: Do not deceive yourselves, saying, "The Chaldeans will surely go away from us," for they will not go away.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 37, 10, 'Even if you defeated the whole army of Chaldeans who are fighting against you, and there remained of them only wounded men in their tents, they would rise up and burn this city with fire.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 37, 11, 'Now when the Chaldean army had withdrawn from Jerusalem at the approach of Pharaoh"s army,', 'en', 'NRSV-CE', 'Jeremiah Is Imprisoned'),
(24, 'Yer', 'Jeremiah', 37, 12, 'Jeremiah set out from Jerusalem to go to the land of Benjamin to receive his share of property among the people there.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 37, 13, 'When he reached the Benjamin Gate, a sentinel there named Irijah son of Shelemiah son of Hananiah arrested the prophet Jeremiah saying, "You are deserting to the Chaldeans."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 37, 14, 'And Jeremiah said, "That is a lie; I am not deserting to the Chaldeans." But Irijah would not listen to him, and arrested Jeremiah and brought him to the officials.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 37, 15, 'The officials were enraged at Jeremiah, and they beat him and imprisoned him in the house of the secretary Jonathan, for it had been made a prison.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 37, 16, 'Thus Jeremiah was put in the cistern house, in the cells, and remained there many days.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 37, 17, 'Then King Zedekiah sent for him, and received him. The king questioned him secretly in his house, and said, "Is there any word from the LORD?" Jeremiah said, "There is!" Then he said, "You shall be handed over to the king of Babylon."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 37, 18, 'Jeremiah also said to King Zedekiah, "What wrong have I done to you or your servants or this people, that you have put me in prison?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 37, 19, 'Where are your prophets who prophesied to you, saying, "The king of Babylon will not come against you and against this land"?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 37, 20, 'Now please hear me, my lord king: be good enough to listen to my plea, and do not send me back to the house of the secretary Jonathan to die there."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 37, 21, 'So King Zedekiah gave orders, and they committed Jeremiah to the court of the guard; and a loaf of bread was given him daily from the bakers" street, until all the bread of the city was gone. So Jeremiah remained in the court of the guard.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 38, 1, 'Now Shephatiah son of Mattan, Gedaliah son of Pashhur, Jucal son of Shelemiah, and Pashhur son of Malchiah heard the words that Jeremiah was saying to all the people,', 'en', 'NRSV-CE', 'Jeremiah in the Cistern'),
(24, 'Yer', 'Jeremiah', 38, 2, 'Thus says the LORD, Those who stay in this city shall die by the sword, by famine, and by pestilence; but those who go out to the Chaldeans shall live; they shall have their lives as a prize of war, and live.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 38, 3, 'Thus says the LORD, This city shall surely be handed over to the army of the king of Babylon and be taken.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 38, 4, 'Then the officials said to the king, "This man ought to be put to death, because he is discouraging the soldiers who are left in this city, and all the people, by speaking such words to them. For this man is not seeking the welfare of this people, but their harm."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 38, 5, 'King Zedekiah said, "Here he is; he is in your hands; for the king is powerless against you."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 38, 6, 'So they took Jeremiah and threw him into the cistern of Malchiah, the king"s son, which was in the court of the guard, letting Jeremiah down by ropes. Now there was no water in the cistern, but only mud, and Jeremiah sank in the mud.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 38, 7, 'Ebed-melech the Ethiopian, a eunuch in the king"s house, heard that they had put Jeremiah into the cistern. The king happened to be sitting at the Benjamin Gate,', 'en', 'NRSV-CE', 'Jeremiah Is Rescued by Ebed-melech'),
(24, 'Yer', 'Jeremiah', 38, 8, 'So Ebed-melech left the king"s house and spoke to the king,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 38, 9, '"My lord king, these men have acted wickedly in all they did to the prophet Jeremiah by throwing him into the cistern to die there of hunger, for there is no bread left in the city."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 38, 10, 'Then the king commanded Ebed-melech the Ethiopian, "Take three men with you from here, and pull the prophet Jeremiah up from the cistern before he dies."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 38, 11, 'So Ebed-melech took the men with him and went to the house of the king, to a wardrobe of the storehouse, and took from there old rags and worn-out clothes, which he let down to Jeremiah in the cistern by ropes.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 38, 12, 'Then Ebed-melech the Ethiopian said to Jeremiah, "Just put the rags and clothes between your armpits and the ropes." Jeremiah did so.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 38, 13, 'Then they drew Jeremiah up by the ropes and pulled him out of the cistern. And Jeremiah remained in the court of the guard.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 38, 14, 'King Zedekiah sent for the prophet Jeremiah and received him at the third entrance of the temple of the LORD. The king said to Jeremiah, "I have something to ask you; do not hide anything from me."', 'en', 'NRSV-CE', 'Zedekiah Consults Jeremiah Again'),
(24, 'Yer', 'Jeremiah', 38, 15, 'Jeremiah said to Zedekiah, "If I tell you, you will put me to death, will you not? And if I give you advice, you will not listen to me."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 38, 16, 'So King Zedekiah swore an oath in secret to Jeremiah, "As the LORD lives, who gave us our lives, I will not put you to death or hand you over to these men who seek your life."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 38, 17, 'Then Jeremiah said to Zedekiah, "Thus says the LORD, the God of hosts, the God of Israel, If you will only surrender to the officials of the king of Babylon, then your life shall be spared, and this city shall not be burned with fire, and you and your house shall live.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 38, 18, 'But if you do not surrender to the officials of the king of Babylon, then this city shall be handed over to the Chaldeans, and they shall burn it with fire, and you yourself shall not escape from their hand."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 38, 19, 'King Zedekiah said to Jeremiah, "I am afraid of the Judeans who have deserted to the Chaldeans, for I might be handed over to them and they would abuse me."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 38, 20, 'Jeremiah said, "That will not happen. Just obey the voice of the LORD in what I say to you, and it shall go well with you, and your life shall be spared.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 38, 21, 'But if you are determined not to surrender, this is what the LORD has shown me--', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 38, 22, 'a vision of all the women remaining in the house of the king of Judah being led out to the officials of the king of Babylon and saying,
"Your trusted friends have seduced you  
    and have overcome you;  
Now that your feet are stuck in the mud,  
    they desert you."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 38, 23, 'All your wives and your children shall be led out to the Chaldeans, and you yourself shall not escape from their hand, but shall be seized by the king of Babylon; and this city shall be burned with fire."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 38, 24, 'Then Zedekiah said to Jeremiah, "Do not let anyone else know of this conversation, or you will die.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 38, 25, 'If the officials should hear that I have spoken with you, and they should come and say to you, "Just tell us what you said to the king; do not conceal it from us, or we will put you to death. What did the king say to you?"', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 38, 26, 'then you shall say to them, "I was presenting my plea to the king not to send me back to the house of Jonathan to die there.""', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 38, 27, 'All the officials did come to Jeremiah and questioned him; and he answered them in the very words the king had commanded. So they stopped questioning him, for the conversation had not been overheard.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 38, 28, 'And Jeremiah remained in the court of the guard until the day that Jerusalem was taken.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 39, 1, 'In the ninth year of King Zedekiah of Judah, in the tenth month, King Nebuchadrezzar of Babylon and all his army came against Jerusalem and besieged it;', 'en', 'NRSV-CE', 'The Fall of Jerusalem'),
(24, 'Yer', 'Jeremiah', 39, 2, 'in the eleventh year of Zedekiah, in the fourth month, on the ninth day of the month, a breach was made in the city.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 39, 3, 'When Jerusalem was taken, all the officials of the king of Babylon came and sat in the middle gate: Nergal-sharezer, Samgar-nebo, Sarsechim the Rabsaris, Nergal-sharezer the Rabmag, with all the rest of the officials of the king of Babylon.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 39, 4, 'When King Zedekiah of Judah and all the soldiers saw them, they fled, going out of the city at night by way of the king"s garden through the gate between the two walls; and they went toward the Arabah.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 39, 5, 'But the army of the Chaldeans pursued them, and overtook Zedekiah in the plains of Jericho; and when they had taken him, they brought him up to King Nebuchadrezzar of Babylon, at Riblah, in the land of Hamath; and he passed sentence on him.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 39, 6, 'The king of Babylon slaughtered the sons of Zedekiah at Riblah before his eyes; also the king of Babylon slaughtered all the nobles of Judah.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 39, 7, 'He put out the eyes of Zedekiah, and bound him in fetters to take him to Babylon.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 39, 8, 'The Chaldeans burned the king"s house and the houses of the people, and broke down the walls of Jerusalem.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 39, 9, 'Then Nebuzaradan the captain of the guard exiled to Babylon the rest of the people who were left in the city, those who had deserted to him, and the people who remained.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 39, 10, 'Nebuzaradan the captain of the guard left in the land of Judah some of the poor people who owned nothing, and gave them vineyards and fields at the same time.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 39, 11, 'King Nebuchadrezzar of Babylon gave command concerning Jeremiah through Nebuzaradan, the captain of the guard, saying,', 'en', 'NRSV-CE', 'Jeremiah, Set Free, Remembers Ebed-melech'),
(24, 'Yer', 'Jeremiah', 39, 12, '"Take him, look after him well and do him no harm, but deal with him as he may ask you."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 39, 13, 'So Nebuzaradan the captain of the guard, Nebushazban the Rabsaris, Nergal-sharezer the Rabmag, and all the chief officers of the king of Babylon sent', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 39, 14, 'and took Jeremiah from the court of the guard. They entrusted him to Gedaliah son of Ahikam son of Shaphan to be brought home. So he stayed with his own people.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 39, 15, 'The word of the LORD came to Jeremiah while he was confined in the court of the guard:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 39, 16, 'Go and say to Ebed-melech the Ethiopian: Thus says the LORD of hosts, the God of Israel: I am going to fulfill my words against this city for evil and not for good, and they shall be accomplished in your presence on that day.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 39, 17, 'But I will save you on that day, says the LORD, and you shall not be handed over to those whom you dread.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 39, 18, 'For I will surely save you, and you shall not fall by the sword; but you shall have your life as a prize of war, because you have trusted in me, says the LORD.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 40, 1, 'The word that came to Jeremiah from the LORD after Nebuzaradan the captain of the guard had let him go from Ramah, when he took him bound in fetters along with all the captives of Jerusalem and Judah who were being exiled to Babylon.', 'en', 'NRSV-CE', 'Jeremiah with Gedaliah the Governor'),
(24, 'Yer', 'Jeremiah', 40, 2, 'The captain of the guard took Jeremiah and said to him, "The LORD your God threatened this place with this disaster;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 40, 3, 'and now the LORD has brought it about, and has done as he said, because all of you sinned against the LORD and did not obey his voice. Therefore this thing has come upon you.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 40, 4, 'Now look, I have just released you today from the fetters on your hands. If you wish to come with me to Babylon, come, and I will take good care of you; but if you do not wish to come with me to Babylon, you need not come. See, the whole land is before you; go wherever you think it good and right to go.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 40, 5, 'If you remain, then return to Gedaliah son of Ahikam son of Shaphan, whom the king of Babylon appointed governor of the towns of Judah, and stay with him among the people; or go wherever you think it right to go." So the captain of the guard gave him an allowance of food and a present, and let him go.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 40, 6, 'Then Jeremiah went to Gedaliah son of Ahikam at Mizpah, and stayed with him among the people who were left in the land.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 40, 7, 'When all the leaders of the forces in the open country and their troops heard that the king of Babylon had appointed Gedaliah son of Ahikam governor in the land, and had committed to him men, women, and children, those of the poorest of the land who had not been taken into exile to Babylon,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 40, 8, 'they went to Gedaliah at Mizpah--Ishmael son of Nethaniah, Johanan son of Kareah, Seraiah son of Tanhumeth, the sons of Ephai the Netophathite, Jezaniah son of the Maacathite, they and their troops.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 40, 9, 'Gedaliah son of Ahikam son of Shaphan swore to them and their troops, saying, "Do not be afraid to serve the Chaldeans. Stay in the land and serve the king of Babylon, and it shall go well with you.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 40, 10, 'As for me, I am staying at Mizpah to represent you before the Chaldeans who come to us; but as for you, gather wine and summer fruits and oil, and store them in your vessels, and live in the towns that you have taken over."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 40, 11, 'Likewise, when all the Judeans who were in Moab and among the Ammonites and in Edom and in other lands heard that the king of Babylon had left a remnant in Judah and had appointed Gedaliah son of Ahikam son of Shaphan as governor over them,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 40, 12, 'then all the Judeans returned from all the places to which they had been scattered and came to the land of Judah, to Gedaliah at Mizpah; and they gathered wine and summer fruits in great abundance.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 40, 13, 'Now Johanan son of Kareah and all the leaders of the forces in the open country came to Gedaliah at Mizpah', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 40, 14, 'and said to him, "Are you at all aware that Baalis king of the Ammonites has sent Ishmael son of Nethaniah to take your life?" But Gedaliah son of Ahikam would not believe them.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 40, 15, 'Then Johanan son of Kareah spoke secretly to Gedaliah at Mizpah, "Please let me go and kill Ishmael son of Nethaniah, and no one else will know. Why should he take your life, so that all the Judeans who are gathered around you would be scattered, and the remnant of Judah would perish?"', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 40, 16, 'But Gedaliah son of Ahikam said to Johanan son of Kareah, "Do not do such a thing, for you are telling a lie about Ishmael."', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 41, 1, 'In the seventh month, Ishmael son of Nethaniah son of Elishama, of the royal family, one of the chief officers of the king, came with ten men to Gedaliah son of Ahikam, at Mizpah. As they ate bread together there at Mizpah,', 'en', 'NRSV-CE', 'Insurrection against Gedaliah'),
(24, 'Yer', 'Jeremiah', 41, 2, 'Ishmael son of Nethaniah and the ten men with him got up and struck down Gedaliah son of Ahikam son of Shaphan with the sword and killed him, because the king of Babylon had appointed him governor in the land.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 41, 3, 'Ishmael also killed all the Judeans who were with Gedaliah at Mizpah, and the Chaldean soldiers who happened to be there.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 41, 4, 'On the day after the murder of Gedaliah, before anyone knew of it,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 41, 5, 'eighty men arrived from Shechem and Shiloh and Samaria, with their beards shaved and their clothes torn, and their bodies gashed, bringing grain offerings and incense to present at the temple of the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 41, 6, 'And Ishmael son of Nethaniah came out from Mizpah to meet them, weeping as he came. As he met them, he said to them, "Come to Gedaliah son of Ahikam."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 41, 7, 'When they reached the middle of the city, Ishmael son of Nethaniah and the men with him slaughtered them, and threw them into a cistern.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 41, 8, 'But there were ten men among them who said to Ishmael, "Do not kill us, for we have stores of wheat, barley, oil, and honey hidden in the fields." So he refrained, and did not kill them along with their companions.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 41, 9, 'Now the cistern into which Ishmael had thrown all the bodies of the men whom he had struck down was the large cistern that King Asa had made for defense against King Baasha of Israel; Ishmael son of Nethaniah filled that cistern with those whom he had killed.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 41, 10, 'Then Ishmael took captive all the rest of the people who were in Mizpah, the king"s daughters and all the people who were left at Mizpah, whom Nebuzaradan, the captain of the guard, had committed to Gedaliah son of Ahikam. Ishmael son of Nethaniah took them captive and set out to cross over to the Ammonites.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 41, 11, 'But when Johanan son of Kareah and all the leaders of the forces with him heard of all the crimes that Ishmael son of Nethaniah had done,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 41, 12, 'they took all their men and went to fight against Ishmael son of Nethaniah. They came upon him at the great pool that is in Gibeon.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 41, 13, 'And when all the people who were with Ishmael saw Johanan son of Kareah and all the leaders of the forces with him, they were glad.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 41, 14, 'So all the people whom Ishmael had carried away captive from Mizpah turned around and came back, and went to Johanan son of Kareah.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 41, 15, 'But Ishmael son of Nethaniah escaped from Johanan with eight men, and went to the Ammonites.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 41, 16, 'Then Johanan son of Kareah and all the leaders of the forces with him took all the rest of the people whom Ishmael son of Nethaniah had carried away captive from Mizpah after he had slain Gedaliah son of Ahikam--soldiers, women, children, and eunuchs, whom Johanan brought back from Gibeon.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 41, 17, 'And they set out, and stopped at Geruth Chimham near Bethlehem, intending to go to Egypt', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 41, 18, 'because of the Chaldeans; for they were afraid of them, because Ishmael son of Nethaniah had killed Gedaliah son of Ahikam, whom the king of Babylon had made governor over the land.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 42, 1, 'Then all the commanders of the forces, and Johanan son of Kareah and Azariah son of Hoshaiah, and all the people from the least to the greatest, approached', 'en', 'NRSV-CE', 'Jeremiah Advises Survivors Not to Migrate'),
(24, 'Yer', 'Jeremiah', 42, 2, 'the prophet Jeremiah and said, "Be good enough to listen to our plea, and pray to the LORD your God for us--for all this remnant. For there are only a few of us left out of many, as your eyes can see.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 42, 3, 'Let the LORD your God show us where we should go and what we should do."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 42, 4, 'The prophet Jeremiah said to them, "Very well: I am going to pray to the LORD your God as you request, and whatever the LORD answers you I will tell you; I will keep nothing back from you."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 42, 5, 'They in their turn said to Jeremiah, "May the LORD be a true and faithful witness against us if we do not act according to everything that the LORD your God sends us through you.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 42, 6, 'Whether it is good or bad, we will obey the voice of the LORD our God to whom we are sending you, in order that it may go well with us when we obey the voice of the LORD our God."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 42, 7, 'At the end of ten days the word of the LORD came to Jeremiah.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 42, 8, 'Then he summoned Johanan son of Kareah and all the commanders of the forces who were with him, and all the people from the least to the greatest,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 42, 9, 'and said to them, "Thus says the LORD, the God of Israel, to whom you sent me to present your plea before him:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 42, 10, 'If you will only remain in this land, then I will build you up and not pull you down; I will plant you, and not pluck you up; for I am sorry for the disaster that I have brought upon you.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 42, 11, 'Do not be afraid of the king of Babylon, as you have been; do not be afraid of him, says the LORD, for I am with you, to save you and to rescue you from his hand.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 42, 12, 'I will grant you mercy, and he will have mercy on you and restore you to your native soil.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 42, 13, 'But if you continue to say, "We will not stay in this land," thus disobeying the voice of the LORD your God', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 42, 14, 'and saying, "No, we will go to the land of Egypt, where we shall not see war, or hear the sound of the trumpet, or be hungry for bread, and there we will stay,"', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 42, 15, 'then hear the word of the LORD, O remnant of Judah. Thus says the LORD of hosts, the God of Israel: If you are determined to enter Egypt and go to settle there,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 42, 16, 'then the sword that you fear shall overtake you there, in the land of Egypt; and the famine that you dread shall follow close after you into Egypt; and there you shall die.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 42, 17, 'All the people who have determined to go to Egypt to settle there shall die by the sword, by famine, and by pestilence; they shall have no remnant or survivor from the disaster that I am bringing upon them.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 42, 18, '"For thus says the LORD of hosts, the God of Israel: Just as my anger and my wrath were poured out on the inhabitants of Jerusalem, so my wrath will be poured out on you when you go to Egypt. You shall become an object of execration and horror, of cursing and ridicule. You shall see this place no more.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 42, 19, 'The LORD has said to you, O remnant of Judah, Do not go to Egypt. Be well aware that I have warned you today', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 42, 20, 'that you have made a fatal mistake. For you yourselves sent me to the LORD your God, saying, "Pray for us to the LORD our God, and whatever the LORD our God says, tell us and we will do it."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 42, 21, 'So I have told you today, but you have not obeyed the voice of the LORD your God in anything that he sent me to tell you.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 42, 22, 'Be well aware, then, that you shall die by the sword, by famine, and by pestilence in the place where you desire to go and settle."', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 43, 1, 'When Jeremiah finished speaking to all the people all these words of the LORD their God, with which the LORD their God had sent him to them,', 'en', 'NRSV-CE', 'Taken to Egypt, Jeremiah Warns of Judgment'),
(24, 'Yer', 'Jeremiah', 43, 2, 'Azariah son of Hoshaiah and Johanan son of Kareah and all the other insolent men said to Jeremiah, "You are telling a lie. The LORD our God did not send you to say, "Do not go to Egypt to settle there";', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 43, 3, 'but Baruch son of Neriah is inciting you against us, to hand us over to the Chaldeans, in order that they may kill us or take us into exile in Babylon."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 43, 4, 'So Johanan son of Kareah and all the commanders of the forces and all the people did not obey the voice of the LORD, to stay in the land of Judah.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 43, 5, 'But Johanan son of Kareah and all the commanders of the forces took all the remnant of Judah who had returned to settle in the land of Judah from all the nations to which they had been driven--', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 43, 6, 'the men, the women, the children, the princesses, and everyone whom Nebuzaradan the captain of the guard had left with Gedaliah son of Ahikam son of Shaphan; also the prophet Jeremiah and Baruch son of Neriah.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 43, 7, 'And they came into the land of Egypt, for they did not obey the voice of the LORD. And they arrived at Tahpanhes.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 43, 8, 'Then the word of the LORD came to Jeremiah in Tahpanhes:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 43, 9, 'Take some large stones in your hands, and bury them in the clay pavement that is at the entrance to Pharaoh"s palace in Tahpanhes. Let the Judeans see you do it,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 43, 10, 'and say to them, Thus says the LORD of hosts, the God of Israel: I am going to send and take my servant King Nebuchadrezzar of Babylon, and he will set his throne above these stones that I have buried, and he will spread his royal canopy over them.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 43, 11, 'He shall come and ravage the land of Egypt, giving
those who are destined for pestilence, to pestilence,  
    and those who are destined for captivity, to captivity,  
    and those who are destined for the sword, to the sword.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 43, 12, 'He shall kindle a fire in the temples of the gods of Egypt; and he shall burn them and carry them away captive; and he shall pick clean the land of Egypt, as a shepherd picks his cloak clean of vermin; and he shall depart from there safely.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 43, 13, 'He shall break the obelisks of Heliopolis, which is in the land of Egypt; and the temples of the gods of Egypt he shall burn with fire.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 44, 1, 'The word that came to Jeremiah for all the Judeans living in the land of Egypt, at Migdol, at Tahpanhes, at Memphis, and in the land of Pathros,', 'en', 'NRSV-CE', 'Denunciation of Persistent Idolatry'),
(24, 'Yer', 'Jeremiah', 44, 2, 'Thus says the LORD of hosts, the God of Israel: You yourselves have seen all the disaster that I have brought on Jerusalem and on all the towns of Judah. Look at them; today they are a desolation, without an inhabitant in them,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 44, 3, 'because of the wickedness that they committed, provoking me to anger, in that they went to make offerings and serve other gods that they had not known, neither they, nor you, nor your ancestors.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 44, 4, 'Yet I persistently sent to you all my servants the prophets, saying, "I beg you not to do this abominable thing that I hate!"', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 44, 5, 'But they did not listen or incline their ear, to turn from their wickedness and make no offerings to other gods.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 44, 6, 'So my wrath and my anger were poured out and kindled in the towns of Judah and in the streets of Jerusalem; and they became a waste and a desolation, as they still are today.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 44, 7, 'And now thus says the LORD God of hosts, the God of Israel: Why are you doing such great harm to yourselves, to cut off man and woman, child and infant, from the midst of Judah, leaving yourselves without a remnant?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 44, 8, 'Why do you provoke me to anger with the works of your hands, making offerings to other gods in the land of Egypt where you have come to settle? Will you be cut off and become an object of cursing and ridicule among all the nations of the earth?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 44, 9, 'Have you forgotten the crimes of your ancestors, of the kings of Judah, of their wives, your own crimes and those of your wives, which they committed in the land of Judah and in the streets of Jerusalem?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 44, 10, 'They have shown no contrition or fear to this day, nor have they walked in my law and my statutes that I set before you and before your ancestors.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 44, 11, 'Therefore thus says the LORD of hosts, the God of Israel: I am determined to bring disaster on you, to bring all Judah to an end.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 44, 12, 'I will take the remnant of Judah who are determined to come to the land of Egypt to settle, and they shall perish, everyone; in the land of Egypt they shall fall; by the sword and by famine they shall perish; from the least to the greatest, they shall die by the sword and by famine; and they shall become an object of execration and horror, of cursing and ridicule.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 44, 13, 'I will punish those who live in the land of Egypt, as I have punished Jerusalem, with the sword, with famine, and with pestilence,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 44, 14, 'so that none of the remnant of Judah who have come to settle in the land of Egypt shall escape or survive or return to the land of Judah. Although they long to go back to live there, they shall not go back, except some fugitives.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 44, 15, 'Then all the men who were aware that their wives had been making offerings to other gods, and all the women who stood by, a great assembly, all the people who lived in Pathros in the land of Egypt, answered Jeremiah:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 44, 16, '"As for the word that you have spoken to us in the name of the LORD, we are not going to listen to you.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 44, 17, 'Instead, we will do everything that we have vowed, make offerings to the queen of heaven and pour out libations to her, just as we and our ancestors, our kings and our officials, used to do in the towns of Judah and in the streets of Jerusalem. We used to have plenty of food, and prospered, and saw no misfortune.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 44, 18, 'But from the time we stopped making offerings to the queen of heaven and pouring out libations to her, we have lacked everything and have perished by the sword and by famine."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 44, 19, 'And the women said, "Indeed we will go on making offerings to the queen of heaven and pouring out libations to her; do you think that we made cakes for her, marked with her image, and poured out libations to her without our husbands" being involved?"', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 44, 20, 'Then Jeremiah said to all the people, men and women, all the people who were giving him this answer:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 44, 21, '"As for the offerings that you made in the towns of Judah and in the streets of Jerusalem, you and your ancestors, your kings and your officials, and the people of the land, did not the LORD remember them? Did it not come into his mind?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 44, 22, 'The LORD could no longer bear the sight of your evil doings, the abominations that you committed; therefore your land became a desolation and a waste and a curse, without inhabitant, as it is to this day.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 44, 23, 'It is because you burned offerings, and because you sinned against the LORD and did not obey the voice of the LORD or walk in his law and in his statutes and in his decrees, that this disaster has befallen you, as is still evident today."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 44, 24, 'Jeremiah said to all the people and all the women, "Hear the word of the LORD, all you Judeans who are in the land of Egypt,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 44, 25, 'Thus says the LORD of hosts, the God of Israel: You and your wives have accomplished in deeds what you declared in words, saying, "We are determined to perform the vows that we have made, to make offerings to the queen of heaven and to pour out libations to her." By all means, keep your vows and make your libations!', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 44, 26, 'Therefore hear the word of the LORD, all you Judeans who live in the land of Egypt: Lo, I swear by my great name, says the LORD, that my name shall no longer be pronounced on the lips of any of the people of Judah in all the land of Egypt, saying, "As the Lord God lives."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 44, 27, 'I am going to watch over them for harm and not for good; all the people of Judah who are in the land of Egypt shall perish by the sword and by famine, until not one is left.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 44, 28, 'And those who escape the sword shall return from the land of Egypt to the land of Judah, few in number; and all the remnant of Judah, who have come to the land of Egypt to settle, shall know whose words will stand, mine or theirs!', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 44, 29, 'This shall be the sign to you, says the LORD, that I am going to punish you in this place, in order that you may know that my words against you will surely be carried out:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 44, 30, 'Thus says the LORD, I am going to give Pharaoh Hophra, king of Egypt, into the hands of his enemies, those who seek his life, just as I gave King Zedekiah of Judah into the hand of King Nebuchadrezzar of Babylon, his enemy who sought his life."', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 45, 1, 'The word that the prophet Jeremiah spoke to Baruch son of Neriah, when he wrote these words in a scroll at the dictation of Jeremiah, in the fourth year of King Jehoiakim son of Josiah of Judah:', 'en', 'NRSV-CE', 'A Word of Comfort to Baruch'),
(24, 'Yer', 'Jeremiah', 45, 2, 'Thus says the LORD, the God of Israel, to you, O Baruch:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 45, 3, 'You said, "Woe is me! The LORD has added sorrow to my pain; I am weary with my groaning, and I find no rest."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 45, 4, 'Thus you shall say to him, "Thus says the LORD: I am going to break down what I have built, and pluck up what I have planted--that is, the whole land.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 45, 5, 'And you, do you seek great things for yourself? Do not seek them; for I am going to bring disaster upon all flesh, says the LORD; but I will give you your life as a prize of war in every place to which you may go."', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 46, 1, 'The word of the LORD that came to the prophet Jeremiah concerning the nations.', 'en', 'NRSV-CE', 'Judgment on Egypt'),
(24, 'Yer', 'Jeremiah', 46, 2, 'Concerning Egypt, about the army of Pharaoh Neco, king of Egypt, which was by the river Euphrates at Carchemish and which King Nebuchadrezzar of Babylon defeated in the fourth year of King Jehoiakim son of Josiah of Judah:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 46, 3, 'Prepare buckler and shield,  
    and advance for battle!', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 46, 4, 'Harness the horses;  
    mount the steeds!  
Take your stations with your helmets,  
    whet your lances,  
    put on your coats of mail!', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 46, 5, 'Why do I see them terrified?  
    They have fallen back;  
their warriors are beaten down,  
    and have fled in haste.  
They do not look back--  
    terror is all around!  
says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 46, 6, 'The swift cannot flee away,  
    nor can the warrior escape;  
in the north by the river Euphrates  
    they have stumbled and fallen.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 46, 7, 'Who is this, rising like the Nile,  
    like rivers whose waters surge?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 46, 8, 'Egypt rises like the Nile,  
    like rivers whose waters surge.  
It said, Let me rise, let me cover the earth,  
    let me destroy cities and their inhabitants.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 46, 9, 'Advance, O horses,  
    and dash madly, O chariots!  
Let the warriors go forth:  
    Ethiopia and Put who carry the shield,  
    the Ludim, who draw the bow.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 46, 10, 'That day is the day of the Lord God of hosts,  
    a day of retribution,  
    to gain vindication from his foes.  
The sword shall devour and be sated,  
    and drink its fill of their blood.  
For the Lord God of hosts holds a sacrifice  
    in the land of the north by the river Euphrates.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 46, 11, 'Go up to Gilead, and take balm,  
    O virgin daughter Egypt!  
In vain you have used many medicines;  
    there is no healing for you.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 46, 12, 'The nations have heard of your shame,  
    and the earth is full of your cry;  
for warrior has stumbled against warrior;  
    both have fallen together.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 46, 13, 'The word that the LORD spoke to the prophet Jeremiah about the coming of King Nebuchadrezzar of Babylon to attack the land of Egypt:', 'en', 'NRSV-CE', 'Babylonia Will Strike Egypt'),
(24, 'Yer', 'Jeremiah', 46, 14, 'Declare in Egypt, and proclaim in Migdol;  
    proclaim in Memphis and Tahpanhes;  
Say, "Take your stations and be ready,  
    for the sword shall devour those around you."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 46, 15, 'Why has Apis fled?  
    Why did your bull not stand?  
    --because the LORD thrust him down.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 46, 16, 'Your multitude stumbled and fell,  
    and one said to another,  
"Come, let us go back to our own people  
    and to the land of our birth,  
    because of the destroying sword."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 46, 17, 'Give Pharaoh, king of Egypt, the name  
    "Braggart who missed his chance."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 46, 18, 'As I live, says the King,  
    whose name is the LORD of hosts,  
one is coming  
    like Tabor among the mountains,  
    and like Carmel by the sea.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 46, 19, 'Pack your bags for exile,  
    sheltered daughter Egypt!  
For Memphis shall become a waste,  
    a ruin, without inhabitant.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 46, 20, 'A beautiful heifer is Egypt--  
    a gadfly from the north lights upon her.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 46, 21, 'Even her mercenaries in her midst  
    are like fatted calves;  
they too have turned and fled together,  
    they did not stand;  
for the day of their calamity has come upon them,  
    the time of their punishment.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 46, 22, 'She makes a sound like a snake gliding away;  
    for her enemies march in force,  
and come against her with axes,  
    like those who fell trees.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 46, 23, 'They shall cut down her forest,  
says the LORD,  
    though it is impenetrable,  
because they are more numerous  
    than locusts;  
    they are without number.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 46, 24, 'Daughter Egypt shall be put to shame;  
    she shall be handed over to a people from the north.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 46, 25, 'The LORD of hosts, the God of Israel, said: See, I am bringing punishment upon Amon of Thebes, and Pharaoh, and Egypt and her gods and her kings, upon Pharaoh and those who trust in him.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 46, 26, 'I will hand them over to those who seek their life, to King Nebuchadrezzar of Babylon and his officers. Afterward Egypt shall be inhabited as in the days of old, says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 46, 27, 'But as for you, have no fear, my servant Jacob,  
    and do not be dismayed, O Israel;  
for I am going to save you from far away,  
    and your offspring from the land of their captivity.  
Jacob shall return and have quiet and ease,  
    and no one shall make him afraid.', 'en', 'NRSV-CE', 'God Will Save Israel'),
(24, 'Yer', 'Jeremiah', 46, 28, 'As for you, have no fear, my servant Jacob,  
says the LORD,  
    for I am with you.  
I will make an end of all the nations  
    among which I have banished you,  
    but I will not make an end of you!  
I will chastise you in just measure,  
    and I will by no means leave you unpunished.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 47, 1, 'The word of the LORD that came to the prophet Jeremiah concerning the Philistines, before Pharaoh attacked Gaza:', 'en', 'NRSV-CE', 'Judgment on the Philistines'),
(24, 'Yer', 'Jeremiah', 47, 2, 'Thus says the LORD:  
See, waters are rising out of the north  
    and shall become an overflowing torrent;  
they shall overflow the land and all that fills it,  
    the city and those who live in it.  
People shall cry out,  
    and all the inhabitants of the land shall wail.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 47, 3, 'At the noise of the stamping of the hoofs of his stallions,  
    at the clatter of his chariots, at the rumbling of their wheels,  
parents do not turn back for children,  
    so feeble are their hands,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 47, 4, 'because of the day that is coming  
    to destroy all the Philistines,  
to cut off from Tyre and Sidon  
    every helper that remains.  
For the LORD is destroying the Philistines,  
    the remnant of the coastland of Caphtor.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 47, 5, 'Baldness has come upon Gaza,  
    Ashkelon is silenced.  
O remnant of their power!  
    How long will you gash yourselves?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 47, 6, 'Ah, sword of the LORD!  
    How long until you are quiet?  
Put yourself into your scabbard,  
    rest and be still!', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 47, 7, 'How can it be quiet,  
    when the LORD has given it an order?  
Against Ashkelon and against the seashore--  
    there he has appointed it.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 48, 1, 'Concerning Moab.
Thus says the LORD of hosts, the God of Israel:
Alas for Nebo, it is laid waste!  
    Kiriathaim is put to shame, it is taken;  
the fortress is put to shame and broken down;', 'en', 'NRSV-CE', 'Judgment on Moab'),
(24, 'Yer', 'Jeremiah', 48, 2, 'the renown of Moab is no more.  
In Heshbon they planned evil against her:  
    "Come, let us cut her off from being a nation!"  
You also, O Madmen, shall be brought to silence;  
    the sword shall pursue you.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 3, 'Hark! a cry from Horonaim,  
    "Desolation and great destruction!"', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 4, '"Moab is destroyed!"  
    her little ones cry out.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 5, 'For at the ascent of Luhith  
    they go up weeping bitterly;  
for at the descent of Horonaim  
    they have heard the distressing cry of anguish.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 6, 'Flee! Save yourselves!  
    Be like a wild ass in the desert!', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 7, 'Surely, because you trusted in your strongholds and your treasures,  
    you also shall be taken;  
Chemosh shall go out into exile,  
    with his priests and his attendants.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 8, 'The destroyer shall come upon every town,  
    and no town shall escape;  
the valley shall perish,  
    and the plain shall be destroyed,  
    as the LORD has spoken.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 9, 'Set aside salt for Moab,  
    for she will surely fall;  
her towns shall become a desolation,  
    with no inhabitant in them.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 10, 'Accursed is the one who is slack in doing the work of the LORD; and accursed is the one who keeps back the sword from bloodshed.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 11, 'Moab has been at ease from his youth,  
    settled like wine on its dregs;  
he has not been emptied from vessel to vessel,  
    nor has he gone into exile;  
therefore his flavor has remained  
    and his aroma is unspoiled.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 12, 'Therefore, the time is surely coming, says the LORD, when I shall send to him decanters to decant him, and empty his vessels, and break his jars in pieces.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 13, 'Then Moab shall be ashamed of Chemosh, as the house of Israel was ashamed of Bethel, their confidence.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 14, 'How can you say, "We are heroes  
    and mighty warriors"?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 15, 'The destroyer of Moab and his towns has come up,  
    and the choicest of his young men have gone down to slaughter,  
    says the King, whose name is the LORD of hosts.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 16, 'The calamity of Moab is near at hand  
    and his doom approaches swiftly.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 17, 'Mourn over him, all you his neighbors,  
    and all who know his name;  
say, "How the mighty scepter is broken,  
    the glorious staff!"', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 18, 'Come down from glory,  
    and sit on the parched ground,  
    enthroned daughter Dibon!  
For the destroyer of Moab has come up against you;  
    he has destroyed your strongholds.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 19, 'Stand by the road and watch,  
    you inhabitant of Aroer!  
Ask the man fleeing and the woman escaping;  
    say, "What has happened?"', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 20, 'Moab is put to shame, for it is broken down;  
    wail and cry!  
Tell it by the Arnon,  
    that Moab is laid waste.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 21, 'Judgment has come upon the tableland, upon Holon, and Jahzah, and Mephaath,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 22, 'and Dibon, and Nebo, and Beth-diblathaim,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 23, 'and Kiriathaim, and Beth-gamul, and Beth-meon,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 24, 'and Kerioth, and Bozrah, and all the towns of the land of Moab, far and near.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 25, 'The horn of Moab is cut off, and his arm is broken, says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 26, 'Make him drunk, because he magnified himself against the LORD; let Moab wallow in his vomit; he too shall become a laughingstock.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 27, 'Israel was a laughingstock for you, though he was not caught among thieves; but whenever you spoke of him you shook your head!', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 28, 'Leave the towns, and live on the rock,  
    O inhabitants of Moab!  
Be like the dove that nests  
    on the sides of the mouth of a gorge.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 29, 'We have heard of the pride of Moab--  
    he is very proud--  
of his loftiness, his pride, and his arrogance,  
    and the haughtiness of his heart.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 30, 'I myself know his insolence, says the LORD;  
    his boasts are false,  
    his deeds are false.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 31, 'Therefore I wail for Moab;  
    I cry out for all Moab;  
    for the people of Kir-heres I mourn.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 32, 'More than for Jazer I weep for you,  
    O vine of Sibmah!  
Your branches crossed over the sea,  
    reached as far as Jazer;  
upon your summer fruits and your vintage  
    the destroyer has fallen.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 33, 'Gladness and joy have been taken away  
    from the fruitful land of Moab;  
I have stopped the wine from the wine presses;  
    no one treads them with shouts of joy;  
    the shouting is not the shout of joy.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 34, 'Heshbon and Elealeh cry out; as far as Jahaz they utter their voice, from Zoar to Horonaim and Eglath-shelishiyah. For even the waters of Nimrim have become desolate.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 35, 'And I will bring to an end in Moab, says the LORD, those who offer sacrifice at a high place and make offerings to their gods.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 36, 'Therefore my heart moans for Moab like a flute, and my heart moans like a flute for the people of Kir-heres; for the riches they gained have perished.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 37, 'For every head is shaved and every beard cut off; on all the hands there are gashes, and on the loins sackcloth.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 38, 'On all the housetops of Moab and in the squares there is nothing but lamentation; for I have broken Moab like a vessel that no one wants, says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 39, 'How it is broken! How they wail! How Moab has turned his back in shame! So Moab has become a derision and a horror to all his neighbors.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 40, 'For thus says the LORD:  
Look, he shall swoop down like an eagle,  
    and spread his wings against Moab;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 41, 'the towns shall be taken  
    and the strongholds seized.  
The hearts of the warriors of Moab, on that day,  
    shall be like the heart of a woman in labor.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 42, 'Moab shall be destroyed as a people,  
    because he magnified himself against the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 43, 'Terror, pit, and trap  
    are before you, O inhabitants of Moab!  
says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 44, 'Everyone who flees from the terror  
    shall fall into the pit,  
and everyone who climbs out of the pit  
    shall be caught in the trap.  
For I will bring these things upon Moab  
    in the year of their punishment,  
says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 45, 'In the shadow of Heshbon  
    fugitives stop exhausted;  
for a fire has gone out from Heshbon,  
    a flame from the house of Sihon;  
it has destroyed the forehead of Moab,  
    the scalp of the people of tumult.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 46, 'Woe to you, O Moab!  
    The people of Chemosh have perished,  
for your sons have been taken captive,  
    and your daughters into captivity.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 48, 47, 'Yet I will restore the fortunes of Moab  
    in the latter days, says the LORD.  
Thus far is the judgment on Moab.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 49, 1, 'Concerning the Ammonites.
Thus says the LORD:
Has Israel no sons?  
    Has he no heir?  
Why then has Milcom dispossessed Gad,  
    and his people settled in its towns?', 'en', 'NRSV-CE', 'Judgment on the Ammonites'),
(24, 'Yer', 'Jeremiah', 49, 2, 'Therefore, the time is surely coming,  
    says the LORD,  
when I will sound the battle alarm  
    against Rabbah of the Ammonites;  
it shall become a desolate mound,  
    and its villages shall be burned with fire;  
then Israel shall dispossess those who dispossessed him,  
    says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 49, 3, 'Wail, O Heshbon, for Ai is laid waste!  
    Cry out, O daughters of Rabbah!  
Put on sackcloth,  
    lament, and slash yourselves with whips!  
For Milcom shall go into exile,  
    with his priests and his attendants.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 49, 4, 'Why do you boast in your strength?  
    Your strength is ebbing,  
O faithless daughter.  
    You trusted in your treasures, saying,  
    "Who will attack me?"', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 49, 5, 'I am going to bring terror upon you,  
    says the Lord God of hosts,  
    from all your neighbors,  
and you will be scattered, each headlong,  
    with no one to gather the fugitives.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 49, 6, 'But afterward I will restore the fortunes of the Ammonites, says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 49, 7, 'Concerning Edom.
Thus says the LORD of hosts:
Is there no longer wisdom in Teman?  
    Has counsel perished from the prudent?  
    Has their wisdom vanished?', 'en', 'NRSV-CE', 'Judgment on Edom'),
(24, 'Yer', 'Jeremiah', 49, 8, 'Flee, turn back, get down low,  
    inhabitants of Dedan!  
For I will bring the calamity of Esau upon him,  
    the time when I punish him.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 49, 9, 'If grape-gatherers came to you,  
    would they not leave gleanings?  
If thieves came by night,  
    even they would pillage only what they wanted.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 49, 10, 'But as for me, I have stripped Esau bare,  
    I have uncovered his hiding places,  
    and he is not able to conceal himself.  
His offspring are destroyed, his kinsfolk  
    and his neighbors; and he is no more.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 49, 11, 'Leave your orphans, I will keep them alive;  
    and let your widows trust in me.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 49, 12, 'For thus says the LORD: If those who do not deserve to drink the cup still have to drink it, shall you be the one to go unpunished? You shall not go unpunished; you must drink it.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 49, 13, 'For by myself I have sworn, says the LORD, that Bozrah shall become an object of horror and ridicule, a waste, and an object of cursing; and all her towns shall be perpetual wastes.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 49, 14, 'I have heard tidings from the LORD,  
    and a messenger has been sent among the nations:  
"Gather yourselves together and come against her,  
    and rise up for battle!"', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 49, 15, 'For I will make you least among the nations,  
    despised by humankind.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 49, 16, 'The terror you inspire  
    and the pride of your heart have deceived you,  
you who live in the clefts of the rock,  
    who hold the height of the hill.  
Although you make your nest as high as the eagle"s,  
    from there I will bring you down,  
says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 49, 17, 'Edom shall become an object of horror; everyone who passes by it will be horrified and will hiss because of all its disasters.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 49, 18, 'As when Sodom and Gomorrah and their neighbors were overthrown, says the LORD, no one shall live there, nor shall anyone settle in it.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 49, 19, 'Like a lion coming up from the thickets of the Jordan against a perennial pasture, I will suddenly chase Edom away from it; and I will appoint over it whomever I choose. For who is like me? Who can summon me? Who is the shepherd who can stand before me?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 49, 20, 'Therefore hear the plan that the LORD has made against Edom and the purposes that he has formed against the inhabitants of Teman: Surely the little ones of the flock shall be dragged away; surely their fold shall be appalled at their fate.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 49, 21, 'At the sound of their fall the earth shall tremble; the sound of their cry shall be heard at the Red Sea.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 49, 22, 'Look, he shall mount up and swoop down like an eagle, and spread his wings against Bozrah, and the heart of the warriors of Edom in that day shall be like the heart of a woman in labor.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 49, 23, 'Concerning Damascus.
Hamath and Arpad are confounded,  
    for they have heard bad news;  
they melt in fear, they are troubled like the sea  
    that cannot be quiet.', 'en', 'NRSV-CE', 'Judgment on Damascus'),
(24, 'Yer', 'Jeremiah', 49, 24, 'Damascus has become feeble, she turned to flee,  
    and panic seized her;  
anguish and sorrows have taken hold of her,  
    as of a woman in labor.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 49, 25, 'How the famous city is forsaken,  
    the joyful town!', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 49, 26, 'Therefore her young men shall fall in her squares,  
    and all her soldiers shall be destroyed in that day,  
says the LORD of hosts.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 49, 27, 'And I will kindle a fire at the wall of Damascus,  
    and it shall devour the strongholds of Ben-hadad.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 49, 28, 'Concerning Kedar and the kingdoms of Hazor that King Nebuchadrezzar of Babylon defeated.
Thus says the LORD:  
Rise up, advance against Kedar!  
    Destroy the people of the east!', 'en', 'NRSV-CE', 'Judgment on Kedar and Hazor'),
(24, 'Yer', 'Jeremiah', 49, 29, 'Take their tents and their flocks,  
    their curtains and all their goods;  
carry off their camels for yourselves,  
    and a cry shall go up: "Terror is all around!"', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 49, 30, 'Flee, wander far away, hide in deep places,  
    O inhabitants of Hazor!  
says the LORD.  
For King Nebuchadrezzar of Babylon  
    has made a plan against you  
    and formed a purpose against you.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 49, 31, 'Rise up, advance against a nation at ease,  
    that lives secure,  
says the LORD,  
that has no gates or bars,  
    that lives alone.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 49, 32, 'Their camels shall become booty,  
    their herds of cattle a spoil.  
I will scatter to every wind  
    those who have shaven temples,  
and I will bring calamity  
    against them from every side,  
says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 49, 33, 'Hazor shall become a lair of jackals,  
    an everlasting waste;  
no one shall live there,  
    nor shall anyone settle in it.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 49, 34, 'The word of the LORD that came to the prophet Jeremiah concerning Elam, at the beginning of the reign of King Zedekiah of Judah.', 'en', 'NRSV-CE', 'Judgment on Elam'),
(24, 'Yer', 'Jeremiah', 49, 35, 'Thus says the LORD of hosts: I am going to break the bow of Elam, the mainstay of their might;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 49, 36, 'and I will bring upon Elam the four winds from the four quarters of heaven; and I will scatter them to all these winds, and there shall be no nation to which the exiles from Elam shall not come.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 49, 37, 'I will terrify Elam before their enemies, and before those who seek their life; I will bring disaster upon them, my fierce anger, says the LORD. I will send the sword after them, until I have consumed them;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 49, 38, 'and I will set my throne in Elam, and destroy their king and officials, says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 49, 39, 'But in the latter days I will restore the fortunes of Elam, says the LORD.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 50, 1, 'The word that the LORD spoke concerning Babylon, concerning the land of the Chaldeans, by the prophet Jeremiah:', 'en', 'NRSV-CE', 'Judgment on Babylon'),
(24, 'Yer', 'Jeremiah', 50, 2, 'Declare among the nations and proclaim,  
    set up a banner and proclaim,  
    do not conceal it, say:  
Babylon is taken,  
    Bel is put to shame,  
    Merodach is dismayed.  
Her images are put to shame,  
    her idols are dismayed.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 3, 'For out of the north a nation has come up against her; it shall make her land a desolation, and no one shall live in it; both human beings and animals shall flee away.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 4, 'In those days and in that time, says the LORD, the people of Israel shall come, they and the people of Judah together; they shall come weeping as they seek the LORD their God.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 5, 'They shall ask the way to Zion, with faces turned toward it, and they shall come and join themselves to the LORD by an everlasting covenant that will never be forgotten.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 6, 'My people have been lost sheep; their shepherds have led them astray, turning them away on the mountains; from mountain to hill they have gone, they have forgotten their fold.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 7, 'All who found them have devoured them, and their enemies have said, "We are not guilty, because they have sinned against the LORD, the true pasture, the LORD, the hope of their ancestors."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 8, 'Flee from Babylon, and go out of the land of the Chaldeans, and be like male goats leading the flock.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 9, 'For I am going to stir up and bring against Babylon a company of great nations from the land of the north; and they shall array themselves against her; from there she shall be taken. Their arrows are like the arrows of a skilled warrior who does not return empty-handed.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 10, 'Chaldea shall be plundered; all who plunder her shall be sated, says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 11, 'Though you rejoice, though you exult,  
    O plunderers of my heritage,  
though you frisk about like a heifer on the grass,  
    and neigh like stallions,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 12, 'your mother shall be utterly shamed,  
    and she who bore you shall be disgraced.  
Lo, she shall be the last of the nations,  
    a wilderness, dry land, and a desert.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 13, 'Because of the wrath of the LORD she shall not be inhabited,  
    but shall be an utter desolation;  
everyone who passes by Babylon shall be appalled  
    and hiss because of all her wounds.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 14, 'Take up your positions around Babylon,  
    all you that bend the bow;  
shoot at her, spare no arrows,  
    for she has sinned against the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 15, 'Raise a shout against her from all sides,  
    "She has surrendered;  
her bulwarks have fallen,  
    her walls are thrown down."  
For this is the vengeance of the LORD:  
    take vengeance on her,  
    do to her as she has done.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 16, 'Cut off from Babylon the sower,  
    and the wielder of the sickle in time of harvest;  
because of the destroying sword  
    all of them shall return to their own people,  
    and all of them shall flee to their own land.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 17, 'Israel is a hunted sheep driven away by lions. First the king of Assyria devoured it, and now at the end King Nebuchadrezzar of Babylon has gnawed its bones.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 18, 'Therefore, thus says the LORD of hosts, the God of Israel: I am going to punish the king of Babylon and his land, as I punished the king of Assyria.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 19, 'I will restore Israel to its pasture, and it shall feed on Carmel and in Bashan, and on the hills of Ephraim and in Gilead its hunger shall be satisfied.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 20, 'In those days and at that time, says the LORD, the iniquity of Israel shall be sought, and there shall be none; and the sins of Judah, and none shall be found; for I will pardon the remnant that I have spared.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 21, 'Go up to the land of Merathaim;  
    go up against her,  
and attack the inhabitants of Pekod  
    and utterly destroy the last of them,  
says the LORD;  
    do all that I have commanded you.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 22, 'The noise of battle is in the land,  
    and great destruction!', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 23, 'How the hammer of the whole earth  
    is cut down and broken!  
How Babylon has become  
    a horror among the nations!', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 24, 'You set a snare for yourself and you were caught, O Babylon,  
    but you did not know it;  
you were discovered and seized,  
    because you challenged the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 25, 'The LORD has opened his armory,  
    and brought out the weapons of his wrath,  
for the Lord God of hosts has a task to do  
    in the land of the Chaldeans.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 26, 'Come against her from every quarter;  
    open her granaries;  
pile her up like heaps of grain, and destroy her utterly;  
    let nothing be left of her.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 27, 'Kill all her bulls,  
    let them go down to the slaughter.  
Alas for them, their day has come,  
    the time of their punishment!', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 28, 'Listen! Fugitives and refugees from the land of Babylon are coming to declare in Zion the vengeance of the LORD our God, vengeance for his temple.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 29, 'Summon archers against Babylon, all who bend the bow. Encamp all around her; let no one escape. Repay her according to her deeds; just as she has done, do to her--for she has arrogantly defied the LORD, the Holy One of Israel.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 30, 'Therefore her young men shall fall in her squares, and all her soldiers shall be destroyed on that day, says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 31, 'I am against you, O arrogant one,  
    says the Lord God of hosts;  
for your day has come,  
    the time when I will punish you.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 32, 'The arrogant one shall stumble and fall,  
    with no one to raise him up,  
and I will kindle a fire in his cities,  
    and it will devour everything around him.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 33, 'Thus says the LORD of hosts: The people of Israel are oppressed, and so too are the people of Judah; all their captors have held them fast and refuse to let them go.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 34, 'Their Redeemer is strong; the LORD of hosts is his name. He will surely plead their cause, that he may give rest to the earth, but unrest to the inhabitants of Babylon.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 35, 'A sword against the Chaldeans, says the LORD,  
    and against the inhabitants of Babylon,  
    and against her officials and her sages!', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 36, 'A sword against the diviners,  
    so that they may become fools!  
A sword against her warriors,  
    so that they may be destroyed!', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 37, 'A sword against her horses and against her chariots,  
    and against all the foreign troops in her midst,  
    so that they may become women!  
A sword against all her treasures,  
    that they may be plundered!', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 38, 'A drought against her waters,  
    that they may be dried up!  
For it is a land of images,  
    and they go mad over idols.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 39, 'Therefore wild animals shall live with hyenas in Babylon, and ostriches shall inhabit her; she shall never again be peopled, or inhabited for all generations.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 40, 'As when God overthrew Sodom and Gomorrah and their neighbors, says the LORD, so no one shall live there, nor shall anyone settle in her.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 41, 'Look, a people is coming from the north;  
    a mighty nation and many kings  
    are stirring from the farthest parts of the earth.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 42, 'They wield bow and spear,  
    they are cruel and have no mercy.  
The sound of them is like the roaring sea;  
    they ride upon horses,  
set in array as a warrior for battle,  
    against you, O daughter Babylon!', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 43, 'The king of Babylon heard news of them,  
    and his hands fell helpless;  
anguish seized him,  
    pain like that of a woman in labor.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 44, 'Like a lion coming up from the thickets of the Jordan against a perennial pasture, I will suddenly chase them away from her; and I will appoint over her whomever I choose. For who is like me? Who can summon me? Who is the shepherd who can stand before me?', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 45, 'Therefore hear the plan that the LORD has made against Babylon, and the purposes that he has formed against the land of the Chaldeans: Surely the little ones of the flock shall be dragged away; surely their fold shall be appalled at their fate.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 50, 46, 'At the sound of the capture of Babylon the earth shall tremble, and her cry shall be heard among the nations.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 51, 1, 'Thus says the LORD:
I am going to stir up a destructive wind  
against Babylon  
    and against the inhabitants of Leb-qamai;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 2, 'and I will send winnowers to Babylon,  
    and they shall winnow her.  
They shall empty her land  
    when they come against her from every side  
    on the day of trouble.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 3, 'Let not the archer bend his bow,  
    and let him not array himself in his coat of mail.  
Do not spare her young men;  
    utterly destroy her entire army.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 4, 'They shall fall down slain in the land of the Chaldeans,  
    and wounded in her streets.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 5, 'Israel and Judah have not been forsaken  
    by their God, the LORD of hosts,  
though their land is full of guilt  
    before the Holy One of Israel.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 6, 'Flee from the midst of Babylon,  
    save your lives, each of you!  
Do not perish because of her guilt,  
    for this is the time of the LORD"s vengeance;  
    he is repaying her what is due.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 7, 'Babylon was a golden cup in the LORD"s hand,  
    making all the earth drunken;  
the nations drank of her wine,  
    and so the nations went mad.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 8, 'Suddenly Babylon has fallen and is shattered;  
    wail for her!  
Bring balm for her wound;  
    perhaps she may be healed.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 9, 'We tried to heal Babylon,  
    but she could not be healed.  
Forsake her, and let each of us go  
    to our own country;  
for her judgment has reached up to heaven  
    and has been lifted up even to the skies.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 10, 'The LORD has brought forth our vindication;  
    come, let us declare in Zion  
    the work of the LORD our God.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 11, 'Sharpen the arrows!  
    Fill the quivers!
The LORD has stirred up the spirit of the kings of the Medes, because his purpose concerning Babylon is to destroy it, for that is the vengeance of the LORD, vengeance for his temple.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 12, 'Raise a standard against the walls of Babylon;  
    make the watch strong;  
post sentinels;  
    prepare the ambushes;  
for the LORD has both planned and done  
    what he spoke concerning the inhabitants of Babylon.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 13, 'You who live by mighty waters,  
    rich in treasures,  
your end has come,  
    the thread of your life is cut.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 14, 'The LORD of hosts has sworn by himself:  
Surely I will fill you with troops like a swarm of locusts,  
    and they shall raise a shout of victory over you.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 15, 'It is he who made the earth by his power,  
    who established the world by his wisdom,  
and by his understanding stretched out the heavens.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 16, 'When he utters his voice there is a tumult of waters in the heavens,  
    and he makes the mist rise from the ends of the earth.  
He makes lightnings for the rain,  
    and he brings out the wind from his storehouses.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 17, 'Everyone is stupid and without knowledge;  
    goldsmiths are all put to shame by their idols;  
for their images are false,  
    and there is no breath in them.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 18, 'They are worthless, a work of delusion;  
    at the time of their punishment they shall perish.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 19, 'Not like these is the LORD, the portion of Jacob,  
    for he is the one who formed all things,  
and Israel is the tribe of his inheritance;  
    the LORD of hosts is his name.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 20, 'You are my war club, my weapon of battle:  
with you I smash nations;  
    with you I destroy kingdoms;', 'en', 'NRSV-CE', 'Israel the Creator"s Instrument'),
(24, 'Yer', 'Jeremiah', 51, 21, 'with you I smash the horse and its rider;  
    with you I smash the chariot and the charioteer;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 22, 'with you I smash man and woman;  
    with you I smash the old man and the boy;  
with you I smash the young man and the girl;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 23, 'with you I smash shepherds and their flocks;  
with you I smash farmers and their teams;  
    with you I smash governors and deputies.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 24, 'I will repay Babylon and all the inhabitants of Chaldea before your very eyes for all the wrong that they have done in Zion, says the LORD.', 'en', 'NRSV-CE', 'The Doom of Babylon'),
(24, 'Yer', 'Jeremiah', 51, 25, 'I am against you, O destroying mountain,  
says the LORD,  
    that destroys the whole earth;  
I will stretch out my hand against you,  
    and roll you down from the crags,  
    and make you a burned-out mountain.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 26, 'No stone shall be taken from you for a corner  
    and no stone for a foundation,  
but you shall be a perpetual waste,  
    says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 27, 'Raise a standard in the land,  
    blow the trumpet among the nations;  
prepare the nations for war against her,  
    summon against her the kingdoms,  
    Ararat, Minni, and Ashkenaz;  
appoint a marshal against her,  
    bring up horses like bristling locusts.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 28, 'Prepare the nations for war against her,  
    the kings of the Medes, with their governors and deputies,  
    and every land under their dominion.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 29, 'The land trembles and writhes,  
    for the LORD"s purposes against Babylon stand,  
to make the land of Babylon a desolation,  
    without inhabitant.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 30, 'The warriors of Babylon have given up fighting,  
    they remain in their strongholds;  
their strength has failed,  
    they have become women;  
her buildings are set on fire,  
    her bars are broken.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 31, 'One runner runs to meet another,  
    and one messenger to meet another,  
to tell the king of Babylon  
    that his city is taken from end to end:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 32, 'the fords have been seized,  
    the marshes have been burned with fire,  
    and the soldiers are in panic.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 33, 'For thus says the LORD of hosts, the God of Israel:  
Daughter Babylon is like a threshing floor  
    at the time when it is trodden;  
yet a little while  
    and the time of her harvest will come.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 34, '"King Nebuchadrezzar of Babylon has devoured me,  
    he has crushed me;  
he has made me an empty vessel,  
    he has swallowed me like a monster;  
he has filled his belly with my delicacies,  
    he has spewed me out.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 35, 'May my torn flesh be avenged on Babylon,"  
    the inhabitants of Zion shall say.  
"May my blood be avenged on the inhabitants of Chaldea,"  
    Jerusalem shall say.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 36, 'Therefore thus says the LORD:  
I am going to defend your cause  
    and take vengeance for you.  
I will dry up her sea  
    and make her fountain dry;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 37, 'and Babylon shall become a heap of ruins,  
    a den of jackals,  
an object of horror and of hissing,  
    without inhabitant.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 38, 'Like lions they shall roar together;  
    they shall growl like lions" whelps.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 39, 'When they are inflamed, I will set out their drink  
    and make them drunk, until they become merry  
and then sleep a perpetual sleep  
    and never wake, says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 40, 'I will bring them down like lambs to the slaughter,  
    like rams and goats.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 41, 'How Sheshach is taken,  
    the pride of the whole earth seized!  
How Babylon has become  
    an object of horror among the nations!', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 42, 'The sea has risen over Babylon;  
    she has been covered by its tumultuous waves.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 43, 'Her cities have become an object of horror,  
    a land of drought and a desert,  
a land in which no one lives,  
    and through which no mortal passes.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 44, 'I will punish Bel in Babylon,  
    and make him disgorge what he has swallowed.  
The nations shall no longer stream to him;  
    the wall of Babylon has fallen.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 45, 'Come out of her, my people!  
    Save your lives, each of you,  
    from the fierce anger of the LORD!', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 46, 'Do not be fainthearted or fearful  
    at the rumors heard in the land--  
one year one rumor comes,  
    the next year another,  
rumors of violence in the land  
    and of ruler against ruler.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 47, 'Assuredly, the days are coming  
    when I will punish the images of Babylon;  
her whole land shall be put to shame,  
    and all her slain shall fall in her midst.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 48, 'Then the heavens and the earth,  
    and all that is in them,  
shall shout for joy over Babylon;  
    for the destroyers shall come against them out of the north,  
says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 49, 'Babylon must fall for the slain of Israel,  
    as the slain of all the earth have fallen because of Babylon.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 50, 'You survivors of the sword,  
    go, do not linger!  
Remember the LORD in a distant land,  
    and let Jerusalem come into your mind:', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 51, 'We are put to shame, for we have heard insults;  
    dishonor has covered our face,  
for aliens have come  
    into the holy places of the LORD"s house.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 52, 'Therefore the time is surely coming, says the LORD,  
    when I will punish her idols,  
and through all her land  
    the wounded shall groan.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 53, 'Though Babylon should mount up to heaven,  
    and though she should fortify her strong height,  
from me destroyers would come upon her,  
    says the LORD.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 54, 'Listen!--a cry from Babylon!  
    A great crashing from the land of the Chaldeans!', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 55, 'For the LORD is laying Babylon waste,  
    and stilling her loud clamor.  
Their waves roar like mighty waters,  
    the sound of their clamor resounds;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 56, 'for a destroyer has come against her,  
    against Babylon;  
her warriors are taken,  
    their bows are broken;  
for the LORD is a God of recompense,  
    he will repay in full.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 57, 'I will make her officials and her sages drunk,  
    also her governors, her deputies, and her warriors;  
they shall sleep a perpetual sleep and never wake,  
    says the King, whose name is the LORD of hosts.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 58, 'Thus says the LORD of hosts:  
The broad wall of Babylon  
    shall be leveled to the ground,  
and her high gates  
    shall be burned with fire.  
The peoples exhaust themselves for nothing,  
    and the nations weary themselves only for fire.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 59, 'The word that the prophet Jeremiah commanded Seraiah son of Neriah son of Mahseiah, when he went with King Zedekiah of Judah to Babylon, in the fourth year of his reign. Seraiah was the quartermaster.', 'en', 'NRSV-CE', 'Jeremiah"s Command to Seraiah'),
(24, 'Yer', 'Jeremiah', 51, 60, 'Jeremiah wrote in a scroll all the disasters that would come on Babylon, all these words that are written concerning Babylon.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 61, 'And Jeremiah said to Seraiah: "When you come to Babylon, see that you read all these words,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 62, 'and say, "O LORD, you yourself threatened to destroy this place so that neither human beings nor animals shall live in it, and it shall be desolate forever."', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 63, 'When you finish reading this scroll, tie a stone to it, and throw it into the middle of the Euphrates,', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 51, 64, 'and say, "Thus shall Babylon sink, to rise no more, because of the disasters that I am bringing on her.""
Thus far are the words of Jeremiah.', 'en', 'NRSV-CE', NULL);

INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(24, 'Yer', 'Jeremiah', 52, 1, 'Zedekiah was twenty-one years old when he began to reign; he reigned eleven years in Jerusalem. His mother"s name was Hamutal daughter of Jeremiah of Libnah.', 'en', 'NRSV-CE', 'The Destruction of Jerusalem Reviewed'),
(24, 'Yer', 'Jeremiah', 52, 2, 'He did what was evil in the sight of the LORD, just as Jehoiakim had done.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 52, 3, 'Indeed, Jerusalem and Judah so angered the LORD that he expelled them from his presence.
Zedekiah rebelled against the king of Babylon.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 52, 4, 'And in the ninth year of his reign, in the tenth month, on the tenth day of the month, King Nebuchadrezzar of Babylon came with all his army against Jerusalem, and they laid siege to it; they built siegeworks against it all around.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 52, 5, 'So the city was besieged until the eleventh year of King Zedekiah.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 52, 6, 'On the ninth day of the fourth month the famine became so severe in the city that there was no food for the people of the land.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 52, 7, 'Then a breach was made in the city wall; and all the soldiers fled and went out from the city by night by the way of the gate between the two walls, by the king"s garden, though the Chaldeans were all around the city. They went in the direction of the Arabah.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 52, 8, 'But the army of the Chaldeans pursued the king, and overtook Zedekiah in the plains of Jericho; and all his army was scattered, deserting him.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 52, 9, 'Then they captured the king, and brought him up to the king of Babylon at Riblah in the land of Hamath, and he passed sentence on him.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 52, 10, 'The king of Babylon killed the sons of Zedekiah before his eyes, and also killed all the officers of Judah at Riblah.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 52, 11, 'He put out the eyes of Zedekiah, and bound him in fetters, and the king of Babylon took him to Babylon, and put him in prison until the day of his death.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 52, 12, 'In the fifth month, on the tenth day of the month--which was the nineteenth year of King Nebuchadrezzar, king of Babylon--Nebuzaradan the captain of the bodyguard who served the king of Babylon, entered Jerusalem.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 52, 13, 'He burned the house of the LORD, the king"s house, and all the houses of Jerusalem; every great house he burned down.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 52, 14, 'All the army of the Chaldeans, who were with the captain of the guard, broke down all the walls around Jerusalem.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 52, 15, 'Nebuzaradan the captain of the guard carried into exile some of the poorest of the people and the rest of the people who were left in the city and the deserters who had defected to the king of Babylon, together with the rest of the artisans.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 52, 16, 'But Nebuzaradan the captain of the guard left some of the poorest people of the land to be vinedressers and tillers of the soil.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 52, 17, 'The pillars of bronze that were in the house of the LORD, and the stands and the bronze sea that were in the house of the LORD, the Chaldeans broke in pieces, and carried all the bronze to Babylon.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 52, 18, 'They took away the pots, the shovels, the snuffers, the basins, the ladles, and all the vessels of bronze used in the temple service.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 52, 19, 'The captain of the guard took away the small bowls also, the firepans, the basins, the pots, the lampstands, the ladles, and the bowls for libation, both those of gold and those of silver.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 52, 20, 'As for the two pillars, the one sea, the twelve bronze bulls that were under the sea, and the stands, which King Solomon had made for the house of the LORD, the bronze of all these vessels was beyond weighing.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 52, 21, 'As for the pillars, the height of the one pillar was eighteen cubits, its circumference was twelve cubits; it was hollow and its thickness was four fingers.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 52, 22, 'Upon it was a capital of bronze; the height of the capital was five cubits; latticework and pomegranates, all of bronze, encircled the top of the capital. And the second pillar had the same, with pomegranates.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 52, 23, 'There were ninety-six pomegranates on the sides; all the pomegranates encircling the latticework numbered one hundred.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 52, 24, 'The captain of the guard took the chief priest Seraiah, the second priest Zephaniah, and the three guardians of the threshold;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 52, 25, 'and from the city he took an officer who had been in command of the soldiers, and seven men of the king"s council who were found in the city; the secretary of the commander of the army who mustered the people of the land; and sixty men of the people of the land who were found inside the city.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 52, 26, 'Then Nebuzaradan the captain of the guard took them, and brought them to the king of Babylon at Riblah.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 52, 27, 'And the king of Babylon struck them down, and put them to death at Riblah in the land of Hamath. So Judah went into exile out of its land.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 52, 28, 'This is the number of the people whom Nebuchadrezzar took into exile: in the seventh year, three thousand twenty-three Judeans;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 52, 29, 'in the eighteenth year of Nebuchadrezzar he took into exile from Jerusalem eight hundred thirty-two persons;', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 52, 30, 'in the twenty-third year of Nebuchadrezzar, Nebuzaradan the captain of the guard took into exile of the Judeans seven hundred forty-five persons; all the persons were four thousand six hundred.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 52, 31, 'In the thirty-seventh year of the exile of King Jehoiachin of Judah, in the twelfth month, on the twenty-fifth day of the month, King Evil-merodach of Babylon, in the year he began to reign, showed favor to King Jehoiachin of Judah and brought him out of prison;', 'en', 'NRSV-CE', 'Jehoiachin Favored in Captivity'),
(24, 'Yer', 'Jeremiah', 52, 32, 'he spoke kindly to him, and gave him a seat above the seats of the other kings who were with him in Babylon.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 52, 33, 'So Jehoiachin put aside his prison clothes, and every day of his life he dined regularly at the king"s table.', 'en', 'NRSV-CE', NULL),
(24, 'Yer', 'Jeremiah', 52, 34, 'For his allowance, a regular daily allowance was given him by the king of Babylon, as long as he lived, up to the day of his death.', 'en', 'NRSV-CE', NULL);

